class RoofFailureMode(Enum):
    TENSILE_FAILURE = "tensile_failure"
    SHEAR_FAILURE = "shear_failure"
    COMBINED_FAILURE = "combined_failure"
    THERMAL_SPALLING = "thermal_spalling"
    HYDROTHERMAL_ALTERATION = "hydrothermal_alteration"
    PORE_PRESSURE_FAILURE = "pore_pressure_failure"

class RockStrength(Enum):
    VERY_WEAK = "very_weak"      # < 25 MPa
    WEAK = "weak"                # 25-50 MPa
    MODERATE = "moderate"        # 50-100 MPa
    STRONG = "strong"            # 100-200 MPa
    VERY_STRONG = "very_strong"  # > 200 MPa

class AlterationIntensity(Enum):
    FRESH = "fresh"
    SLIGHT = "slight"
    MODERATE = "moderate"
    INTENSE = "intense"
    COMPLETE = "complete"

@dataclass
class CapRockProperties:
    """Physical and mechanical properties of cap rock"""
    thickness_km: float
    lithology: str
    unconfined_compressive_strength_mpa: float
    tensile_strength_mpa: float
    cohesion_mpa: float
    friction_angle_deg: float
    elastic_modulus_gpa: float
    poisson_ratio: float
    permeability_m2: float
    porosity: float
    thermal_conductivity_w_m_k: float
    thermal_expansion_per_k: float
    alteration_minerals: Dict[str, float]
    fracture_density_per_m3: float
    joint_sets: List[Dict[str, float]]

@dataclass
class StressState:
    """3D stress state at reservoir roof"""
    sigma_1: float  # Maximum principal stress (MPa)
    sigma_2: float  # Intermediate principal stress (MPa)
    sigma_3: float  # Minimum principal stress (MPa)
    pore_pressure_mpa: float
    temperature_c: float
    effective_stress_1: float  # σ1 - Pp
    effective_stress_3: float  # σ3 - Pp
    differential_stress: float # σ1 - σ3
    mean_stress: float         # (σ1 + σ2 + σ3) / 3

@dataclass
class FailureAnalysis:
    """Comprehensive failure analysis results"""
    failure_probability: float
    primary_failure_mode: RoofFailureMode
    time_to_failure_years: Optional[float]
    critical_stress_ratio: float
    safety_factor: float
    failure_surface_area_km2: float
    failure_initiation_points: List[Tuple[float, float, float]]
    contributing_factors: Dict[str, float]
    uncertainty_bounds: Tuple[float, float]

class CapRockStabilityNN(nn.Module):
    """Neural network for cap rock stability prediction"""
    
    def __init__(self, input_features: int = 25, hidden_dims: List[int] = [512, 256, 128, 64]):
        super().__init__()
        
        # Feature processing layers
        layers = []
        prev_dim = input_features
        
        for hidden_dim in hidden_dims:
            layers.extend([
                nn.Linear(prev_dim, hidden_dim),
                nn.BatchNorm1d(hidden_dim),
                nn.ReLU(),
                nn.Dropout(0.3)
            ])
            prev_dim = hidden_dim
        
        self.feature_extractor = nn.Sequential(*layers)
        
        # Attention mechanism for feature importance
        self.attention = nn.MultiheadAttention(prev_dim, num_heads=8, batch_first=True)
        
        # Multiple prediction heads
        self.stability_head = nn.Linear(prev_dim, 1)  # Stability probability
        self.failure_mode_head = nn.Linear(prev_dim, len(RoofFailureMode))
        self.time_to_failure_head = nn.Linear(prev_dim, 1)
        self.critical_ratio_head = nn.Linear(prev_dim, 1)
        self.safety_factor_head = nn.Linear(prev_dim, 1)


class TidalForcePredictor(nn.Module):
    """Real Neural Network for tidal force prediction with physics constraints"""
    
    def __init__(self, input_dim: int, hidden_dims: List[int] = [256, 128, 64, 32]):
        super().__init__()
        self._version = "2.0"
        self.input_dim = input_dim
        
        # Input normalization layer
        self.input_norm = nn.LayerNorm(input_dim)
        
        # Feature extraction layers with residual connections
        self.feature_layers = nn.ModuleList()
        self.residual_layers = nn.ModuleList()
        
        prev_dim = input_dim
        for hidden_dim in hidden_dims:
            # Main pathway
            self.feature_layers.append(nn.Sequential(
                nn.Linear(prev_dim, hidden_dim),
                nn.BatchNorm1d(hidden_dim),
                nn.GELU(),
                nn.Dropout(0.2)
            ))
            
            # Residual connection (if dimensions match)
            if prev_dim == hidden_dim:
                self.residual_layers.append(nn.Identity())
            else:
                self.residual_layers.append(nn.Linear(prev_dim, hidden_dim))
            
            prev_dim = hidden_dim
        
        # Physics-informed constraint layer
        self.physics_constraint = PhysicsConstraintLayer(prev_dim)
        
        # Multi-head output for different tidal components
        self.radial_head = nn.Sequential(
            nn.Linear(prev_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1)
        )
        
        self.tangential_head = nn.Sequential(
            nn.Linear(prev_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1)
        )
        
        self.lunar_force_head = nn.Sequential(
            nn.Linear(prev_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1)
        )
        
        self.solar_force_head = nn.Sequential(
            nn.Linear(prev_dim, 32),
            nn.ReLU(),
            nn.Linear(32, 1)
        )
        
        # Confidence prediction head
        self.confidence_head = nn.Sequential(
            nn.Linear(prev_dim, 16),
            nn.ReLU(),
            nn.Linear(16, 1),
            nn.Sigmoid()
        )
        
        # Initialize weights
        self._initialize_weights()
    
    def _initialize_weights(self):
        """Initialize network weights using physics-informed initialization"""
        for module in self.modules():
            if isinstance(module, nn.Linear):
                # Xavier initialization for most layers
                nn.init.xavier_uniform_(module.weight)
                if module.bias is not None:
                    nn.init.constant_(module.bias, 0.0)
            elif isinstance(module, nn.BatchNorm1d):
                nn.init.constant_(module.weight, 1.0)
                nn.init.constant_(module.bias, 0.0)
    
    def forward(self, x: torch.Tensor) -> Dict[str, torch.Tensor]:
        # Input normalization
        x = self.input_norm(x)
        
        # Feature extraction with residual connections
        for i, (feature_layer, residual_layer) in enumerate(zip(self.feature_layers, self.residual_layers)):
            residual = residual_layer(x)
            x = feature_layer(x)
            x = x + residual  # Residual connection
        
        # Apply physics constraints
        x = self.physics_constraint(x)
        
        # Multi-head predictions
        radial_accel = self.radial_head(x) * 1e-7  # Scale to realistic values
        tangential_accel = self.tangential_head(x) * 0.8 * radial_accel
        lunar_force = self.lunar_force_head(x) * 2.1e14 * torch.abs(radial_accel)
        solar_force = self.solar_force_head(x) * 0.46 * lunar_force
        confidence = self.confidence_head(x)
        
        return {
            'radial_acceleration': radial_accel.squeeze(-1),
            'tangential_acceleration': tangential_accel.squeeze(-1),
            'lunar_force': lunar_force.squeeze(-1),
            'solar_force': solar_force.squeeze(-1),
            'confidence': confidence.squeeze(-1)
        }


class PhysicsConstraintLayer(nn.Module):
    """Physics-informed constraint layer for tidal force predictions"""
    
    def __init__(self, feature_dim: int):
        super().__init__()
        self.feature_dim = feature_dim
        
        # Learnable physics parameters
        self.gravitational_constant = nn.Parameter(torch.tensor(6.674e-11))
        self.lunar_mass_ratio = nn.Parameter(torch.tensor(1.0))
        self.solar_mass_ratio = nn.Parameter(torch.tensor(332946.0))
        
        # Constraint enforcement layers
        self.constraint_layer = nn.Sequential(
            nn.Linear(feature_dim, feature_dim // 2),
            nn.Tanh(),
            nn.Linear(feature_dim // 2, feature_dim)
        )
        
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Apply physics constraints
        constrained = self.constraint_layer(x)
        
        # Ensure physical bounds (e.g., tidal forces can't exceed certain limits)
        constrained = torch.clamp(constrained, min=-10.0, max=10.0)
        
        return x + constrained * 0.1  # Residual physics correction
        
        # Predictions
        stability_prob = torch.sigmoid(self.stability_head(constrained_features))
        failure_mode_logits = self.failure_mode_head(constrained_features)
        time_to_failure = torch.exp(self.time_to_failure_head(constrained_features))  # Always positive
        critical_ratio = torch.sigmoid(self.critical_ratio_head(constrained_features)) * 2  # 0-2 range
        safety_factor = torch.exp(self.safety_factor_head(constrained_features))  # Always positive
        
        uncertainty = torch.softplus(self.uncertainty_head(constrained_features))  # Positive variance
        
        return {
            'stability_probability': stability_prob,
            'failure_mode_logits': failure_mode_logits,
            'time_to_failure_years': time_to_failure,
            'critical_stress_ratio': critical_ratio,
            'safety_factor': safety_factor,
            'uncertainty_mean': uncertainty[:, 0:1],
            'uncertainty_variance': uncertainty[:, 1:2],
            'attention_weights': attention_weights.squeeze(1),
            'features': constrained_features
        }

