    async def _ensure_db_initialized(self):
        """Ensure database connection and tables are initialized"""
        if self._db_initialized:
            return
        
        try:
            if not self.db_config:
                return
            
            # Initialize async connection pool
            self.db_pool = await self._initialize_async_db_pool(self.db_config)
            
            if self.db_pool:
                # Create necessary tables
                await self._create_ml_tables()
                self._db_initialized = True
                self.logger.info("Database pool and ML tables initialized")
            
        except Exception as e:
            self.logger.error(f"Failed to initialize database: {e}")
            self.db_pool = None
    
    async def _initialize_async_db_pool(self, db_config):
        """Initialize async database connection pool"""
        try:
            import asyncpg
            
            pool = await asyncpg.create_pool(
                host=db_config.host,
                port=db_config.port,
                user=db_config.user,
                password=db_config.password,
                database=db_config.database,
                min_size=2,
                max_size=10
            )
            return pool
            
        except Exception as e:
            self.logger.error(f"Failed to create async database pool: {e}")
            return None
    
    async def _create_ml_tables(self):
        """Create database tables for ML operations"""
        try:
            if not self.db_pool:
                return
            
            async with self.db_pool.acquire() as connection:
                # Create tidal predictions table
                await connection.execute('''
                    CREATE TABLE IF NOT EXISTS tidal_predictions (
                        id SERIAL PRIMARY KEY,
                        feature_vector JSONB NOT NULL,
                        radial_acceleration FLOAT NOT NULL,
                        tangential_acceleration FLOAT NOT NULL,
                        lunar_force FLOAT NOT NULL,
                        solar_force FLOAT NOT NULL,
                        confidence FLOAT NOT NULL,
                        model_version TEXT NOT NULL,
                        created_at TIMESTAMPTZ DEFAULT NOW()
                    );
                ''')
                
                # Create index for time-series queries
                await connection.execute('''
                    CREATE INDEX IF NOT EXISTS idx_tidal_predictions_created_at 
                    ON tidal_predictions(created_at);
                ''')
                
                # Create model metrics table
                await connection.execute('''
                    CREATE TABLE IF NOT EXISTS model_metrics (
                        id SERIAL PRIMARY KEY,
                        model_name TEXT NOT NULL,
                        model_type TEXT NOT NULL,
                        metric_name TEXT NOT NULL,
                        metric_value FLOAT NOT NULL,
                        metadata JSONB,
                        created_at TIMESTAMPTZ DEFAULT NOW()
                    );
                ''')
                
                self.logger.info("ML database tables created successfully")
                
        except Exception as e:
            self.logger.error(f"Failed to create ML tables: {e}")
    
