    async def _ensure_rock_db_initialized(self):
        """Ensure rock database is initialized"""
        if not self._rock_db_initialized:
            self.rock_properties_db = await self._initialize_rock_database()
            self._rock_db_initialized = True

    async def _initialize_rock_database(self) -> Dict[str, Dict]:
        """Initialize database of rock properties from comprehensive database sources"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            from .model_manager import ModelManager
            
            # Setup database connection
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            db_manager = PostgreSQLGISManager(db_config)
            rock_properties = {}
            
            # Query database for rock mechanical properties
            rock_data = await self._query_rock_properties_database(db_manager)
            
            if rock_data:
                for rock_type, properties in rock_data.items():
                    rock_properties[rock_type] = properties
                self.logger.info(f"Loaded {len(rock_properties)} rock types from database")
            else:
                self.logger.warning("No rock properties found in database, using ML predictions")
                
                # Fallback: Use ModelManager for ML-based rock property prediction
                if hasattr(self, 'model_manager') and self.model_manager:
                    rock_properties = await self._predict_rock_properties_with_ml()
            
            # Final fallback: Use curated geological literature database
            if not rock_properties:
                rock_properties = await self._load_literature_rock_properties()
            
            return rock_properties
            
        except Exception as e:
            self.logger.error(f"Failed to initialize rock database: {e}")
            # Ultimate fallback to ensure system continues operating
            return await self._get_fallback_rock_properties()
    
    async def _query_rock_properties_database(self, db_manager: 'PostgreSQLGISManager') -> Dict[str, Dict]:
        """Query rock mechanical properties from PostgreSQL database"""
        
        try:
            query = """
            SELECT 
                rp.lithology,
                AVG(rp.unconfined_compressive_strength_mpa) as ucs_mpa,
                AVG(rp.tensile_strength_mpa) as tensile_mpa,
                AVG(rp.cohesion_mpa) as cohesion_mpa,
                AVG(rp.friction_angle_deg) as friction_angle_deg,
                AVG(rp.elastic_modulus_gpa) as elastic_modulus_gpa,
                AVG(rp.poisson_ratio) as poisson_ratio,
                AVG(rp.permeability_m2) as permeability_m2,
                AVG(rp.thermal_conductivity_w_m_k) as thermal_conductivity,
                AVG(rp.thermal_expansion_per_k) as thermal_expansion,
                AVG(rp.porosity) as porosity,
                AVG(rp.fracture_density_per_m3) as fracture_density,
                COUNT(*) as sample_count,
                STDDEV(rp.unconfined_compressive_strength_mpa) as ucs_std
            FROM rock_mechanical_properties rp
            INNER JOIN geological_formations gf ON rp.formation_id = gf.formation_id
            WHERE rp.data_quality_grade IN ('A', 'B', 'C')
            AND rp.test_standard IN ('ASTM', 'ISRM', 'BS', 'DIN')
            GROUP BY rp.lithology
            HAVING COUNT(*) >= 5
            ORDER BY COUNT(*) DESC, rp.lithology;
            """
            
            async with db_manager.get_async_session() as session:
                result = await session.execute(query)
                rows = result.fetchall()
                
                rock_data = {}
                for row in rows:
                    lithology = row['lithology'].lower().replace(' ', '_')
                    
                    # Apply confidence weighting based on sample count
                    confidence = min(1.0, row['sample_count'] / 50.0)
                    
                    rock_data[lithology] = {
                        'ucs_mpa': float(row['ucs_mpa']),
                        'tensile_mpa': float(row['tensile_mpa']),
                        'cohesion_mpa': float(row['cohesion_mpa']),
                        'friction_angle_deg': float(row['friction_angle_deg']),
                        'elastic_modulus_gpa': float(row['elastic_modulus_gpa']),
                        'poisson_ratio': float(row['poisson_ratio']),
                        'permeability_m2': float(row['permeability_m2']),
                        'thermal_conductivity': float(row['thermal_conductivity']),
                        'thermal_expansion': float(row['thermal_expansion']),
                        'porosity': float(row['porosity']),
                        'fracture_density': float(row['fracture_density']),
                        'sample_count': row['sample_count'],
                        'confidence': confidence,
                        'uncertainty': float(row['ucs_std']) if row['ucs_std'] else 0.0
                    }
                
                return rock_data
                
        except Exception as e:
            self.logger.error(f"Database query for rock properties failed: {e}")
            return {}
    
