    async def _load_literature_rock_properties(self) -> Dict[str, Dict]:
        """Load rock properties from published geological literature database"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            db_manager = PostgreSQLGISManager(db_config)
            
            query = """
            SELECT 
                lr.rock_type,
                lr.property_name,
                lr.property_value,
                lr.property_unit,
                lr.reference_doi,
                lr.confidence_level
            FROM literature_rock_properties lr
            WHERE lr.confidence_level >= 0.7
            AND lr.rock_type IN ('granite', 'rhyolite', 'dacite', 'andesite', 'altered_volcanic')
            ORDER BY lr.confidence_level DESC, lr.rock_type;
            """
            
            async with db_manager.get_async_session() as session:
                result = await session.execute(query)
                rows = result.fetchall()
                
                # Organize by rock type
                literature_data = {}
                for row in rows:
                    rock_type = row['rock_type']
                    if rock_type not in literature_data:
                        literature_data[rock_type] = {}
                    
                    prop_name = row['property_name']
                    prop_value = float(row['property_value'])
                    confidence = float(row['confidence_level'])
                    
                    # Map property names to our standardized format
                    property_mapping = {
                        'compressive_strength': 'ucs_mpa',
                        'tensile_strength': 'tensile_mpa',
                        'cohesion': 'cohesion_mpa',
                        'friction_angle': 'friction_angle_deg',
                        'elastic_modulus': 'elastic_modulus_gpa',
                        'poisson_ratio': 'poisson_ratio',
                        'permeability': 'permeability_m2',
                        'thermal_conductivity': 'thermal_conductivity',
                        'thermal_expansion': 'thermal_expansion'
                    }
                    
                    if prop_name in property_mapping:
                        std_name = property_mapping[prop_name]
                        literature_data[rock_type][std_name] = prop_value
                        literature_data[rock_type][f'{std_name}_confidence'] = confidence
                
                return literature_data
                
        except Exception as e:
            self.logger.error(f"Literature database query failed: {e}")
            return {}
    
