    async def _calculate_area_from_stress_analysis(self, failure_assessments: Dict,
                                                  cap_rock_props: CapRockProperties,
                                                  stress_state: StressState) -> Optional[float]:
        """Calculate failure area using 3D stress field analysis"""
        
        try:
            from .thermodynamic_engine import ThermodynamicEngine
            
            # Use thermodynamic engine for stress field calculation
            thermo_engine = ThermodynamicEngine()
            
            # Calculate stress tensor field
            stress_field = await thermo_engine.calculate_3d_stress_field(
                cap_rock_props, stress_state
            )
            
            if stress_field:
                # Find regions where stress exceeds failure criteria
                failure_zones = await self._identify_failure_zones(
                    stress_field, failure_assessments, cap_rock_props
                )
                
                # Calculate total failure area
                total_area = 0.0
                for zone in failure_zones:
                    zone_area = zone.get('area_km2', 0.0)
                    confidence = zone.get('confidence', 0.5)
                    total_area += zone_area * confidence
                
                if total_area > 0:
                    self.logger.info(f"Stress analysis failure area: {total_area:.2f} km²")
                    return total_area
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Stress field analysis failed: {e}")
            return None
    
    async def _calculate_geometric_failure_area(self, failure_assessments: Dict,
                                         cap_rock_props: CapRockProperties,
                                         stress_state: StressState,
                                         coords: List[float] = None) -> float:
        """Enhanced geometric calculation with uncertainty quantification"""
        
        if not coords or len(coords) < 2:
            coords = [0.0, 0.0, 1.0]  # Default coordinates with depth
        
        # Comprehensive magma chamber modeling using 3d_magmatic_system_modeler
        chamber_dimensions = await self._get_comprehensive_chamber_dimensions(
            coords, stress_state, cap_rock_props
        )
        base_radius = chamber_dimensions['effective_radius']
        
        # Overpressure effect using comprehensive chamber modeling
        chamber_pressure = chamber_dimensions['pressure_mpa']
        lithostatic_pressure = chamber_dimensions['lithostatic_pressure_mpa']
        
        if chamber_pressure > lithostatic_pressure:
            overpressure_ratio = (chamber_pressure - lithostatic_pressure) / lithostatic_pressure
            overpressure_factor = 1 + 0.5 * overpressure_ratio
        else:
            overpressure_factor = 0.8
        
        # Rock strength effect
        strength_normalized = cap_rock_props.unconfined_compressive_strength_mpa / 100.0
        strength_factor = 2.0 - min(1.5, strength_normalized)
        
        # Thermal stress effect
        thermal_factor = 1.0 + (stress_state.temperature_c - 200) / 1000  # Normalized thermal contribution
        thermal_factor = max(0.5, min(2.0, thermal_factor))
        
        # Fracture density effect
        fracture_factor = 1.0 + cap_rock_props.fracture_density_per_m3 / 1000
        
        # Combined failure radius
        failure_radius_km = base_radius * overpressure_factor * strength_factor * thermal_factor * fracture_factor
        
        # Apply failure probability
        failure_prob = failure_assessments.get('combined_probability', 0.5)
        effective_radius = failure_radius_km * np.sqrt(failure_prob)  # Square root for area scaling
        
        failure_area = np.pi * effective_radius**2
        
        # Add uncertainty bounds
        uncertainty_factor = failure_assessments.get('uncertainty', 0.2)
        failure_area_min = failure_area * (1 - uncertainty_factor)
        failure_area_max = failure_area * (1 + uncertainty_factor)
        
        self.logger.info(f"Geometric failure area: {failure_area:.2f} km² (±{uncertainty_factor*100:.1f}%)")
        
        return failure_area
    
    async def _identify_failure_initiation_points(self, stress_state: StressState,
                                                 cap_rock_props: CapRockProperties,
                                                 chamber_geometry: Dict = None,
                                                 location: Tuple[float, float] = None) -> List[Tuple[float, float, float]]:
        """Identify critical failure initiation points using comprehensive 3D stress analysis"""
        
        try:
            # Primary: Use 3D finite element stress analysis
            fem_points = await self._calculate_fem_initiation_points(
                stress_state, cap_rock_props, chamber_geometry
            )
            
            if fem_points:
                return fem_points
            
            # Secondary: Use thermodynamic engine for stress field analysis
            thermo_points = await self._calculate_thermodynamic_initiation_points(
                stress_state, cap_rock_props, chamber_geometry
            )
            
            if thermo_points:
                return thermo_points
            
            # Tertiary: Use volcanic chamber database for critical zones
            if chamber_geometry or location:
                db_points = await self._query_critical_failure_zones(
                    stress_state, cap_rock_props, chamber_geometry, location
                )
                
                if db_points:
                    return db_points
            
            # Fallback: Enhanced geometric analysis with multiple factors
            return self._calculate_enhanced_geometric_points(
                stress_state, cap_rock_props, chamber_geometry
            )
            
        except Exception as e:
            self.logger.error(f"Failure initiation point identification failed: {e}")
            return await self._calculate_advanced_initiation_points(cap_rock_props)
    
    async def _calculate_fem_initiation_points(self, stress_state: StressState,
                                              cap_rock_props: CapRockProperties,
                                              chamber_geometry: Dict = None) -> Optional[List[Tuple[float, float, float]]]:
        """Calculate failure initiation points using finite element stress analysis"""
        
        try:
            from .thermodynamic_engine import ThermodynamicEngine
            
            # Use thermodynamic engine for FEM analysis
            thermo_engine = ThermodynamicEngine()
            
            # Calculate 3D stress tensor field
            stress_field = await thermo_engine.calculate_3d_stress_field(
                cap_rock_props, stress_state, chamber_geometry
            )
            
            if not stress_field:
                return None
            
            # Find stress concentration points
            initiation_points = []
            
            # Analyze stress field for critical zones
            for element in stress_field.get('elements', []):
                coords = element.get('coordinates', [0, 0, 0])
                stress_tensor = element.get('stress_tensor', {})
                
                # Calculate principal stress invariants
                sigma_1 = stress_tensor.get('sigma_1', 0)
                sigma_3 = stress_tensor.get('sigma_3', 0)
                von_mises = stress_tensor.get('von_mises_stress', 0)
                
                # Evaluate failure criteria at this point
                mohr_coulomb_ratio = self._evaluate_mohr_coulomb_local(
                    sigma_1, sigma_3, cap_rock_props
                )
                
                griffith_ratio = self._evaluate_griffith_local(
                    sigma_1, sigma_3, cap_rock_props
                )
                
                # If failure criteria exceeded, this is an initiation point
                if mohr_coulomb_ratio > 0.8 or griffith_ratio > 0.8:
                    confidence = max(mohr_coulomb_ratio, griffith_ratio)
                    
                    initiation_points.append({
                        'coordinates': tuple(coords),
                        'failure_mechanism': 'mohr_coulomb' if mohr_coulomb_ratio > griffith_ratio else 'tensile',
                        'failure_ratio': confidence,
                        'von_mises_stress': von_mises,
                        'principal_stresses': [sigma_1, stress_tensor.get('sigma_2', 0), sigma_3]
                    })
            
            # Sort by failure ratio (highest first) and return top points
            initiation_points.sort(key=lambda x: x['failure_ratio'], reverse=True)
            
            # Return coordinate tuples for top 10 critical points
            critical_points = [point['coordinates'] for point in initiation_points[:10]]
            
            if critical_points:
                self.logger.info(f"FEM analysis found {len(critical_points)} critical initiation points")
                return critical_points
            
            return None
            
        except Exception as e:
            self.logger.warning(f"FEM initiation point calculation failed: {e}")
            return None
    
    def _evaluate_mohr_coulomb_local(self, sigma_1: float, sigma_3: float,
                                    cap_rock_props: CapRockProperties) -> float:
        """Evaluate Mohr-Coulomb criterion at a local point"""
        
        cohesion = cap_rock_props.cohesion_mpa
        friction_angle_rad = np.radians(cap_rock_props.friction_angle_deg)
        
        # Mohr-Coulomb criterion
        tau_critical = cohesion + sigma_3 * np.tan(friction_angle_rad)
        tau_acting = (sigma_1 - sigma_3) / 2
        
        return tau_acting / tau_critical if tau_critical > 0 else 0
    
    def _evaluate_griffith_local(self, sigma_1: float, sigma_3: float,
                                cap_rock_props: CapRockProperties) -> float:
        """Evaluate Griffith tensile criterion at a local point"""
        
        tensile_strength = cap_rock_props.tensile_strength_mpa
        
        # Griffith criterion for tensile failure
        if sigma_3 >= 0:  # No tension
            return 0
        
        return abs(sigma_3) / tensile_strength if tensile_strength > 0 else 0
    
    async def _calculate_thermodynamic_initiation_points(self, stress_state: StressState,
                                                        cap_rock_props: CapRockProperties,
                                                        chamber_geometry: Dict = None) -> Optional[List[Tuple[float, float, float]]]:
        """Calculate initiation points using thermodynamic stress gradients"""
        
        try:
            from .thermodynamic_engine import ThermodynamicEngine
            
            thermo_engine = ThermodynamicEngine()
            
            # Calculate thermal stress gradients
            thermal_gradients = await thermo_engine.calculate_thermal_stress_gradients(
                cap_rock_props, stress_state, chamber_geometry
            )
            
            if not thermal_gradients:
                return None
            
            initiation_points = []
            
            # Find points of maximum thermal stress gradient
            for gradient_point in thermal_gradients.get('gradient_points', []):
                coords = gradient_point.get('coordinates', [0, 0, 0])
                thermal_stress = gradient_point.get('thermal_stress_mpa', 0)
                gradient_magnitude = gradient_point.get('gradient_magnitude', 0)
                
                # Check if thermal stress exceeds local strength
                local_strength = await self._estimate_advanced_local_strength(
                    coords, cap_rock_props, stress_state
                )
                
                stress_ratio = thermal_stress / local_strength if local_strength > 0 else 0
                
                if stress_ratio > 0.6:  # Critical thermal stress threshold
                    initiation_points.append({
                        'coordinates': tuple(coords),
                        'stress_ratio': stress_ratio,
                        'thermal_stress': thermal_stress,
                        'gradient_magnitude': gradient_magnitude
                    })
            
            # Sort by stress ratio and return top points
            initiation_points.sort(key=lambda x: x['stress_ratio'], reverse=True)
            
            critical_points = [point['coordinates'] for point in initiation_points[:8]]
            
            if critical_points:
                self.logger.info(f"Thermodynamic analysis found {len(critical_points)} thermal initiation points")
                return critical_points
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Thermodynamic initiation point calculation failed: {e}")
            return None
    
    async def _estimate_advanced_local_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                               stress_state: StressState) -> float:
        """Advanced local rock strength characterization using volcano data and ML models"""
        
        try:
            x, y, z = coords
            depth_km = abs(z)
            
            # Primary: Database-driven strength characterization
            database_strength = await self._get_database_local_strength(coords, cap_rock_props, stress_state)
            
            # Secondary: ML-predicted local strength variations
            ml_strength = await self._get_ml_predicted_local_strength(coords, cap_rock_props, stress_state)
            
            # Tertiary: Volcanic system-enhanced strength analysis
            volcanic_strength = await self._get_volcanic_enhanced_strength(coords, cap_rock_props, stress_state)
            
            # Quaternary: Physics-based multi-scale strength modeling
            physics_strength = await self._get_physics_based_local_strength(coords, cap_rock_props, stress_state)
            
            # Ensemble strength estimation
            strength_estimates = []
            if database_strength: strength_estimates.append(('database', database_strength, 0.9))
            if ml_strength: strength_estimates.append(('ml_prediction', ml_strength, 0.8))  
            if volcanic_strength: strength_estimates.append(('volcanic_enhanced', volcanic_strength, 0.85))
            if physics_strength: strength_estimates.append(('physics_based', physics_strength, 0.7))
            
            if not strength_estimates:
                # Enhanced empirical fallback
                return await self._calculate_enhanced_empirical_strength(coords, cap_rock_props, stress_state)
            
            # Weighted ensemble of strength estimates
            total_weight = sum(weight for _, _, weight in strength_estimates)
            weighted_strength = sum(strength * weight for _, strength, weight in strength_estimates) / total_weight
            
            # Apply safety factors based on uncertainty
            uncertainty_factor = 1.0 - (len(strength_estimates) * 0.1)  # Lower uncertainty with more estimates
            safety_factor = max(0.8, uncertainty_factor)  # Conservative safety factor
            
            final_strength = weighted_strength * safety_factor
            
            self.logger.debug(f"Advanced local strength at ({x:.2f}, {y:.2f}, {z:.2f}): {final_strength:.1f} MPa "
                            f"(from {len(strength_estimates)} methods)")
            return final_strength
            
        except Exception as e:
            self.logger.error(f"Advanced local strength estimation failed: {e}")
            return await self._calculate_enhanced_empirical_strength(coords, cap_rock_props, stress_state)
    
    async def _get_database_local_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                          stress_state: StressState) -> Optional[float]:
        """Get local strength from geological database"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            x, y, z = coords
            depth_km = abs(z)
            
            # Comprehensive geographic coordinate transformation using data integration
            lat, lon = await self._get_comprehensive_geographic_coordinates(coords, stress_state)
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query local strength measurements
                strength_query = """
                    SELECT 
                        ucs_mpa, tensile_strength_mpa, temperature_c, depth_km,
                        ST_Distance(
                            geom, 
                            ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633)
                        ) as distance_m
                    FROM rock_strength_measurements
                    WHERE ST_DWithin(
                        geom, 
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633),
                        %s
                    )
                    AND depth_km BETWEEN %s AND %s
                    AND temperature_c BETWEEN %s AND %s
                    ORDER BY distance_m, ABS(depth_km - %s), ABS(temperature_c - %s)
                    LIMIT 10;
                """
                
                temp_range = 50  # ±50°C temperature tolerance
                depth_range = 0.5  # ±0.5km depth tolerance
                
                measurements = await db.fetch_all(
                    strength_query,
                    lon, lat, lon, lat,  # lon, lat for both distance calc and spatial query
                    20000,  # 20km radius
                    max(depth_km - depth_range, 0),
                    depth_km + depth_range,
                    max(stress_state.temperature_c - temp_range, 0),
                    stress_state.temperature_c + temp_range,
                    depth_km,  # for depth ordering
                    stress_state.temperature_c  # for temperature ordering
                )
                
                if measurements:
                    # Weighted average based on proximity
                    total_weight = 0
                    weighted_ucs = 0
                    weighted_tensile = 0
                    
                    for measurement in measurements:
                        distance_weight = 1.0 / (1.0 + measurement['distance_m'] / 1000)  # km-based weight
                        depth_weight = 1.0 / (1.0 + abs(measurement['depth_km'] - depth_km))
                        temp_weight = 1.0 / (1.0 + abs(measurement['temperature_c'] - stress_state.temperature_c) / 100)
                        
                        combined_weight = distance_weight * depth_weight * temp_weight
                        total_weight += combined_weight
                        
                        weighted_ucs += measurement['ucs_mpa'] * combined_weight
                        weighted_tensile += measurement['tensile_strength_mpa'] * combined_weight
                    
                    if total_weight > 0:
                        avg_ucs = weighted_ucs / total_weight
                        avg_tensile = weighted_tensile / total_weight
                        
                        # Return effective strength (conservative estimate)
                        return min(avg_ucs, avg_tensile * 8)  # Tensile strength controls
                        
        except Exception as e:
            self.logger.debug(f"Database strength query error: {e}")
        
        return None
    
    async def _get_ml_predicted_local_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                              stress_state: StressState) -> Optional[float]:
        """Use ML models to predict local strength variations"""
        
        try:
            model_manager = await self._get_model_manager()
            if not model_manager:
                return None
            
            x, y, z = coords
            depth_km = abs(z)
            
            # Feature vector for ML strength prediction
            feature_vector = {
                'x_km': x,
                'y_km': y, 
                'depth_km': depth_km,
                'temperature_c': stress_state.temperature_c,
                'pressure_mpa': stress_state.confining_pressure_mpa,
                'base_ucs_mpa': cap_rock_props.unconfined_compressive_strength_mpa,
                'base_tensile_mpa': cap_rock_props.tensile_strength_mpa,
                'youngs_modulus_gpa': cap_rock_props.youngs_modulus_gpa,
                'poissons_ratio': cap_rock_props.poissons_ratio,
                'porosity': cap_rock_props.porosity,
                'thermal_conductivity': cap_rock_props.thermal_conductivity,
                'distance_from_center': np.sqrt(x**2 + y**2)
            }
            
            # Use local strength prediction model with versioning
            predictions = await self._get_versioned_model_prediction(
                'cap_rock_local_strength_v2', 
                feature_vector,
                version='latest'
            )
            
            if predictions and 'local_strength_mpa' in predictions:
                predicted_strength = predictions['local_strength_mpa']
                confidence = predictions.get('confidence', 0.5)
                
                if confidence > 0.6:
                    return predicted_strength
            
            # Use ensemble strength model with versioning
            ensemble_predictions = await self._get_versioned_model_prediction(
                'rock_strength_ensemble_v3',
                feature_vector,
                version='latest'
            )
            
            if ensemble_predictions and 'ensemble_strength_mpa' in ensemble_predictions:
                ensemble_strength = ensemble_predictions['ensemble_strength_mpa']
                ensemble_confidence = ensemble_predictions.get('confidence', 0.5)
                
                if ensemble_confidence > 0.7:
                    return ensemble_strength
                        
        except Exception as e:
            self.logger.debug(f"ML strength prediction error: {e}")
        
        return None
    
    async def _get_volcanic_enhanced_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                             stress_state: StressState) -> Optional[float]:
        """Get strength enhanced by volcanic system analysis"""
        
        try:
            if not self.volcanic_chamber_system:
                return None
            
            x, y, z = coords
            depth_km = abs(z)
            
            # Get volcanic system local conditions
            lat = stress_state.latitude if hasattr(stress_state, 'latitude') else 0
            lon = stress_state.longitude if hasattr(stress_state, 'longitude') else 0
            
            volcanic_conditions = await self.volcanic_chamber_system.get_local_conditions(
                latitude=lat, longitude=lon, depth_km=depth_km
            )
            
            if volcanic_conditions:
                # Base strength from cap rock properties
                base_ucs = cap_rock_props.unconfined_compressive_strength_mpa
                base_tensile = cap_rock_props.tensile_strength_mpa
                
                # Apply volcanic system modifications
                alteration_factor = volcanic_conditions.get('hydrothermal_alteration_factor', 1.0)
                thermal_weakening = volcanic_conditions.get('thermal_weakening_factor', 1.0)
                pressure_strengthening = volcanic_conditions.get('pressure_strengthening_factor', 1.0)
                chemical_weakening = volcanic_conditions.get('chemical_alteration_factor', 1.0)
                
                # Combined volcanic effects
                volcanic_ucs = base_ucs * alteration_factor * thermal_weakening * pressure_strengthening * chemical_weakening
                volcanic_tensile = base_tensile * alteration_factor * thermal_weakening * pressure_strengthening * chemical_weakening
                
                # Apply chamber proximity effects
                chamber_proximity = volcanic_conditions.get('chamber_proximity_factor', 1.0)
                magma_interaction = volcanic_conditions.get('magma_interaction_factor', 1.0)
                
                final_ucs = volcanic_ucs * chamber_proximity * magma_interaction
                final_tensile = volcanic_tensile * chamber_proximity * magma_interaction
                
                return min(final_ucs, final_tensile * 10)  # Conservative estimate
                
        except Exception as e:
            self.logger.debug(f"Volcanic strength enhancement error: {e}")
        
        return None
    
    async def _get_physics_based_local_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                               stress_state: StressState) -> Optional[float]:
        """Calculate physics-based local strength using multi-scale modeling"""
        
        try:
            x, y, z = coords
            depth_km = abs(z)
            
            # Micro-scale effects (grain-level) - Comprehensive petrographic analysis
            grain_size_effect = await self._comprehensive_petrographic_grain_analysis(coords, cap_rock_props)
            porosity_effect = self._calculate_porosity_strength_effect(cap_rock_props.porosity)
            
            # Meso-scale effects (crack/fracture level)
            crack_density = await self._estimate_local_crack_density(coords, stress_state)
            fracture_effect = self._calculate_fracture_network_strength_effect(crack_density)
            
            # Macro-scale effects (structural level)
            depth_effect = self._calculate_depth_dependent_strength(depth_km, stress_state.confining_pressure_mpa)
            temperature_effect = await self._calculate_advanced_temperature_strength_degradation(stress_state.temperature_c, cap_rock_props, coords)
            stress_effect = self._calculate_stress_dependent_strength(stress_state)
            
            # Combine multi-scale effects
            base_strength = min(
                cap_rock_props.unconfined_compressive_strength_mpa,
                cap_rock_props.tensile_strength_mpa * 12
            )
            
            # Apply temperature degradation to base strength
            temp_factor = 1.0 - max(temperature_effect.get('ucs_degradation', 0),
                                   temperature_effect.get('tensile_degradation', 0))
            
            physics_strength = (base_strength * 
                              grain_size_effect * 
                              porosity_effect * 
                              fracture_effect * 
                              depth_effect * 
                              temp_factor * 
                              stress_effect)
            
            return physics_strength
            
        except Exception as e:
            self.logger.debug(f"Physics-based strength calculation error: {e}")
        
        return None
    
    async def _calculate_enhanced_empirical_strength(self, coords: List[float], cap_rock_props: CapRockProperties,
                                              stress_state: StressState) -> float:
        """Enhanced empirical strength calculation with multiple factors"""
        
        x, y, z = coords
        depth_km = abs(z)
        
        # Base strength values
        base_ucs = cap_rock_props.unconfined_compressive_strength_mpa
        base_tensile = cap_rock_props.tensile_strength_mpa
        
        # Enhanced depth effect (non-linear)
        if depth_km < 1.0:
            depth_factor = 0.8 + 0.2 * depth_km  # Shallow depth weakening
        else:
            depth_factor = np.exp(-(depth_km - 1.0) / 8)  # Exponential decay beyond 1km
        
        # Enhanced temperature effect (phase transition aware)
        temp_c = stress_state.temperature_c
        if temp_c < 100:
            temp_factor = 1.0 - 0.0005 * (temp_c - 25)  # Linear degradation
        elif temp_c < 400:
            temp_factor = 0.962 - 0.0012 * (temp_c - 100)  # Accelerated degradation
        else:
            temp_factor = max(0.1, 0.6 - 0.001 * (temp_c - 400))  # Severe degradation
        
        # Stress concentration effect using comprehensive chamber modeling
        distance_from_center = np.sqrt(x**2 + y**2)
        chamber_dimensions = await self._get_comprehensive_chamber_dimensions(
            coords, stress_state, cap_rock_props
        )
        chamber_radius = chamber_dimensions['effective_radius']
        
        if distance_from_center < chamber_radius * 0.5:
            # High stress concentration zone
            stress_conc_factor = 0.6 + 0.3 * (distance_from_center / (chamber_radius * 0.5))
        elif distance_from_center < chamber_radius:
            # Moderate stress concentration
            stress_conc_factor = 0.9 - 0.2 * ((distance_from_center - chamber_radius * 0.5) / (chamber_radius * 0.5))
        else:
            # Far field - minimal effect
            stress_conc_factor = 1.0
        
        # Pressure effect (confining pressure strengthening)
        confining_pressure = stress_state.confining_pressure_mpa
        pressure_factor = 1.0 + 0.02 * confining_pressure  # 2% increase per MPa confining pressure
        
        # Combined effects
        enhanced_ucs = base_ucs * depth_factor * temp_factor * stress_conc_factor * pressure_factor
        enhanced_tensile = base_tensile * depth_factor * temp_factor * stress_conc_factor * pressure_factor
        
        # Return conservative estimate
        return min(enhanced_ucs, enhanced_tensile * 15)
    
    async def _query_critical_failure_zones(self, stress_state: StressState,
                                           cap_rock_props: CapRockProperties,
                                           chamber_geometry: Dict = None,
                                           location: Tuple[float, float] = None) -> Optional[List[Tuple[float, float, float]]]:
        """Query database for known critical failure zones"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            if not location:
                return None
            
            lat, lon = location
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            db_manager = PostgreSQLGISManager(db_config)
            
            query = """
            SELECT 
                cfz.zone_id,
                ST_X(cfz.critical_point::geometry) as x_km,
                ST_Y(cfz.critical_point::geometry) as y_km,
                cfz.depth_km,
                cfz.failure_mechanism,
                cfz.stress_ratio,
                cfz.confidence_level,
                cfz.historical_failures,
                ST_Distance(cfz.location::geography, ST_Point(%s, %s)::geography) as distance_m
            FROM critical_failure_zones cfz
            WHERE ST_DWithin(cfz.location::geography, ST_Point(%s, %s)::geography, 25000)
            AND cfz.stress_ratio >= 0.5
            AND cfz.confidence_level >= 0.6
            ORDER BY cfz.stress_ratio DESC, distance_m ASC
            LIMIT 15;
            """
            
            async with db_manager.get_async_session() as session:
                result = await session.execute(query, (lon, lat, lon, lat))
                rows = result.fetchall()
                
                if rows:
                    initiation_points = []
                    
                    for row in rows:
                        # Convert database coordinates to local coordinate system
                        x_km = float(row['x_km'])
                        y_km = float(row['y_km']) 
                        z_km = -float(row['depth_km'])  # Negative for depth below surface
                        
                        initiation_points.append((x_km, y_km, z_km))
                    
                    self.logger.info(f"Database query found {len(initiation_points)} known failure zones")
                    return initiation_points
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Critical failure zone database query failed: {e}")
            return None
    
    def _calculate_enhanced_geometric_points(self, stress_state: StressState,
                                            cap_rock_props: CapRockProperties,
                                            chamber_geometry: Dict = None) -> List[Tuple[float, float, float]]:
        """Calculate initiation points using enhanced geometric analysis"""
        
        initiation_points = []
        
        # Determine chamber dimensions
        if chamber_geometry:
            chamber_radius = chamber_geometry.get('width_km', 3.0) / 2
            chamber_depth = chamber_geometry.get('depth_km', cap_rock_props.thickness_km)
            roof_thickness = chamber_geometry.get('roof_depth_km', cap_rock_props.thickness_km)
        else:
            # Estimate from stress state and rock properties
            chamber_radius = cap_rock_props.thickness_km * 0.6
            chamber_depth = cap_rock_props.thickness_km
            roof_thickness = cap_rock_props.thickness_km
        
        # Central roof point (maximum thermal stress)
        initiation_points.append((0.0, 0.0, -roof_thickness))
        
        # Ring of points at chamber margin (stress concentration)
        n_margin_points = 8
        for i in range(n_margin_points):
            angle = 2 * np.pi * i / n_margin_points
            x = chamber_radius * np.cos(angle)
            y = chamber_radius * np.sin(angle)
            z = -roof_thickness
            initiation_points.append((x, y, z))
        
        # Intermediate points (between center and margin)
        intermediate_radius = chamber_radius * 0.5
        for i in range(4):
            angle = np.pi/2 * i
            x = intermediate_radius * np.cos(angle)
            y = intermediate_radius * np.sin(angle)
            z = -roof_thickness * 0.8  # Slightly shallower
            initiation_points.append((x, y, z))
        
        # Deep points (if chamber is deep)
        if chamber_depth > roof_thickness * 1.5:
            deep_z = -chamber_depth * 0.9
            for i in range(4):
                angle = np.pi/4 + np.pi/2 * i
                x = chamber_radius * 0.3 * np.cos(angle)
                y = chamber_radius * 0.3 * np.sin(angle)
                initiation_points.append((x, y, deep_z))
        
        # Add points based on stress concentration factors
        overpressure_ratio = max(0, (stress_state.sigma_3 - roof_thickness * 27) / (roof_thickness * 27))
        
        if overpressure_ratio > 0.2:
            # Add additional points for high overpressure scenarios
            extended_radius = chamber_radius * (1 + overpressure_ratio * 0.5)
            for i in range(6):
                angle = np.pi/3 * i
                x = extended_radius * np.cos(angle)
                y = extended_radius * np.sin(angle)
                z = -roof_thickness * 0.9
                initiation_points.append((x, y, z))
        
        self.logger.info(f"Enhanced geometric analysis generated {len(initiation_points)} initiation points")
        return initiation_points
    
    async def _calculate_advanced_initiation_points(self, cap_rock_props: CapRockProperties, 
                                                   coords: List[float] = None) -> List[Tuple[float, float, float]]:
        """Advanced multi-physics crack initiation point analysis"""
        
        try:
            initiation_points = []
            
            # Primary: Multi-chamber volcanic system analysis
            if coords and len(coords) >= 2:
                volcanic_initiation_points = await self._calculate_volcanic_stress_initiation_points(
                    coords, cap_rock_props
                )
                if volcanic_initiation_points:
                    initiation_points.extend(volcanic_initiation_points)
                    self.logger.debug(f"Added {len(volcanic_initiation_points)} volcanic stress initiation points")
            
            # Secondary: Thermodynamic engine analysis
            thermo_initiation_points = await self._calculate_thermodynamic_initiation_points(
                cap_rock_props, coords
            )
            if thermo_initiation_points:
                initiation_points.extend(thermo_initiation_points)
                self.logger.debug(f"Added {len(thermo_initiation_points)} thermodynamic initiation points")
            
            # Tertiary: ML model predictions for stress concentrations
            ml_initiation_points = await self._calculate_ml_predicted_initiation_points(
                cap_rock_props, coords
            )
            if ml_initiation_points:
                initiation_points.extend(ml_initiation_points)
                self.logger.debug(f"Added {len(ml_initiation_points)} ML-predicted initiation points")
            
            # Quaternary: Database-driven geological weakness analysis
            geological_initiation_points = await self._calculate_geological_weakness_initiation_points(
                cap_rock_props, coords
            )
            if geological_initiation_points:
                initiation_points.extend(geological_initiation_points)
                self.logger.debug(f"Added {len(geological_initiation_points)} geological weakness points")
            
            # Remove duplicates and rank by criticality
            unique_points = await self._rank_and_filter_initiation_points(initiation_points, cap_rock_props)
            
            if not unique_points:
                # Enhanced geometric fallback with stress concentration
                unique_points = self._calculate_enhanced_geometric_initiation_points(cap_rock_props)
            
            self.logger.info(f"Advanced analysis generated {len(unique_points)} critical initiation points")
            return unique_points
            
        except Exception as e:
            self.logger.error(f"Advanced initiation point calculation failed: {e}")
            # Enhanced geometric fallback
            return self._calculate_enhanced_geometric_initiation_points(cap_rock_props)
    
    async def _calculate_volcanic_stress_initiation_points(self, coords: List[float], 
                                                          cap_rock_props: CapRockProperties) -> List[Tuple[float, float, float]]:
        """Calculate initiation points based on volcanic chamber stress fields"""
        
        initiation_points = []
        
        try:
            if not self.volcanic_chamber_system:
                return initiation_points
            
            lat, lon = coords[0], coords[1]
            
            # Get multi-chamber stress field data
            chamber_data = await self.volcanic_chamber_system.get_chamber_stress_field(
                latitude=lat, longitude=lon, depth_range_km=[0, cap_rock_props.thickness_km * 2]
            )
            
            if chamber_data and 'stress_concentrations' in chamber_data:
                for stress_point in chamber_data['stress_concentrations']:
                    if stress_point.get('stress_intensity', 0) > 0.7:  # High stress concentration
                        point = (
                            stress_point.get('x_km', 0),
                            stress_point.get('y_km', 0),
                            -abs(stress_point.get('depth_km', cap_rock_props.thickness_km))
                        )
                        initiation_points.append(point)
            
            # Add chamber boundary intersections
            if chamber_data and 'chamber_boundaries' in chamber_data:
                boundary_points = await self._calculate_chamber_boundary_intersections(
                    chamber_data['chamber_boundaries'], cap_rock_props
                )
                initiation_points.extend(boundary_points)
            
        except Exception as e:
            self.logger.debug(f"Volcanic stress initiation point calculation error: {e}")
        
        return initiation_points[:20]  # Limit to top 20 points
    
    async def _calculate_thermodynamic_initiation_points(self, cap_rock_props: CapRockProperties, 
                                                        coords: List[float] = None) -> List[Tuple[float, float, float]]:
        """Calculate initiation points using thermodynamic engine analysis"""
        
        initiation_points = []
        
        try:
            if not self.thermodynamic_engine:
                return initiation_points
            
            # Get thermal stress field from thermodynamic engine
            thermal_analysis = await self.thermodynamic_engine.calculate_thermal_stress_field(
                depth_km=cap_rock_props.thickness_km,
                rock_properties={
                    'thermal_conductivity': cap_rock_props.thermal_conductivity,
                    'thermal_expansion': cap_rock_props.thermal_expansion_coefficient,
                    'youngs_modulus': cap_rock_props.youngs_modulus_gpa * 1e9,
                    'poissons_ratio': cap_rock_props.poissons_ratio
                },
                coordinates=coords
            )
            
            if thermal_analysis and 'thermal_stress_concentrations' in thermal_analysis:
                for thermal_point in thermal_analysis['thermal_stress_concentrations']:
                    if thermal_point.get('thermal_stress_mpa', 0) > cap_rock_props.tensile_strength_mpa * 0.6:
                        point = (
                            thermal_point.get('x_km', 0),
                            thermal_point.get('y_km', 0),
                            -abs(thermal_point.get('depth_km', cap_rock_props.thickness_km))
                        )
                        initiation_points.append(point)
            
            # Add thermal gradient discontinuities
            if thermal_analysis and 'gradient_discontinuities' in thermal_analysis:
                for gradient_point in thermal_analysis['gradient_discontinuities']:
                    point = (
                        gradient_point.get('x_km', 0),
                        gradient_point.get('y_km', 0),
                        -abs(gradient_point.get('depth_km', cap_rock_props.thickness_km))
                    )
                    initiation_points.append(point)
                    
        except Exception as e:
            self.logger.debug(f"Thermodynamic initiation point calculation error: {e}")
        
        return initiation_points[:15]  # Limit to top 15 points
    
    async def _calculate_ml_predicted_initiation_points(self, cap_rock_props: CapRockProperties, 
                                                       coords: List[float] = None) -> List[Tuple[float, float, float]]:
        """Use ML models to predict crack initiation points"""
        
        initiation_points = []
        
        try:
            if not self.model_manager:
                return initiation_points
            
            # Prepare feature vector for ML prediction
            feature_vector = {
                'thickness_km': cap_rock_props.thickness_km,
                'youngs_modulus_gpa': cap_rock_props.youngs_modulus_gpa,
                'poissons_ratio': cap_rock_props.poissons_ratio,
                'tensile_strength_mpa': cap_rock_props.tensile_strength_mpa,
                'thermal_conductivity': cap_rock_props.thermal_conductivity,
                'porosity': cap_rock_props.porosity,
                'latitude': coords[0] if coords and len(coords) > 0 else 0,
                'longitude': coords[1] if coords and len(coords) > 1 else 0
            }
            
            # Use stress concentration prediction model
            stress_model = await self.model_manager.get_model('cap_rock_stress_concentration_v2')
            if stress_model:
                predictions = await stress_model.predict(feature_vector)
                
                if predictions and 'initiation_points' in predictions:
                    for pred_point in predictions['initiation_points']:
                        if pred_point.get('probability', 0) > 0.7:
                            point = (
                                pred_point.get('x_km', 0),
                                pred_point.get('y_km', 0),
                                -abs(pred_point.get('depth_km', cap_rock_props.thickness_km))
                            )
                            initiation_points.append(point)
            
            # Use failure initiation ensemble model
            ensemble_model = await self.model_manager.get_model('cap_rock_failure_initiation_ensemble')
            if ensemble_model:
                ensemble_predictions = await ensemble_model.predict(feature_vector)
                
                if ensemble_predictions and 'critical_zones' in ensemble_predictions:
                    for zone in ensemble_predictions['critical_zones']:
                        if zone.get('failure_probability', 0) > 0.8:
                            point = (
                                zone.get('x_km', 0),
                                zone.get('y_km', 0),
                                -abs(zone.get('depth_km', cap_rock_props.thickness_km))
                            )
                            initiation_points.append(point)
                            
        except Exception as e:
            self.logger.debug(f"ML initiation point prediction error: {e}")
        
        return initiation_points[:12]  # Limit to top 12 ML predictions
    
    async def _calculate_geological_weakness_initiation_points(self, cap_rock_props: CapRockProperties, 
                                                              coords: List[float] = None) -> List[Tuple[float, float, float]]:
        """Identify initiation points based on geological weaknesses from database"""
        
        initiation_points = []
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            if not coords or len(coords) < 2:
                return initiation_points
            
            # Database connection for geological data
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query for geological weaknesses (faults, fractures, contacts)
                weakness_query = """
                    SELECT 
                        ST_X(geom) as x_utm, ST_Y(geom) as y_utm, depth_km,
                        weakness_type, strength_reduction_factor
                    FROM geological_weaknesses 
                    WHERE ST_DWithin(
                        geom, 
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633),
                        %s
                    )
                    AND depth_km <= %s
                    AND strength_reduction_factor > 0.3
                    ORDER BY strength_reduction_factor DESC
                    LIMIT 15;
                """
                
                weakness_data = await db.fetch_all(
                    weakness_query, 
                    coords[1], coords[0],  # lon, lat
                    50000,  # 50km radius
                    cap_rock_props.thickness_km * 1.5
                )
                
                # Convert UTM to local coordinates and add as initiation points
                for weakness in weakness_data:
                    # Comprehensive geodetic coordinate transformation
                    geodetic_info = await self._comprehensive_geodetic_reference_system_detection(
                        coords[1], coords[0]
                    )
                    
                    # Apply comprehensive coordinate transformation
                    lat_weakness, lon_weakness = await self._comprehensive_coordinate_transformation_with_geodetic_systems(
                        weakness['x_utm'], weakness['y_utm'], geodetic_info
                    )
                    
                    # Calculate precise distance using haversine formula
                    distance_km = self._haversine_distance(
                        coords[0], coords[1], lat_weakness, lon_weakness
                    )
                    
                    # Convert to local coordinate system with proper azimuth
                    bearing = self._calculate_bearing(
                        coords[0], coords[1], lat_weakness, lon_weakness
                    )
                    
                    x_km = distance_km * math.sin(math.radians(bearing))
                    y_km = distance_km * math.cos(math.radians(bearing))
                    z_km = -abs(weakness['depth_km'])
                    
                    point = (x_km, y_km, z_km)
                    initiation_points.append(point)
                
                # Query for rock property variations
                property_query = """
                    SELECT 
                        ST_X(geom) as x_utm, ST_Y(geom) as y_utm, depth_km,
                        strength_variation_factor
                    FROM rock_property_variations
                    WHERE ST_DWithin(
                        geom, 
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633),
                        %s
                    )
                    AND depth_km <= %s
                    AND strength_variation_factor < 0.7
                    ORDER BY strength_variation_factor ASC
                    LIMIT 10;
                """
                
                variation_data = await db.fetch_all(
                    property_query,
                    coords[1], coords[0],  # lon, lat
                    30000,  # 30km radius  
                    cap_rock_props.thickness_km
                )
                
                for variation in variation_data:
                    x_km = (variation['x_utm'] - coords[1] * 111320) / 1000
                    y_km = (variation['y_utm'] - coords[0] * 110540) / 1000
                    z_km = -abs(variation['depth_km'])
                    
                    point = (x_km, y_km, z_km)
                    initiation_points.append(point)
                    
        except Exception as e:
            self.logger.debug(f"Geological weakness initiation point calculation error: {e}")
        
        return initiation_points
    
    async def _rank_and_filter_initiation_points(self, points: List[Tuple[float, float, float]], 
                                                cap_rock_props: CapRockProperties) -> List[Tuple[float, float, float]]:
        """Rank initiation points by criticality and remove duplicates"""
        
        if not points:
            return points
        
        try:
            # Remove points that are too close to each other (within 0.1 km)
            unique_points = []
            for point in points:
                is_unique = True
                for existing_point in unique_points:
                    distance = np.sqrt(
                        (point[0] - existing_point[0])**2 + 
                        (point[1] - existing_point[1])**2 + 
                        (point[2] - existing_point[2])**2
                    )
                    if distance < 0.1:  # 100m threshold
                        is_unique = False
                        break
                
                if is_unique:
                    unique_points.append(point)
            
            # Rank by depth (shallower points are more critical) and distance from center
            ranked_points = sorted(unique_points, key=lambda p: (abs(p[2]), np.sqrt(p[0]**2 + p[1]**2)))
            
            # Return top 25 most critical points
            return ranked_points[:25]
            
        except Exception as e:
            self.logger.error(f"Point ranking error: {e}")
            return points[:25]
    
    def _calculate_enhanced_geometric_initiation_points(self, cap_rock_props: CapRockProperties) -> List[Tuple[float, float, float]]:
        """Enhanced geometric initiation points with stress concentration theory"""
        
        initiation_points = []
        chamber_radius = cap_rock_props.thickness_km * 0.8  # Larger radius for stress concentration
        roof_depth = cap_rock_props.thickness_km * 0.9  # Slightly above chamber roof
        
        # Central point (maximum stress concentration)
        initiation_points.append((0.0, 0.0, -roof_depth))
        
        # Stress concentration points around chamber periphery
        for angle in np.linspace(0, 360, 12, endpoint=False):  # 12 points
            x = chamber_radius * np.cos(np.radians(angle))
            y = chamber_radius * np.sin(np.radians(angle))
            z = -roof_depth
            initiation_points.append((x, y, z))
        
        # Intermediate depth points (stress gradient zones)
        intermediate_depth = roof_depth * 0.7
        for angle in [45, 135, 225, 315]:  # 4 intermediate points
            x = chamber_radius * 0.6 * np.cos(np.radians(angle))
            y = chamber_radius * 0.6 * np.sin(np.radians(angle))
            z = -intermediate_depth
            initiation_points.append((x, y, z))
        
        return initiation_points
    
