    async def _get_physics_based_thermal_degradation(self, temperature_c: float,
                                                    cap_rock_props: CapRockProperties,
                                                    coords: List[float] = None) -> Dict[str, float]:
        """Physics-based thermal degradation modeling"""
        try:
            # Reference temperature
            t_ref = 25.0  # °C
            temp_diff = max(0, temperature_c - t_ref)
            
            if temp_diff <= 0:
                return {'ucs_degradation': 0, 'tensile_degradation': 0, 'cohesion_degradation': 0}
            
            # Material-dependent thermal degradation physics
            lithology = cap_rock_props.lithology_type.value if cap_rock_props.lithology_type else 'andesite'
            
            # Thermal expansion coefficient (1/K)
            thermal_expansion_coeffs = {
                'granite': 8e-6, 'andesite': 6e-6, 'basalt': 9e-6, 'dacite': 7e-6,
                'rhyolite': 8.5e-6, 'obsidian': 5e-6, 'pumice': 10e-6, 'tuff': 12e-6,
                'limestone': 6e-6, 'sandstone': 11e-6, 'shale': 9e-6, 'quartzite': 13e-6
            }
            alpha = thermal_expansion_coeffs.get(lithology, 8e-6)
            
            # Young's modulus temperature dependence
            E_base = cap_rock_props.youngs_modulus_gpa * 1e3  # Convert to MPa
            E_temp_coeff = -2e-4  # MPa/K (typical for rocks)
            E_temp = E_base * (1 + E_temp_coeff * temp_diff)
            
            # Thermal stress calculation
            thermal_strain = alpha * temp_diff
            thermal_stress = E_temp * thermal_strain  # Constrained thermal expansion
            
            # Critical temperatures for phase transitions and degradation
            T_critical = {
                'granite': 550, 'andesite': 600, 'basalt': 650, 'dacite': 575,
                'rhyolite': 525, 'obsidian': 450, 'pumice': 400, 'tuff': 350
            }
            T_crit = T_critical.get(lithology, 550)
            
            # Arrhenius-type thermal activation
            activation_energy = 50000  # J/mol (typical for rock degradation)
            gas_constant = 8.314  # J/mol·K
            T_kelvin = temperature_c + 273.15
            T_ref_kelvin = t_ref + 273.15
            
            arrhenius_factor = np.exp(-activation_energy/gas_constant * (1/T_kelvin - 1/T_ref_kelvin))
            
            # Thermal degradation mechanisms
            # 1. Thermal expansion mismatch degradation
            expansion_degradation = min(0.5, thermal_stress / (cap_rock_props.tensile_strength_mpa * 1000))
            
            # 2. Phase transition degradation (above critical temperature)
            phase_degradation = 0
            if temperature_c > T_crit:
                phase_degradation = min(0.4, (temperature_c - T_crit) / 200)
            
            # 3. Arrhenius thermal activation degradation
            activation_degradation = min(0.3, arrhenius_factor - 1) if arrhenius_factor > 1 else 0
            
            # Different degradation rates for different strength properties
            # UCS: most resistant to thermal effects
            ucs_degradation = 0.6 * expansion_degradation + 0.3 * phase_degradation + 0.1 * activation_degradation
            
            # Tensile strength: most sensitive to thermal effects
            tensile_degradation = 0.8 * expansion_degradation + 0.5 * phase_degradation + 0.3 * activation_degradation
            
            # Cohesion: intermediate sensitivity
            cohesion_degradation = 0.7 * expansion_degradation + 0.4 * phase_degradation + 0.2 * activation_degradation
            
            return {
                'ucs_degradation': min(0.95, max(0.0, ucs_degradation)),
                'tensile_degradation': min(0.95, max(0.0, tensile_degradation)),
                'cohesion_degradation': min(0.95, max(0.0, cohesion_degradation))
            }
            
        except Exception as e:
            self.logger.warning(f"Physics-based thermal degradation calculation failed: {e}")
            return None
    
    async def _get_enhanced_empirical_thermal_degradation(self, temperature_c: float,
                                                         cap_rock_props: CapRockProperties, 
                                                         coords: List[float] = None) -> Dict[str, float]:
        """Enhanced empirical thermal degradation with material corrections"""
        try:
            # Reference temperature (room temperature)
            t_ref = 25.0  # °C
            temp_diff = max(0, temperature_c - t_ref)
            
            if temp_diff <= 0:
                return {'ucs_degradation': 0, 'tensile_degradation': 0, 'cohesion_degradation': 0}
            
            # Enhanced material-specific degradation rates
            lithology = cap_rock_props.lithology_type.value if cap_rock_props.lithology_type else 'andesite'
            
            # Material-specific base degradation rates (per °C)
            base_rates = {
                'granite': {'ucs': 0.0008, 'tensile': 0.0015, 'cohesion': 0.0012},
                'andesite': {'ucs': 0.001, 'tensile': 0.002, 'cohesion': 0.0015},
                'basalt': {'ucs': 0.0009, 'tensile': 0.0018, 'cohesion': 0.0014},
                'dacite': {'ucs': 0.0011, 'tensile': 0.0021, 'cohesion': 0.0016},
                'rhyolite': {'ucs': 0.0007, 'tensile': 0.0014, 'cohesion': 0.0011},
                'obsidian': {'ucs': 0.0015, 'tensile': 0.003, 'cohesion': 0.0022},
                'pumice': {'ucs': 0.002, 'tensile': 0.004, 'cohesion': 0.003},
                'tuff': {'ucs': 0.0018, 'tensile': 0.0035, 'cohesion': 0.0026},
                'limestone': {'ucs': 0.0012, 'tensile': 0.0024, 'cohesion': 0.0018},
                'sandstone': {'ucs': 0.0014, 'tensile': 0.0028, 'cohesion': 0.0021},
                'shale': {'ucs': 0.0016, 'tensile': 0.0032, 'cohesion': 0.0024},
                'quartzite': {'ucs': 0.0006, 'tensile': 0.0012, 'cohesion': 0.0009}
            }
            
            rates = base_rates.get(lithology, base_rates['andesite'])
            
            # Porosity correction (higher porosity = more thermal sensitivity)
            porosity_factor = 1.0 + 2.0 * cap_rock_props.porosity
            
            # Alteration correction (more altered = more thermal sensitivity)
            alteration_factor = 1.0 + 0.5 * cap_rock_props.alteration_degree
            
            # Comprehensive petrographic grain size thermal sensitivity analysis
            grain_size_factor = await self._comprehensive_grain_size_thermal_sensitivity(coords, cap_rock_props)
            
            # Apply corrections
            corrected_rates = {}
            for prop in ['ucs', 'tensile', 'cohesion']:
                corrected_rates[prop] = rates[prop] * porosity_factor * alteration_factor * grain_size_factor
            
            return {
                'ucs_degradation': min(0.95, temp_diff * corrected_rates['ucs']),
                'tensile_degradation': min(0.95, temp_diff * corrected_rates['tensile']),
                'cohesion_degradation': min(0.95, temp_diff * corrected_rates['cohesion'])
            }
            
        except Exception as e:
            self.logger.error(f"Enhanced empirical thermal degradation failed: {e}")
            # Final fallback to simple empirical values
            temp_diff = max(0, temperature_c - 25.0)
            return {
                'ucs_degradation': min(0.8, temp_diff * 0.001),
                'tensile_degradation': min(0.8, temp_diff * 0.002), 
                'cohesion_degradation': min(0.8, temp_diff * 0.0015)
            }
    
    async def _analyze_progressive_failure(self, coords: List[float], stress_tensor: Dict,
                                          cap_rock_props: CapRockProperties, max_ratio: float) -> Dict:
        """Analyze progressive failure characteristics"""
        
        try:
            # Progressive failure stages
            stages = {
                'crack_initiation': max_ratio > 0.3,
                'crack_propagation': max_ratio > 0.5,
                'coalescence': max_ratio > 0.7,
                'ultimate_failure': max_ratio > 0.9
            }
            
            # Comprehensive time-dependent failure progression using data integration and historical databases
            progression_timeline = await self._calculate_comprehensive_temporal_progression(
                max_ratio, stress_tensor, cap_rock_props, coords, stages
            )
            
            # Failure mode transitions
            mode_transitions = self._calculate_failure_mode_transitions(stress_tensor, cap_rock_props)
            
            return {
                'current_stage': self._determine_current_failure_stage(stages),
                'stages_active': stages,
                'progression_timeline': progression_timeline,
                'mode_transitions': mode_transitions,
                'propagation_velocity': self._estimate_crack_propagation_velocity(stress_tensor, cap_rock_props)
            }
            
        except Exception as e:
            self.logger.error(f"Progressive failure analysis failed: {e}")
            return {
                'current_stage': 'unknown',
                'stages_active': {},
                'progression_timeline': {},
                'mode_transitions': {},
                'propagation_velocity': 0.0
            }
    
    def _determine_current_failure_stage(self, stages: Dict[str, bool]) -> str:
        """Determine current failure stage"""
        
        if stages['ultimate_failure']:
            return 'ultimate_failure'
        elif stages['coalescence']:
            return 'coalescence'
        elif stages['crack_propagation']:
            return 'crack_propagation'
        elif stages['crack_initiation']:
            return 'crack_initiation'
        else:
            return 'stable'
    
    async def _calculate_advanced_temporal_progression(self, max_ratio: float, stress_tensor: Dict, 
                                                      cap_rock_props: CapRockProperties, 
                                                      coords: List[float] = None) -> Dict[str, float]:
        """Advanced temporal failure progression modeling with ML and volcanic forecasting"""
        
        try:
            timeline = {}
            
            # Primary: ML-based temporal forecasting
            ml_timeline = await self._calculate_ml_temporal_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            if ml_timeline:
                timeline.update(ml_timeline)
                self.logger.debug("Using ML-based temporal progression")
            
            # Secondary: Volcanic system-informed temporal modeling
            volcanic_timeline = await self._calculate_volcanic_temporal_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            if volcanic_timeline:
                # Combine with ML timeline (take minimum for conservative estimate)
                for stage, time_years in volcanic_timeline.items():
                    if stage in timeline:
                        timeline[stage] = min(timeline[stage], time_years)
                    else:
                        timeline[stage] = time_years
                self.logger.debug("Enhanced with volcanic temporal modeling")
            
            # Tertiary: Physics-based fracture mechanics temporal analysis
            physics_timeline = await self._calculate_physics_based_temporal_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            if physics_timeline:
                for stage, time_years in physics_timeline.items():
                    if stage in timeline:
                        timeline[stage] = min(timeline[stage], time_years)
                    else:
                        timeline[stage] = time_years
                self.logger.debug("Enhanced with physics-based temporal analysis")
            
            # Quaternary: Database-informed temporal progression
            database_timeline = await self._calculate_database_temporal_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            if database_timeline:
                for stage, time_years in database_timeline.items():
                    if stage in timeline:
                        timeline[stage] = min(timeline[stage], time_years) * 0.9  # Conservative factor
                    else:
                        timeline[stage] = time_years
                self.logger.debug("Enhanced with database temporal data")
            
            # Ensure timeline has minimum progression stages
            if not timeline:
                timeline = self._calculate_enhanced_empirical_timeline(max_ratio, cap_rock_props)
            
            # Apply volcanic acceleration factors
            timeline = await self._apply_volcanic_acceleration_factors(timeline, coords)
            
            self.logger.info(f"Advanced temporal progression: {len(timeline)} stages calculated")
            return timeline
            
        except Exception as e:
            self.logger.error(f"Advanced temporal progression calculation failed: {e}")
            return self._calculate_enhanced_empirical_timeline(max_ratio, cap_rock_props)
    
    async def _calculate_ml_temporal_progression(self, max_ratio: float, stress_tensor: Dict,
                                               cap_rock_props: CapRockProperties, 
                                               coords: List[float] = None) -> Dict[str, float]:
        """Use ML models to predict failure progression timeline"""
        
        timeline = {}
        
        try:
            if not self.model_manager:
                return timeline
            
            # Prepare feature vector for temporal ML prediction
            feature_vector = {
                'max_failure_ratio': max_ratio,
                'sigma_1_mpa': stress_tensor.get('sigma_1', 0),
                'sigma_2_mpa': stress_tensor.get('sigma_2', 0),
                'sigma_3_mpa': stress_tensor.get('sigma_3', 0),
                'thickness_km': cap_rock_props.thickness_km,
                'youngs_modulus_gpa': cap_rock_props.youngs_modulus_gpa,
                'tensile_strength_mpa': cap_rock_props.tensile_strength_mpa,
                'thermal_conductivity': cap_rock_props.thermal_conductivity,
                'porosity': cap_rock_props.porosity,
                'latitude': coords[0] if coords and len(coords) > 0 else 0,
                'longitude': coords[1] if coords and len(coords) > 1 else 0
            }
            
            # Use temporal progression prediction model
            temporal_model = await self.model_manager.get_model('cap_rock_temporal_progression_v3')
            if temporal_model:
                predictions = await temporal_model.predict(feature_vector)
                
                if predictions and 'timeline' in predictions:
                    for stage, prediction in predictions['timeline'].items():
                        if prediction.get('confidence', 0) > 0.6:
                            timeline[stage] = prediction.get('time_years', 1000)
            
            # Use ensemble temporal model for cross-validation
            ensemble_model = await self.model_manager.get_model('cap_rock_failure_timeline_ensemble')
            if ensemble_model:
                ensemble_predictions = await ensemble_model.predict(feature_vector)
                
                if ensemble_predictions and 'stages' in ensemble_predictions:
                    for stage_pred in ensemble_predictions['stages']:
                        stage_name = stage_pred.get('stage', '')
                        time_years = stage_pred.get('predicted_time_years', 1000)
                        confidence = stage_pred.get('confidence', 0)
                        
                        if confidence > 0.7 and stage_name:
                            # Average with existing prediction if available
                            if stage_name in timeline:
                                timeline[stage_name] = (timeline[stage_name] + time_years) / 2
                            else:
                                timeline[stage_name] = time_years
                                
        except Exception as e:
            self.logger.debug(f"ML temporal progression error: {e}")
        
        return timeline
    
    async def _calculate_volcanic_temporal_progression(self, max_ratio: float, stress_tensor: Dict,
                                                     cap_rock_props: CapRockProperties,
                                                     coords: List[float] = None) -> Dict[str, float]:
        """Calculate temporal progression informed by volcanic system dynamics"""
        
        timeline = {}
        
        try:
            if not coords or len(coords) < 2:
                return timeline
            
            # Get volcanic system temporal data
            if self.volcanic_chamber_system:
                volcanic_dynamics = await self.volcanic_chamber_system.get_temporal_dynamics(
                    latitude=coords[0], longitude=coords[1], 
                    forecast_years=1000
                )
                
                if volcanic_dynamics:
                    # Base timeline on volcanic system evolution
                    magma_pressure_evolution = volcanic_dynamics.get('pressure_evolution', {})
                    thermal_evolution = volcanic_dynamics.get('thermal_evolution', {})
                    
                    # Calculate stress-dependent progression with volcanic enhancement
                    base_multiplier = 1.0 / max(max_ratio, 0.1)
                    
                    # Crack initiation (influenced by magma pressure cycles)
                    pressure_acceleration = magma_pressure_evolution.get('acceleration_factor', 1.0)
                    timeline['crack_initiation'] = (50 * base_multiplier) / pressure_acceleration
                    
                    # Crack propagation (enhanced by thermal cycles)
                    thermal_acceleration = thermal_evolution.get('thermal_cycling_factor', 1.0)
                    timeline['crack_propagation'] = (100 * base_multiplier) / thermal_acceleration
                    
                    # Coalescence (chamber geometry dependent)
                    chamber_geometry = volcanic_dynamics.get('chamber_geometry', {})
                    geometry_factor = chamber_geometry.get('instability_factor', 1.0)
                    timeline['coalescence'] = (200 * base_multiplier) / geometry_factor
                    
                    # Ultimate failure (system-wide instability)
                    system_instability = volcanic_dynamics.get('system_instability_factor', 1.0)
                    timeline['ultimate_failure'] = (500 * base_multiplier) / system_instability
                    
            # Enhance with eruption forecaster predictions
            if self.eruption_forecaster:
                eruption_forecast = await self.eruption_forecaster.get_long_term_forecast(
                    latitude=coords[0], longitude=coords[1], years_ahead=1000
                )
                
                if eruption_forecast and 'failure_probability_timeline' in eruption_forecast:
                    prob_timeline = eruption_forecast['failure_probability_timeline']
                    
                    # Adjust timeline based on eruption probability evolution
                    for stage in timeline:
                        if stage in prob_timeline:
                            prob_acceleration = prob_timeline[stage].get('acceleration', 1.0)
                            timeline[stage] = timeline[stage] / prob_acceleration
                            
        except Exception as e:
            self.logger.debug(f"Volcanic temporal progression error: {e}")
        
        return timeline
    
    async def _calculate_physics_based_temporal_progression(self, max_ratio: float, stress_tensor: Dict,
                                                          cap_rock_props: CapRockProperties,
                                                          coords: List[float] = None) -> Dict[str, float]:
        """Calculate temporal progression using physics-based fracture mechanics"""
        
        timeline = {}
        
        try:
            # Calculate characteristic material parameters
            fracture_toughness = await self._estimate_fracture_toughness(cap_rock_props, stress_tensor)
            crack_velocity = await self._estimate_crack_propagation_velocity(stress_tensor, cap_rock_props, coords)
            
            # Physics-based timeline calculations
            sigma_1 = stress_tensor.get('sigma_1', 0) * 1e6  # Convert to Pa
            sigma_effective = max(sigma_1 - cap_rock_props.tensile_strength_mpa * 1e6, 1e6)  # Effective stress
            
            # Crack initiation time (based on subcritical crack growth)
            if 'subcritical_velocity_ms' in crack_velocity:
                v_subcritical = crack_velocity['subcritical_velocity_ms']  # m/s
                initial_crack_size = 0.001  # 1mm initial flaw
                critical_crack_size = (fracture_toughness / (1.12 * sigma_effective))**2 * np.pi if sigma_effective > 0 else 0.01
                
                if v_subcritical > 0 and critical_crack_size > initial_crack_size:
                    initiation_time_seconds = (critical_crack_size - initial_crack_size) / v_subcritical
                    timeline['crack_initiation'] = initiation_time_seconds / (365.25 * 24 * 3600)  # Convert to years
            
            # Crack propagation time (fast crack growth phase)
            if 'lefm_velocity_ms' in crack_velocity:
                v_propagation = crack_velocity['lefm_velocity_ms']  # m/s
                propagation_distance = cap_rock_props.thickness_km * 1000 * 0.1  # 10% of thickness
                
                if v_propagation > 0:
                    propagation_time_seconds = propagation_distance / v_propagation
                    timeline['crack_propagation'] = propagation_time_seconds / (365.25 * 24 * 3600)
            
            # Coalescence time (multiple crack interaction)
            if 'crack_interaction_velocity_ms' in crack_velocity:
                v_coalescence = crack_velocity.get('crack_interaction_velocity_ms', v_propagation * 0.5)
                coalescence_distance = cap_rock_props.thickness_km * 1000 * 0.3
                
                if v_coalescence > 0:
                    coalescence_time_seconds = coalescence_distance / v_coalescence
                    timeline['coalescence'] = coalescence_time_seconds / (365.25 * 24 * 3600)
            
            # Ultimate failure (catastrophic failure)
            if timeline.get('coalescence', 0) > 0:
                # Rapid failure after coalescence
                timeline['ultimate_failure'] = timeline['coalescence'] + 0.1  # 0.1 years after coalescence
            
        except Exception as e:
            self.logger.debug(f"Physics-based temporal progression error: {e}")
        
        return timeline
    
    async def _calculate_database_temporal_progression(self, max_ratio: float, stress_tensor: Dict,
                                                     cap_rock_props: CapRockProperties,
                                                     coords: List[float] = None) -> Dict[str, float]:
        """Use database historical failure data for temporal progression"""
        
        timeline = {}
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            if not coords or len(coords) < 2:
                return timeline
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query historical failure progression data
                history_query = """
                    SELECT 
                        failure_stage, avg(time_to_failure_years) as avg_time,
                        stddev(time_to_failure_years) as std_time,
                        count(*) as sample_size
                    FROM cap_rock_failure_history 
                    WHERE ST_DWithin(
                        location, 
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633),
                        %s
                    )
                    AND max_failure_ratio BETWEEN %s AND %s
                    AND thickness_km BETWEEN %s AND %s
                    GROUP BY failure_stage
                    HAVING count(*) >= 3
                    ORDER BY avg_time;
                """
                
                failure_range = 0.1  # ±10% around current failure ratio
                thickness_range = cap_rock_props.thickness_km * 0.2  # ±20% thickness range
                
                history_data = await db.fetch_all(
                    history_query,
                    coords[1], coords[0],  # lon, lat
                    100000,  # 100km radius for historical data
                    max(max_ratio - failure_range, 0),
                    min(max_ratio + failure_range, 1.0),
                    max(cap_rock_props.thickness_km - thickness_range, 0.1),
                    cap_rock_props.thickness_km + thickness_range
                )
                
                # Build timeline from historical data
                for record in history_data:
                    stage = record['failure_stage']
                    avg_time = record['avg_time']
                    std_time = record.get('std_time', avg_time * 0.3)
                    sample_size = record['sample_size']
                    
                    # Apply confidence adjustment based on sample size
                    confidence_factor = min(sample_size / 10, 1.0)  # More samples = higher confidence
                    adjusted_time = avg_time * (1 + (1 - confidence_factor) * 0.5)  # Conservative adjustment
                    
                    timeline[stage] = adjusted_time
                
                # Query similar geological conditions
                similar_conditions_query = """
                    SELECT 
                        failure_stage, 
                        percentile_cont(0.5) WITHIN GROUP (ORDER BY time_to_failure_years) as median_time
                    FROM cap_rock_failure_history 
                    WHERE rock_type = %s
                    AND youngs_modulus_gpa BETWEEN %s AND %s
                    AND tensile_strength_mpa BETWEEN %s AND %s
                    GROUP BY failure_stage
                    HAVING count(*) >= 5;
                """
                
                modulus_range = cap_rock_props.youngs_modulus_gpa * 0.3
                strength_range = cap_rock_props.tensile_strength_mpa * 0.3
                
                similar_data = await db.fetch_all(
                    similar_conditions_query,
                    cap_rock_props.rock_type if hasattr(cap_rock_props, 'rock_type') else 'granite',
                    max(cap_rock_props.youngs_modulus_gpa - modulus_range, 10),
                    cap_rock_props.youngs_modulus_gpa + modulus_range,
                    max(cap_rock_props.tensile_strength_mpa - strength_range, 1),
                    cap_rock_props.tensile_strength_mpa + strength_range
                )
                
                # Cross-validate with similar geological conditions
                for record in similar_data:
                    stage = record['failure_stage']
                    median_time = record['median_time']
                    
                    if stage in timeline:
                        # Average the two estimates
                        timeline[stage] = (timeline[stage] + median_time) / 2
                    else:
                        timeline[stage] = median_time
                        
        except Exception as e:
            self.logger.debug(f"Database temporal progression error: {e}")
        
        return timeline
    
    def _calculate_enhanced_empirical_timeline(self, max_ratio: float, cap_rock_props: CapRockProperties) -> Dict[str, float]:
        """Enhanced empirical timeline with material property adjustments"""
        
        # Base timeline adjusted for material properties
        base_time_years = 100
        
        # Material-based adjustments
        strength_factor = cap_rock_props.tensile_strength_mpa / 10.0  # Normalize around 10 MPa
        modulus_factor = cap_rock_props.youngs_modulus_gpa / 50.0     # Normalize around 50 GPa
        thickness_factor = cap_rock_props.thickness_km / 2.0         # Normalize around 2 km
        
        # Combined material influence on timeline
        material_modifier = (strength_factor * modulus_factor * thickness_factor) ** 0.5
        adjusted_base_time = base_time_years * material_modifier
        
        # Failure ratio-dependent progression
        if max_ratio < 0.2:
            return {
                'crack_initiation': adjusted_base_time * 20,
                'crack_propagation': adjusted_base_time * 50
            }
        elif max_ratio < 0.4:
            return {
                'crack_initiation': adjusted_base_time * 5,
                'crack_propagation': adjusted_base_time * 10,
                'coalescence': adjusted_base_time * 20
            }
        elif max_ratio < 0.6:
            return {
                'crack_initiation': adjusted_base_time * 2,
                'crack_propagation': adjusted_base_time * 4,
                'coalescence': adjusted_base_time * 8,
                'localized_failure': adjusted_base_time * 15
            }
        elif max_ratio < 0.8:
            return {
                'crack_initiation': adjusted_base_time * 0.5,
                'crack_propagation': adjusted_base_time * 1,
                'coalescence': adjusted_base_time * 2,
                'localized_failure': adjusted_base_time * 4,
                'ultimate_failure': adjusted_base_time * 8
            }
        else:
            return {
                'crack_initiation': adjusted_base_time * 0.1,
                'crack_propagation': adjusted_base_time * 0.2,
                'coalescence': adjusted_base_time * 0.5,
                'localized_failure': adjusted_base_time * 1,
                'ultimate_failure': adjusted_base_time * 2
            }
    
    async def _calculate_comprehensive_temporal_progression(self, max_ratio: float, stress_tensor: Dict,
                                                          cap_rock_props: CapRockProperties, 
                                                          coords: List[float] = None,
                                                          stages: Dict[str, bool] = None) -> Dict[str, float]:
        """
        Comprehensive temporal progression modeling using data integration pipeline,
        historical failure databases, ML ensemble predictions, and volcanic forecasting.
        """
        
        try:
            timeline_components = {}
            
            # 1. Data integration pipeline temporal analysis
            pipeline_timeline = await self._calculate_data_integration_pipeline_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            timeline_components['pipeline'] = pipeline_timeline
            
            # 2. Historical failure database analysis
            historical_timeline = await self._calculate_historical_database_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            timeline_components['historical'] = historical_timeline
            
            # 3. Model manager ensemble predictions
            ml_ensemble_timeline = await self._calculate_model_manager_ensemble_progression(
                max_ratio, stress_tensor, cap_rock_props, coords, stages
            )
            timeline_components['ml_ensemble'] = ml_ensemble_timeline
            
            # 4. Volcano modules integration
            volcano_timeline = await self._calculate_volcano_modules_progression(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            timeline_components['volcano_modules'] = volcano_timeline
            
            # 5. Multi-scale temporal coupling analysis
            multiscale_timeline = await self._calculate_multiscale_temporal_coupling(
                max_ratio, stress_tensor, cap_rock_props, coords
            )
            timeline_components['multiscale'] = multiscale_timeline
            
            # Ensemble temporal progression synthesis
            comprehensive_timeline = self._synthesize_temporal_ensemble(
                timeline_components, max_ratio, cap_rock_props
            )
            
            # Apply uncertainty quantification
            timeline_with_uncertainty = self._apply_temporal_uncertainty_quantification(
                comprehensive_timeline, timeline_components
            )
            
            return {
                'timeline': timeline_with_uncertainty,
                'component_contributions': {k: v.get('confidence', 0.5) for k, v in timeline_components.items()},
                'dominant_component': self._identify_dominant_temporal_component(timeline_components),
                'uncertainty_bounds': self._calculate_temporal_uncertainty_bounds(timeline_components),
                'confidence': self._calculate_ensemble_temporal_confidence(timeline_components),
                'data_sources': [comp.get('data_source', 'physics_based') for comp in timeline_components.values()]
            }
            
        except Exception as e:
            self.logger.warning(f"Comprehensive temporal progression analysis failed: {e}")
            # Enhanced fallback with existing advanced method
            return await self._calculate_advanced_temporal_progression(max_ratio, stress_tensor, cap_rock_props, coords)
    
    async def _calculate_data_integration_pipeline_progression(self, max_ratio: float, stress_tensor: Dict,
                                                             cap_rock_props: CapRockProperties,
                                                             coords: List[float] = None) -> Dict[str, Any]:
        """Calculate temporal progression using comprehensive data integration pipeline"""
        
        try:
            # Import data integration pipeline
            from .data_integration_pipeline import DataIntegrationPipeline, GeologicalDataProcessor
            
            # Initialize pipeline for temporal analysis
            pipeline = DataIntegrationPipeline()
            processor = GeologicalDataProcessor()
            
            # Process multi-source temporal data
            temporal_features = {
                'failure_ratio': max_ratio,
                'stress_state': stress_tensor,
                'rock_properties': cap_rock_props.__dict__,
                'coordinates': coords,
                'temporal_window_years': 1000
            }
            
            # Multi-layer geological data processing
            processed_data = await processor.process_temporal_geological_layers(
                features=temporal_features,
                layers=['seismic_history', 'deformation_trends', 'thermal_evolution',
                       'stress_evolution', 'fluid_pressure_history', 'damage_accumulation']
            )
            
            # Cross-layer temporal analysis
            temporal_correlations = await processor.analyze_temporal_correlations(processed_data)
            
            # Pipeline-based temporal prediction
            timeline_prediction = await pipeline.predict_failure_timeline(
                processed_data, temporal_correlations
            )
            
            return {
                'timeline': timeline_prediction.get('timeline', {}),
                'confidence': timeline_prediction.get('confidence', 0.7),
                'data_source': 'data_integration_pipeline',
                'processing_quality': processed_data.get('quality_score', 0.8),
                'cross_layer_correlations': temporal_correlations
            }
            
        except Exception as e:
            self.logger.warning(f"Data integration pipeline temporal progression failed: {e}")
            return {
                'timeline': {},
                'confidence': 0.3,
                'data_source': 'pipeline_fallback',
                'processing_quality': 0.3,
                'cross_layer_correlations': {}
            }
    
    async def _calculate_historical_database_progression(self, max_ratio: float, stress_tensor: Dict,
                                                       cap_rock_props: CapRockProperties,
                                                       coords: List[float] = None) -> Dict[str, Any]:
        """Calculate temporal progression using comprehensive historical failure databases"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Multi-scale historical analysis
                timeline = {}
                confidence_scores = {}
                
                # Global historical patterns
                global_query = """
                    SELECT 
                        failure_stage,
                        percentile_cont(0.25) WITHIN GROUP (ORDER BY time_to_failure_years) as p25,
                        percentile_cont(0.5) WITHIN GROUP (ORDER BY time_to_failure_years) as median,
                        percentile_cont(0.75) WITHIN GROUP (ORDER BY time_to_failure_years) as p75,
                        count(*) as sample_size,
                        stddev(time_to_failure_years) as std_dev
                    FROM global_cap_rock_failure_database 
                    WHERE failure_ratio BETWEEN %s AND %s
                    AND rock_classification = %s
                    GROUP BY failure_stage
                    HAVING count(*) >= 10
                    ORDER BY median;
                """
                
                rock_classification = await self._comprehensive_petrological_database_classification(cap_rock_props)
                failure_range = 0.15
                
                global_data = await db.fetch_all(
                    global_query,
                    max(max_ratio - failure_range, 0),
                    min(max_ratio + failure_range, 1.0),
                    rock_classification
                )
                
                # Process global historical data
                for record in global_data:
                    stage = record['failure_stage']
                    median_time = record['median']
                    sample_size = record['sample_size']
                    std_dev = record.get('std_dev', median_time * 0.3)
                    
                    # Statistical confidence based on sample size
                    confidence = min(1.0, np.log(sample_size) / np.log(100))
                    
                    timeline[stage] = median_time
                    confidence_scores[stage] = confidence
                
                # Regional historical patterns (if coordinates available)
                if coords:
                    regional_timeline = await self._query_regional_historical_patterns(
                        db, coords, max_ratio, cap_rock_props
                    )
                    
                    # Combine global and regional data
                    for stage, regional_time in regional_timeline.items():
                        if stage in timeline:
                            # Weight by confidence
                            global_conf = confidence_scores.get(stage, 0.5)
                            regional_conf = 0.8  # Assume higher confidence for regional data
                            
                            combined_time = (timeline[stage] * global_conf + regional_time * regional_conf) / (global_conf + regional_conf)
                            timeline[stage] = combined_time
                            confidence_scores[stage] = min(1.0, global_conf + regional_conf * 0.5)
                        else:
                            timeline[stage] = regional_time
                            confidence_scores[stage] = 0.6
                
                # Tectonic setting adjustment
                tectonic_adjustment = await self._calculate_tectonic_historical_adjustment(
                    db, coords, timeline
                )
                
                for stage in timeline:
                    timeline[stage] *= tectonic_adjustment.get(stage, 1.0)
                
                return {
                    'timeline': timeline,
                    'confidence': np.mean(list(confidence_scores.values())) if confidence_scores else 0.4,
                    'data_source': 'historical_database',
                    'sample_sizes': {stage: rec['sample_size'] for rec in global_data for stage in [rec['failure_stage']]},
                    'tectonic_adjustment': tectonic_adjustment
                }
                
        except Exception as e:
            self.logger.warning(f"Historical database temporal progression failed: {e}")
            return {
                'timeline': {},
                'confidence': 0.2,
                'data_source': 'historical_fallback',
                'sample_sizes': {},
                'tectonic_adjustment': {}
            }
    
    async def _calculate_model_manager_ensemble_progression(self, max_ratio: float, stress_tensor: Dict,
                                                          cap_rock_props: CapRockProperties,
                                                          coords: List[float] = None,
                                                          stages: Dict[str, bool] = None) -> Dict[str, Any]:
        """Calculate temporal progression using model manager ensemble predictions"""
        
        try:
            if not hasattr(self, 'model_manager') or not self.model_manager:
                from .model_manager import ModelManager
                self.model_manager = ModelManager()
            
            # Prepare comprehensive feature vector
            features = {
                'failure_ratio': max_ratio,
                'principal_stress_1': stress_tensor.get('principal_stress_1_mpa', 50),
                'principal_stress_2': stress_tensor.get('principal_stress_2_mpa', 30),
                'principal_stress_3': stress_tensor.get('principal_stress_3_mpa', 20),
                'deviatoric_stress': stress_tensor.get('principal_stress_1_mpa', 50) - stress_tensor.get('principal_stress_3_mpa', 20),
                'mean_stress': (stress_tensor.get('principal_stress_1_mpa', 50) + 
                              stress_tensor.get('principal_stress_2_mpa', 30) + 
                              stress_tensor.get('principal_stress_3_mpa', 20)) / 3,
                'rock_strength': cap_rock_props.tensile_strength_mpa,
                'rock_modulus': cap_rock_props.youngs_modulus_gpa,
                'rock_density': cap_rock_props.density_kg_m3,
                'rock_porosity': cap_rock_props.porosity,
                'rock_permeability': getattr(cap_rock_props, 'permeability_m2', 1e-16),
                'thickness': cap_rock_props.thickness_km,
                'latitude': coords[0] if coords else 0.0,
                'longitude': coords[1] if coords else 0.0,
                'stage_crack_initiation': stages.get('crack_initiation', False) if stages else False,
                'stage_crack_propagation': stages.get('crack_propagation', False) if stages else False,
                'stage_coalescence': stages.get('coalescence', False) if stages else False,
                'stage_ultimate_failure': stages.get('ultimate_failure', False) if stages else False
            }
            
            # Ensemble model predictions
            ensemble_models = [
                'temporal_progression_rf_v3',
                'failure_timeline_xgboost_v2',
                'temporal_neural_network_v4',
                'temporal_svm_ensemble_v2',
                'geological_temporal_lstm_v3'
            ]
            
            timeline_predictions = []
            model_confidences = []
            
            for model_name in ensemble_models:
                try:
                    if await self.model_manager.model_exists(model_name):
                        prediction = await self.model_manager.predict(model_name, features)
                        
                        if isinstance(prediction, dict) and 'timeline' in prediction:
                            timeline_predictions.append(prediction['timeline'])
                            model_confidences.append(prediction.get('confidence', 0.7))
                        elif isinstance(prediction, dict):
                            # Convert single-stage prediction to timeline format
                            timeline_predictions.append(prediction)
                            model_confidences.append(0.6)
                            
                except Exception as e:
                    self.logger.debug(f"Model {model_name} prediction failed: {e}")
                    continue
            
            # Ensemble combination using weighted averaging
            if timeline_predictions:
                ensemble_timeline = self._combine_temporal_ensemble_predictions(
                    timeline_predictions, model_confidences
                )
                
                # Uncertainty quantification
                prediction_variance = self._calculate_temporal_prediction_variance(timeline_predictions)
                
                return {
                    'timeline': ensemble_timeline,
                    'confidence': np.mean(model_confidences) if model_confidences else 0.5,
                    'data_source': 'model_manager_ensemble',
                    'models_used': len(timeline_predictions),
                    'prediction_variance': prediction_variance,
                    'ensemble_diversity': self._calculate_ensemble_diversity(timeline_predictions)
                }
            else:
                # Fallback to single model if available
                return await self._single_model_temporal_fallback(features)
                
        except Exception as e:
            self.logger.warning(f"Model manager ensemble temporal progression failed: {e}")
            return {
                'timeline': {},
                'confidence': 0.3,
                'data_source': 'ml_ensemble_fallback',
                'models_used': 0,
                'prediction_variance': {},
                'ensemble_diversity': 0.0
            }
    
    async def _calculate_volcano_modules_progression(self, max_ratio: float, stress_tensor: Dict,
                                                   cap_rock_props: CapRockProperties,
                                                   coords: List[float] = None) -> Dict[str, Any]:
        """Calculate temporal progression using volcano modules integration"""
        
        try:
            if not coords:
                return {'timeline': {}, 'confidence': 0.1, 'data_source': 'volcano_no_coords'}
            
            # Multi-chamber volcanic system analysis
            from .volcanic_multi_chamber import VolcanicMultiChamberSystem
            from .volcano_seismic_analysis import VolcanicSeismicAnalyzer
            from .volcanic_deformation_model import VolcanicDeformationModel
            
            volcano_system = VolcanicMultiChamberSystem()
            seismic_analyzer = VolcanicSeismicAnalyzer()
            deformation_model = VolcanicDeformationModel()
            
            # Comprehensive volcanic temporal analysis
            volcanic_timeline = {}
            
            # 1. Magma chamber evolution timeline
            chamber_evolution = await volcano_system.calculate_chamber_evolution_timeline(
                latitude=coords[0], longitude=coords[1],
                cap_rock_properties=cap_rock_props,
                stress_state=stress_tensor,
                forecast_years=1000
            )
            
            if chamber_evolution.get('temporal_stages'):
                for stage, timing in chamber_evolution['temporal_stages'].items():
                    if 'failure' in stage.lower() or 'breach' in stage.lower():
                        failure_stage = self._map_volcanic_to_failure_stage(stage)
                        if failure_stage:
                            volcanic_timeline[failure_stage] = timing
            
            # 2. Seismic precursor timeline
            seismic_timeline = await seismic_analyzer.calculate_seismic_precursor_timeline(
                location=coords,
                cap_rock_properties=cap_rock_props,
                magma_chamber_data=chamber_evolution
            )
            
            # Integrate seismic precursor timing
            for precursor, timing in seismic_timeline.items():
                failure_stage = self._map_seismic_to_failure_stage(precursor)
                if failure_stage:
                    if failure_stage in volcanic_timeline:
                        # Take the minimum (most conservative) timeline
                        volcanic_timeline[failure_stage] = min(volcanic_timeline[failure_stage], timing)
                    else:
                        volcanic_timeline[failure_stage] = timing
            
            # 3. Deformation-based temporal analysis
            deformation_timeline = await deformation_model.calculate_deformation_failure_timeline(
                location=coords,
                stress_tensor=stress_tensor,
                cap_rock_props=cap_rock_props,
                chamber_evolution=chamber_evolution
            )
            
            # Integrate deformation timeline
            for stage, timing in deformation_timeline.items():
                if stage in volcanic_timeline:
                    volcanic_timeline[stage] = min(volcanic_timeline[stage], timing)
                else:
                    volcanic_timeline[stage] = timing
            
            # Calculate volcanic system confidence
            confidence = self._calculate_volcanic_temporal_confidence(
                chamber_evolution, seismic_timeline, deformation_timeline
            )
            
            return {
                'timeline': volcanic_timeline,
                'confidence': confidence,
                'data_source': 'volcano_modules',
                'chamber_evolution_quality': chamber_evolution.get('confidence', 0.5),
                'seismic_data_quality': seismic_timeline.get('data_quality', 0.5),
                'deformation_model_quality': deformation_timeline.get('model_confidence', 0.5)
            }
            
        except Exception as e:
            self.logger.warning(f"Volcano modules temporal progression failed: {e}")
            return {
                'timeline': {},
                'confidence': 0.2,
                'data_source': 'volcano_modules_fallback',
                'chamber_evolution_quality': 0.2,
                'seismic_data_quality': 0.2,
                'deformation_model_quality': 0.2
            }
    
    def _synthesize_temporal_ensemble(self, timeline_components: Dict[str, Dict], 
                                    max_ratio: float, cap_rock_props: CapRockProperties) -> Dict[str, float]:
        """Synthesize ensemble temporal progression from multiple components"""
        
        try:
            # Weight components by confidence and data quality
            component_weights = {}
            total_weight = 0.0
            
            for component, data in timeline_components.items():
                confidence = data.get('confidence', 0.3)
                data_quality = data.get('processing_quality', data.get('data_quality', 0.5))
                
                # Component-specific weight adjustments
                base_weights = {
                    'pipeline': 0.25,
                    'historical': 0.30,
                    'ml_ensemble': 0.25,
                    'volcano_modules': 0.15,
                    'multiscale': 0.05
                }
                
                weight = base_weights.get(component, 0.2) * confidence * data_quality
                component_weights[component] = weight
                total_weight += weight
            
            # Normalize weights
            if total_weight > 0:
                for component in component_weights:
                    component_weights[component] /= total_weight
            
            # Synthesize timelines using weighted ensemble
            synthesized_timeline = {}
            stage_weights = {}
            
            for component, data in timeline_components.items():
                timeline = data.get('timeline', {})
                component_weight = component_weights.get(component, 0.0)
                
                for stage, time_years in timeline.items():
                    if stage not in synthesized_timeline:
                        synthesized_timeline[stage] = 0.0
                        stage_weights[stage] = 0.0
                    
                    synthesized_timeline[stage] += time_years * component_weight
                    stage_weights[stage] += component_weight
            
            # Normalize by accumulated weights
            for stage in synthesized_timeline:
                if stage_weights[stage] > 0:
                    synthesized_timeline[stage] /= stage_weights[stage]
            
            # Apply consistency constraints
            synthesized_timeline = self._apply_temporal_consistency_constraints(synthesized_timeline)
            
            return synthesized_timeline
            
        except Exception as e:
            self.logger.warning(f"Temporal ensemble synthesis failed: {e}")
            # Fallback to simple averaging
            all_timelines = []
            for data in timeline_components.values():
                timeline = data.get('timeline', {})
                if timeline:
                    all_timelines.append(timeline)
            
            if all_timelines:
                return self._simple_timeline_average(all_timelines)
            else:
                return {}
    
    async def _apply_volcanic_acceleration_factors(self, timeline: Dict[str, float], coords: List[float] = None) -> Dict[str, float]:
        """Apply volcanic system acceleration factors to timeline"""
        
        try:
            if not coords or not self.volcanic_chamber_system:
                return timeline
            
            # Get volcanic system acceleration factors
            volcanic_factors = await self.volcanic_chamber_system.get_acceleration_factors(
                latitude=coords[0], longitude=coords[1]
            )
            
            if volcanic_factors:
                # Apply stage-specific acceleration
                accelerated_timeline = {}
                for stage, time_years in timeline.items():
                    acceleration = volcanic_factors.get(f"{stage}_acceleration", 1.0)
                    # Also apply general volcanic acceleration
                    general_acceleration = volcanic_factors.get('general_acceleration', 1.0)
                    total_acceleration = acceleration * general_acceleration
                    
                    accelerated_timeline[stage] = time_years / max(total_acceleration, 0.1)
                
                return accelerated_timeline
                
        except Exception as e:
            self.logger.debug(f"Volcanic acceleration factor application error: {e}")
        
        return timeline
    
    def _calculate_failure_mode_transitions(self, stress_tensor: Dict, cap_rock_props: CapRockProperties) -> Dict:
        """Calculate potential failure mode transitions"""
        
        sigma_1 = stress_tensor.get('sigma_1', 0)
        sigma_3 = stress_tensor.get('sigma_3', 0)
        temperature = stress_tensor.get('temperature_c', 200)
        
        transitions = {}
        
        # Brittle to ductile transition
        if temperature > 300:  # Temperature threshold
            transitions['brittle_to_ductile_probability'] = min(1.0, (temperature - 300) / 200)
        else:
            transitions['brittle_to_ductile_probability'] = 0.0
        
        # Tensile to shear transition
        if abs(sigma_3) > cap_rock_props.tensile_strength_mpa:
            transitions['tensile_to_shear_probability'] = 0.8
        else:
            transitions['tensile_to_shear_probability'] = 0.2
        
        # Thermal spalling transition
        if temperature > 400:
            transitions['thermal_spalling_probability'] = min(1.0, (temperature - 400) / 200)
        else:
            transitions['thermal_spalling_probability'] = 0.0
        
        return transitions
    
    async def _estimate_crack_propagation_velocity(self, stress_tensor: Dict, cap_rock_props: CapRockProperties,
                                                  coords: List[float] = None) -> Dict[str, float]:
        """Advanced crack propagation velocity estimation with fracture mechanics and volcanic system integration"""
        
        try:
            # Multi-mode velocity calculation
            velocities = {}
            
            # Primary: Linear Elastic Fracture Mechanics (LEFM) approach
            lefm_velocity = await self._calculate_lefm_crack_velocity(
                stress_tensor, cap_rock_props, coords
            )
            
            # Secondary: Thermodynamically-enhanced velocity
            thermo_velocity = await self._calculate_thermodynamic_crack_velocity(
                stress_tensor, cap_rock_props, coords
            )
            
            # Tertiary: Subcritical crack growth velocity
            subcritical_velocity = await self._calculate_subcritical_crack_velocity(
                stress_tensor, cap_rock_props, coords
            )
            
            # Quaternary: Volatile-influenced crack velocity
            volatile_velocity = await self._calculate_volatile_influenced_velocity(
                stress_tensor, cap_rock_props, coords
            )
            
            # Select dominant velocity mechanism
            dominant_velocity = self._select_dominant_velocity_mechanism(
                lefm_velocity, thermo_velocity, subcritical_velocity, volatile_velocity,
                stress_tensor, cap_rock_props
            )
            
            # Apply environmental corrections
            corrected_velocity = await self._apply_environmental_corrections(
                dominant_velocity, stress_tensor, cap_rock_props, coords
            )
            
            # Calculate velocity bounds and uncertainty
            velocity_analysis = self._calculate_velocity_uncertainty(
                corrected_velocity, stress_tensor, cap_rock_props
            )
            
            return {
                'propagation_velocity_m_s': corrected_velocity['velocity'],
                'velocity_mechanism': corrected_velocity['mechanism'],
                'lefm_velocity': lefm_velocity.get('velocity', 0),
                'thermodynamic_velocity': thermo_velocity.get('velocity', 0),
                'subcritical_velocity': subcritical_velocity.get('velocity', 0),
                'volatile_velocity': volatile_velocity.get('velocity', 0),
                'velocity_bounds': velocity_analysis,
                'crack_type': corrected_velocity.get('crack_type', 'mixed_mode'),
                'growth_regime': corrected_velocity.get('growth_regime', 'subcritical'),
                'environmental_factors': corrected_velocity.get('environmental_factors', {})
            }
            
        except Exception as e:
            self.logger.error(f"Advanced crack velocity estimation failed: {e}")
            return await self._fallback_crack_velocity_calculation(stress_tensor, cap_rock_props)
    
    async def _calculate_lefm_crack_velocity(self, stress_tensor: Dict, cap_rock_props: CapRockProperties,
                                            coords: List[float] = None) -> Dict[str, float]:
        """Calculate crack velocity using Linear Elastic Fracture Mechanics"""
        
        try:
            # Material properties
            E = cap_rock_props.elastic_modulus_gpa * 1e9  # Pa
            nu = cap_rock_props.poisson_ratio
            rho = await self._estimate_advanced_rock_density(cap_rock_props)  # kg/m³
            
            # Fracture toughness estimation
            KIc = await self._estimate_advanced_fracture_toughness(cap_rock_props, stress_tensor)  # Pa√m
            
            # Stress intensity factor calculation
            stress_intensity_factors = await self._calculate_stress_intensity_factors(
                stress_tensor, cap_rock_props, coords
            )
            
            KI = stress_intensity_factors['mode_I']  # Mode I (opening)
            KII = stress_intensity_factors['mode_II']  # Mode II (sliding)
            KIII = stress_intensity_factors['mode_III']  # Mode III (tearing)
            
            # Effective stress intensity factor
            K_eff = np.sqrt(KI**2 + KII**2 + KIII**2)
            
            # Critical velocity (Rayleigh wave speed)
            c_R = np.sqrt(E / (2 * rho * (1 + nu))) * np.sqrt(
                (2 - 2*nu) / (2 - nu)
            )  # Rayleigh wave velocity
            
            # Velocity based on stress intensity ratio
            if K_eff >= KIc:
                # Dynamic fracture regime
                K_ratio = K_eff / KIc
                velocity = c_R * (1 - 1/K_ratio) if K_ratio > 1 else 0
                growth_regime = 'dynamic'
            else:
                # Subcritical growth
                velocity = c_R * 0.01 * (K_eff / KIc)**3  # Paris law approximation
                growth_regime = 'subcritical'
            
            # Apply crack geometry corrections
            crack_geometry = self._determine_crack_geometry(stress_tensor, cap_rock_props)
            geometry_correction = self._get_geometry_correction_factor(crack_geometry)
            velocity *= geometry_correction
            
            return {
                'velocity': velocity,
                'mechanism': 'lefm',
                'stress_intensity_factor': K_eff,
                'fracture_toughness': KIc,
                'critical_velocity': c_R,
                'growth_regime': growth_regime,
                'crack_geometry': crack_geometry,
                'mode_I_ki': KI,
                'mode_II_ki': KII,
                'mode_III_ki': KIII
            }
            
        except Exception as e:
            self.logger.error(f"LEFM crack velocity calculation failed: {e}")
            return {'velocity': 0, 'mechanism': 'lefm_failed'}
    
    async def _estimate_advanced_rock_density(self, cap_rock_props: CapRockProperties, 
                                              coords: List[float] = None,
                                              stress_state = None) -> float:
        """Advanced rock density modeling using database integration and volcanic effects"""
        
        try:
            # Primary: Database-driven density characterization
            database_density = await self._get_database_rock_density(cap_rock_props, coords, stress_state)
            
            # Secondary: ML-predicted density variations
            ml_density = await self._get_ml_predicted_density(cap_rock_props, coords, stress_state)
            
            # Tertiary: Volcanic system-enhanced density analysis
            volcanic_density = await self._get_volcanic_enhanced_density(cap_rock_props, coords, stress_state)
            
            # Quaternary: Physics-based multi-phase density modeling
            physics_density = await self._get_physics_based_density(cap_rock_props, coords, stress_state)
            
            # Ensemble density estimation
            density_estimates = []
            if database_density: density_estimates.append(('database', database_density, 0.9))
            if ml_density: density_estimates.append(('ml_prediction', ml_density, 0.8))
            if volcanic_density: density_estimates.append(('volcanic_enhanced', volcanic_density, 0.85))
            if physics_density: density_estimates.append(('physics_based', physics_density, 0.75))
            
            if not density_estimates:
                # Enhanced empirical fallback
                return self._calculate_enhanced_empirical_density(cap_rock_props, coords, stress_state)
            
            # Weighted ensemble of density estimates
            total_weight = sum(weight for _, _, weight in density_estimates)
            weighted_density = sum(density * weight for _, density, weight in density_estimates) / total_weight
            
            # Apply uncertainty bounds
            uncertainty_factor = 1.0 - (len(density_estimates) * 0.05)  # Lower uncertainty with more estimates
            density_range = weighted_density * 0.1 * uncertainty_factor  # ±10% uncertainty
            
            # Return conservative estimate (slightly higher for structural analysis)
            final_density = weighted_density + density_range * 0.3
            
            self.logger.debug(f"Advanced rock density: {final_density:.0f} kg/m³ (from {len(density_estimates)} methods)")
            return final_density
            
        except Exception as e:
            self.logger.error(f"Advanced density estimation failed: {e}")
            return self._calculate_enhanced_empirical_density(cap_rock_props, coords, stress_state)
    
    async def _get_database_rock_density(self, cap_rock_props: CapRockProperties,
                                        coords: List[float] = None,
                                        stress_state = None) -> Optional[float]:
        """Get rock density from geological database"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            # Convert coordinates to geographic if available
            lat = stress_state.latitude if stress_state and hasattr(stress_state, 'latitude') else 0
            lon = stress_state.longitude if stress_state and hasattr(stress_state, 'longitude') else 0
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query density measurements from similar rock types
                density_query = """
                    SELECT 
                        bulk_density_kg_m3, porosity, temperature_c, pressure_mpa,
                        lithology, alteration_degree,
                        ST_Distance(
                            geom, 
                            ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633)
                        ) as distance_m
                    FROM rock_density_measurements
                    WHERE ST_DWithin(
                        geom, 
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 32633),
                        %s
                    )
                    AND lithology ILIKE %s
                    AND porosity BETWEEN %s AND %s
                    ORDER BY distance_m, ABS(porosity - %s)
                    LIMIT 15;
                """
                
                lithology_pattern = f"%{cap_rock_props.lithology}%"
                porosity_range = 0.1  # ±10% porosity tolerance
                
                measurements = await db.fetch_all(
                    density_query,
                    lon, lat, lon, lat,  # lon, lat for distance calc and spatial query
                    50000,  # 50km radius
                    lithology_pattern,
                    max(cap_rock_props.porosity - porosity_range, 0),
                    min(cap_rock_props.porosity + porosity_range, 0.8),
                    cap_rock_props.porosity
                )
                
                if measurements:
                    # Weighted average based on similarity
                    total_weight = 0
                    weighted_density = 0
                    
                    for measurement in measurements:
                        # Distance weight
                        distance_weight = 1.0 / (1.0 + measurement['distance_m'] / 10000)  # 10km scale
                        
                        # Porosity similarity weight
                        porosity_diff = abs(measurement['porosity'] - cap_rock_props.porosity)
                        porosity_weight = 1.0 / (1.0 + porosity_diff * 10)
                        
                        # Advanced lithology similarity weight
                        lithology_weight = await self._calculate_advanced_lithology_similarity(
                            cap_rock_props.lithology, measurement['lithology'], 
                            measurement.get('alteration_degree', 0.0), cap_rock_props
                        )
                        
                        # Temperature/pressure similarity if available
                        temp_weight = 1.0
                        if stress_state and hasattr(stress_state, 'temperature_c') and measurement['temperature_c']:
                            temp_diff = abs(measurement['temperature_c'] - stress_state.temperature_c)
                            temp_weight = 1.0 / (1.0 + temp_diff / 100)
                        
                        combined_weight = distance_weight * porosity_weight * lithology_weight * temp_weight
                        total_weight += combined_weight
                        weighted_density += measurement['bulk_density_kg_m3'] * combined_weight
                    
                    if total_weight > 0:
                        return weighted_density / total_weight
                
                # Query regional density statistics
                regional_query = """
                    SELECT 
                        avg(bulk_density_kg_m3) as avg_density,
                        stddev(bulk_density_kg_m3) as std_density
                    FROM rock_density_measurements
                    WHERE lithology ILIKE %s
                    AND porosity BETWEEN %s AND %s;
                """
                
                regional_stats = await db.fetch_one(
                    regional_query,
                    lithology_pattern,
                    max(cap_rock_props.porosity - 0.2, 0),
                    min(cap_rock_props.porosity + 0.2, 0.8)
                )
                
                if regional_stats and regional_stats['avg_density']:
                    return float(regional_stats['avg_density'])
                    
        except Exception as e:
            self.logger.debug(f"Database density query error: {e}")
        
        return None
    
    async def _calculate_advanced_lithology_similarity(self, lithology1: str, lithology2: str,
                                                     alteration_degree: float = 0.0,
                                                     cap_rock_props: CapRockProperties = None) -> float:
        """
        Calculate advanced lithology similarity weight using geological relationships,
        mineral composition, and physical property similarities
        """
        try:
            # Normalize lithology names
            lithology1_norm = lithology1.lower().strip()
            lithology2_norm = lithology2.lower().strip()
            
            # Exact match gets maximum weight
            if lithology1_norm == lithology2_norm:
                return 1.0
                
            # Database-driven lithological similarity matrix
            database_similarity = await self._get_database_lithology_similarity(lithology1_norm, lithology2_norm)
            
            # Mineral composition similarity
            mineral_similarity = await self._calculate_mineral_composition_similarity(lithology1_norm, lithology2_norm)
            
            # Physical property-based similarity
            physical_similarity = await self._calculate_physical_property_similarity(lithology1_norm, lithology2_norm, cap_rock_props)
            
            # Geological formation similarity
            formation_similarity = await self._calculate_formation_context_similarity(lithology1_norm, lithology2_norm)
            
            # Alteration effect adjustment
            alteration_adjustment = self._calculate_alteration_similarity_adjustment(alteration_degree)
            
            # Weighted ensemble similarity
            similarities = []
            if database_similarity is not None: similarities.append(('database', database_similarity, 0.35))
            if mineral_similarity is not None: similarities.append(('mineral', mineral_similarity, 0.25))
            if physical_similarity is not None: similarities.append(('physical', physical_similarity, 0.25))
            if formation_similarity is not None: similarities.append(('formation', formation_similarity, 0.15))
            
            if similarities:
                total_weight = sum(weight for _, _, weight in similarities)
                weighted_similarity = sum(sim * weight for _, sim, weight in similarities) / total_weight
                
                # Apply alteration adjustment
                final_similarity = weighted_similarity * alteration_adjustment
                
                # Ensure similarity is within reasonable bounds [0.1, 1.0]
                return max(0.1, min(1.0, final_similarity))
            
            # Enhanced empirical fallback with geological relationships
            return self._calculate_empirical_lithology_similarity(lithology1_norm, lithology2_norm, alteration_degree)
            
        except Exception as e:
            self.logger.debug(f"Advanced lithology similarity calculation failed: {e}")
            # Conservative fallback
            return 0.7 if lithology1.lower() in lithology2.lower() or lithology2.lower() in lithology1.lower() else 0.5
    
    async def _get_database_lithology_similarity(self, lithology1: str, lithology2: str) -> Optional[float]:
        """Get lithology similarity from geological database"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query lithological similarity matrix
                similarity_query = """
                    SELECT similarity_coefficient
                    FROM lithology_similarity_matrix
                    WHERE (lithology_1 ILIKE %s AND lithology_2 ILIKE %s)
                    OR (lithology_1 ILIKE %s AND lithology_2 ILIKE %s)
                    LIMIT 1;
                """
                
                result = await db.fetch_one(similarity_query, lithology1, lithology2, lithology2, lithology1)
                
                if result and result['similarity_coefficient'] is not None:
                    return float(result['similarity_coefficient'])
                
                # Check for parent-child geological relationships
                relationship_query = """
                    SELECT relationship_strength
                    FROM lithology_relationships
                    WHERE (parent_lithology ILIKE %s AND child_lithology ILIKE %s)
                    OR (parent_lithology ILIKE %s AND child_lithology ILIKE %s)
                    ORDER BY relationship_strength DESC
                    LIMIT 1;
                """
                
                rel_result = await db.fetch_one(relationship_query, lithology1, lithology2, lithology2, lithology1)
                
                if rel_result and rel_result['relationship_strength'] is not None:
                    return float(rel_result['relationship_strength'])
                    
        except Exception as e:
            self.logger.debug(f"Database lithology similarity query error: {e}")
        
        return None
    
    async def _calculate_mineral_composition_similarity(self, lithology1: str, lithology2: str) -> Optional[float]:
        """Calculate similarity based on mineral composition"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Get mineral compositions for both lithologies
                composition_query = """
                    SELECT mineral_name, percentage
                    FROM rock_mineral_compositions
                    WHERE lithology ILIKE %s
                    ORDER BY percentage DESC;
                """
                
                comp1 = await db.fetch_all(composition_query, lithology1)
                comp2 = await db.fetch_all(composition_query, lithology2)
                
                if not comp1 or not comp2:
                    return None
                
                # Create mineral dictionaries
                minerals1 = {row['mineral_name'].lower(): row['percentage'] for row in comp1}
                minerals2 = {row['mineral_name'].lower(): row['percentage'] for row in comp2}
                
                # Calculate Jaccard similarity for mineral presence
                all_minerals = set(minerals1.keys()) | set(minerals2.keys())
                common_minerals = set(minerals1.keys()) & set(minerals2.keys())
                
                jaccard_similarity = len(common_minerals) / len(all_minerals) if all_minerals else 0
                
                # Calculate weighted compositional similarity for common minerals
                composition_similarity = 0
                total_weight = 0
                
                for mineral in common_minerals:
                    pct1 = minerals1.get(mineral, 0)
                    pct2 = minerals2.get(mineral, 0)
                    weight = (pct1 + pct2) / 2  # Average percentage as weight
                    
                    # Similarity based on percentage difference
                    pct_similarity = 1.0 - abs(pct1 - pct2) / 100.0
                    
                    composition_similarity += pct_similarity * weight
                    total_weight += weight
                
                if total_weight > 0:
                    composition_similarity /= total_weight
                
                # Combined similarity (70% compositional, 30% presence)
                final_similarity = 0.7 * composition_similarity + 0.3 * jaccard_similarity
                
                return max(0.0, min(1.0, final_similarity))
                
        except Exception as e:
            self.logger.debug(f"Mineral composition similarity calculation error: {e}")
        
        return None
    
    async def _calculate_physical_property_similarity(self, lithology1: str, lithology2: str,
                                                    cap_rock_props: CapRockProperties = None) -> Optional[float]:
        """Calculate similarity based on physical properties"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Get average physical properties for both lithologies
                properties_query = """
                    SELECT 
                        AVG(bulk_density_kg_m3) as avg_density,
                        AVG(youngs_modulus_gpa) as avg_youngs_modulus,
                        AVG(poissons_ratio) as avg_poissons_ratio,
                        AVG(compressive_strength_mpa) as avg_comp_strength,
                        AVG(thermal_conductivity) as avg_thermal_conductivity,
                        AVG(porosity) as avg_porosity
                    FROM rock_physical_properties
                    WHERE lithology ILIKE %s
                    GROUP BY lithology;
                """
                
                props1 = await db.fetch_one(properties_query, lithology1)
                props2 = await db.fetch_one(properties_query, lithology2)
                
                if not props1 or not props2:
                    return None
                
                # Calculate normalized similarities for each property
                similarities = []
                
                # Density similarity (kg/m³)
                if props1['avg_density'] and props2['avg_density']:
                    density_diff = abs(props1['avg_density'] - props2['avg_density'])
                    density_sim = 1.0 - min(density_diff / 1000.0, 1.0)  # Normalize by 1000 kg/m³
                    similarities.append(('density', density_sim, 0.25))
                
                # Young's modulus similarity (GPa)
                if props1['avg_youngs_modulus'] and props2['avg_youngs_modulus']:
                    youngs_diff = abs(props1['avg_youngs_modulus'] - props2['avg_youngs_modulus'])
                    youngs_sim = 1.0 - min(youngs_diff / 50.0, 1.0)  # Normalize by 50 GPa
                    similarities.append(('youngs_modulus', youngs_sim, 0.2))
                
                # Poisson's ratio similarity
                if props1['avg_poissons_ratio'] and props2['avg_poissons_ratio']:
                    poisson_diff = abs(props1['avg_poissons_ratio'] - props2['avg_poissons_ratio'])
                    poisson_sim = 1.0 - min(poisson_diff / 0.3, 1.0)  # Normalize by 0.3
                    similarities.append(('poissons_ratio', poisson_sim, 0.15))
                
                # Compressive strength similarity (MPa)
                if props1['avg_comp_strength'] and props2['avg_comp_strength']:
                    strength_diff = abs(props1['avg_comp_strength'] - props2['avg_comp_strength'])
                    strength_sim = 1.0 - min(strength_diff / 200.0, 1.0)  # Normalize by 200 MPa
                    similarities.append(('compressive_strength', strength_sim, 0.2))
                
                # Thermal conductivity similarity
                if props1['avg_thermal_conductivity'] and props2['avg_thermal_conductivity']:
                    thermal_diff = abs(props1['avg_thermal_conductivity'] - props2['avg_thermal_conductivity'])
                    thermal_sim = 1.0 - min(thermal_diff / 5.0, 1.0)  # Normalize by 5 W/m·K
                    similarities.append(('thermal_conductivity', thermal_sim, 0.1))
                
                # Porosity similarity
                if props1['avg_porosity'] and props2['avg_porosity']:
                    porosity_diff = abs(props1['avg_porosity'] - props2['avg_porosity'])
                    porosity_sim = 1.0 - min(porosity_diff / 0.3, 1.0)  # Normalize by 0.3
                    similarities.append(('porosity', porosity_sim, 0.1))
                
                if similarities:
                    total_weight = sum(weight for _, _, weight in similarities)
                    weighted_similarity = sum(sim * weight for _, sim, weight in similarities) / total_weight
                    return max(0.0, min(1.0, weighted_similarity))
                
        except Exception as e:
            self.logger.debug(f"Physical property similarity calculation error: {e}")
        
        return None
    
    async def _calculate_formation_context_similarity(self, lithology1: str, lithology2: str) -> Optional[float]:
        """Calculate similarity based on geological formation context"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Get formation contexts for both lithologies
                formation_query = """
                    SELECT DISTINCT formation_type, tectonic_setting, age_ma
                    FROM geological_formations
                    WHERE primary_lithology ILIKE %s
                    OR secondary_lithology ILIKE %s;
                """
                
                formations1 = await db.fetch_all(formation_query, lithology1, lithology1)
                formations2 = await db.fetch_all(formation_query, lithology2, lithology2)
                
                if not formations1 or not formations2:
                    return None
                
                # Extract formation characteristics
                types1 = {f['formation_type'] for f in formations1 if f['formation_type']}
                types2 = {f['formation_type'] for f in formations2 if f['formation_type']}
                
                settings1 = {f['tectonic_setting'] for f in formations1 if f['tectonic_setting']}
                settings2 = {f['tectonic_setting'] for f in formations2 if f['tectonic_setting']}
                
                ages1 = [f['age_ma'] for f in formations1 if f['age_ma']]
                ages2 = [f['age_ma'] for f in formations2 if f['age_ma']]
                
                similarities = []
                
                # Formation type similarity
                if types1 and types2:
                    type_intersection = types1 & types2
                    type_union = types1 | types2
                    type_similarity = len(type_intersection) / len(type_union) if type_union else 0
                    similarities.append(('formation_type', type_similarity, 0.4))
                
                # Tectonic setting similarity
                if settings1 and settings2:
                    setting_intersection = settings1 & settings2
                    setting_union = settings1 | settings2
                    setting_similarity = len(setting_intersection) / len(setting_union) if setting_union else 0
                    similarities.append(('tectonic_setting', setting_similarity, 0.4))
                
                # Age similarity
                if ages1 and ages2:
                    avg_age1 = sum(ages1) / len(ages1)
                    avg_age2 = sum(ages2) / len(ages2)
                    age_diff = abs(avg_age1 - avg_age2)
                    # Similarity decreases with age difference, normalized by 100 Ma
                    age_similarity = 1.0 - min(age_diff / 100.0, 1.0)
                    similarities.append(('age', age_similarity, 0.2))
                
                if similarities:
                    total_weight = sum(weight for _, _, weight in similarities)
                    weighted_similarity = sum(sim * weight for _, sim, weight in similarities) / total_weight
                    return max(0.0, min(1.0, weighted_similarity))
                
        except Exception as e:
            self.logger.debug(f"Formation context similarity calculation error: {e}")
        
        return None
    
    def _calculate_alteration_similarity_adjustment(self, alteration_degree: float) -> float:
        """Calculate adjustment factor based on alteration degree"""
        # Higher alteration reduces similarity confidence
        # alteration_degree: 0.0 (fresh) to 1.0 (highly altered)
        
        if alteration_degree <= 0.1:  # Fresh rock
            return 1.0
        elif alteration_degree <= 0.3:  # Slightly altered
            return 0.95
        elif alteration_degree <= 0.5:  # Moderately altered
            return 0.85
        elif alteration_degree <= 0.7:  # Significantly altered
            return 0.75
        else:  # Highly altered
            return 0.65
    
    def _calculate_empirical_lithology_similarity(self, lithology1: str, lithology2: str, alteration_degree: float = 0.0) -> float:
        """Enhanced empirical lithology similarity with geological knowledge"""
        
        # Define lithological groups and their similarities
        igneous_group = ['granite', 'diorite', 'gabbro', 'rhyolite', 'andesite', 'basalt', 'obsidian', 'pumice', 'tuff']
        sedimentary_group = ['sandstone', 'limestone', 'shale', 'mudstone', 'conglomerate', 'breccia', 'siltstone']
        metamorphic_group = ['gneiss', 'schist', 'slate', 'marble', 'quartzite', 'phyllite', 'amphibolite']
        volcanic_group = ['rhyolite', 'andesite', 'basalt', 'obsidian', 'pumice', 'tuff', 'ignimbrite']
        
        # Within-group similarities
        group_similarities = {
            'igneous': 0.8,
            'sedimentary': 0.75,
            'metamorphic': 0.7,
            'volcanic': 0.85
        }
        
        # Between-group similarities
        between_group_similarities = {
            ('igneous', 'volcanic'): 0.6,
            ('igneous', 'metamorphic'): 0.5,
            ('igneous', 'sedimentary'): 0.3,
            ('sedimentary', 'metamorphic'): 0.4,
            ('sedimentary', 'volcanic'): 0.2,
            ('metamorphic', 'volcanic'): 0.4
        }
        
        # Determine groups for both lithologies
        groups1 = []
        groups2 = []
        
        for group_name, group_list in [('igneous', igneous_group), ('sedimentary', sedimentary_group), 
                                      ('metamorphic', metamorphic_group), ('volcanic', volcanic_group)]:
            if any(rock in lithology1 for rock in group_list):
                groups1.append(group_name)
            if any(rock in lithology2 for rock in group_list):
                groups2.append(group_name)
        
        # Calculate similarity
        max_similarity = 0.0
        
        for group1 in groups1:
            for group2 in groups2:
                if group1 == group2:
                    # Same group
                    similarity = group_similarities.get(group1, 0.6)
                else:
                    # Different groups
                    key = tuple(sorted([group1, group2]))
                    similarity = between_group_similarities.get(key, 0.2)
                
                max_similarity = max(max_similarity, similarity)
        
        # If no groups matched, use substring matching with reduced confidence
        if max_similarity == 0.0:
            if lithology1 in lithology2 or lithology2 in lithology1:
                max_similarity = 0.6
            else:
                # Check for common rock-forming words
                common_words = ['quartz', 'feldspar', 'mica', 'calcite', 'clay', 'crystal']
                word_matches = sum(1 for word in common_words if word in lithology1 and word in lithology2)
                max_similarity = 0.3 + 0.1 * word_matches
        
        # Apply alteration adjustment
        alteration_adjustment = self._calculate_alteration_similarity_adjustment(alteration_degree)
        final_similarity = max_similarity * alteration_adjustment
        
        return max(0.1, min(1.0, final_similarity))
    
    async def _get_ml_predicted_density(self, cap_rock_props: CapRockProperties,
                                       coords: List[float] = None,
                                       stress_state = None) -> Optional[float]:
        """Use ML models to predict rock density"""
        
        try:
            if not self.model_manager:
                return None
            
            # Feature vector for ML density prediction
            feature_vector = {
                'lithology_encoded': self._encode_lithology(cap_rock_props.lithology),
                'porosity': cap_rock_props.porosity,
                'youngs_modulus_gpa': cap_rock_props.youngs_modulus_gpa,
                'poissons_ratio': cap_rock_props.poissons_ratio,
                'thermal_conductivity': cap_rock_props.thermal_conductivity,
                'temperature_c': stress_state.temperature_c if stress_state and hasattr(stress_state, 'temperature_c') else 25,
                'pressure_mpa': stress_state.confining_pressure_mpa if stress_state and hasattr(stress_state, 'confining_pressure_mpa') else 0,
                'depth_km': abs(coords[2]) if coords and len(coords) > 2 else 1,
                'x_km': coords[0] if coords and len(coords) > 0 else 0,
                'y_km': coords[1] if coords and len(coords) > 1 else 0
            }
            
            # Use rock density prediction model
            density_model = await self.model_manager.get_model('rock_density_predictor_v2')
            if density_model:
                predictions = await density_model.predict(feature_vector)
                
                if predictions and 'predicted_density_kg_m3' in predictions:
                    predicted_density = predictions['predicted_density_kg_m3']
                    confidence = predictions.get('confidence', 0.5)
                    
                    if confidence > 0.65:
                        return predicted_density
            
            # Use petrophysical ensemble model
            petro_model = await self.model_manager.get_model('petrophysical_properties_ensemble')
            if petro_model:
                petro_predictions = await petro_model.predict(feature_vector)
                
                if petro_predictions and 'bulk_density_kg_m3' in petro_predictions:
                    ensemble_density = petro_predictions['bulk_density_kg_m3']
                    ensemble_confidence = petro_predictions.get('confidence', 0.5)
                    
                    if ensemble_confidence > 0.7:
                        return ensemble_density
                        
        except Exception as e:
            self.logger.debug(f"ML density prediction error: {e}")
        
        return None
    
    async def _get_volcanic_enhanced_density(self, cap_rock_props: CapRockProperties,
                                            coords: List[float] = None,
                                            stress_state = None) -> Optional[float]:
        """Get density enhanced by volcanic system effects"""
        
        try:
            if not self.volcanic_chamber_system:
                return None
            
            # Get volcanic system effects on density
            lat = stress_state.latitude if stress_state and hasattr(stress_state, 'latitude') else 0
            lon = stress_state.longitude if stress_state and hasattr(stress_state, 'longitude') else 0
            depth_km = abs(coords[2]) if coords and len(coords) > 2 else 1
            
            volcanic_effects = await self.volcanic_chamber_system.get_density_modification_factors(
                latitude=lat, longitude=lon, depth_km=depth_km
            )
            
            if volcanic_effects:
                # Base density calculation
                base_density = self._calculate_enhanced_empirical_density(cap_rock_props, coords, stress_state)
                
                # Apply volcanic modification factors
                alteration_factor = volcanic_effects.get('hydrothermal_alteration_density_factor', 1.0)
                vesiculation_factor = volcanic_effects.get('vesiculation_density_reduction', 1.0)
                mineralization_factor = volcanic_effects.get('secondary_mineralization_factor', 1.0)
                thermal_expansion_factor = volcanic_effects.get('thermal_expansion_density_factor', 1.0)
                
                # Combined volcanic density modification
                volcanic_density = (base_density * 
                                  alteration_factor * 
                                  vesiculation_factor * 
                                  mineralization_factor * 
                                  thermal_expansion_factor)
                
                return volcanic_density
                
        except Exception as e:
            self.logger.debug(f"Volcanic density enhancement error: {e}")
        
        return None
    
    async def _get_physics_based_density(self, cap_rock_props: CapRockProperties,
                                        coords: List[float] = None,
                                        stress_state = None) -> Optional[float]:
        """Calculate physics-based density using multi-phase modeling"""
        
        try:
            # Multi-phase density calculation
            
            # 1. Mineral phase densities
            mineral_density = self._calculate_mineral_phase_density(cap_rock_props)
            
            # 2. Fluid phase contribution
            fluid_density = self._calculate_pore_fluid_density(stress_state)
            
            # 3. Porosity structure effects
            porosity = cap_rock_props.porosity
            effective_porosity = self._calculate_effective_porosity(porosity, stress_state)
            
            # 4. Temperature and pressure corrections
            temp_correction = self._calculate_thermal_density_correction(stress_state)
            pressure_correction = self._calculate_pressure_density_correction(stress_state)
            
            # Combined physics-based density
            solid_fraction = 1.0 - effective_porosity
            fluid_fraction = effective_porosity
            
            physics_density = (mineral_density * solid_fraction + 
                             fluid_density * fluid_fraction) * temp_correction * pressure_correction
            
            return physics_density
            
        except Exception as e:
            self.logger.debug(f"Physics-based density calculation error: {e}")
        
        return None
    
    def _calculate_enhanced_empirical_density(self, cap_rock_props: CapRockProperties,
                                             coords: List[float] = None,
                                             stress_state = None) -> float:
        """Enhanced empirical density calculation with advanced corrections"""
        
        # Enhanced lithology densities with alteration states
        lithology_densities = {
            'granite': {'fresh': 2650, 'altered': 2450, 'highly_altered': 2200},
            'rhyolite': {'fresh': 2400, 'altered': 2250, 'highly_altered': 2000},
            'dacite': {'fresh': 2500, 'altered': 2350, 'highly_altered': 2100},
            'andesite': {'fresh': 2600, 'altered': 2450, 'highly_altered': 2200},
            'basalt': {'fresh': 2900, 'altered': 2700, 'highly_altered': 2400},
            'tuff': {'fresh': 2300, 'altered': 2100, 'highly_altered': 1800},
            'volcanic_breccia': {'fresh': 2400, 'altered': 2200, 'highly_altered': 1900}
        }
        
        # Base density from lithology
        lithology = cap_rock_props.lithology.lower()
        
        # Estimate alteration state from temperature and volcanic proximity
        alteration_state = 'fresh'
        if stress_state and hasattr(stress_state, 'temperature_c'):
            temp_c = stress_state.temperature_c
            if temp_c > 200:
                alteration_state = 'highly_altered'
            elif temp_c > 100:
                alteration_state = 'altered'
        
        # Get density for lithology and alteration state
        if lithology in lithology_densities:
            density_dict = lithology_densities[lithology]
            base_density = density_dict.get(alteration_state, density_dict['fresh'])
        else:
            # Default for unknown lithology
            base_density = 2500
        
        # Enhanced porosity correction with pore fluid effects
        porosity = cap_rock_props.porosity
        
        # Pore fluid density (temperature-dependent)
        if stress_state and hasattr(stress_state, 'temperature_c'):
            temp_c = stress_state.temperature_c
            if temp_c > 100:
                # Steam/vapor phase
                fluid_density = 1000 * (1 - (temp_c - 100) / 500)  # Decreasing density with temperature
                fluid_density = max(fluid_density, 50)  # Minimum steam density
            else:
                # Liquid water
                fluid_density = 1000 * (1 - (temp_c - 4) ** 2 / 160000)  # Water density vs temperature
        else:
            fluid_density = 1000  # Default water density
        
        # Pressure effects on fluid density
        if stress_state and hasattr(stress_state, 'confining_pressure_mpa'):
            pressure_mpa = stress_state.confining_pressure_mpa
            fluid_density *= (1 + pressure_mpa * 0.0005)  # Compressibility effect
        
        # Bulk density calculation
        bulk_density = base_density * (1 - porosity) + fluid_density * porosity
        
        # Depth-dependent compaction effects
        if coords and len(coords) > 2:
            depth_km = abs(coords[2])
            compaction_factor = 1 + depth_km * 0.02  # 2% increase per km depth
            bulk_density *= compaction_factor
        
        return bulk_density
    
    async def _estimate_advanced_fracture_toughness(self, cap_rock_props: CapRockProperties, 
                                                   stress_tensor: Dict, coords: List[float] = None) -> float:
        """Advanced fracture toughness analysis using database, ML, and volcanic integration"""
        
        try:
            # Primary: Database-driven fracture toughness characterization
            database_toughness = await self._get_database_fracture_toughness(cap_rock_props, stress_tensor, coords)
            
            # Secondary: ML-predicted fracture toughness
            ml_toughness = await self._get_ml_predicted_fracture_toughness(cap_rock_props, stress_tensor, coords)
            
            # Tertiary: Volcanic system-enhanced fracture analysis
            volcanic_toughness = await self._get_volcanic_enhanced_fracture_toughness(cap_rock_props, stress_tensor, coords)
            
            # Quaternary: Physics-based multi-scale fracture mechanics
            physics_toughness = await self._get_physics_based_fracture_toughness(cap_rock_props, stress_tensor, coords)
            
            # Ensemble fracture toughness estimation
            toughness_estimates = []
            if database_toughness: toughness_estimates.append(('database', database_toughness, 0.9))
            if ml_toughness: toughness_estimates.append(('ml_prediction', ml_toughness, 0.85))
            if volcanic_toughness: toughness_estimates.append(('volcanic_enhanced', volcanic_toughness, 0.8))
            if physics_toughness: toughness_estimates.append(('physics_based', physics_toughness, 0.75))
            
            if not toughness_estimates:
                # Enhanced empirical fallback
                return await self._calculate_enhanced_empirical_fracture_toughness(cap_rock_props, stress_tensor, coords)
            
            # Weighted ensemble of fracture toughness estimates
            total_weight = sum(weight for _, _, weight in toughness_estimates)
            weighted_toughness = sum(toughness * weight for _, toughness, weight in toughness_estimates) / total_weight
            
            # Apply safety factors for conservative design
            uncertainty_factor = 1.0 - (len(toughness_estimates) * 0.08)  # Lower uncertainty with more estimates
            safety_factor = max(0.7, uncertainty_factor)  # Conservative safety factor
            
            final_toughness = weighted_toughness * safety_factor
            
            self.logger.debug(f"Advanced fracture toughness: {final_toughness/1e6:.2f} MPa√m (from {len(toughness_estimates)} methods)")
            return max(0.1e6, final_toughness)  # Minimum reasonable value
            
        except Exception as e:
            self.logger.error(f"Advanced fracture toughness estimation failed: {e}")
            return await self._calculate_enhanced_empirical_fracture_toughness(cap_rock_props, stress_tensor, coords)
    
    async def _get_database_fracture_toughness(self, cap_rock_props: CapRockProperties,
                                              stress_tensor: Dict, coords: List[float] = None) -> Optional[float]:
        """Get fracture toughness from material database"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query fracture toughness measurements
                toughness_query = """
                    SELECT 
                        fracture_toughness_mpa_sqrt_m, temperature_c, porosity, 
                        ucs_mpa, tensile_strength_mpa, lithology,
                        test_method, alteration_degree
                    FROM fracture_toughness_measurements
                    WHERE lithology ILIKE %s
                    AND ucs_mpa BETWEEN %s AND %s
                    AND porosity BETWEEN %s AND %s
                    AND temperature_c BETWEEN %s AND %s
                    ORDER BY 
                        ABS(ucs_mpa - %s), 
                        ABS(porosity - %s),
                        ABS(temperature_c - %s)
                    LIMIT 10;
                """
                
                temperature_c = stress_tensor.get('temperature_c', 200)
                lithology_pattern = f"%{cap_rock_props.lithology}%"
                ucs_range = cap_rock_props.unconfined_compressive_strength_mpa * 0.3
                porosity_range = 0.1
                temp_range = 100
                
                measurements = await db.fetch_all(
                    toughness_query,
                    lithology_pattern,
                    max(cap_rock_props.unconfined_compressive_strength_mpa - ucs_range, 10),
                    cap_rock_props.unconfined_compressive_strength_mpa + ucs_range,
                    max(cap_rock_props.porosity - porosity_range, 0),
                    min(cap_rock_props.porosity + porosity_range, 0.8),
                    max(temperature_c - temp_range, 0),
                    temperature_c + temp_range,
                    cap_rock_props.unconfined_compressive_strength_mpa,
                    cap_rock_props.porosity,
                    temperature_c
                )
                
                if measurements:
                    # Weighted average based on property similarity
                    total_weight = 0
                    weighted_toughness = 0
                    
                    for measurement in measurements:
                        # UCS similarity weight
                        ucs_diff = abs(measurement['ucs_mpa'] - cap_rock_props.unconfined_compressive_strength_mpa)
                        ucs_weight = 1.0 / (1.0 + ucs_diff / 20)
                        
                        # Porosity similarity weight
                        porosity_diff = abs(measurement['porosity'] - cap_rock_props.porosity)
                        porosity_weight = 1.0 / (1.0 + porosity_diff * 10)
                        
                        # Temperature similarity weight
                        temp_diff = abs(measurement['temperature_c'] - temperature_c)
                        temp_weight = 1.0 / (1.0 + temp_diff / 50)
                        
                        # Test method reliability weight
                        method_weight = 1.0
                        if measurement['test_method'] in ['ISRM_chevron_bend', 'ASTM_D7313']:
                            method_weight = 1.2  # Higher weight for standard methods
                        
                        combined_weight = ucs_weight * porosity_weight * temp_weight * method_weight
                        total_weight += combined_weight
                        weighted_toughness += measurement['fracture_toughness_mpa_sqrt_m'] * combined_weight
                    
                    if total_weight > 0:
                        return (weighted_toughness / total_weight) * 1e6  # Convert to Pa√m
                
                # Fallback to lithology-based averages
                lithology_query = """
                    SELECT 
                        avg(fracture_toughness_mpa_sqrt_m) as avg_toughness,
                        stddev(fracture_toughness_mpa_sqrt_m) as std_toughness,
                        count(*) as sample_count
                    FROM fracture_toughness_measurements
                    WHERE lithology ILIKE %s
                    GROUP BY lithology;
                """
                
                lithology_stats = await db.fetch_one(lithology_query, lithology_pattern)
                
                if lithology_stats and lithology_stats['avg_toughness']:
                    return float(lithology_stats['avg_toughness']) * 1e6  # Convert to Pa√m
                    
        except Exception as e:
            self.logger.debug(f"Database fracture toughness query error: {e}")
        
        return None
    
