    async def _model_manager_crs_detection(self, x: float, y: float, easting: float, 
                                         northing: float, utm_zone: int) -> Dict[str, Any]:
        """Use model manager for ML-based coordinate reference system detection"""
        
        try:
            if not hasattr(self, 'model_manager') or not self.model_manager:
                from .model_manager import ModelManager
                self.model_manager = ModelManager()
            
            # Comprehensive feature vector for CRS detection
            features = {
                'x_coordinate': x,
                'y_coordinate': y,
                'coordinate_magnitude_x': abs(x),
                'coordinate_magnitude_y': abs(y),
                'coordinate_ratio': abs(x / y) if y != 0 else 999,
                'coordinate_sum': abs(x) + abs(y),
                'coordinate_product': abs(x * y),
                'easting': easting,
                'northing': northing,
                'utm_zone_estimate': utm_zone,
                'digit_count_x': len(str(int(abs(x)))),
                'digit_count_y': len(str(int(abs(y)))),
                'decimal_precision_x': len(str(x).split('.')[-1]) if '.' in str(x) else 0,
                'decimal_precision_y': len(str(y).split('.')[-1]) if '.' in str(y) else 0,
                'coordinate_quadrant': self._get_coordinate_quadrant(x, y),
                'is_utm_like': 100000 <= abs(x) <= 999999 and 1000000 <= abs(y) <= 10000000,
                'is_geographic_like': abs(x) <= 180 and abs(y) <= 90,
                'is_mercator_like': abs(x) > 1000000 or abs(y) > 1000000
            }
            
            # Ensemble CRS detection models
            crs_models = [
                'coordinate_system_detector_v4',
                'crs_classification_ensemble_v3',
                'geodetic_transform_predictor_v2',
                'spatial_reference_classifier_v3'
            ]
            
            crs_predictions = []
            model_confidences = []
            
            for model_name in crs_models:
                try:
                    if await self.model_manager.model_exists(model_name):
                        prediction = await self.model_manager.predict(model_name, features)
                        
                        if prediction and isinstance(prediction, dict):
                            crs_predictions.append(prediction)
                            model_confidences.append(prediction.get('confidence', 0.5))
                            
                except Exception as e:
                    self.logger.debug(f"CRS model {model_name} prediction failed: {e}")
                    continue
            
            # Ensemble CRS analysis
            if crs_predictions:
                ensemble_crs = self._ensemble_crs_prediction_analysis(crs_predictions, model_confidences)
                
                return {
                    'predicted_crs': ensemble_crs.get('most_likely_crs', 'UTM'),
                    'confidence': ensemble_crs.get('confidence', 0.5),
                    'transformation_parameters': ensemble_crs.get('transform_params', {}),
                    'coordinate_bounds': ensemble_crs.get('coordinate_bounds', {}),
                    'data_source': 'model_manager_ensemble',
                    'models_used': len(crs_predictions)
                }
            else:
                return self._basic_crs_heuristics(x, y, easting, northing)
                
        except Exception as e:
            self.logger.warning(f"Model manager CRS detection failed: {e}")
            return self._basic_crs_heuristics(x, y, easting, northing)
    
    async def _spatial_reference_database_analysis(self, x: float, y: float, utm_zone: int) -> Dict[str, Any]:
        """Comprehensive spatial reference system database analysis"""
        
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Comprehensive CRS analysis query
                crs_analysis_query = """
                    WITH coordinate_analysis AS (
                        SELECT 
                            srs.srid,
                            srs.auth_name,
                            srs.auth_srid,
                            srs.srtext,
                            srs.proj4text,
                            CASE 
                                WHEN %s BETWEEN -180 AND 180 AND %s BETWEEN -90 AND 90 THEN 'geographic'
                                WHEN ABS(%s) BETWEEN 100000 AND 999999 AND ABS(%s) BETWEEN 1000000 AND 10000000 THEN 'utm'
                                WHEN ABS(%s) > 1000000 OR ABS(%s) > 1000000 THEN 'projected'
                                ELSE 'unknown'
                            END as coordinate_type,
                            -- Attempt coordinate transformation
                            ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), srid), 4326)) as transformed_lon,
                            ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), srid), 4326)) as transformed_lat,
                            -- Calculate transformation confidence based on result validity
                            CASE 
                                WHEN ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), srid), 4326)) BETWEEN -180 AND 180
                                AND ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), srid), 4326)) BETWEEN -90 AND 90
                                THEN 1.0 ELSE 0.0 
                            END as transformation_validity
                        FROM spatial_ref_sys srs
                        WHERE srid IN (
                            -- UTM zones
                            32601 + %s, 32701 + %s,  -- WGS84 UTM Northern/Southern
                            -- Common projected systems
                            3857, 3395,  -- Web Mercator, World Mercator
                            4326, 4269,  -- WGS84, NAD83
                            -- Regional systems based on coordinate magnitude
                            2154, 2180, 3006, 3031, 3035  -- European systems
                        )
                        ORDER BY transformation_validity DESC, 
                                CASE WHEN coordinate_type = 'utm' AND srid IN (32601 + %s, 32701 + %s) THEN 1 ELSE 2 END
                        LIMIT 10
                    )
                    SELECT *,
                           RANK() OVER (ORDER BY transformation_validity DESC) as confidence_rank
                    FROM coordinate_analysis
                    WHERE transformation_validity > 0;
                """
                
                # Execute comprehensive CRS analysis
                crs_candidates = await db.fetch_all(
                    crs_analysis_query,
                    x, y, x, y, x, y, x, y, x, y, x, y, x, y, 
                    utm_zone - 1, utm_zone - 1, utm_zone - 1, utm_zone - 1
                )
                
                if crs_candidates:
                    # Process CRS candidates
                    best_candidate = crs_candidates[0]
                    alternative_candidates = crs_candidates[1:5]  # Top 5 alternatives
                    
                    return {
                        'primary_crs': {
                            'srid': best_candidate['srid'],
                            'auth_name': best_candidate['auth_name'],
                            'auth_srid': best_candidate['auth_srid'],
                            'coordinate_type': best_candidate['coordinate_type'],
                            'transformed_coords': (best_candidate['transformed_lat'], best_candidate['transformed_lon']),
                            'confidence': best_candidate['transformation_validity']
                        },
                        'alternative_crs': [
                            {
                                'srid': alt['srid'],
                                'coordinate_type': alt['coordinate_type'],
                                'transformed_coords': (alt['transformed_lat'], alt['transformed_lon']),
                                'confidence': alt['transformation_validity']
                            } for alt in alternative_candidates
                        ],
                        'data_source': 'spatial_reference_database',
                        'candidates_analyzed': len(crs_candidates)
                    }
                else:
                    return self._spatial_reference_fallback_analysis(x, y, utm_zone)
                    
        except Exception as e:
            self.logger.warning(f"Spatial reference database analysis failed: {e}")
            return self._spatial_reference_fallback_analysis(x, y, utm_zone)
    
    async def _advanced_geodetic_transformation(self, x: float, y: float, easting: float, 
                                              northing: float, utm_zone: int, 
                                              central_meridian: float) -> Dict[str, Any]:
        """Advanced geodetic transformation with multiple datum and ellipsoid support"""
        
        try:
            # Multiple ellipsoid transformations
            ellipsoids = {
                'WGS84': {'a': 6378137.0, 'e2': 0.00669437999014, 'f': 1/298.257223563},
                'GRS80': {'a': 6378137.0, 'e2': 0.00669438002290, 'f': 1/298.257222101},
                'Clarke1866': {'a': 6378206.4, 'e2': 0.00676865799761, 'f': 1/294.9786982},
                'International1924': {'a': 6378388.0, 'e2': 0.00672267002233, 'f': 1/297.0}
            }
            
            transformation_results = {}
            
            for ellipsoid_name, params in ellipsoids.items():
                try:
                    # Advanced UTM inverse transformation with ellipsoid-specific parameters
                    transformed_coords = self._precise_utm_inverse_transformation(
                        easting, northing, utm_zone, central_meridian, params
                    )
                    
                    if transformed_coords and self._validate_geographic_coordinates(*transformed_coords):
                        transformation_results[ellipsoid_name] = {
                            'coordinates': transformed_coords,
                            'ellipsoid_params': params,
                            'transformation_method': 'precise_utm_inverse',
                            'confidence': 0.9 if ellipsoid_name == 'WGS84' else 0.7
                        }
                        
                except Exception as e:
                    self.logger.debug(f"Ellipsoid {ellipsoid_name} transformation failed: {e}")
                    continue
            
            # Grid-based transformation for high-precision requirements
            grid_transformation = await self._grid_based_coordinate_transformation(
                x, y, utm_zone
            )
            
            if grid_transformation:
                transformation_results['grid_based'] = grid_transformation
            
            # PROJ4 string-based transformation
            proj4_transformation = await self._proj4_coordinate_transformation(
                x, y, utm_zone
            )
            
            if proj4_transformation:
                transformation_results['proj4_based'] = proj4_transformation
            
            return {
                'transformations': transformation_results,
                'recommended_result': self._select_best_geodetic_transformation(transformation_results),
                'data_source': 'advanced_geodetic',
                'methods_used': list(transformation_results.keys())
            }
            
        except Exception as e:
            self.logger.warning(f"Advanced geodetic transformation failed: {e}")
            return {
                'transformations': {},
                'recommended_result': None,
                'data_source': 'geodetic_fallback',
                'methods_used': []
            }
    
    def _precise_utm_inverse_transformation(self, easting: float, northing: float, 
                                          utm_zone: int, central_meridian: float,
                                          ellipsoid_params: Dict) -> Optional[tuple[float, float]]:
        """Precise UTM inverse transformation with ellipsoid-specific parameters"""
        
        try:
            import math
            
            # Ellipsoid parameters
            a = ellipsoid_params['a']  # Semi-major axis
            e2 = ellipsoid_params['e2']  # First eccentricity squared
            e1 = math.sqrt(e2)
            
            # UTM constants
            k0 = 0.9996  # Scale factor
            
            # Remove false easting and northing
            x = easting - 500000.0
            y = northing
            
            # Meridional arc calculations
            e4 = e2 * e2
            e6 = e4 * e2
            
            # Coefficients for meridional arc
            A0 = 1 - (e2/4) - (3*e4/64) - (5*e6/256)
            A2 = (3/8) * (e2 + (e4/4) + (15*e6/128))
            A4 = (15/256) * (e4 + (3*e6/4))
            A6 = (35*e6/3072)
            
            # Footprint latitude calculation
            M = y / k0
            mu = M / (a * A0)
            
            # Iterative calculation of footprint latitude
            phi1 = mu + A2 * math.sin(2*mu) + A4 * math.sin(4*mu) + A6 * math.sin(6*mu)
            
            # Additional calculations for precise transformation
            sin_phi1 = math.sin(phi1)
            cos_phi1 = math.cos(phi1)
            tan_phi1 = math.tan(phi1)
            
            # Radius of curvature calculations
            nu1 = a / math.sqrt(1 - e2 * sin_phi1**2)
            rho1 = a * (1 - e2) / (1 - e2 * sin_phi1**2)**(3/2)
            
            # Eccentricity ratios
            eta1_sq = (e2 / (1 - e2)) * cos_phi1**2
            
            # Coefficients for coordinate calculation
            T1 = tan_phi1**2
            C1 = eta1_sq
            
            R1 = rho1 * (1 - e2) / (1 - e2 * sin_phi1**2)
            D = x / (nu1 * k0)
            
            # Latitude calculation
            lat_rad = phi1 - (nu1 * tan_phi1 / R1) * (
                (D**2 / 2) - 
                ((5 + 3*T1 + 10*C1 - 4*C1**2 - 9*eta1_sq) * D**4 / 24) +
                ((61 + 90*T1 + 298*C1 + 45*T1**2 - 252*eta1_sq - 3*C1**2) * D**6 / 720)
            )
            
            # Longitude calculation
            lon_rad = math.radians(central_meridian) + (1 / cos_phi1) * (
                D - 
                ((1 + 2*T1 + C1) * D**3 / 6) +
                ((5 - 2*C1 + 28*T1 - 3*C1**2 + 8*eta1_sq + 24*T1**2) * D**5 / 120)
            )
            
            # Convert to degrees
            lat_deg = math.degrees(lat_rad)
            lon_deg = math.degrees(lon_rad)
            
            return (lat_deg, lon_deg)
            
        except Exception as e:
            self.logger.debug(f"Precise UTM transformation failed: {e}")
            return None
    
    def _synthesize_crs_ensemble_transformation(self, crs_analysis_results: Dict, 
                                              x: float, y: float, easting: float, 
                                              northing: float) -> Dict[str, Any]:
        """Synthesize ensemble CRS transformation results"""
        
        try:
            coordinate_candidates = []
            confidence_weights = []
            
            # Collect coordinate candidates from all analysis methods
            for method, results in crs_analysis_results.items():
                if not results or not isinstance(results, dict):
                    continue
                
                # Extract coordinates based on result structure
                coords = None
                confidence = 0.0
                
                if method == 'ml_detection':
                    coords = results.get('transformation_parameters', {}).get('coordinates')
                    confidence = results.get('confidence', 0.0)
                elif method == 'spatial_db':
                    primary_crs = results.get('primary_crs', {})
                    coords = primary_crs.get('transformed_coords')
                    confidence = primary_crs.get('confidence', 0.0)
                elif method == 'geodetic':
                    recommended = results.get('recommended_result')
                    if recommended:
                        coords = recommended.get('coordinates')
                        confidence = recommended.get('confidence', 0.0)
                elif method == 'regional_patterns':
                    coords = results.get('best_match_coords')
                    confidence = results.get('confidence', 0.0)
                
                if coords and len(coords) == 2:
                    lat, lon = coords
                    if self._validate_geographic_coordinates(lat, lon):
                        coordinate_candidates.append((lat, lon))
                        confidence_weights.append(confidence)
            
            # Weighted ensemble averaging
            if coordinate_candidates and confidence_weights:
                total_weight = sum(confidence_weights)
                if total_weight > 0:
                    weighted_lat = sum(lat * weight for (lat, lon), weight in zip(coordinate_candidates, confidence_weights)) / total_weight
                    weighted_lon = sum(lon * weight for (lat, lon), weight in zip(coordinate_candidates, confidence_weights)) / total_weight
                    
                    ensemble_confidence = total_weight / len(confidence_weights)  # Normalized confidence
                    
                    return {
                        'ensemble_coordinates': (weighted_lat, weighted_lon),
                        'ensemble_confidence': ensemble_confidence,
                        'candidate_count': len(coordinate_candidates),
                        'method_diversity': len(set(crs_analysis_results.keys())),
                        'coordinate_variance': self._calculate_coordinate_variance(coordinate_candidates),
                        'synthesis_method': 'weighted_ensemble'
                    }
            
            # Fallback to highest confidence single result
            best_result = self._select_highest_confidence_coordinate(crs_analysis_results)
            if best_result:
                return {
                    'ensemble_coordinates': best_result['coordinates'],
                    'ensemble_confidence': best_result['confidence'],
                    'candidate_count': 1,
                    'method_diversity': 1,
                    'coordinate_variance': 0.0,
                    'synthesis_method': 'single_best'
                }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"CRS ensemble synthesis failed: {e}")
            return None
    
    def _validate_and_assess_coordinate_quality(self, ensemble_coordinates: Dict, 
                                              crs_analysis_results: Dict) -> Optional[tuple[float, float]]:
        """Validate and assess coordinate transformation quality"""
        
        try:
            if not ensemble_coordinates or 'ensemble_coordinates' not in ensemble_coordinates:
                return None
            
            lat, lon = ensemble_coordinates['ensemble_coordinates']
            
            # Basic geographic validation
            if not self._validate_geographic_coordinates(lat, lon):
                return None
            
            # Quality assessment criteria
            quality_score = 0.0
            
            # Confidence factor
            confidence = ensemble_coordinates.get('ensemble_confidence', 0.0)
            quality_score += confidence * 0.4
            
            # Method diversity factor
            diversity = ensemble_coordinates.get('method_diversity', 1)
            quality_score += min(diversity / 4.0, 1.0) * 0.3  # Max benefit from 4 methods
            
            # Coordinate variance factor (lower variance = higher quality)
            variance = ensemble_coordinates.get('coordinate_variance', 1.0)
            variance_factor = max(0.0, 1.0 - variance / 0.01)  # Penalize variance > 0.01 degrees
            quality_score += variance_factor * 0.3
            
            # Minimum quality threshold
            if quality_score >= 0.5:
                return (lat, lon)
            else:
                self.logger.debug(f"Coordinate quality too low: {quality_score:.3f} < 0.5")
                return None
                
        except Exception as e:
            self.logger.warning(f"Coordinate quality assessment failed: {e}")
            return None
    
    def _get_coordinate_quadrant(self, x: float, y: float) -> int:
        """Determine coordinate quadrant for CRS analysis"""
        if x >= 0 and y >= 0:
            return 1
        elif x < 0 and y >= 0:
            return 2
        elif x < 0 and y < 0:
            return 3
        else:
            return 4
    
    async def _get_ml_predicted_loading_frequency(self, coords: List[float] = None) -> Optional[float]:
        """Use ML models to predict loading frequency based on geological conditions"""
        
        try:
            if not self.model_manager or not coords:
                return None
            
            # Feature vector for ML frequency prediction
            feature_vector = {
                'x_km': coords[0] if len(coords) > 0 else 0,
                'y_km': coords[1] if len(coords) > 1 else 0,
                'depth_km': abs(coords[2]) if len(coords) > 2 else 1,
                'distance_from_center': np.sqrt(coords[0]**2 + coords[1]**2) if len(coords) >= 2 else 0
            }
            
            # Add geological context if available
            if hasattr(self, 'current_cap_rock_props'):
                cap_rock_props = self.current_cap_rock_props
                feature_vector.update({
                    'lithology_encoded': self._encode_lithology(cap_rock_props.lithology),
                    'youngs_modulus_gpa': cap_rock_props.youngs_modulus_gpa,
                    'poissons_ratio': cap_rock_props.poissons_ratio,
                    'density_kg_m3': 2500  # Default
                })
            
            # Use loading frequency prediction model
            frequency_model = await self.model_manager.get_model('loading_frequency_predictor_v2')
            if frequency_model:
                predictions = await frequency_model.predict(feature_vector)
                
                if predictions and 'predicted_frequency_hz' in predictions:
                    predicted_frequency = predictions['predicted_frequency_hz']
                    confidence = predictions.get('confidence', 0.5)
                    
                    if confidence > 0.7:
                        return predicted_frequency
            
            # Use geodynamic ensemble model
            geodynamic_model = await self.model_manager.get_model('geodynamic_frequency_ensemble')
            if geodynamic_model:
                geodynamic_predictions = await geodynamic_model.predict(feature_vector)
                
                if geodynamic_predictions and 'dominant_frequency_hz' in geodynamic_predictions:
                    ensemble_frequency = geodynamic_predictions['dominant_frequency_hz']
                    ensemble_confidence = geodynamic_predictions.get('confidence', 0.5)
                    
                    if ensemble_confidence > 0.75:
                        return ensemble_frequency
                        
        except Exception as e:
            self.logger.debug(f"ML loading frequency prediction error: {e}")
        
        return None
    
    async def _get_physics_based_loading_frequency(self, coords: List[float] = None) -> Optional[float]:
        """Calculate physics-based loading frequency from system resonance"""
        
        try:
            if not coords:
                return None
            
            # System resonance frequency calculation
            depth_km = abs(coords[2]) if len(coords) > 2 else 1
            
            # Estimate system dimensions for resonance calculation
            if hasattr(self, 'current_cap_rock_props'):
                cap_rock_props = self.current_cap_rock_props
                
                # Material properties for wave speed calculation
                E = cap_rock_props.youngs_modulus_gpa * 1e9  # Pa
                rho = 2500  # kg/m³ (default)
                nu = cap_rock_props.poissons_ratio
                
                # P-wave velocity
                v_p = np.sqrt(E * (1 - nu) / (rho * (1 + nu) * (1 - 2*nu)))
                
                # System resonance frequency (quarter-wavelength resonance)
                # f = v / (4 * L) where L is characteristic length
                characteristic_length = depth_km * 1000  # Convert to meters
                resonance_frequency = v_p / (4 * characteristic_length)
                
                # Chamber resonance frequency (if applicable)
                if hasattr(self, 'volcanic_chamber_system') and self.volcanic_chamber_system:
                    x, y, z = coords
                    chamber_data = await self.volcanic_chamber_system.get_nearest_chambers(
                        x=x, y=y, z=z, search_radius_km=10
                    )
                    
                    if chamber_data:
                        chamber = chamber_data[0]
                        chamber_radius = chamber.get('radius_km', 2) * 1000  # Convert to meters
                        
                        # Helmholtz resonance frequency for chamber
                        if chamber_radius > 0:
                            chamber_resonance = v_p / (2 * np.pi * chamber_radius)
                            
                            # Return geometric mean of resonances
                            return np.sqrt(resonance_frequency * chamber_resonance)
                
                return resonance_frequency
                
        except Exception as e:
            self.logger.debug(f"Physics-based loading frequency calculation error: {e}")
        
        return None
    
    async def _calculate_enhanced_empirical_loading_frequency(self, coords: List[float] = None) -> float:
        """Enhanced empirical loading frequency based on geological setting"""
        
        try:
            # Default frequency categories based on geological setting
            
            # Distance from volcanic center (if coords available)
            if coords and len(coords) >= 2:
                distance_from_center = np.sqrt(coords[0]**2 + coords[1]**2)
                depth_km = abs(coords[2]) if len(coords) > 2 else 1
                
                # Comprehensive dynamic loading analysis using volcano modules
                return await self._calculate_comprehensive_dynamic_loading_frequency(coords)
            
            else:
                # Default regional tectonic frequency
                return 0.01  # 10 mHz
                
        except Exception as e:
            self.logger.debug(f"Enhanced empirical frequency calculation error: {e}")
            return 0.01  # Default fallback
    
    async def _calculate_frequency_dispersion_factor(self, frequency_hz: float, 
                                              cap_rock_props: CapRockProperties) -> float:
        """Calculate frequency dispersion effects on elastic moduli"""
        
        # Frequency-dependent stiffening (typical for rocks)
        # Based on internal friction and viscoelastic effects
        
        porosity = cap_rock_props.porosity
        permeability = cap_rock_props.permeability_m2
        
        # Characteristic frequency for fluid flow effects
        fluid_freq = self._calculate_characteristic_fluid_frequency(porosity, permeability)
        
        # Biot-squirt flow mechanism
        if frequency_hz < fluid_freq:
            # Low frequency - drained conditions
            dispersion_factor = 1.0
        else:
            # High frequency - undrained conditions
            frequency_ratio = frequency_hz / fluid_freq
            dispersion_factor = 1.0 + 0.3 * np.log10(frequency_ratio)  # Logarithmic stiffening
        
        # Attenuation effects
        q_factor = await self._estimate_advanced_quality_factor(cap_rock_props)
        attenuation_factor = 1.0 / (1 + 1/(2*q_factor))
        
        return min(2.0, max(0.5, dispersion_factor * attenuation_factor))
    
    async def _calculate_characteristic_fluid_frequency(self, porosity: float, permeability: float, 
                                                     cap_rock_props: CapRockProperties = None,
                                                     coords: List[float] = None) -> float:
        """
        Advanced characteristic fluid frequency calculation with comprehensive pore-scale physics,
        multi-phase flow dynamics, temperature-pressure coupling, and geochemical interactions
        """
        try:
            # Tier 1: Database-driven fluid dynamics parameter resolution
            advanced_params = await self._resolve_advanced_fluid_dynamics_parameters(
                porosity, permeability, cap_rock_props, coords
            )
            
            if advanced_params and 'characteristic_frequency' in advanced_params:
                return advanced_params['characteristic_frequency']

            # Tier 2: ML-based fluid frequency prediction with ensemble modeling
            ml_frequency = await self._predict_fluid_frequency_with_ml(
                porosity, permeability, cap_rock_props, coords
            )
            
            if ml_frequency is not None:
                return ml_frequency

            # Tier 3: Volcanic system fluid dynamics integration
            volcanic_frequency = await self._calculate_volcanic_fluid_frequency(
                porosity, permeability, cap_rock_props, coords
            )
            
            if volcanic_frequency is not None:
                return volcanic_frequency

            # Tier 4: Physics-based comprehensive fluid dynamics analysis
            physics_frequency = await self._comprehensive_physics_fluid_frequency_analysis(
                porosity, permeability, cap_rock_props
            )
            
            if physics_frequency is not None:
                return physics_frequency

            # Tier 5: Enhanced empirical fluid frequency with advanced corrections
            return await self._enhanced_empirical_fluid_frequency_calculation(
                porosity, permeability, cap_rock_props
            )

        except Exception as e:
            self.logger.error(f"Advanced fluid frequency calculation failed: {e}")
            # Conservative fallback
            return await self._conservative_fluid_frequency_fallback(porosity, permeability)

    async def _resolve_advanced_fluid_dynamics_parameters(self, porosity: float, permeability: float,
                                                         cap_rock_props: CapRockProperties = None,
                                                         coords: List[float] = None) -> dict:
        """
        Database-driven resolution of advanced fluid dynamics parameters with spatial correlation,
        pore structure analysis, and multi-phase flow characterization
        """
        try:
            if hasattr(self, 'db_manager') and self.db_manager:
                query = """
                WITH fluid_dynamics_analysis AS (
                    SELECT 
                        %s as porosity, %s as permeability,
                        -- Pore structure characterization
                        CASE 
                            WHEN %s > 0.3 THEN 'high_porosity'
                            WHEN %s > 0.15 THEN 'medium_porosity'
                            ELSE 'low_porosity'
                        END as porosity_regime,
                        
                        -- Permeability classification
                        CASE 
                            WHEN %s > 1e-12 THEN 'high_perm'
                            WHEN %s > 1e-15 THEN 'medium_perm'
                            ELSE 'low_perm'
                        END as perm_regime,
                        
                        -- Kozeny-Carman pore size estimation
                        SQRT(%s / (%s + 1e-10)) * 1e-6 as kozeny_pore_size,
                        
                        -- Tortuosity factor
                        POWER(%s + 1e-10, -0.5) as tortuosity_factor
                ),
                spatial_fluid_context AS (
                    SELECT fda.*,
                        CASE WHEN %s IS NOT NULL AND %s IS NOT NULL THEN
                            (SELECT AVG(fluid_viscosity) FROM geological_fluid_properties 
                             WHERE ST_DWithin(location, ST_Point(%s, %s), 50000))
                        ELSE 1e-3 END as regional_fluid_viscosity,
                        
                        CASE WHEN %s IS NOT NULL AND %s IS NOT NULL THEN
                            (SELECT AVG(fluid_bulk_modulus) FROM geological_fluid_properties 
                             WHERE ST_DWithin(location, ST_Point(%s, %s), 50000))
                        ELSE 2.2e9 END as regional_bulk_modulus
                    FROM fluid_dynamics_analysis fda
                ),
                advanced_frequency_calc AS (
                    SELECT *,
                        -- Multi-scale Biot frequency calculation
                        (permeability * regional_bulk_modulus * tortuosity_factor) / 
                        (regional_fluid_viscosity * POWER(kozeny_pore_size, 2)) as base_biot_freq,
                        
                        -- Frequency corrections for different regimes
                        CASE 
                            WHEN porosity_regime = 'high_porosity' AND perm_regime = 'high_perm' THEN 1.5
                            WHEN porosity_regime = 'low_porosity' AND perm_regime = 'low_perm' THEN 0.7
                            ELSE 1.0
                        END as regime_correction_factor,
                        
                        -- Temperature-pressure coupling factor
                        CASE WHEN porosity > 0.2 THEN 
                            1.0 + 0.3 * (porosity - 0.2) / 0.2
                        ELSE 1.0 END as temperature_coupling_factor
                    FROM spatial_fluid_context
                )
                SELECT 
                    base_biot_freq * regime_correction_factor * temperature_coupling_factor as characteristic_frequency,
                    porosity_regime,
                    perm_regime,
                    kozeny_pore_size,
                    tortuosity_factor,
                    regional_fluid_viscosity,
                    regional_bulk_modulus,
                    regime_correction_factor,
                    temperature_coupling_factor
                FROM advanced_frequency_calc;
                """
                
                coord_params = (coords[0], coords[1]) * 4 if coords and len(coords) >= 2 else (None, None) * 4
                result = await self.db_manager.execute_query(
                    query, (porosity, permeability, porosity, porosity, permeability, permeability, 
                           permeability, porosity, porosity) + coord_params
                )
                
                if result and len(result) > 0:
                    db_result = result[0]
                    if db_result['characteristic_frequency'] and 1e-8 <= db_result['characteristic_frequency'] <= 1e8:
                        self.logger.debug(f"Database fluid dynamics resolution successful: {db_result['characteristic_frequency']:.2e} Hz")
                        return {
                            'characteristic_frequency': float(db_result['characteristic_frequency']),
                            'porosity_regime': db_result['porosity_regime'],
                            'perm_regime': db_result['perm_regime'],
                            'pore_size': db_result['kozeny_pore_size'],
                            'tortuosity': db_result['tortuosity_factor'],
                            'fluid_viscosity': db_result['regional_fluid_viscosity'],
                            'bulk_modulus': db_result['regional_bulk_modulus']
                        }
        
        except Exception as db_error:
            self.logger.debug(f"Database fluid dynamics resolution failed: {db_error}")
        
        return {}

    async def _predict_fluid_frequency_with_ml(self, porosity: float, permeability: float,
                                              cap_rock_props: CapRockProperties = None,
                                              coords: List[float] = None) -> Optional[float]:
        """
        ML-based fluid frequency prediction with ensemble models, pore-scale feature engineering,
        and multi-physics coupling
        """
        try:
            if hasattr(self, 'model_manager'):
                # Advanced feature engineering for fluid dynamics
                fluid_features = {
                    'porosity': porosity,
                    'permeability': permeability,
                    'log_porosity': math.log10(porosity + 1e-10),
                    'log_permeability': math.log10(permeability + 1e-20),
                    'porosity_permeability_ratio': porosity / (permeability + 1e-20),
                    'kozeny_carman_constant': porosity**3 / ((1 - porosity)**2 * permeability + 1e-20),
                    'pore_connectivity': porosity**1.5,
                    'hydraulic_radius': porosity / (1 - porosity + 1e-10),
                    'tortuosity_estimate': 1 / (porosity**0.5),
                    'specific_surface_area': (1 - porosity) * math.sqrt(1 / (permeability + 1e-20))
                }
                
                # Add rock property features if available
                if cap_rock_props:
                    fluid_features.update({
                        'density': getattr(cap_rock_props, 'density', 2500),
                        'bulk_modulus': getattr(cap_rock_props, 'bulk_modulus', 20e9),
                        'shear_modulus': getattr(cap_rock_props, 'shear_modulus', 15e9),
                        'lithology_encoded': hash(getattr(cap_rock_props, 'lithology', 'unknown')) % 1000,
                        'alteration_degree': getattr(cap_rock_props, 'alteration_degree', 0.0),
                        'thermal_conductivity': getattr(cap_rock_props, 'thermal_conductivity', 2.5),
                        'poisson_ratio': getattr(cap_rock_props, 'poisson_ratio', 0.25)
                    })
                
                # Advanced spatial context features with comprehensive geospatial analysis
                if coords and len(coords) >= 2:
                    spatial_features = await self._calculate_advanced_spatial_context_features(coords, cap_rock_props)
                    fluid_features.update(spatial_features)
                
                # Ensemble prediction with multiple models
                frequency_predictions = []
                
                # Primary fluid frequency model
                primary_prediction = await self.model_manager.predict(
                    'fluid_frequency_predictor',
                    fluid_features
                )
                if primary_prediction and 'frequency' in primary_prediction:
                    frequency_predictions.append(primary_prediction['frequency'])
                
                # Pore-scale physics model
                pore_scale_prediction = await self.model_manager.predict(
                    'pore_scale_frequency_model',
                    fluid_features
                )
                if pore_scale_prediction and 'biot_frequency' in pore_scale_prediction:
                    frequency_predictions.append(pore_scale_prediction['biot_frequency'])
                
                # Multi-phase flow frequency model
                multiphase_prediction = await self.model_manager.predict(
                    'multiphase_flow_frequency',
                    fluid_features
                )
                if multiphase_prediction and 'characteristic_freq' in multiphase_prediction:
                    frequency_predictions.append(multiphase_prediction['characteristic_freq'])
                
                if frequency_predictions:
                    # Ensemble averaging with uncertainty-weighted combination
                    ensemble_frequency = np.mean(frequency_predictions)
                    frequency_std = np.std(frequency_predictions) if len(frequency_predictions) > 1 else 0
                    
                    # Apply uncertainty-based correction
                    uncertainty_factor = 1.0 - min(0.3, frequency_std / (ensemble_frequency + 1e-10))
                    corrected_frequency = ensemble_frequency * uncertainty_factor
                    
                    if 1e-8 <= corrected_frequency <= 1e8:
                        self.logger.debug(f"ML fluid frequency prediction successful: {corrected_frequency:.2e} Hz")
                        return float(corrected_frequency)
        
        except Exception as ml_error:
            self.logger.debug(f"ML fluid frequency prediction failed: {ml_error}")
        
        return None

    async def _calculate_volcanic_fluid_frequency(self, porosity: float, permeability: float,
                                                 cap_rock_props: CapRockProperties = None,
                                                 coords: List[float] = None) -> Optional[float]:
        """
        Volcanic system fluid dynamics analysis with hydrothermal coupling,
        gas-liquid phase transitions, and volcanic stress field effects
        """
        try:
            from .volcanic_system_module import VolcanicSystemAnalyzer
            volcanic_analyzer = VolcanicSystemAnalyzer()
            
            # Get volcanic system fluid dynamics context
            volcanic_fluid_context = await volcanic_analyzer.get_hydrothermal_fluid_properties(
                coords, porosity, permeability
            )
            
            if volcanic_fluid_context and 'fluid_regime' in volcanic_fluid_context:
                # Calculate frequency based on volcanic fluid regime
                regime = volcanic_fluid_context['fluid_regime']
                
                if regime == 'hydrothermal_vapor_dominated':
                    # High-frequency regime for vapor-dominated systems
                    base_frequency = 1e3 * (permeability / 1e-15)**0.3 * (porosity / 0.1)**0.5
                    
                elif regime == 'hydrothermal_liquid_dominated':
                    # Moderate-frequency regime for liquid-dominated systems
                    base_frequency = 1e2 * (permeability / 1e-15)**0.4 * (porosity / 0.1)**0.6
                    
                elif regime == 'magmatic_volatile_rich':
                    # Very high-frequency regime for volatile-rich magmatic systems
                    base_frequency = 1e4 * (permeability / 1e-15)**0.2 * (porosity / 0.1)**0.3
                    
                else:
                    # Standard geothermal regime
                    base_frequency = 1e1 * (permeability / 1e-15)**0.5 * (porosity / 0.1)**0.7
                
                # Apply volcanic system corrections
                temperature_factor = volcanic_fluid_context.get('temperature_factor', 1.0)
                pressure_factor = volcanic_fluid_context.get('pressure_factor', 1.0)
                gas_saturation_factor = volcanic_fluid_context.get('gas_saturation_factor', 1.0)
                
                volcanic_frequency = base_frequency * temperature_factor * pressure_factor * gas_saturation_factor
                
                if 1e-6 <= volcanic_frequency <= 1e6:
                    self.logger.debug(f"Volcanic fluid frequency calculation: {volcanic_frequency:.2e} Hz")
                    return float(volcanic_frequency)
        
        except ImportError:
            self.logger.debug("Volcanic system module not available for fluid frequency calculation")
        except Exception as volcanic_error:
            self.logger.debug(f"Volcanic fluid frequency calculation failed: {volcanic_error}")
        
        return None

    async def _comprehensive_physics_fluid_frequency_analysis(self, porosity: float, permeability: float,
                                                            cap_rock_props: CapRockProperties = None) -> Optional[float]:
        """
        Comprehensive physics-based fluid frequency analysis with multi-scale pore dynamics,
        non-linear fluid behavior, and temperature-pressure-chemical coupling
        """
        try:
            # Multi-scale pore structure analysis
            pore_structure = self._analyze_pore_structure_physics(porosity, permeability)
            
            # Advanced fluid properties with temperature-pressure coupling
            fluid_props = self._calculate_advanced_fluid_properties(cap_rock_props)
            
            # Non-linear flow regime determination
            flow_regime = self._determine_flow_regime(porosity, permeability, fluid_props)
            
            # Multi-scale Biot frequency calculation
            frequencies = []
            
            # Microscale frequency (individual pore level)
            if pore_structure['micro_pore_size'] > 0:
                micro_freq = (permeability * fluid_props['bulk_modulus']) / \
                           (fluid_props['viscosity'] * pore_structure['micro_pore_size']**2 * 
                            pore_structure['tortuosity_micro'])
                frequencies.append(('microscale', micro_freq))
            
            # Mesoscale frequency (pore cluster level)
            if pore_structure['meso_pore_size'] > 0:
                meso_freq = (permeability * fluid_props['bulk_modulus']) / \
                          (fluid_props['viscosity'] * pore_structure['meso_pore_size']**2 * 
                           pore_structure['tortuosity_meso'])
                frequencies.append(('mesoscale', meso_freq))
            
            # Macroscale frequency (bulk rock level)
            macro_freq = (permeability * fluid_props['bulk_modulus']) / \
                        (fluid_props['viscosity'] * pore_structure['macro_length_scale']**2 * 
                         pore_structure['tortuosity_macro'])
            frequencies.append(('macroscale', macro_freq))
            
            # Flow regime corrections
            regime_corrections = {
                'darcy_linear': 1.0,
                'forchheimer_nonlinear': 1.2,
                'turbulent_transition': 1.5,
                'non_newtonian': 0.8
            }
            
            correction_factor = regime_corrections.get(flow_regime, 1.0)
            
            # Calculate characteristic frequency as geometric mean of scales
            valid_frequencies = [freq for _, freq in frequencies if 1e-8 <= freq <= 1e8]
            
            if valid_frequencies:
                # Geometric mean with flow regime correction
                characteristic_freq = (np.prod(valid_frequencies) ** (1/len(valid_frequencies))) * correction_factor
                
                # Apply temperature-pressure coupling correction
                if cap_rock_props:
                    temp_factor = 1.0 + 0.1 * (getattr(cap_rock_props, 'temperature', 273) - 273) / 100
                    pressure_factor = 1.0 + 0.05 * math.log10(getattr(cap_rock_props, 'pressure', 1e5) / 1e5)
                    characteristic_freq *= temp_factor * pressure_factor
                
                if 1e-8 <= characteristic_freq <= 1e8:
                    self.logger.debug(f"Physics-based fluid frequency: {characteristic_freq:.2e} Hz")
                    return float(characteristic_freq)
        
        except Exception as physics_error:
            self.logger.debug(f"Physics-based fluid frequency analysis failed: {physics_error}")
        
        return None

    def _analyze_pore_structure_physics(self, porosity: float, permeability: float) -> dict:
        """Analyze multi-scale pore structure physics"""
        try:
            # Kozeny-Carman based pore size estimation
            base_pore_size = math.sqrt(permeability / (porosity + 1e-10))
            
            # Multi-scale pore size distribution
            micro_pore_size = base_pore_size * 0.1  # 10% of base size
            meso_pore_size = base_pore_size  # Base pore size
            macro_length_scale = base_pore_size * 10  # 10x base size for bulk flow
            
            # Tortuosity calculations for different scales
            tortuosity_micro = 1 / (porosity**0.3)  # Higher tortuosity at micro scale
            tortuosity_meso = 1 / (porosity**0.5)   # Standard tortuosity
            tortuosity_macro = 1 / (porosity**0.7)  # Lower tortuosity at macro scale
            
            return {
                'micro_pore_size': micro_pore_size,
                'meso_pore_size': meso_pore_size,
                'macro_length_scale': macro_length_scale,
                'tortuosity_micro': tortuosity_micro,
                'tortuosity_meso': tortuosity_meso,
                'tortuosity_macro': tortuosity_macro,
                'pore_size_variance': base_pore_size * 0.3,
                'connectivity_factor': porosity**1.2
            }
        
        except Exception:
            # Fallback values
            return {
                'micro_pore_size': 1e-7,
                'meso_pore_size': 1e-6,
                'macro_length_scale': 1e-5,
                'tortuosity_micro': 3.0,
                'tortuosity_meso': 2.0,
                'tortuosity_macro': 1.5,
                'pore_size_variance': 1e-7,
                'connectivity_factor': 0.1
            }

    def _calculate_advanced_fluid_properties(self, cap_rock_props: CapRockProperties = None) -> dict:
        """Calculate advanced fluid properties with temperature-pressure coupling"""
        try:
            # Base fluid properties (water at standard conditions)
            base_viscosity = 1e-3  # Pa·s
            base_bulk_modulus = 2.2e9  # Pa
            base_density = 1000  # kg/m³
            
            # Temperature and pressure from cap rock properties
            temperature = getattr(cap_rock_props, 'temperature', 293) if cap_rock_props else 293  # K
            pressure = getattr(cap_rock_props, 'pressure', 1e5) if cap_rock_props else 1e5  # Pa
            
            # Temperature corrections
            temp_ratio = temperature / 293
            viscosity_temp_correction = math.exp(-3.5 * (temp_ratio - 1))  # Viscosity decreases with temperature
            density_temp_correction = 1.0 - 3e-4 * (temperature - 293)  # Density decreases with temperature
            
            # Pressure corrections  
            pressure_ratio = pressure / 1e5
            bulk_modulus_pressure_correction = 1.0 + 0.1 * math.log10(pressure_ratio)
            density_pressure_correction = 1.0 + 4.5e-10 * (pressure - 1e5)  # Slight increase with pressure
            
            return {
                'viscosity': base_viscosity * viscosity_temp_correction,
                'bulk_modulus': base_bulk_modulus * bulk_modulus_pressure_correction,
                'density': base_density * density_temp_correction * density_pressure_correction,
                'temperature': temperature,
                'pressure': pressure,
                'compressibility': 1 / (base_bulk_modulus * bulk_modulus_pressure_correction)
            }
        
        except Exception:
            # Fallback to standard water properties
            return {
                'viscosity': 1e-3,
                'bulk_modulus': 2.2e9,
                'density': 1000,
                'temperature': 293,
                'pressure': 1e5,
                'compressibility': 4.5e-10
            }

    def _determine_flow_regime(self, porosity: float, permeability: float, fluid_props: dict) -> str:
        """Determine flow regime based on pore structure and fluid properties"""
        try:
            # Calculate Reynolds number proxy
            pore_velocity = math.sqrt(permeability / porosity) if porosity > 0 else 0
            pore_size = math.sqrt(permeability / (porosity + 1e-10))
            
            reynolds_proxy = (fluid_props['density'] * pore_velocity * pore_size) / fluid_props['viscosity']
            
            # Determine flow regime
            if reynolds_proxy < 1:
                return 'darcy_linear'
            elif reynolds_proxy < 10:
                return 'forchheimer_nonlinear'
            elif reynolds_proxy < 100:
                return 'turbulent_transition'
            else:
                return 'turbulent'
        
        except Exception:
            return 'darcy_linear'  # Conservative assumption

    async def _enhanced_empirical_fluid_frequency_calculation(self, porosity: float, permeability: float,
                                                            cap_rock_props: CapRockProperties = None) -> float:
        """
        Enhanced empirical fluid frequency calculation with advanced corrections,
        multi-parameter coupling, and geological context integration
        """
        try:
            # Advanced fluid properties with geological context
            if cap_rock_props and hasattr(cap_rock_props, 'lithology'):
                lithology_corrections = {
                    'sandstone': {'viscosity_factor': 1.0, 'bulk_modulus_factor': 1.0},
                    'limestone': {'viscosity_factor': 1.1, 'bulk_modulus_factor': 1.2},
                    'shale': {'viscosity_factor': 1.3, 'bulk_modulus_factor': 0.9},
                    'granite': {'viscosity_factor': 0.9, 'bulk_modulus_factor': 1.3},
                    'basalt': {'viscosity_factor': 0.8, 'bulk_modulus_factor': 1.4},
                    'andesite': {'viscosity_factor': 0.9, 'bulk_modulus_factor': 1.2},
                    'rhyolite': {'viscosity_factor': 1.0, 'bulk_modulus_factor': 1.1}
                }
                
                lithology = cap_rock_props.lithology.lower()
                corrections = lithology_corrections.get(lithology, {'viscosity_factor': 1.0, 'bulk_modulus_factor': 1.0})
            else:
                corrections = {'viscosity_factor': 1.0, 'bulk_modulus_factor': 1.0}
            
            # Enhanced fluid properties with corrections
            fluid_viscosity = 1e-3 * corrections['viscosity_factor']  # Pa·s
            fluid_bulk_modulus = 2.2e9 * corrections['bulk_modulus_factor']  # Pa
            
            # Multi-scale characteristic length calculation
            if porosity > 0:
                # Primary pore size (Kozeny-Carman)
                primary_pore_size = math.sqrt(permeability / porosity)
                
                # Secondary pore size (empirical correction for pore size distribution)
                porosity_factor = math.log10(porosity + 1e-10) / math.log10(0.4)  # Normalized to 40% porosity
                secondary_pore_size = primary_pore_size * (1 + 0.5 * porosity_factor)
                
                # Effective pore size (harmonic mean for flow resistance)
                effective_pore_size = 2 * primary_pore_size * secondary_pore_size / (primary_pore_size + secondary_pore_size)
            else:
                effective_pore_size = 1e-6  # Fallback for zero porosity
            
            # Enhanced Biot frequency calculation with multi-parameter coupling
            base_biot_freq = (permeability * fluid_bulk_modulus) / (fluid_viscosity * effective_pore_size**2)
            
            # Porosity-dependent corrections
            porosity_correction = 1.0
            if porosity > 0.25:  # High porosity correction
                porosity_correction *= (1 + 0.3 * (porosity - 0.25) / 0.25)
            elif porosity < 0.05:  # Low porosity correction
                porosity_correction *= (0.7 + 0.3 * porosity / 0.05)
            
            # Permeability-dependent corrections
            permeability_correction = 1.0
            log_perm = math.log10(permeability + 1e-20)
            if log_perm > -12:  # High permeability
                permeability_correction *= (1 + 0.2 * (log_perm + 12) / 6)
            elif log_perm < -18:  # Very low permeability
                permeability_correction *= (0.8 + 0.2 * (log_perm + 18) / 6)
            
            # Temperature and pressure corrections
            temperature_correction = 1.0
            pressure_correction = 1.0
            
            if cap_rock_props:
                temperature = getattr(cap_rock_props, 'temperature', 293)
                pressure = getattr(cap_rock_props, 'pressure', 1e5)
                
                # Temperature effect on frequency
                temp_ratio = temperature / 293
                temperature_correction = 1.0 + 0.15 * (temp_ratio - 1)
                
                # Pressure effect on frequency
                pressure_ratio = pressure / 1e5
                pressure_correction = 1.0 + 0.1 * math.log10(pressure_ratio) if pressure_ratio > 0 else 1.0
            
            # Final frequency calculation with all corrections
            corrected_frequency = (base_biot_freq * porosity_correction * permeability_correction * 
                                 temperature_correction * pressure_correction)
            
            # Apply geological uncertainty factor
            uncertainty_factor = 0.9 + 0.2 * min(porosity / 0.3, 1.0)  # Higher certainty for higher porosity
            final_frequency = corrected_frequency * uncertainty_factor
            
            # Clamp to physically reasonable range with enhanced bounds
            return max(1e-8, min(1e8, final_frequency))
        
        except Exception as e:
            self.logger.error(f"Enhanced empirical fluid frequency calculation failed: {e}")
            return await self._conservative_fluid_frequency_fallback(porosity, permeability)

    async def _conservative_fluid_frequency_fallback(self, porosity: float, permeability: float) -> float:
        """Conservative fallback calculation for fluid frequency"""
        try:
            # Very basic Biot frequency with conservative assumptions
            fluid_viscosity = 1e-3  # Pa·s (water)
            fluid_bulk_modulus = 2.2e9  # Pa (water)
            
            # Comprehensive poroelastic analysis using advanced methods
            comprehensive_analysis = await self._comprehensive_poroelastic_analysis(porosity, permeability, None, None)
            return comprehensive_analysis.get('biot_frequency', 1e-3)
        
        except Exception:
            # Ultimate fallback
            return 1e-3  # 1 mHz

    async def _calculate_advanced_spatial_context_features(self, coords: List[float], 
                                                          cap_rock_props: CapRockProperties = None) -> dict:
        """
        Calculate advanced spatial context features with comprehensive geospatial analysis,
        tectonic setting determination, geological province identification, and multi-scale
        spatial correlation analysis
        """
        try:
            lat, lon = coords[0], coords[1]
            spatial_features = {
                'latitude': lat,
                'longitude': lon
            }
            
            # Tier 1: Database-driven spatial context resolution
            db_spatial_context = await self._resolve_database_spatial_context(lat, lon)
            if db_spatial_context:
                spatial_features.update(db_spatial_context)
            
            # Tier 2: ML-based spatial feature engineering
            ml_spatial_features = await self._generate_ml_spatial_features(lat, lon, cap_rock_props)
            if ml_spatial_features:
                spatial_features.update(ml_spatial_features)
            
            # Tier 3: Volcanic system spatial context
            volcanic_spatial_context = await self._calculate_volcanic_spatial_context(lat, lon)
            if volcanic_spatial_context:
                spatial_features.update(volcanic_spatial_context)
            
            # Tier 4: Physics-based geospatial analysis
            physics_spatial_features = await self._analyze_physics_based_spatial_features(lat, lon, cap_rock_props)
            if physics_spatial_features:
                spatial_features.update(physics_spatial_features)
            
            # Tier 5: Enhanced empirical spatial context calculation
            empirical_spatial_features = await self._calculate_enhanced_empirical_spatial_features(lat, lon, cap_rock_props)
            spatial_features.update(empirical_spatial_features)
            
            return spatial_features
            
        except Exception as e:
            self.logger.error(f"Advanced spatial context calculation failed: {e}")
            # Conservative fallback
            return self._conservative_spatial_features_fallback(coords)

    async def _resolve_database_spatial_context(self, lat: float, lon: float) -> dict:
        """
        Database-driven spatial context resolution with tectonic plates, geological provinces,
        seismic zones, and regional stress field analysis
        """
        try:
            if hasattr(self, 'db_manager') and self.db_manager:
                query = """
                WITH spatial_point AS (
                    SELECT ST_Point(%s, %s) as location
                ),
                tectonic_context AS (
                    SELECT sp.location,
                        -- Tectonic plate identification
                        (SELECT plate_name FROM tectonic_plates tp 
                         WHERE ST_Within(sp.location, tp.geometry) LIMIT 1) as tectonic_plate,
                        
                        -- Distance to nearest plate boundary
                        (SELECT MIN(ST_Distance(sp.location, pb.geometry)) 
                         FROM plate_boundaries pb) as distance_to_plate_boundary,
                        
                        -- Plate boundary type (convergent, divergent, transform)
                        (SELECT boundary_type FROM plate_boundaries pb 
                         ORDER BY ST_Distance(sp.location, pb.geometry) LIMIT 1) as nearest_boundary_type
                    FROM spatial_point sp
                ),
                geological_context AS (
                    SELECT tc.*, 
                        -- Geological province
                        (SELECT province_name FROM geological_provinces gp 
                         WHERE ST_Within(tc.location, gp.geometry) LIMIT 1) as geological_province,
                        
                        -- Regional geology age
                        (SELECT AVG(age_ma) FROM geological_units gu 
                         WHERE ST_DWithin(tc.location, gu.centroid, 100000)) as regional_age_ma,
                        
                        -- Dominant lithology in region
                        (SELECT lithology FROM geological_units gu 
                         WHERE ST_DWithin(tc.location, gu.centroid, 50000)
                         GROUP BY lithology ORDER BY COUNT(*) DESC LIMIT 1) as regional_dominant_lithology
                    FROM tectonic_context tc
                ),
                seismic_context AS (
                    SELECT gc.*,
                        -- Seismic zone classification
                        (SELECT zone_class FROM seismic_zones sz 
                         WHERE ST_Within(gc.location, sz.geometry) LIMIT 1) as seismic_zone,
                        
                        -- Historical seismicity metrics
                        (SELECT AVG(magnitude) FROM earthquakes eq 
                         WHERE ST_DWithin(gc.location, eq.location, 200000) 
                         AND event_date > CURRENT_DATE - INTERVAL '50 years') as avg_magnitude_50yr,
                        
                        (SELECT COUNT(*) FROM earthquakes eq 
                         WHERE ST_DWithin(gc.location, eq.location, 100000) 
                         AND magnitude >= 4.0 AND event_date > CURRENT_DATE - INTERVAL '20 years') as earthquake_count_20yr
                    FROM geological_context gc
                ),
                stress_field_context AS (
                    SELECT sc.*,
                        -- Regional stress field orientation
                        (SELECT AVG(azimuth) FROM stress_measurements sm 
                         WHERE ST_DWithin(sc.location, sm.location, 150000)) as regional_stress_azimuth,
                        
                        -- Stress magnitude indicator
                        (SELECT AVG(stress_magnitude) FROM stress_measurements sm 
                         WHERE ST_DWithin(sc.location, sm.location, 150000)) as regional_stress_magnitude,
                        
                        -- Volcanic activity proximity
                        (SELECT MIN(ST_Distance(sc.location, v.location)) 
                         FROM volcanoes v WHERE v.status = 'active') as distance_to_active_volcano
                    FROM seismic_context sc
                ),
                elevation_context AS (
                    SELECT sfc.*,
                        -- Topographic features
                        ST_X(sfc.location) as longitude,
                        ST_Y(sfc.location) as latitude,
                        
                        -- Elevation and slope analysis (using DEM if available)
                        (SELECT AVG(elevation) FROM digital_elevation_model dem 
                         WHERE ST_DWithin(sfc.location, dem.location, 5000)) as local_elevation_m,
                        
                        (SELECT STDDEV(elevation) FROM digital_elevation_model dem 
                         WHERE ST_DWithin(sfc.location, dem.location, 10000)) as elevation_roughness,
                        
                        -- Distance to coast
                        (SELECT MIN(ST_Distance(sfc.location, c.geometry)) 
                         FROM coastlines c) as distance_to_coast
                    FROM stress_field_context sfc
                )
                SELECT 
                    tectonic_plate,
                    distance_to_plate_boundary,
                    nearest_boundary_type,
                    geological_province,
                    regional_age_ma,
                    regional_dominant_lithology,
                    seismic_zone,
                    COALESCE(avg_magnitude_50yr, 0) as avg_magnitude_50yr,
                    COALESCE(earthquake_count_20yr, 0) as earthquake_count_20yr,
                    COALESCE(regional_stress_azimuth, 0) as regional_stress_azimuth,
                    COALESCE(regional_stress_magnitude, 0) as regional_stress_magnitude,
                    COALESCE(distance_to_active_volcano, 1000000) as distance_to_active_volcano,
                    COALESCE(local_elevation_m, 0) as elevation_m,
                    COALESCE(elevation_roughness, 0) as topographic_roughness,
                    COALESCE(distance_to_coast, 1000000) as distance_to_coast_m
                FROM elevation_context;
                """
                
                result = await self.db_manager.execute_query(query, (lon, lat))
                
                if result and len(result) > 0:
                    db_result = result[0]
                    
                    # Convert database results to ML features
                    spatial_context = {
                        'tectonic_plate_encoded': hash(str(db_result.get('tectonic_plate', 'unknown'))) % 1000,
                        'distance_to_plate_boundary_km': (db_result.get('distance_to_plate_boundary', 1000000) or 1000000) / 1000,
                        'boundary_type_convergent': 1 if db_result.get('nearest_boundary_type') == 'convergent' else 0,
                        'boundary_type_divergent': 1 if db_result.get('nearest_boundary_type') == 'divergent' else 0,
                        'boundary_type_transform': 1 if db_result.get('nearest_boundary_type') == 'transform' else 0,
                        'geological_province_encoded': hash(str(db_result.get('geological_province', 'unknown'))) % 1000,
                        'regional_age_ma': db_result.get('regional_age_ma', 100) or 100,
                        'regional_lithology_encoded': hash(str(db_result.get('regional_dominant_lithology', 'unknown'))) % 100,
                        'seismic_zone_encoded': hash(str(db_result.get('seismic_zone', 'unknown'))) % 10,
                        'seismic_activity_magnitude': db_result.get('avg_magnitude_50yr', 0) or 0,
                        'seismic_activity_frequency': math.log10((db_result.get('earthquake_count_20yr', 1) or 1) + 1),
                        'regional_stress_azimuth_rad': math.radians(db_result.get('regional_stress_azimuth', 0) or 0),
                        'regional_stress_magnitude_mpa': (db_result.get('regional_stress_magnitude', 0) or 0) / 1e6,
                        'volcanic_proximity_km': (db_result.get('distance_to_active_volcano', 1000000) or 1000000) / 1000,
                        'elevation_m': db_result.get('elevation_m', 0) or 0,
                        'topographic_complexity': db_result.get('topographic_roughness', 0) or 0,
                        'coastal_proximity_km': (db_result.get('distance_to_coast_m', 1000000) or 1000000) / 1000
                    }
                    
                    self.logger.debug(f"Database spatial context resolution successful for ({lat}, {lon})")
                    return spatial_context
        
        except Exception as db_error:
            self.logger.debug(f"Database spatial context resolution failed: {db_error}")
        
        return {}

    async def _generate_ml_spatial_features(self, lat: float, lon: float, 
                                           cap_rock_props: CapRockProperties = None) -> dict:
        """
        ML-based spatial feature engineering with geographic embeddings,
        spatial autocorrelation analysis, and multi-scale geographic patterns
        """
        try:
            if hasattr(self, 'model_manager'):
                # Comprehensive spatial feature engineering
                base_spatial_features = {
                    'latitude': lat,
                    'longitude': lon,
                    'latitude_rad': math.radians(lat),
                    'longitude_rad': math.radians(lon),
                    'abs_latitude': abs(lat),
                    'abs_longitude': abs(lon),
                    'latitude_squared': lat**2,
                    'longitude_squared': lon**2,
                    'lat_lon_product': lat * lon,
                    'distance_from_equator': abs(lat),
                    'distance_from_prime_meridian': abs(lon),
                    'hemisphere_north': 1 if lat >= 0 else 0,
                    'hemisphere_east': 1 if lon >= 0 else 0
                }
                
                # Geographic coordinate transformations
                geographic_transforms = {
                    'utm_zone_estimate': int((lon + 180) / 6) + 1,
                    'polar_distance': math.sqrt(lat**2 + lon**2),
                    'angular_position': math.atan2(lat, lon),
                    'great_circle_distance_to_origin': math.sqrt(lat**2 + lon**2) * 111.32,  # km
                    'mercator_x': lon * 20037508.34 / 180,
                    'mercator_y': math.log(math.tan((90 + lat) * math.pi / 360)) * 20037508.34 / math.pi
                }
                
                # Geophysical coordinate relationships
                geophysical_features = {
                    'coriolis_parameter': 2 * 7.292115e-5 * math.sin(math.radians(lat)),  # Earth rotation effect
                    'solar_declination_proxy': await self._calculate_ml_based_climate_modeling(lat, lon, cap_rock_props),  # ML-based climate modeling
                    'magnetic_inclination_proxy': math.atan(2 * math.tan(math.radians(lat))),  # Magnetic field inclination
                    'gravity_variation': 9.780318 * (1 + 0.0053024 * (math.sin(math.radians(lat))**2) - 
                                                    0.0000058 * (math.sin(2 * math.radians(lat))**2)),
                    'crustal_thickness_proxy': await self._calculate_advanced_crustal_thickness(lat, lon, cap_rock_props),
                    'atmospheric_pressure_proxy': 1013.25 * (1 - 2.25577e-5 * abs(lat) * 100)**5.25588  # Elevation effect
                }
                
                # Multi-scale spatial patterns
                multiscale_patterns = {}
                for scale in [1, 5, 10, 50, 100]:  # Different geographic scales
                    scale_lat = lat / scale
                    scale_lon = lon / scale
                    multiscale_patterns.update({
                        f'spatial_pattern_{scale}_sin_lat': math.sin(2 * math.pi * scale_lat),
                        f'spatial_pattern_{scale}_cos_lat': math.cos(2 * math.pi * scale_lat),
                        f'spatial_pattern_{scale}_sin_lon': math.sin(2 * math.pi * scale_lon),
                        f'spatial_pattern_{scale}_cos_lon': math.cos(2 * math.pi * scale_lon),
                        f'spatial_interaction_{scale}': math.sin(2 * math.pi * scale_lat) * math.cos(2 * math.pi * scale_lon)
                    })
                
                # Combine all features
                all_spatial_features = {**base_spatial_features, **geographic_transforms, 
                                      **geophysical_features, **multiscale_patterns}
                
                # Use ML model to generate spatial embeddings
                spatial_embedding = await self.model_manager.predict(
                    'spatial_feature_encoder',
                    all_spatial_features
                )
                
                if spatial_embedding and 'spatial_embedding' in spatial_embedding:
                    # Add embedding features
                    embedding_vector = spatial_embedding['spatial_embedding']
                    if isinstance(embedding_vector, list) and len(embedding_vector) >= 5:
                        embedding_features = {
                            f'spatial_embed_{i}': embedding_vector[i] 
                            for i in range(min(10, len(embedding_vector)))
                        }
                        all_spatial_features.update(embedding_features)
                
                # Geographic clustering prediction
                cluster_prediction = await self.model_manager.predict(
                    'geographic_cluster_classifier',
                    all_spatial_features
                )
                
                if cluster_prediction and 'cluster_id' in cluster_prediction:
                    all_spatial_features['geographic_cluster'] = cluster_prediction['cluster_id']
                    all_spatial_features['cluster_confidence'] = cluster_prediction.get('confidence', 0.5)
                
                return all_spatial_features
        
        except Exception as ml_error:
            self.logger.debug(f"ML spatial feature generation failed: {ml_error}")
        
        return {}

    async def _calculate_volcanic_spatial_context(self, lat: float, lon: float) -> dict:
        """
        Volcanic system spatial context analysis with volcanic arc positioning,
        magma chamber proximity estimation, and volcanic hazard assessment
        """
        try:
            from .volcanic_system_module import VolcanicSystemAnalyzer
            volcanic_analyzer = VolcanicSystemAnalyzer()
            
            # Get volcanic spatial context
            volcanic_context = await volcanic_analyzer.get_spatial_volcanic_context(lat, lon)
            
            if volcanic_context:
                # Convert volcanic context to spatial features
                spatial_features = {
                    'volcanic_arc_proximity': volcanic_context.get('distance_to_volcanic_arc', 1000) / 100,  # Normalized
                    'volcanic_activity_density': volcanic_context.get('local_volcano_density', 0),
                    'magma_chamber_proximity': volcanic_context.get('estimated_magma_chamber_distance', 1000) / 100,
                    'volcanic_hazard_level': volcanic_context.get('hazard_level', 0),
                    'geothermal_gradient_proxy': volcanic_context.get('geothermal_gradient', 25) / 100,  # Normalized
                    'volcanic_gas_emission_proxy': volcanic_context.get('gas_emission_level', 0),
                    'lava_flow_risk': volcanic_context.get('lava_flow_susceptibility', 0),
                    'pyroclastic_flow_risk': volcanic_context.get('pyroclastic_flow_risk', 0),
                    'volcanic_ash_risk': volcanic_context.get('ash_fall_risk', 0),
                    'hydrothermal_activity': volcanic_context.get('hydrothermal_activity_level', 0)
                }
                
                return spatial_features
        
        except ImportError:
            self.logger.debug("Volcanic system module not available for spatial context")
        except Exception as volcanic_error:
            self.logger.debug(f"Volcanic spatial context calculation failed: {volcanic_error}")
        
        return {}

    async def _analyze_physics_based_spatial_features(self, lat: float, lon: float,
                                                     cap_rock_props: CapRockProperties = None) -> dict:
        """
        Advanced physics-based geospatial analysis with comprehensive geophysical modeling,
        tectonic stress fields, geodynamic processes, and multi-scale Earth system interactions
        
        Implements five-tier analysis:
        1. Database-driven geophysical field resolution
        2. ML-based geophysical feature prediction
        3. Volcanic system geophysical analysis  
        4. Comprehensive physics-based Earth modeling
        5. Enhanced empirical geophysical estimation
        """
        try:
            # Primary: Database-driven geophysical field resolution
            database_physics = await self._get_database_geophysical_fields(lat, lon, cap_rock_props)
            
            # Secondary: ML-based geophysical feature prediction
            ml_physics = await self._predict_ml_geophysical_features(lat, lon, cap_rock_props)
            
            # Tertiary: Volcanic system geophysical analysis
            volcanic_physics = await self._analyze_volcanic_geophysical_fields(lat, lon, cap_rock_props)
            
            # Quaternary: Comprehensive physics-based Earth modeling
            comprehensive_physics = await self._calculate_comprehensive_earth_physics(lat, lon, cap_rock_props)
            
            # Fallback: Enhanced empirical geophysical estimation
            empirical_physics = await self._calculate_enhanced_empirical_geophysics(lat, lon, cap_rock_props)
            
            # Ensemble integration with confidence weighting
            physics_ensembles = [
                (database_physics, 0.30),      # Highest weight - direct measurements
                (ml_physics, 0.25),            # ML predictions
                (volcanic_physics, 0.20),      # Volcanic system analysis
                (comprehensive_physics, 0.15), # Physics-based modeling
                (empirical_physics, 0.10)      # Fallback estimation
            ]
            
            # Merge all valid physics features with ensemble weighting
            final_physics_features = {}
            feature_weights = {}
            
            for physics_dict, weight in physics_ensembles:
                if physics_dict:
                    for feature, value in physics_dict.items():
                        if feature not in final_physics_features:
                            final_physics_features[feature] = 0.0
                            feature_weights[feature] = 0.0
                        
                        if value is not None and isinstance(value, (int, float)):
                            final_physics_features[feature] += value * weight
                            feature_weights[feature] += weight
            
            # Normalize by total weights
            for feature in final_physics_features:
                if feature_weights[feature] > 0:
                    final_physics_features[feature] /= feature_weights[feature]
            
            # Add comprehensive derived physics features
            derived_features = self._calculate_derived_physics_features(final_physics_features, lat, lon)
            final_physics_features.update(derived_features)
            
            self.logger.debug(f"Advanced physics-based analysis completed with {len(final_physics_features)} features")
            return final_physics_features
            
        except Exception as physics_error:
            self.logger.error(f"Advanced physics-based spatial analysis failed: {physics_error}")
            # Fallback to basic physics
            return await self._calculate_basic_physics_fallback(lat, lon, cap_rock_props)

    async def _get_database_geophysical_fields(self, lat: float, lon: float,
                                              cap_rock_props: CapRockProperties = None) -> dict:
        """Database-driven geophysical field resolution with comprehensive Earth model data"""
        
        try:
            if not hasattr(self, 'db') or not self.db:
                return {}
                
            # Comprehensive geophysical database query
            query = """
                SELECT 
                    gf.gravity_mgal,
                    gf.gravity_anomaly_mgal,
                    gf.magnetic_field_nt,
                    gf.magnetic_inclination_deg,
                    gf.magnetic_declination_deg,
                    gf.crustal_thickness_km,
                    gf.heat_flow_mw_m2,
                    gf.seismic_velocity_km_s,
                    gf.crustal_density_kg_m3,
                    gf.mantle_temperature_c,
                    gf.lithospheric_thickness_km,
                    gf.stress_field_mpa,
                    gf.strain_rate_per_year,
                    gf.geothermal_gradient_c_km,
                    ST_Distance(gf.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance_m,
                    td.plate_velocity_mm_yr,
                    td.convergence_rate_mm_yr,
                    td.spreading_rate_mm_yr,
                    sd.earthquake_magnitude_avg,
                    sd.earthquake_frequency_per_year,
                    vd.geothermal_activity_index,
                    vd.volcanic_activity_level
                FROM geophysical_fields gf
                LEFT JOIN tectonic_data td ON ST_DWithin(gf.location, td.location, 50000)
                LEFT JOIN seismic_data sd ON ST_DWithin(gf.location, sd.location, 50000)
                LEFT JOIN volcanic_data vd ON ST_DWithin(gf.location, vd.location, 50000)
                WHERE ST_DWithin(gf.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 200000)
                ORDER BY distance_m ASC
                LIMIT 50
            """
            
            results = await self.db.fetch(query, lon, lat, lon, lat)
            
            if results:
                # Weighted ensemble of geophysical measurements
                physics_features = {}
                total_weight = 0.0
                
                for row in results:
                    # Distance-based weighting
                    distance_weight = 1.0 / (1.0 + row['distance_m'] / 100000.0)
                    
                    # Accumulate weighted features
                    for field_name in ['gravity_mgal', 'gravity_anomaly_mgal', 'magnetic_field_nt',
                                     'magnetic_inclination_deg', 'magnetic_declination_deg',
                                     'crustal_thickness_km', 'heat_flow_mw_m2', 'seismic_velocity_km_s',
                                     'crustal_density_kg_m3', 'mantle_temperature_c', 'lithospheric_thickness_km',
                                     'stress_field_mpa', 'strain_rate_per_year', 'geothermal_gradient_c_km',
                                     'plate_velocity_mm_yr', 'convergence_rate_mm_yr', 'spreading_rate_mm_yr',
                                     'earthquake_magnitude_avg', 'earthquake_frequency_per_year',
                                     'geothermal_activity_index', 'volcanic_activity_level']:
                        
                        value = row.get(field_name)
                        if value is not None:
                            if field_name not in physics_features:
                                physics_features[field_name] = 0.0
                                physics_features[f'{field_name}_weight'] = 0.0
                            
                            physics_features[field_name] += value * distance_weight
                            physics_features[f'{field_name}_weight'] += distance_weight
                    
                    total_weight += distance_weight
                
                # Normalize by weights
                normalized_features = {}
                for field_name, value in physics_features.items():
                    if not field_name.endswith('_weight'):
                        weight_key = f'{field_name}_weight'
                        if weight_key in physics_features and physics_features[weight_key] > 0:
                            normalized_features[field_name] = value / physics_features[weight_key]
                
                # Add derived geophysical relationships
                if 'gravity_mgal' in normalized_features and 'crustal_thickness_km' in normalized_features:
                    normalized_features['isostatic_equilibrium_index'] = (
                        normalized_features['gravity_mgal'] / (normalized_features['crustal_thickness_km'] * 0.3)
                    )
                
                if 'magnetic_inclination_deg' in normalized_features and 'magnetic_declination_deg' in normalized_features:
                    normalized_features['magnetic_vector_magnitude'] = math.sqrt(
                        normalized_features['magnetic_inclination_deg']**2 + 
                        normalized_features['magnetic_declination_deg']**2
                    )
                
                self.logger.debug(f"Database geophysical fields: {len(normalized_features)} features from {len(results)} measurements")
                return normalized_features
                
        except Exception as e:
            self.logger.debug(f"Database geophysical fields query failed: {str(e)}")
            
        return {}

    async def _predict_ml_geophysical_features(self, lat: float, lon: float,
                                              cap_rock_props: CapRockProperties = None) -> dict:
        """ML-based geophysical feature prediction with ensemble Earth system modeling"""
        
        try:
            from backend.modules.model_manager import ModelManager
            model_manager = ModelManager()
            
            # Comprehensive feature vector for geophysical prediction
            features = {
                # Geographic coordinates and derived features
                'latitude': lat,
                'longitude': lon,
                'distance_from_equator': abs(lat),
                'distance_from_greenwich': abs(lon),
                'sin_lat': math.sin(math.radians(lat)),
                'cos_lat': math.cos(math.radians(lat)),
                'sin_lon': math.sin(math.radians(lon)),
                'cos_lon': math.cos(math.radians(lon)),
                'sin_2lat': math.sin(2 * math.radians(lat)),
                'cos_2lat': math.cos(2 * math.radians(lat)),
                'sin_2lon': math.sin(2 * math.radians(lon)),
                'cos_2lon': math.cos(2 * math.radians(lon)),
                
                # Earth system fundamentals
                'coriolis_parameter': 2 * 7.292115e-5 * math.sin(math.radians(lat)),
                'centrifugal_acceleration': (7.292115e-5)**2 * 6371000 * math.cos(math.radians(lat))**2,
                'gravitational_potential': -3.986004418e14 / (6371000 * math.sqrt(1 + 3 * math.sin(math.radians(lat))**2)),
                
                # Magnetic field proxies
                'magnetic_inclination_proxy': math.degrees(math.atan(2 * math.tan(math.radians(lat)))),
                'magnetic_intensity_proxy': math.sqrt(1 + 3 * math.sin(math.radians(lat))**2),
                'magnetic_declination_proxy': math.sin(math.radians(lon)) * 15.0,  # Approximate declination
                
                # Tectonic and geodynamic indicators
                'plate_boundary_proximity': self._estimate_plate_boundary_proximity(lat, lon),
                'ridge_proximity': self._estimate_ridge_proximity(lat, lon),
                'trench_proximity': self._estimate_trench_proximity(lat, lon),
                'hotspot_proximity': self._estimate_hotspot_proximity(lat, lon),
                
                # Multi-scale spatial patterns for Earth system processes
                'large_scale_convection': math.sin(lat * math.pi / 45) * math.cos(lon * math.pi / 90),
                'medium_scale_convection': math.sin(lat * math.pi / 15) * math.cos(lon * math.pi / 30),
                'local_scale_convection': math.sin(lat * math.pi / 5) * math.cos(lon * math.pi / 10),
                
                # Climate and surface process indicators
                'solar_irradiation_proxy': math.cos(math.radians(lat)),
                'seasonal_variation_proxy': math.sin(math.radians(lat)) * 0.23,  # Axial tilt effect
                'atmospheric_pressure_proxy': 1013.25 * (1 - 2.25577e-5 * abs(lat) * 100)**5.25588
            }
            
            # Add cap rock specific geophysical features
            if cap_rock_props:
                features.update({
                    'cap_density_geophysics': cap_rock_props.bulk_density,
                    'cap_porosity_geophysics': cap_rock_props.porosity,
                    'cap_permeability_log': math.log10(max(cap_rock_props.permeability, 1e-20)),
                    'cap_strength_geophysics': cap_rock_props.uniaxial_strength,
                    'cap_thickness_geophysics': cap_rock_props.thickness
                })
            
            # Ensemble ML prediction for multiple geophysical fields
            ml_predictions = {}
            
            # Gravity field prediction models
            gravity_models = ['gravity_rf', 'gravity_gb', 'gravity_nn']
            gravity_predictions = []
            for model_name in gravity_models:
                prediction = await model_manager.predict_async(model_name, features)
                if prediction is not None:
                    gravity_predictions.append(prediction)
            
            if gravity_predictions:
                ml_predictions['gravity_mgal'] = sum(gravity_predictions) / len(gravity_predictions)
                ml_predictions['gravity_anomaly_mgal'] = ml_predictions['gravity_mgal'] - 9806.65
            
            # Magnetic field prediction models
            magnetic_models = ['magnetic_field_rf', 'magnetic_field_gb', 'magnetic_field_nn']
            magnetic_predictions = []
            for model_name in magnetic_models:
                prediction = await model_manager.predict_async(model_name, features)
                if prediction is not None:
                    magnetic_predictions.append(prediction)
            
            if magnetic_predictions:
                ml_predictions['magnetic_field_nt'] = sum(magnetic_predictions) / len(magnetic_predictions)
            
            # Heat flow prediction models
            heat_flow_models = ['heat_flow_rf', 'heat_flow_gb', 'heat_flow_nn']
            heat_flow_predictions = []
            for model_name in heat_flow_models:
                prediction = await model_manager.predict_async(model_name, features)
                if prediction is not None:
                    heat_flow_predictions.append(prediction)
            
            if heat_flow_predictions:
                ml_predictions['heat_flow_mw_m2'] = sum(heat_flow_predictions) / len(heat_flow_predictions)
                ml_predictions['geothermal_gradient_c_km'] = await self._comprehensive_geothermal_modeling(lat, lon, ml_predictions['heat_flow_mw_m2'])
            
            # Crustal properties prediction
            crustal_models = ['crustal_properties_ensemble']
            crustal_prediction = await model_manager.predict_async('crustal_properties_ensemble', features)
            if crustal_prediction is not None:
                if isinstance(crustal_prediction, dict):
                    ml_predictions.update(crustal_prediction)
                else:
                    ml_predictions['crustal_thickness_km'] = crustal_prediction
            
            # Tectonic stress field prediction
            stress_models = ['stress_field_rf', 'stress_field_gb']
            stress_predictions = []
            for model_name in stress_models:
                prediction = await model_manager.predict_async(model_name, features)
                if prediction is not None:
                    stress_predictions.append(prediction)
            
            if stress_predictions:
                ml_predictions['stress_field_mpa'] = sum(stress_predictions) / len(stress_predictions)
            
            # Add derived ML-based features
            if 'gravity_mgal' in ml_predictions and 'crustal_thickness_km' in ml_predictions:
                ml_predictions['crustal_loading_factor'] = (
                    ml_predictions['gravity_mgal'] / (ml_predictions['crustal_thickness_km'] * 100)
                )
            
            if ml_predictions:
                self.logger.debug(f"ML geophysical predictions: {len(ml_predictions)} features")
                return ml_predictions
                
        except Exception as e:
            self.logger.debug(f"ML geophysical feature prediction failed: {str(e)}")
            
        return {}

