    async def _model_radiogenic_heat_production(self, lat: float, lon: float) -> Dict[str, Any]:
        """Radiogenic heat production modeling"""
        try:
            import numpy as np
            
            # Simplified radiogenic heat production based on crustal composition
            # Typical values for different crustal compositions
            heat_sources = {
                'uranium_ppm': 2.5,  # Average crustal uranium
                'thorium_ppm': 10.0,  # Average crustal thorium
                'potassium_percent': 2.8,  # Average crustal potassium
                'total_crustal_production_mw_m2': 0.0
            }
            
            # Calculate radiogenic heat production (simplified)
            # Using standard heat production rates
            u_heat_production = heat_sources['uranium_ppm'] * 0.0096  # μW/m³ per ppm U
            th_heat_production = heat_sources['thorium_ppm'] * 0.0026  # μW/m³ per ppm Th  
            k_heat_production = heat_sources['potassium_percent'] * 0.0033  # μW/m³ per % K
            
            total_heat_production_uw_m3 = u_heat_production + th_heat_production + k_heat_production
            
            # Convert to surface heat flow contribution (assuming 10 km enriched layer)
            enriched_layer_thickness_km = 10.0
            heat_flow_contribution_mw_m2 = (total_heat_production_uw_m3 * 
                                          enriched_layer_thickness_km * 1000.0 / 1e6)
            
            heat_sources['total_crustal_production_mw_m2'] = heat_flow_contribution_mw_m2
            
            return {
                'success': True,
                'heat_sources': heat_sources,
                'enriched_layer_thickness_km': enriched_layer_thickness_km,
                'modeling_method': 'radiogenic_crustal'
            }
            
        except Exception as e:
            self.logger.error(f"Radiogenic heat production modeling failed: {e}")
            return {'success': False}
    
