    async def _quantify_thermal_gradient_uncertainty(self, thermal_analysis: Dict, lat: float, lon: float) -> Dict[str, Any]:
        """Comprehensive uncertainty quantification for thermal gradient predictions"""
        try:
            import numpy as np
            
            uncertainties = {}
            
            # Model uncertainty (based on method diversity)
            available_methods = len([k for k in thermal_analysis.get('heat_sources', {}).keys()])
            model_uncertainty_c_km = max(2.0, 8.0 - available_methods)
            uncertainties['model_uncertainty_c_km'] = model_uncertainty_c_km
            
            # Data uncertainty (based on heat flow quality)
            data_uncertainty_c_km = 3.0  # Base uncertainty
            uncertainties['data_uncertainty_c_km'] = data_uncertainty_c_km
            
            # Structural uncertainty (geological complexity)
            geological_complexity = await self._assess_geological_complexity(lat, lon)
            structural_uncertainty = geological_complexity.get('complexity_factor', 1.0) * 2.0
            uncertainties['structural_uncertainty_c_km'] = structural_uncertainty
            
            # Total uncertainty (root sum of squares)
            total_uncertainty = np.sqrt(
                uncertainties.get('model_uncertainty_c_km', 3.0)**2 +
                uncertainties.get('data_uncertainty_c_km', 3.0)**2 +
                uncertainties.get('structural_uncertainty_c_km', 2.0)**2
            )
            
            # Calculate confidence
            gradient_c_km = thermal_analysis.get('surface_gradient_c_km', 25.0)
            uncertainty_ratio = total_uncertainty / gradient_c_km
            confidence = max(0.3, min(0.95, 1.0 - uncertainty_ratio / 2.0))
            
            uncertainty_bounds = {
                'lower_bound_c_km': max(5.0, gradient_c_km - 1.96 * total_uncertainty),
                'upper_bound_c_km': min(150.0, gradient_c_km + 1.96 * total_uncertainty),
                'total_uncertainty_c_km': total_uncertainty
            }
            
            return {
                'success': True,
                'uncertainty_bounds': uncertainty_bounds,
                'overall_confidence': confidence,
                'uncertainty_components': uncertainties
            }
            
        except Exception as e:
            self.logger.error(f"Thermal gradient uncertainty quantification failed: {e}")
            return {'success': False}
    
    async def _apply_tectonic_thermal_constraints(self, gradient_c_km: float, lat: float, lon: float) -> Dict[str, Any]:
        """Apply tectonic setting constraints to thermal gradients"""
        try:
            # Query tectonic setting
            tectonic_data = await self._comprehensive_tectonic_database_analysis([lat, lon])
            
            if tectonic_data.get('success', False):
                boundary_type = tectonic_data.get('boundary_type', 'passive')
                
                # Tectonic setting thermal constraints
                constraints = {
                    'convergent': {'min': 15.0, 'max': 80.0, 'typical': 35.0},
                    'divergent': {'min': 40.0, 'max': 120.0, 'typical': 65.0},
                    'transform': {'min': 20.0, 'max': 60.0, 'typical': 30.0},
                    'passive': {'min': 15.0, 'max': 45.0, 'typical': 25.0},
                    'complex': {'min': 20.0, 'max': 100.0, 'typical': 40.0}
                }
                
                setting_constraints = constraints.get(boundary_type, constraints['passive'])
                
                # Apply constraints
                constrained_gradient = max(setting_constraints['min'], 
                                         min(gradient_c_km, setting_constraints['max']))
                
                return {
                    'constrained_gradient': constrained_gradient,
                    'tectonic_setting': boundary_type,
                    'constraints_applied': True
                }
            else:
                return {'constrained_gradient': gradient_c_km, 'constraints_applied': False}
                
        except Exception as e:
            self.logger.error(f"Tectonic thermal constraints application failed: {e}")
            return {'constrained_gradient': gradient_c_km, 'constraints_applied': False}
    
    async def _enhanced_physics_based_thermal_fallback(self, heat_flow_mw_m2: float, lat: float, lon: float) -> float:
        """Enhanced physics-based thermal fallback using fundamental heat transfer principles"""
        try:
            import numpy as np
            
            # Enhanced thermal conductivity estimation based on location
            base_conductivity = 2.5  # W/m·K
            
            # Adjust conductivity based on tectonic setting (simplified)
            if abs(lat) > 60.0:  # High latitude (cratonic)
                thermal_conductivity = base_conductivity * 1.2
            elif abs(lat) < 30.0:  # Low latitude (often more mafic)
                thermal_conductivity = base_conductivity * 0.9
            else:
                thermal_conductivity = base_conductivity
            
            # Basic Fourier's law: q = -k * dT/dz
            gradient_c_km = (heat_flow_mw_m2 * 1e-3) / thermal_conductivity * 1000
            
            # Physics-based corrections
            # Radiogenic heat production (typical crustal values)
            radiogenic_contribution = 15.0  # mW/m² from 10km enriched crust
            corrected_mantle_flux = max(20.0, heat_flow_mw_m2 - radiogenic_contribution)
            
            # Recalculate gradient with corrected heat flow
            corrected_gradient = (corrected_mantle_flux * 1e-3) / thermal_conductivity * 1000
            
            # Add radiogenic gradient in upper crust (higher gradient in top 10km)
            radiogenic_gradient = (radiogenic_contribution * 1e-3) / (thermal_conductivity * 0.8) * 1000
            
            # Weighted average (assuming depth relevance)
            final_gradient = 0.6 * corrected_gradient + 0.4 * radiogenic_gradient
            
            # Apply enhanced physical bounds
            final_gradient = max(8.0, min(final_gradient, 100.0))
            
            return final_gradient
            
        except Exception as e:
            self.logger.error(f"Enhanced physics-based thermal fallback failed: {e}")
            return 25.0  # Ultimate fallback

    async def _volcanic_thermal_gradient_modeling(self, lat: float, lon: float, 
                                                volcanic_geophysics: dict) -> float:
        """Volcanic thermal gradient modeling using volcano modules"""
        try:
            # Base volcanic thermal enhancement
            thermal_anomaly = volcanic_geophysics.get('thermal_anomaly_c_km', 0)
            volcanic_activity = volcanic_geophysics.get('volcanic_activity_index', 0.1)
            
            # Use comprehensive geothermal modeling with volcanic enhancement
            base_heat_flow = volcanic_geophysics.get('surface_heat_flux_mw_m2', 80.0)
            
            # Volcanic enhancement factor
            volcanic_enhancement = 1.0 + volcanic_activity * 2.0  # Up to 3x enhancement
            enhanced_heat_flow = base_heat_flow * volcanic_enhancement
            
            # Apply comprehensive geothermal modeling
            gradient_c_km = await self._comprehensive_geothermal_modeling(lat, lon, enhanced_heat_flow)
            
            # Add direct thermal anomaly contribution
            total_gradient = gradient_c_km + thermal_anomaly
            
            return max(25.0, min(total_gradient, 150.0))  # Reasonable bounds for volcanic areas
            
        except Exception as e:
            self.logger.error(f"Volcanic thermal gradient modeling failed: {e}")
            return 50.0  # Default enhanced volcanic gradient

    async def _comprehensive_thermal_gradient_stress_modeling(self, lat: float, lon: float) -> float:
        """Comprehensive thermal gradient stress modeling using volcano modules"""
        try:
            # Get comprehensive geothermal gradient
            geothermal_gradient = await self._get_comprehensive_geothermal_gradient(lat, lon)
            
            # Convert gradient to stress using thermal expansion
            thermal_expansion = 3e-5  # /°C (typical rock thermal expansion)
            reference_temp = 15.0  # °C surface temperature
            depth_km = 5.0  # Representative depth for stress calculation
            
            # Temperature at depth
            temp_at_depth = reference_temp + geothermal_gradient * depth_km
            
            # Thermal stress from temperature gradient
            thermal_stress_pa = thermal_expansion * (temp_at_depth - reference_temp) * 30e9  # 30 GPa Young's modulus
            thermal_stress_mpa = thermal_stress_pa / 1e6  # Convert to MPa
            
            # Regional stress amplification
            latitude_factor = 1.0 + 0.3 * abs(math.sin(math.radians(lat * 2)))
            
            # Volcanic proximity enhancement
            volcanic_proximity = await self._estimate_volcanic_proximity(lat, lon)
            if volcanic_proximity < 50:  # Within 50 km of volcanic system
                volcanic_factor = 2.0 - (volcanic_proximity / 50.0)  # 1.0 to 2.0 enhancement
            else:
                volcanic_factor = 1.0
            
            total_stress = thermal_stress_mpa * latitude_factor * volcanic_factor
            
            return max(5.0, min(total_stress, 50.0))  # Reasonable stress bounds
            
        except Exception as e:
            self.logger.error(f"Comprehensive thermal gradient stress modeling failed: {e}")
            return 15.0  # Default thermal stress

    async def _get_comprehensive_geothermal_gradient(self, lat: float, lon: float) -> float:
        """Get comprehensive geothermal gradient using all available methods"""
        try:
            # Estimate typical heat flow for the region
            regional_heat_flow = await self._estimate_regional_heat_flow(lat, lon)
            
            # Use comprehensive geothermal modeling
            gradient_c_km = await self._comprehensive_geothermal_modeling(lat, lon, regional_heat_flow)
            
            return gradient_c_km
            
        except Exception as e:
            self.logger.error(f"Comprehensive geothermal gradient calculation failed: {e}")
            return 25.0  # Default gradient

    async def _estimate_regional_heat_flow(self, lat: float, lon: float) -> float:
        """Estimate regional heat flow based on tectonic setting"""
        try:
            # Classify tectonic setting
            tectonic_setting = await self._classify_regional_tectonic_setting(lat, lon)
            
            # Heat flow by tectonic setting
            if tectonic_setting == 'volcanic_arc':
                return 80.0  # Higher heat flow in volcanic regions
            elif tectonic_setting == 'cratonic':
                return 40.0  # Lower heat flow in stable cratons
            elif tectonic_setting == 'oceanic':
                return 60.0  # Moderate oceanic heat flow
            elif tectonic_setting == 'rift':
                return 100.0  # High heat flow in rift zones
            else:
                return 60.0  # Average continental heat flow
                
        except Exception as e:
            self.logger.error(f"Regional heat flow estimation failed: {e}")
            return 60.0

    async def _classify_regional_tectonic_setting(self, lat: float, lon: float) -> str:
        """Classify regional tectonic setting for thermal modeling"""
        try:
            # Check for volcanic proximity
            volcanic_proximity = await self._estimate_volcanic_proximity(lat, lon)
            if volcanic_proximity < 50:
                return 'volcanic_arc'
            
            # Check for cratonic regions (simplified by latitude)
            continental_factor = abs(lat) / 90.0
            if continental_factor > 0.7 and abs(lat) > 45:
                return 'cratonic'
            
            # Check for oceanic regions
            if continental_factor < 0.3:
                return 'oceanic'
            
            # Check for rift zones (simplified)
            if abs(lat) < 30 and 30 < abs(lon) < 60:  # Simplified African rift approximation
                return 'rift'
            
            return 'continental'
            
        except Exception as e:
            self.logger.error(f"Tectonic setting classification failed: {e}")
            return 'continental'

    async def _ml_geodynamic_prediction(self, lat: float, lon: float,
                                      cap_rock_props: dict) -> dict:
        """ML-based geodynamic process prediction with ensemble modeling"""
        try:
            # Feature engineering for geodynamic prediction
            features = await self._extract_geodynamic_ml_features(lat, lon, cap_rock_props)
            
            # Ensemble predictions
            predictions = []
            confidences = []
            
            # Random Forest geodynamic prediction
            rf_pred = await self._rf_geodynamic_prediction(features)
            if rf_pred.get('confidence', 0) > 0.6:
                predictions.append(rf_pred)
                confidences.append(rf_pred['confidence'])
            
            # Gradient Boosting geodynamic prediction
            gb_pred = await self._gb_geodynamic_prediction(features)
            if gb_pred.get('confidence', 0) > 0.6:
                predictions.append(gb_pred)
                confidences.append(gb_pred['confidence'])
            
            # Neural Network geodynamic prediction
            nn_pred = await self._nn_geodynamic_prediction(features)
            if nn_pred.get('confidence', 0) > 0.6:
                predictions.append(nn_pred)
                confidences.append(nn_pred['confidence'])
            
            if not predictions:
                return {'confidence': 0.0}
            
            # Ensemble weighting
            total_weight = sum(confidences)
            if total_weight == 0:
                return {'confidence': 0.0}
            
            # Weighted averages for key parameters
            plate_distance = sum(pred['plate_boundary_distance_km'] * conf for pred, conf in zip(predictions, confidences)) / total_weight
            ridge_prox = sum(pred['ridge_proximity_index'] * conf for pred, conf in zip(predictions, confidences)) / total_weight
            subduction_prox = sum(pred['subduction_proximity_index'] * conf for pred, conf in zip(predictions, confidences)) / total_weight
            transform_prox = sum(pred['transform_proximity_index'] * conf for pred, conf in zip(predictions, confidences)) / total_weight
            
            ensemble_confidence = min(0.9, sum(confidences) / len(predictions))
            uncertainty = plate_distance * (1.0 - ensemble_confidence) * 0.5
            
            # Generate stress tensor from ML prediction
            stress_tensor = np.zeros((3, 3))
            if ridge_prox > 0.5:
                stress_tensor[0, 0] = -ridge_prox * 10  # Extension
            if subduction_prox > 0.5:
                stress_tensor[1, 1] = subduction_prox * 20  # Compression
            if transform_prox > 0.5:
                stress_tensor[0, 1] = transform_prox * 8  # Shear
                stress_tensor[1, 0] = transform_prox * 8
            
            return {
                'plate_boundary_distance_km': plate_distance,
                'ridge_proximity_index': ridge_prox,
                'subduction_proximity_index': subduction_prox,
                'transform_proximity_index': transform_prox,
                'fracture_zone_proximity_index': (ridge_prox + transform_prox) * 0.5,
                'hotspot_proximity_index': max(0, ridge_prox - 0.3),
                'plate_motion_velocity_mm_yr': (ridge_prox + subduction_prox + transform_prox) * 30,
                'convergence_rate_mm_yr': subduction_prox * 50,
                'spreading_rate_mm_yr': ridge_prox * 40,
                'plate_age_ma': max(0, 200 - ridge_prox * 150),
                'lithospheric_thickness_km': 50 + 100 * (1 - ridge_prox),
                'geodynamic_stress_tensor': stress_tensor,
                'seismic_coupling_coefficient': subduction_prox * 0.8,
                'confidence': ensemble_confidence,
                'uncertainty_bounds': (plate_distance - uncertainty, plate_distance + uncertainty),
                'data_sources': ['ml_ensemble']
            }
            
        except Exception as e:
            self.logger.error(f"ML geodynamic prediction failed: {e}")
            return {'confidence': 0.0}

    async def _extract_geodynamic_ml_features(self, lat: float, lon: float,
                                            cap_rock_props: dict) -> np.ndarray:
        """Extract comprehensive features for geodynamic ML prediction"""
        try:
            features = []
            
            # Geographic features
            features.extend([lat, lon, abs(lat), lon % 180])
            
            # Distance from major tectonic features (approximate)
            features.extend([
                abs(lat),  # Distance from equator
                min(abs(lat - 60), abs(lat + 60)),  # Distance from major subduction zones
                abs(lon % 60),  # Distance from major ridge systems
                math.sqrt((lat - 30)**2 + (lon - 150)**2),  # Distance from Pacific Ring of Fire
                math.sqrt(lat**2 + lon**2)  # Distance from origin
            ])
            
            # Geological features
            elevation = cap_rock_props.get('elevation_m', 0)
            distance_to_coast = cap_rock_props.get('distance_to_coast_km', 100)
            features.extend([
                elevation / 5000.0,
                distance_to_coast / 1000.0,
                math.log10(max(1, elevation)),
                math.sqrt(max(0, distance_to_coast))
            ])
            
            # Tectonic proxies based on global patterns
            pacific_factor = max(0, 1 - abs(lon - 180) / 180)  # Pacific proximity
            atlantic_factor = max(0, 1 - min(abs(lon), abs(lon - 360)) / 60)  # Atlantic proximity
            features.extend([
                pacific_factor,
                atlantic_factor,
                pacific_factor * abs(lat / 90),  # Pacific Ring of Fire proxy
                atlantic_factor * (1 - abs(lat / 90))  # Atlantic Ridge proxy
            ])
            
            # Magnetic and gravity proxies
            magnetic_anomaly = 100 * math.sin(math.radians(lat * 2)) * math.cos(math.radians(lon))
            gravity_anomaly = 50 * math.cos(math.radians(lat)) * math.sin(math.radians(lon * 2))
            features.extend([
                magnetic_anomaly / 200.0,
                gravity_anomaly / 100.0
            ])
            
            # Age proxies (distance from ridges approximation)
            ridge_distance_proxy = min(abs(lon % 60), abs((lon + 30) % 60))
            age_proxy = ridge_distance_proxy * 3  # Rough age estimate
            features.extend([
                age_proxy / 200.0,
                math.exp(-ridge_distance_proxy / 20.0)  # Ridge proximity decay
            ])
            
            return np.array(features, dtype=np.float32)
            
        except Exception as e:
            self.logger.error(f"Geodynamic ML feature extraction failed: {e}")
            return np.zeros(25, dtype=np.float32)

