    async def _comprehensive_petrographic_grain_damage_analysis(self, coords: List[float],
                                                              cap_rock_props: CapRockProperties,
                                                              features: dict) -> dict:
        """Comprehensive petrographic grain size damage susceptibility analysis"""
        try:
            grain_analysis = await self._comprehensive_petrographic_grain_analysis(coords, cap_rock_props)
            # Normalize grain analysis to 0-1 scale for damage calculation
            normalized_grain_size = min(1.0, grain_analysis / 5.0)  # 5mm max for normalization
            damage_susceptibility_factor = 1.0 + 0.3 * (1 - normalized_grain_size)  # Finer grains → more damage
            return {'damage_susceptibility_factor': damage_susceptibility_factor}
        except Exception:
            # Fallback to features-based approach
            grain_size_feature = features.get('grain_size', 0.5)
            damage_susceptibility_factor = 1.0 + 0.3 * (1 - grain_size_feature)
            return {'damage_susceptibility_factor': damage_susceptibility_factor}
    
