    async def _get_physics_based_thermal_cycling(self, coords: List[float],
                                               cap_rock_props: CapRockProperties) -> Optional[Dict[str, float]]:
        """Physics-based thermal cycling modeling"""
        try:
            if not cap_rock_props:
                return None
            
            # Physics-based thermal cycling calculations
            cycling_params = {}
            
            # Thermal diffusion time scales
            thermal_diffusivity = (cap_rock_props.thermal_conductivity_w_m_k or 2.5) / (
                (cap_rock_props.density_g_cm3 or 2.5) * 1000 * 1000)  # m²/s
            
            depth_m = (cap_rock_props.depth_km or 1.0) * 1000
            
            # Characteristic thermal diffusion time
            thermal_time_scale = depth_m**2 / thermal_diffusivity  # seconds
            
            # Thermal cycling frequency from diffusion time
            cycling_params['cycle_frequency'] = min(1e-2, max(1e-8, 1.0 / thermal_time_scale))
            
            # Temperature range from geothermal gradient and material properties
            geothermal_gradient = await self._get_comprehensive_geothermal_gradient(lat, lon) / 1000.0  # Convert C/km to C/m
            surface_temp = 15.0  # °C
            depth_temp = surface_temp + geothermal_gradient * depth_m
            
            # Thermal cycling amplitude (fraction of total temperature difference)
            cycling_fraction = 0.1  # Typically 10% of total temperature difference
            temperature_range = max(5.0, (depth_temp - surface_temp) * cycling_fraction)
            
            cycling_params['temperature_range'] = temperature_range
            
            # Thermal stress amplitude from thermal expansion
            thermal_expansion = cap_rock_props.thermal_expansion_per_k or 2e-5  # K⁻¹
            elastic_modulus = (cap_rock_props.elastic_modulus_gpa or 50.0) * 1e9  # Pa
            
            # Maximum thermal stress (constrained thermal expansion)
            thermal_stress = thermal_expansion * elastic_modulus * temperature_range
            cycling_params['thermal_stress_amplitude'] = min(1e9, max(1e6, thermal_stress))
            
            # Realistic geological aging and accumulated cycles calculation
            aging_analysis = await self._calculate_realistic_geological_aging(
                coords, cap_rock_props, cycling_params)
            
            accumulated_cycles = aging_analysis['total_accumulated_cycles']
            
            cycling_params['accumulated_cycles'] = min(1e8, max(100, accumulated_cycles))
            
            return cycling_params
            
        except Exception as e:
            self.logger.debug(f"Physics-based thermal cycling calculation failed: {e}")
            return None
    
    async def _get_enhanced_empirical_thermal_cycling(self, coords: List[float],
                                                    cap_rock_props: CapRockProperties) -> Dict[str, float]:
        """Enhanced empirical thermal cycling with comprehensive corrections"""
        try:
            # Enhanced baseline parameters based on geological setting
            base_params = {
                'temperature_range': 50.0,    # °C
                'cycle_frequency': 1e-5,      # Hz (daily cycles)
                'accumulated_cycles': 1e3,     # Total cycles
                'thermal_stress_amplitude': 1e7  # Pa
            }
            
            # Depth-dependent corrections
            if cap_rock_props and cap_rock_props.depth_km:
                depth_factor = 1.0 + np.log10(max(0.1, cap_rock_props.depth_km))
                base_params['temperature_range'] *= depth_factor
                base_params['thermal_stress_amplitude'] *= depth_factor
                # Deeper = slower cycling
                base_params['cycle_frequency'] /= depth_factor
            
            # Lithology-dependent corrections
            if cap_rock_props and cap_rock_props.lithology:
                lithology = cap_rock_props.lithology.lower()
                lithology_factors = {
                    'granite': {'temp_mult': 1.2, 'stress_mult': 1.3, 'freq_mult': 0.8},
                    'rhyolite': {'temp_mult': 1.5, 'stress_mult': 1.4, 'freq_mult': 1.2},
                    'dacite': {'temp_mult': 1.3, 'stress_mult': 1.2, 'freq_mult': 1.0},
                    'andesite': {'temp_mult': 1.1, 'stress_mult': 1.1, 'freq_mult': 0.9},
                    'basalt': {'temp_mult': 0.9, 'stress_mult': 0.9, 'freq_mult': 0.7},
                    'altered_volcanic': {'temp_mult': 0.7, 'stress_mult': 0.6, 'freq_mult': 0.5}
                }
                
                factors = lithology_factors.get(lithology, {'temp_mult': 1.0, 'stress_mult': 1.0, 'freq_mult': 1.0})
                base_params['temperature_range'] *= factors['temp_mult']
                base_params['thermal_stress_amplitude'] *= factors['stress_mult']
                base_params['cycle_frequency'] *= factors['freq_mult']
            
            # Porosity and fracturing corrections
            if cap_rock_props and cap_rock_props.porosity:
                # Higher porosity = reduced thermal cycling effectiveness
                porosity_factor = 1.0 - min(0.5, cap_rock_props.porosity * 2.0)
                base_params['thermal_stress_amplitude'] *= porosity_factor
            
            if cap_rock_props and cap_rock_props.fracture_density_per_m3:
                # Fractures provide thermal relief, reducing stress but increasing cycling
                fracture_factor = 1.0 / (1.0 + cap_rock_props.fracture_density_per_m3 / 10.0)
                base_params['thermal_stress_amplitude'] *= fracture_factor
                base_params['cycle_frequency'] *= (2.0 - fracture_factor)  # More frequent cycling
            
            # Alteration effects
            if cap_rock_props and cap_rock_props.alteration_minerals:
                alteration_intensity = sum(cap_rock_props.alteration_minerals.values())
                # Alteration reduces thermal cycling intensity
                alteration_factor = 1.0 / (1.0 + alteration_intensity * 1.5)
                base_params['thermal_stress_amplitude'] *= alteration_factor
                base_params['temperature_range'] *= alteration_factor
            
            # Advanced regional volcanic activity estimation with comprehensive analysis
            if coords:
                regional_analysis = await self._calculate_advanced_regional_volcanic_activity(
                    coords, cap_rock_props)
                
                # Apply regional corrections to thermal cycling parameters
                for param_key, correction_factor in regional_analysis['correction_factors'].items():
                    if param_key in base_params:
                        base_params[param_key] *= correction_factor
            
            # Time-scale corrections for accumulated cycles
            time_scale_years = 1e4  # 10,000 years
            annual_cycles = base_params['cycle_frequency'] * 365 * 24 * 3600
            base_params['accumulated_cycles'] = max(100, min(1e8, annual_cycles * time_scale_years))
            
            # Ensure all parameters are within reasonable bounds
            final_params = {
                'temperature_range': max(5.0, min(500.0, base_params['temperature_range'])),
                'cycle_frequency': max(1e-8, min(1e-2, base_params['cycle_frequency'])),
                'accumulated_cycles': max(100, min(1e8, base_params['accumulated_cycles'])),
                'thermal_stress_amplitude': max(1e6, min(1e9, base_params['thermal_stress_amplitude'])),
                'confidence_score': 0.6  # Medium confidence for empirical estimates
            }
            
            return final_params
            
        except Exception as e:
            self.logger.warning(f"Enhanced empirical thermal cycling failed: {e}")
            # Ultimate fallback
            return {
                'temperature_range': 50.0,
                'cycle_frequency': 1e-5,
                'accumulated_cycles': 1e3,
                'thermal_stress_amplitude': 1e7,
                'confidence_score': 0.3
            }
    
    def _calculate_thermal_expansion_mismatch(self, temperature_c: float,
                                            cap_rock_props: CapRockProperties,
                                            stress_tensor: Dict = None) -> Dict[str, float]:
        """Calculate thermal expansion mismatch effects"""
        
        # Temperature differential from reference
        T_ref = 25  # °C
        delta_T = temperature_c - T_ref
        
        if delta_T <= 0:
            return {'mismatch_factor': 1.0}
        
        # Thermal expansion coefficient
        alpha = cap_rock_props.thermal_expansion_per_k
        
        # Thermal strain
        thermal_strain = alpha * delta_T
        
        # Mineral composition effects (approximate)
        # Different minerals have different expansion coefficients
        lithology = cap_rock_props.lithology.lower()
        
        # Thermal expansion anisotropy factor
        anisotropy_factors = {
            'granite': 1.5,      # High quartz content - anisotropic expansion
            'rhyolite': 1.3,
            'dacite': 1.2,
            'andesite': 1.1,
            'altered_volcanic': 2.0  # Clay minerals - highly anisotropic
        }
        
        anisotropy_factor = anisotropy_factors.get(lithology, 1.2)
        
        # Mismatch stress (approximate)
        E = cap_rock_props.elastic_modulus_gpa * 1e3  # MPa
        mismatch_stress = E * thermal_strain * (anisotropy_factor - 1.0)
        
        # Mismatch acceleration factor
        if mismatch_stress < 10:  # MPa
            mismatch_factor = 1.0
        else:
            mismatch_factor = 1.0 + (mismatch_stress / 100)**0.5  # Square root dependence
        
        return {
            'mismatch_factor': min(3.0, mismatch_factor),
            'thermal_strain': thermal_strain,
            'mismatch_stress_mpa': mismatch_stress,
            'anisotropy_factor': anisotropy_factor,
            'delta_temperature': delta_T
        }
    
    async def _calculate_phase_transition_effects(self, temperature_c: float,
                                                 cap_rock_props: CapRockProperties,
                                                 coords: List[float] = None) -> Dict[str, float]:
        """Calculate phase transition effects on thermal fatigue"""
        
        phase_effects = {'transition_factor': 1.0}
        
        try:
            # Common phase transitions in volcanic rocks
            transitions = []
            
            # Quartz alpha-beta transition (573°C)
            if 550 <= temperature_c <= 600:
                quartz_effect = 1.0 + 0.5 * np.exp(-(temperature_c - 573)**2 / 100)
                transitions.append(('quartz_alpha_beta', quartz_effect))
            
            # Feldspar structural transitions (variable, ~400-800°C)
            if 400 <= temperature_c <= 800:
                feldspar_effect = 1.0 + 0.2 * np.sin(np.pi * (temperature_c - 400) / 400)**2
                transitions.append(('feldspar_structural', feldspar_effect))
            
            # Clay mineral dehydration (100-500°C)
            alteration_minerals = cap_rock_props.alteration_minerals or {}
            clay_content = sum(alteration_minerals.get(mineral, 0) 
                             for mineral in ['kaolinite', 'montmorillonite', 'illite'])
            
            if clay_content > 0 and 100 <= temperature_c <= 500:
                dehydration_effect = 1.0 + clay_content * 2.0 * np.exp(-(temperature_c - 300)**2 / 10000)
                transitions.append(('clay_dehydration', dehydration_effect))
            
            # Water vaporization (100°C at 1 atm, higher at pressure)
            if coords:
                depth_km = abs(coords[2])
                pressure_mpa = depth_km * 27  # Lithostatic pressure
                boiling_point = 100 + pressure_mpa * 3  # Approximate pressure dependence
                
                if abs(temperature_c - boiling_point) < 20:
                    vaporization_effect = 1.0 + 1.0 * np.exp(-(temperature_c - boiling_point)**2 / 100)
                    transitions.append(('water_vaporization', vaporization_effect))
            
            # Combined transition effect
            if transitions:
                total_effect = 1.0
                for name, effect in transitions:
                    total_effect *= effect
                
                phase_effects['transition_factor'] = min(5.0, total_effect)
                phase_effects['active_transitions'] = dict(transitions)
            
        except Exception as e:
            self.logger.warning(f"Phase transition calculation failed: {e}")
        
        return phase_effects
    
    def _calculate_thermal_shock_effects(self, temperature_c: float,
                                        cap_rock_props: CapRockProperties,
                                        stress_tensor: Dict = None) -> Dict[str, float]:
        """Calculate thermal shock effects"""
        
        # Thermal shock resistance parameter
        # R = σt·k / (α·E) where σt=tensile strength, k=thermal conductivity, 
        # α=thermal expansion, E=elastic modulus
        
        sigma_t = cap_rock_props.tensile_strength_mpa * 1e6  # Pa
        k = cap_rock_props.thermal_conductivity_w_m_k  # W/m·K
        alpha = cap_rock_props.thermal_expansion_per_k  # /K
        E = cap_rock_props.elastic_modulus_gpa * 1e9  # Pa
        
        if alpha > 0 and E > 0:
            thermal_shock_resistance = (sigma_t * k) / (alpha * E)
        else:
            thermal_shock_resistance = 1.0
        
        # Temperature gradient severity (approximate)
        if stress_tensor and stress_tensor.get('thermal_gradient_k_m'):
            thermal_gradient = stress_tensor.get('thermal_gradient_k_m', 0.025)  # K/m
        else:
            thermal_gradient = 0.025  # Typical geothermal gradient
        
        # Critical temperature difference for thermal shock
        critical_delta_T = thermal_shock_resistance / (alpha * E / sigma_t) if sigma_t > 0 else 1000
        
        # Actual temperature difference (estimated)
        surface_temp = 15  # °C
        delta_T = temperature_c - surface_temp
        
        # Thermal shock factor
        if delta_T < critical_delta_T:
            shock_factor = 1.0
        else:
            shock_factor = 1.0 + (delta_T / critical_delta_T - 1.0)**2  # Quadratic increase
        
        return {
            'shock_factor': min(4.0, shock_factor),
            'thermal_shock_resistance': thermal_shock_resistance,
            'critical_delta_T': critical_delta_T,
            'actual_delta_T': delta_T,
            'thermal_gradient': thermal_gradient
        }
    
    def _calculate_water_vapor_effects(self, temperature_c: float,
                                      cap_rock_props: CapRockProperties,
                                      stress_tensor: Dict = None) -> Dict[str, float]:
        """Calculate water vapor effects on thermal fatigue"""
        
        vapor_effects = {'vapor_factor': 1.0}
        
        # Pore pressure from water vaporization
        pore_pressure = stress_tensor.get('pore_pressure_mpa', 0) if stress_tensor else 0
        
        if temperature_c > 100 and pore_pressure > 0:
            # Water vapor pressure using Antoine equation for accurate calculation
            # Antoine equation: log10(P_mmHg) = A - B/(C + T_celsius)
            # Constants for water (valid 1-100°C, extended for geological temps)
            
            if temperature_c <= 374.0:  # Below critical point
                # Antoine equation for water vapor pressure
                A, B, C = 8.07131, 1730.63, 233.426  # Antoine constants for water
                log_p_mmhg = A - B / (C + temperature_c)
                vapor_pressure_mmhg = 10**log_p_mmhg
                vapor_pressure_mpa = vapor_pressure_mmhg * 0.000133322  # Convert mmHg to MPa
            else:
                # Above critical point - use Wagner-Pruss equation of state for supercritical water
                # High-accuracy formulation for water properties at extreme conditions
                T_critical = 647.096  # Critical temperature in Kelvin
                P_critical = 22.064   # Critical pressure in MPa
                
                # Convert to Kelvin and calculate reduced properties
                T_kelvin = temperature_c + 273.15
                tau = T_critical / T_kelvin  # Inverse reduced temperature
                
                # Wagner-Pruss equation coefficients for supercritical region
                # Simplified form for geological applications (high T, variable P)
                if T_kelvin <= 1273.15:  # Up to 1000°C
                    # Polynomial fit to NIST data for supercritical water vapor pressure
                    T_reduced = T_kelvin / T_critical
                    ln_pr = (
                        -7.85951783 * (1 - 1/T_reduced) +
                        1.84408259 * (1 - 1/T_reduced)**1.5 +
                        -11.7866497 * (1 - 1/T_reduced)**3 +
                        22.6807411 * (1 - 1/T_reduced)**3.5 +
                        -15.9618719 * (1 - 1/T_reduced)**4 +
                        1.80122502 * (1 - 1/T_reduced)**7.5
                    )
                    vapor_pressure_mpa = P_critical * np.exp(ln_pr * T_critical / T_kelvin)
                else:
                    # Extreme high temperature extrapolation
                    # Based on ideal gas behavior with real gas corrections
                    T_reduced = T_kelvin / T_critical
                    vapor_pressure_mpa = P_critical * (T_reduced**1.2) * np.exp(-2000/T_kelvin)
            
            # Effective vapor pressure (limited by available pore water)
            # Cannot exceed pore pressure significantly due to mass balance
            max_vapor_pressure = pore_pressure * 2.0  # Allow some overpressure
            effective_vapor_pressure = min(vapor_pressure_mpa, max_vapor_pressure)
            
            # Vapor expansion effect
            porosity = cap_rock_props.porosity
            permeability = cap_rock_props.permeability_m2
            
            # High porosity and permeability allow more vapor effects
            vapor_accessibility = porosity * min(1.0, np.log10(permeability + 1e-20) / (-10))
            
            # Vapor-induced stress
            vapor_stress = effective_vapor_pressure * vapor_accessibility
            
            # Acceleration factor
            vapor_factor = 1.0 + vapor_stress / 10  # Linear with vapor stress
            
            vapor_effects = {
                'vapor_factor': min(3.0, vapor_factor),
                'vapor_pressure_mpa': vapor_pressure_mpa,
                'effective_vapor_pressure': effective_vapor_pressure,
                'vapor_accessibility': vapor_accessibility,
                'vapor_stress': vapor_stress
            }
        
        return vapor_effects
    
    def _combine_thermal_effects(self, thermal_effects: Dict, temperature_c: float) -> float:
        """Combine multiple thermal effects into single factor"""
        
        # Extract individual factors
        cycling_factor = thermal_effects.get('cycling_fatigue', {}).get('cycling_factor', 1.0)
        mismatch_factor = thermal_effects.get('expansion_mismatch', {}).get('mismatch_factor', 1.0)
        transition_factor = thermal_effects.get('phase_transitions', {}).get('transition_factor', 1.0)
        shock_factor = thermal_effects.get('thermal_shock', {}).get('shock_factor', 1.0)
        vapor_factor = thermal_effects.get('vapor_effects', {}).get('vapor_factor', 1.0)
        
        # Temperature regime weighting
        if temperature_c < 200:
            # Low temperature - minimal thermal effects
            weights = [0.5, 0.3, 0.1, 0.1, 0.0]  # [cycling, mismatch, transition, shock, vapor]
        elif temperature_c < 400:
            # Moderate temperature
            weights = [0.3, 0.3, 0.2, 0.1, 0.1]
        elif temperature_c < 600:
            # High temperature
            weights = [0.2, 0.2, 0.3, 0.2, 0.1]
        else:
            # Very high temperature
            weights = [0.1, 0.2, 0.3, 0.3, 0.1]
        
        # Weighted combination
        factors = [cycling_factor, mismatch_factor, transition_factor, shock_factor, vapor_factor]
        combined_factor = sum(w * f for w, f in zip(weights, factors))
        
        return max(0.1, combined_factor)
    
    async def _calculate_environmental_thermal_amplification(self, temperature_c: float,
                                                            cap_rock_props: CapRockProperties,
                                                            coords: List[float] = None) -> Dict[str, float]:
        """Calculate environmental amplification of thermal effects"""
        
        amplification = {'amplification_factor': 1.0}
        
        try:
            # Volcanic gas amplification
            if coords and self.volcanic_chamber_system:
                gas_amplification = await self._calculate_gas_thermal_amplification(coords, temperature_c)
                amplification['gas_amplification'] = gas_amplification
            else:
                gas_amplification = 1.0
            
            # Hydrothermal alteration amplification
            alteration_amplification = self._calculate_alteration_thermal_amplification(
                cap_rock_props, temperature_c
            )
            amplification['alteration_amplification'] = alteration_amplification
            
            # Depth/pressure amplification
            depth_amplification = self._calculate_depth_thermal_amplification(coords, temperature_c)
            amplification['depth_amplification'] = depth_amplification
            
            # Combined amplification
            total_amplification = gas_amplification * alteration_amplification * depth_amplification
            amplification['amplification_factor'] = min(5.0, max(0.5, total_amplification))
            
        except Exception as e:
            self.logger.warning(f"Environmental thermal amplification calculation failed: {e}")
        
        return amplification
    
    async def _calculate_gas_thermal_amplification(self, coords: List[float], temperature_c: float) -> float:
        """Calculate gas-enhanced thermal amplification"""
        
        try:
            x, y, z = coords
            chamber_data = await self.volcanic_chamber_system.get_nearest_chambers(
                x=x, y=y, z=z, search_radius_km=10
            )
            
            if not chamber_data:
                return 1.0
            
            chamber = chamber_data[0]
            volatile_content = chamber.get('volatile_content', {})
            
            # Temperature-dependent gas reactivity
            h2o_reactivity = volatile_content.get('H2O_wt_percent', 0) * (1 + temperature_c / 500)
            co2_reactivity = volatile_content.get('CO2_wt_percent', 0) * (1 + temperature_c / 1000)
            so2_reactivity = volatile_content.get('SO2_wt_percent', 0) * (1 + temperature_c / 300)
            
            total_gas_effect = 1.0 + (h2o_reactivity + co2_reactivity + so2_reactivity) * 0.1
            
            return min(2.0, total_gas_effect)
            
        except Exception as e:
            self.logger.warning(f"Gas thermal amplification calculation failed: {e}")
            return 1.0
    
    def _calculate_alteration_thermal_amplification(self, cap_rock_props: CapRockProperties,
                                                   temperature_c: float) -> float:
        """Calculate hydrothermal alteration thermal amplification"""
        
        alteration_minerals = cap_rock_props.alteration_minerals or {}
        
        # Temperature-sensitive alteration minerals
        clay_content = sum(alteration_minerals.get(mineral, 0) 
                          for mineral in ['kaolinite', 'montmorillonite', 'illite'])
        
        zeolite_content = alteration_minerals.get('zeolites', 0)
        sulfate_content = alteration_minerals.get('gypsum', 0) + alteration_minerals.get('anhydrite', 0)
        
        # Temperature-dependent alteration effects
        if temperature_c > 100:
            clay_amplification = 1.0 + clay_content * (temperature_c - 100) / 1000
            zeolite_amplification = 1.0 + zeolite_content * (temperature_c - 100) / 500
            sulfate_amplification = 1.0 + sulfate_content * (temperature_c - 100) / 200
        else:
            clay_amplification = zeolite_amplification = sulfate_amplification = 1.0
        
        total_alteration_effect = clay_amplification * zeolite_amplification * sulfate_amplification
        
        return min(2.5, total_alteration_effect)
    
    def _calculate_depth_thermal_amplification(self, coords: List[float] = None,
                                              temperature_c: float = 200) -> float:
        """Calculate depth-dependent thermal amplification"""
        
        if not coords:
            return 1.0
        
        depth_km = abs(coords[2])
        
        # Confining pressure effects on thermal processes
        # Higher confining pressure can suppress some thermal effects but enhance others
        
        if depth_km < 1:
            # Shallow depth - surface effects dominate
            depth_factor = 1.2  # Enhanced thermal cycling
        elif depth_km < 5:
            # Intermediate depth
            depth_factor = 1.0 + 0.1 * (5 - depth_km)  # Linear decrease
        else:
            # Deep - confining pressure suppresses some thermal effects
            depth_factor = 0.9
        
        return max(0.5, min(1.5, depth_factor))
    
    def _classify_temperature_regime(self, temperature_c: float) -> str:
        """Classify temperature regime for thermal effects"""
        
        if temperature_c < 100:
            return 'ambient'
        elif temperature_c < 200:
            return 'low_temperature'
        elif temperature_c < 400:
            return 'moderate_temperature'
        elif temperature_c < 600:
            return 'high_temperature'
        else:
            return 'extreme_temperature'
    
    def _identify_dominant_thermal_mechanism(self, thermal_effects: Dict) -> str:
        """Identify dominant thermal mechanism"""
        
        mechanisms = {
            'cycling_fatigue': thermal_effects.get('cycling_fatigue', {}).get('cycling_factor', 1.0),
            'expansion_mismatch': thermal_effects.get('expansion_mismatch', {}).get('mismatch_factor', 1.0),
            'phase_transitions': thermal_effects.get('phase_transitions', {}).get('transition_factor', 1.0),
            'thermal_shock': thermal_effects.get('thermal_shock', {}).get('shock_factor', 1.0),
            'vapor_effects': thermal_effects.get('vapor_effects', {}).get('vapor_factor', 1.0)
        }
        
        # Find mechanism with highest factor
        dominant = max(mechanisms, key=mechanisms.get)
        
        return dominant
    
    def _assess_thermal_calculation_confidence(self, thermal_effects: Dict) -> float:
        """Assess confidence in thermal calculations"""
        
        # Base confidence
        confidence = 0.7
        
        # Reduce confidence if many mechanisms are active (more complex)
        active_mechanisms = sum(1 for effect in thermal_effects.values() 
                               if isinstance(effect, dict) and 
                               any(v > 1.1 for v in effect.values() if isinstance(v, (int, float))))
        
        if active_mechanisms > 3:
            confidence *= 0.8
        elif active_mechanisms > 2:
            confidence *= 0.9
        
        # Increase confidence if we have volcanic system data
        if self.volcanic_chamber_system:
            confidence *= 1.1
        
        return min(1.0, confidence)
    
    async def _fallback_thermal_fatigue_calculation(self, temperature_c: float,
                                                   cap_rock_props: CapRockProperties) -> Dict[str, float]:
        """Fallback thermal fatigue calculation"""
        
        # Enhanced simple calculation
        T_ref = 25  # °C
        
        if temperature_c <= T_ref:
            fatigue_factor = 1.0
        else:
            # Non-linear temperature dependence
            temp_diff = temperature_c - T_ref
            
            # Base factor with exponential growth
            base_factor = 1.0 + (temp_diff / 200)**1.5  # Power law
            
            # Thermal expansion sensitivity
            alpha = cap_rock_props.thermal_expansion_per_k
            expansion_enhancement = 1.0 + alpha * 1e5 * 0.5
            
            fatigue_factor = base_factor * expansion_enhancement
        
        return {
            'thermal_fatigue_factor': min(5.0, fatigue_factor),
            'temperature_regime': self._classify_temperature_regime(temperature_c),
            'confidence': 0.4  # Lower confidence for fallback
        }
    
    async def _calculate_subcritical_crack_velocity(self, stress_tensor: Dict, cap_rock_props: CapRockProperties,
                                                   coords: List[float] = None) -> Dict[str, float]:
        """Calculate subcritical crack growth velocity using stress corrosion"""
        
        try:
            # Stress corrosion parameters
            K_threshold = await self._estimate_stress_corrosion_threshold(cap_rock_props, stress_tensor)
            stress_intensity = self._calculate_effective_stress_intensity(stress_tensor, cap_rock_props)
            
            if stress_intensity <= K_threshold:
                return {'velocity': 0, 'mechanism': 'below_threshold'}
            
            # Paris law parameters (empirical for rocks)
            C = self._estimate_paris_law_coefficient(cap_rock_props, stress_tensor)  # Material constant
            m = self._estimate_paris_law_exponent(cap_rock_props)  # Exponent (typically 2-6)
            
            # Subcritical crack growth rate (da/dt = C * ΔK^m)
            delta_K = stress_intensity - K_threshold
            crack_growth_rate = C * (delta_K)**m  # m/s
            
            # Environmental effects
            environmental_factor = await self._calculate_environmental_acceleration(
                stress_tensor, cap_rock_props, coords
            )
            
            subcritical_velocity = crack_growth_rate * environmental_factor
            
            # Water-assisted cracking enhancement
            water_effect = self._calculate_water_assisted_cracking(stress_tensor, cap_rock_props)
            
            final_velocity = subcritical_velocity * water_effect
            
            return {
                'velocity': final_velocity,
                'mechanism': 'subcritical_growth',
                'threshold_ki': K_threshold,
                'effective_ki': stress_intensity,
                'paris_c': C,
                'paris_m': m,
                'environmental_factor': environmental_factor,
                'water_effect': water_effect
            }
            
        except Exception as e:
            self.logger.error(f"Subcritical crack velocity calculation failed: {e}")
            return {'velocity': 0, 'mechanism': 'subcritical_error'}
    
    async def _estimate_stress_corrosion_threshold(self, cap_rock_props: CapRockProperties,
                                                  stress_tensor: Dict) -> float:
        """Estimate stress corrosion threshold"""
        
        # Base threshold from fracture toughness
        KIc = await self._estimate_advanced_fracture_toughness(cap_rock_props, stress_tensor)
        K_threshold = KIc * 0.3  # Typical threshold is 30% of KIc
        
        # Temperature effect on threshold
        temperature_c = stress_tensor.get('temperature_c', 200)
        if temperature_c > 100:
            temp_reduction = 1.0 - (temperature_c - 100) / 1000  # Reduces with temperature
            K_threshold *= max(0.1, temp_reduction)
        
        return K_threshold
    
    def _calculate_effective_stress_intensity(self, stress_tensor: Dict, 
                                            cap_rock_props: CapRockProperties) -> float:
        """Calculate effective stress intensity factor"""
        
        stress_factors = self._calculate_stress_intensity_factors(stress_tensor, cap_rock_props)
        KI = stress_factors['mode_I']
        KII = stress_factors['mode_II']
        
        # Equivalent stress intensity factor
        K_eq = np.sqrt(KI**2 + KII**2)
        
        return K_eq
    
    async def _estimate_advanced_paris_law_coefficient(self, cap_rock_props: CapRockProperties,
                                                     stress_tensor: Dict, coords: List[float] = None) -> Dict[str, float]:
        """Advanced Paris law coefficient estimation with comprehensive database and modeling"""
        
        try:
            # Primary: Database-driven Paris law coefficient characterization
            database_coeff = await self._get_database_paris_coefficient(cap_rock_props, stress_tensor, coords)
            
            # Secondary: ML-predicted Paris law coefficient variations
            ml_coeff = await self._get_ml_predicted_paris_coefficient(cap_rock_props, stress_tensor, coords)
            
            # Tertiary: Volcanic system-enhanced Paris coefficient analysis
            volcanic_coeff = await self._get_volcanic_enhanced_paris_coefficient(cap_rock_props, stress_tensor, coords)
            
            # Quaternary: Physics-based Paris coefficient modeling
            physics_coeff = await self._get_physics_based_paris_coefficient(cap_rock_props, stress_tensor)
            
            # Enhanced empirical fallback
            empirical_coeff = self._get_enhanced_empirical_paris_coefficient(cap_rock_props, stress_tensor)
            
            # Weighted ensemble estimation
            weights = {
                'database': 0.35 if database_coeff.get('confidence', 0) > 0.7 else 0.15,
                'ml': 0.25 if ml_coeff.get('confidence', 0) > 0.6 else 0.10,
                'volcanic': 0.20 if volcanic_coeff.get('confidence', 0) > 0.5 else 0.05,
                'physics': 0.15,
                'empirical': 0.05
            }
            
            # Normalize weights
            total_weight = sum(weights.values())
            weights = {k: v/total_weight for k, v in weights.items()}
            
            # Ensemble Paris coefficient calculation
            ensemble_coefficient = (
                weights['database'] * database_coeff.get('coefficient', empirical_coeff['coefficient']) +
                weights['ml'] * ml_coeff.get('coefficient', empirical_coeff['coefficient']) +
                weights['volcanic'] * volcanic_coeff.get('coefficient', empirical_coeff['coefficient']) +
                weights['physics'] * physics_coeff.get('coefficient', empirical_coeff['coefficient']) +
                weights['empirical'] * empirical_coeff['coefficient']
            )
            
            # Calculate confidence and uncertainty
            confidence = (
                weights['database'] * database_coeff.get('confidence', 0.3) +
                weights['ml'] * ml_coeff.get('confidence', 0.3) +
                weights['volcanic'] * volcanic_coeff.get('confidence', 0.3) +
                weights['physics'] * physics_coeff.get('confidence', 0.4) +
                weights['empirical'] * empirical_coeff['confidence']
            )
            
            return {
                'coefficient': max(1e-15, min(1e-8, ensemble_coefficient)),
                'confidence': confidence,
                'uncertainty': 1.0 - confidence,
                'components': {
                    'database': database_coeff,
                    'ml': ml_coeff,
                    'volcanic': volcanic_coeff,
                    'physics': physics_coeff,
                    'empirical': empirical_coeff
                },
                'weights': weights
            }
            
        except Exception as e:
            self.logger.error(f"Advanced Paris coefficient estimation failed: {e}")
            # Fallback to enhanced empirical
            empirical_coeff = self._get_enhanced_empirical_paris_coefficient(cap_rock_props, stress_tensor)
            return {
                'coefficient': empirical_coeff['coefficient'],
                'confidence': empirical_coeff['confidence'],
                'uncertainty': 1.0 - empirical_coeff['confidence'],
                'fallback_used': True
            }
    
    async def _estimate_advanced_paris_law_exponent(self, cap_rock_props: CapRockProperties,
                                                  stress_tensor: Dict = None, coords: List[float] = None) -> Dict[str, float]:
        """Advanced Paris law exponent estimation with comprehensive database and modeling"""
        
        try:
            # Primary: Database-driven Paris law exponent characterization
            database_exp = await self._get_database_paris_exponent(cap_rock_props, coords)
            
            # Secondary: ML-predicted Paris law exponent variations
            ml_exp = await self._get_ml_predicted_paris_exponent(cap_rock_props, stress_tensor, coords)
            
            # Tertiary: Volcanic system-enhanced Paris exponent analysis
            volcanic_exp = await self._get_volcanic_enhanced_paris_exponent(cap_rock_props, stress_tensor, coords)
            
            # Quaternary: Physics-based Paris exponent modeling
            physics_exp = await self._get_physics_based_paris_exponent(cap_rock_props, stress_tensor)
            
            # Enhanced empirical fallback
            empirical_exp = self._get_enhanced_empirical_paris_exponent(cap_rock_props)
            
            # Weighted ensemble estimation
            weights = {
                'database': 0.35 if database_exp.get('confidence', 0) > 0.7 else 0.15,
                'ml': 0.25 if ml_exp.get('confidence', 0) > 0.6 else 0.10,
                'volcanic': 0.20 if volcanic_exp.get('confidence', 0) > 0.5 else 0.05,
                'physics': 0.15,
                'empirical': 0.05
            }
            
            # Normalize weights
            total_weight = sum(weights.values())
            weights = {k: v/total_weight for k, v in weights.items()}
            
            # Ensemble Paris exponent calculation
            ensemble_exponent = (
                weights['database'] * database_exp.get('exponent', empirical_exp['exponent']) +
                weights['ml'] * ml_exp.get('exponent', empirical_exp['exponent']) +
                weights['volcanic'] * volcanic_exp.get('exponent', empirical_exp['exponent']) +
                weights['physics'] * physics_exp.get('exponent', empirical_exp['exponent']) +
                weights['empirical'] * empirical_exp['exponent']
            )
            
            # Calculate confidence and uncertainty
            confidence = (
                weights['database'] * database_exp.get('confidence', 0.3) +
                weights['ml'] * ml_exp.get('confidence', 0.3) +
                weights['volcanic'] * volcanic_exp.get('confidence', 0.3) +
                weights['physics'] * physics_exp.get('confidence', 0.4) +
                weights['empirical'] * empirical_exp['confidence']
            )
            
            return {
                'exponent': max(1.5, min(8.0, ensemble_exponent)),
                'confidence': confidence,
                'uncertainty': 1.0 - confidence,
                'components': {
                    'database': database_exp,
                    'ml': ml_exp,
                    'volcanic': volcanic_exp,
                    'physics': physics_exp,
                    'empirical': empirical_exp
                },
                'weights': weights
            }
            
        except Exception as e:
            self.logger.error(f"Advanced Paris exponent estimation failed: {e}")
            # Fallback to enhanced empirical
            empirical_exp = self._get_enhanced_empirical_paris_exponent(cap_rock_props)
            return {
                'exponent': empirical_exp['exponent'],
                'confidence': empirical_exp['confidence'],
                'uncertainty': 1.0 - empirical_exp['confidence'],
                'fallback_used': True
            }
    
    async def _calculate_environmental_acceleration(self, stress_tensor: Dict, cap_rock_props: CapRockProperties,
                                                   coords: List[float] = None) -> float:
        """Calculate environmental acceleration factors"""
        
        acceleration_factor = 1.0
        
        # Temperature acceleration
        temperature_c = stress_tensor.get('temperature_c', 200)
        temp_acceleration = np.exp((temperature_c - 25) / 150)  # Exponential with temperature
        acceleration_factor *= temp_acceleration
        
        # Humidity/water vapor effects
        pore_pressure = stress_tensor.get('pore_pressure_mpa', 0)
        if pore_pressure > 0:
            water_acceleration = 1.0 + pore_pressure / 10  # Linear with pore pressure
            acceleration_factor *= water_acceleration
        
        # Volcanic gas effects (if available)
        if self.volcanic_chamber_system and coords:
            try:
                gas_effect = await self._calculate_volcanic_gas_acceleration(coords)
                acceleration_factor *= gas_effect
            except:
                pass  # Fail silently
        
        return min(10.0, acceleration_factor)  # Cap at 10x acceleration
    
    async def _calculate_volcanic_gas_acceleration(self, coords: List[float]) -> float:
        """Calculate acceleration due to volcanic gases"""
        
        try:
            x, y, z = coords
            chamber_data = await self.volcanic_chamber_system.get_nearest_chambers(
                x=x, y=y, z=z, search_radius_km=5
            )
            
            if not chamber_data:
                return 1.0
            
            nearest_chamber = chamber_data[0]
            volatile_content = nearest_chamber.get('volatile_content', {})
            
            # Different gases have different corrosive effects
            h2s_effect = volatile_content.get('H2S_ppm', 0) * 0.001  # H2S is very corrosive
            so2_effect = volatile_content.get('SO2_wt_percent', 0) * 0.05  # SO2 moderate effect
            co2_effect = volatile_content.get('CO2_wt_percent', 0) * 0.01  # CO2 mild effect
            
            total_gas_effect = 1.0 + h2s_effect + so2_effect + co2_effect
            
            return min(5.0, total_gas_effect)
            
        except:
            return 1.0
    
    def _calculate_water_assisted_cracking(self, stress_tensor: Dict, 
                                          cap_rock_props: CapRockProperties) -> float:
        """Calculate water-assisted cracking enhancement"""
        
        # Water weakening effect
        pore_pressure = stress_tensor.get('pore_pressure_mpa', 0)
        if pore_pressure <= 0:
            return 1.0
        
        # Permeability effect (higher permeability = more water access)
        permeability = cap_rock_props.permeability_m2
        permeability_factor = min(2.0, 1.0 + np.log10(permeability + 1e-20) / (-15))
        
        # Temperature effect (higher temp = more reaction)
        temperature_c = stress_tensor.get('temperature_c', 200)
        temp_factor = 1.0 + (temperature_c - 25) / 200
        
        # Combined water effect
        water_effect = 1.0 + pore_pressure / 50 * permeability_factor * temp_factor
        
        return min(3.0, water_effect)  # Cap at 3x enhancement
    
    async def _calculate_volatile_influenced_velocity(self, stress_tensor: Dict, cap_rock_props: CapRockProperties,
                                                     coords: List[float] = None) -> Dict[str, float]:
        """Calculate crack velocity influenced by volcanic volatiles"""
        
        try:
            if not self.volcanic_chamber_system or not coords:
                return {'velocity': 0, 'mechanism': 'volatile_unavailable'}
            
            x, y, z = coords
            chamber_data = await self.volcanic_chamber_system.get_nearest_chambers(
                x=x, y=y, z=z, search_radius_km=10
            )
            
            if not chamber_data:
                return {'velocity': 0, 'mechanism': 'no_chamber_influence'}
            
            nearest_chamber = chamber_data[0]
            volatile_content = nearest_chamber.get('volatile_content', {})
            distance_km = nearest_chamber.get('distance_km', 10)
            
            # Base mechanical velocity
            base_velocity = await self._calculate_base_mechanical_velocity(stress_tensor, cap_rock_props)
            
            # Volatile effects on crack propagation
            volatile_effects = {
                'H2O': self._calculate_h2o_crack_effect(volatile_content.get('H2O_wt_percent', 0)),
                'CO2': self._calculate_co2_crack_effect(volatile_content.get('CO2_wt_percent', 0)),
                'SO2': self._calculate_so2_crack_effect(volatile_content.get('SO2_wt_percent', 0)),
                'H2S': self._calculate_h2s_crack_effect(volatile_content.get('H2S_ppm', 0)),
                'HF': self._calculate_hf_crack_effect(volatile_content.get('HF_ppm', 0))
            }
            
            # Combined volatile acceleration
            total_volatile_factor = 1.0
            for gas, effect in volatile_effects.items():
                total_volatile_factor *= effect
            
            # Distance decay
            distance_factor = np.exp(-distance_km / 5.0)  # 5 km characteristic distance
            
            # Pressure-enhanced diffusion
            chamber_pressure = nearest_chamber.get('pressure_mpa', 0)
            pressure_enhancement = 1.0 + chamber_pressure / 100
            
            volatile_velocity = (
                base_velocity * 
                total_volatile_factor * 
                distance_factor * 
                pressure_enhancement
            )
            
            return {
                'velocity': volatile_velocity,
                'mechanism': 'volatile_enhanced',
                'volatile_effects': volatile_effects,
                'distance_factor': distance_factor,
                'pressure_enhancement': pressure_enhancement,
                'total_volatile_factor': total_volatile_factor
            }
            
        except Exception as e:
            self.logger.error(f"Volatile-influenced velocity calculation failed: {e}")
            return {'velocity': 0, 'mechanism': 'volatile_error'}
    
    def _calculate_h2o_crack_effect(self, h2o_wt_percent: float) -> float:
        """Calculate H2O effect on crack propagation (stress corrosion)"""
        return 1.0 + h2o_wt_percent * 0.1  # 10% increase per wt% H2O
    
    def _calculate_co2_crack_effect(self, co2_wt_percent: float) -> float:
        """Calculate CO2 effect on crack propagation (carbonation weakening)"""
        return 1.0 + co2_wt_percent * 0.03  # 3% increase per wt% CO2
    
    def _calculate_so2_crack_effect(self, so2_wt_percent: float) -> float:
        """Calculate SO2 effect on crack propagation (sulfate attack)"""
        return 1.0 + so2_wt_percent * 0.08  # 8% increase per wt% SO2
    
    def _calculate_h2s_crack_effect(self, h2s_ppm: float) -> float:
        """Calculate H2S effect on crack propagation (severe corrosion)"""
        return 1.0 + h2s_ppm * 0.001  # 0.1% increase per ppm H2S (very potent)
    
    def _calculate_hf_crack_effect(self, hf_ppm: float) -> float:
        """Calculate HF effect on crack propagation (etching attack)"""
        return 1.0 + hf_ppm * 0.002  # 0.2% increase per ppm HF
    
    def _select_dominant_velocity_mechanism(self, lefm_vel: Dict, thermo_vel: Dict,
                                           subcrit_vel: Dict, volatile_vel: Dict,
                                           stress_tensor: Dict, cap_rock_props: CapRockProperties) -> Dict:
        """Select the dominant velocity mechanism based on conditions"""
        
        candidates = [
            (lefm_vel, 'lefm'),
            (thermo_vel, 'thermodynamic'), 
            (subcrit_vel, 'subcritical'),
            (volatile_vel, 'volatile')
        ]
        
        # Filter out failed calculations
        valid_candidates = [(vel, name) for vel, name in candidates 
                           if vel.get('velocity', 0) > 0]
        
        if not valid_candidates:
            return {'velocity': 0, 'mechanism': 'no_valid_mechanism'}
        
        # Determine dominant mechanism based on stress/temperature conditions
        temperature_c = stress_tensor.get('temperature_c', 200)
        sigma_1 = stress_tensor.get('sigma_1', 0)
        ucs = cap_rock_props.unconfined_compressive_strength_mpa
        
        stress_ratio = sigma_1 / ucs if ucs > 0 else 0
        
        # Selection logic
        if temperature_c > 400 and thermo_vel.get('velocity', 0) > 0:
            # High temperature favors thermodynamic mechanism
            selected = thermo_vel
            selected['mechanism'] = 'thermodynamic_dominant'
        elif stress_ratio > 0.8 and lefm_vel.get('velocity', 0) > 0:
            # High stress ratio favors LEFM
            selected = lefm_vel  
            selected['mechanism'] = 'lefm_dominant'
        elif volatile_vel.get('velocity', 0) > subcrit_vel.get('velocity', 0):
            # Volatile effects dominate over subcritical
            selected = volatile_vel
            selected['mechanism'] = 'volatile_dominant'
        else:
            # Default to subcritical growth
            selected = subcrit_vel
            selected['mechanism'] = 'subcritical_dominant'
        
        return selected
    
    async def _apply_environmental_corrections(self, velocity_result: Dict, stress_tensor: Dict,
                                              cap_rock_props: CapRockProperties, 
                                              coords: List[float] = None) -> Dict:
        """Apply environmental corrections to crack velocity"""
        
        base_velocity = velocity_result.get('velocity', 0)
        if base_velocity <= 0:
            return velocity_result
        
        corrections = {}
        corrected_velocity = base_velocity
        
        # Depth correction (confining pressure effect)
        if coords:
            depth_km = abs(coords[2])
            depth_correction = max(0.1, 1.0 - depth_km * 0.05)  # Decreases with depth
            corrections['depth'] = depth_correction
            corrected_velocity *= depth_correction
        
        # Fracture density correction
        fracture_density = cap_rock_props.fracture_density_per_m3
        if fracture_density > 0:
            fracture_correction = 1.0 + fracture_density / 1000  # Slight increase
            corrections['fracture_density'] = fracture_correction
            corrected_velocity *= fracture_correction
        
        # Alteration correction
        alteration_minerals = cap_rock_props.alteration_minerals or {}
        clay_fraction = sum(alteration_minerals.get(mineral, 0) 
                           for mineral in ['kaolinite', 'montmorillonite', 'illite'])
        if clay_fraction > 0:
            alteration_correction = 1.0 + clay_fraction * 0.5  # Clays enhance cracking
            corrections['alteration'] = alteration_correction
            corrected_velocity *= alteration_correction
        
        # Update result
        result = velocity_result.copy()
        result['velocity'] = corrected_velocity
        result['environmental_factors'] = corrections
        
        return result
    
    def _calculate_velocity_uncertainty(self, velocity_result: Dict, stress_tensor: Dict,
                                       cap_rock_props: CapRockProperties) -> Dict:
        """Calculate uncertainty bounds for crack velocity"""
        
        base_velocity = velocity_result.get('velocity', 0)
        mechanism = velocity_result.get('mechanism', 'unknown')
        
        # Uncertainty factors by mechanism
        uncertainty_factors = {
            'lefm': 0.3,           # ±30% for LEFM
            'thermodynamic': 0.5,   # ±50% for thermodynamic
            'subcritical': 0.4,     # ±40% for subcritical
            'volatile': 0.6,        # ±60% for volatile effects
            'unknown': 0.8          # ±80% for unknown
        }
        
        base_uncertainty = uncertainty_factors.get(mechanism.split('_')[0], 0.5)
        
        # Data quality adjustment
        data_quality = self._assess_crack_data_quality(stress_tensor, cap_rock_props)
        quality_adjustment = 1.0 - data_quality * 0.3  # Better data = lower uncertainty
        
        final_uncertainty = base_uncertainty * quality_adjustment
        
        return {
            'velocity_min': base_velocity * (1 - final_uncertainty),
            'velocity_max': base_velocity * (1 + final_uncertainty),
            'uncertainty_factor': final_uncertainty,
            'confidence_level': 1.0 - final_uncertainty,
            'data_quality': data_quality
        }
    
    def _assess_crack_data_quality(self, stress_tensor: Dict, cap_rock_props: CapRockProperties) -> float:
        """Assess quality of data for crack velocity calculations"""
        
        quality_score = 0.0
        
        # Stress tensor completeness
        stress_completeness = sum([
            1 if stress_tensor.get('sigma_1') is not None else 0,
            1 if stress_tensor.get('sigma_2') is not None else 0, 
            1 if stress_tensor.get('sigma_3') is not None else 0,
            1 if stress_tensor.get('temperature_c') is not None else 0
        ]) / 4
        quality_score += stress_completeness * 0.4
        
        # Rock property completeness
        prop_completeness = sum([
            1 if cap_rock_props.elastic_modulus_gpa > 0 else 0,
            1 if cap_rock_props.poisson_ratio > 0 else 0,
            1 if cap_rock_props.unconfined_compressive_strength_mpa > 0 else 0,
            1 if cap_rock_props.fracture_density_per_m3 >= 0 else 0
        ]) / 4
        quality_score += prop_completeness * 0.4
        
        # Integration availability
        integration_score = 0.0
        if self.thermodynamic_engine:
            integration_score += 0.5
        if self.volcanic_chamber_system:
            integration_score += 0.5
        quality_score += integration_score * 0.2
        
        return min(1.0, quality_score)
    
    async def _fallback_crack_velocity_calculation(self, stress_tensor: Dict, 
                                                  cap_rock_props: CapRockProperties) -> Dict:
        """Fallback calculation if advanced methods fail"""
        
        # Simple velocity based on wave speed
        E = cap_rock_props.elastic_modulus_gpa * 1e9
        rho = await self._estimate_advanced_rock_density(cap_rock_props)
        nu = cap_rock_props.poisson_ratio
        
        # Rayleigh wave velocity
        c_R = np.sqrt(E / (2 * rho * (1 + nu))) * 0.9
        
        # Stress-based scaling
        sigma_1 = stress_tensor.get('sigma_1', 0)
        ucs = cap_rock_props.unconfined_compressive_strength_mpa
        stress_factor = min(0.1, sigma_1 / ucs * 0.05) if ucs > 0 else 0.01
        
        fallback_velocity = c_R * stress_factor
        
        return {
            'propagation_velocity_m_s': fallback_velocity,
            'velocity_mechanism': 'fallback_simplified',
            'velocity_bounds': {
                'velocity_min': fallback_velocity * 0.5,
                'velocity_max': fallback_velocity * 2.0,
                'uncertainty_factor': 0.8,
                'confidence_level': 0.2
            }
        }
    
    async def _quantify_failure_zone_uncertainty(self, coords: List[float], stress_tensor: Dict,
                                                cap_rock_props: CapRockProperties, max_ratio: float) -> Dict:
        """Quantify uncertainty in failure zone analysis"""
        
        try:
            # Data quality assessment
            data_quality = self._assess_data_quality(stress_tensor, cap_rock_props)
            
            # Model uncertainty
            model_uncertainty = self._assess_model_uncertainty(max_ratio, coords)
            
            # Parameter uncertainty
            parameter_uncertainty = self._assess_parameter_uncertainty(cap_rock_props)
            
            # Combined uncertainty
            confidence_factor = (
                data_quality['confidence'] * 0.4 +
                (1 - model_uncertainty['uncertainty']) * 0.3 +
                (1 - parameter_uncertainty['uncertainty']) * 0.3
            )
            
            return {
                'confidence_factor': confidence_factor,
                'area_uncertainty': model_uncertainty['area_uncertainty'],
                'ratio_uncertainty': parameter_uncertainty['ratio_uncertainty'],
                'data_quality_grade': data_quality['grade'],
                'uncertainty_sources': {
                    'data_quality': data_quality,
                    'model_uncertainty': model_uncertainty,
                    'parameter_uncertainty': parameter_uncertainty
                }
            }
            
        except Exception as e:
            self.logger.error(f"Uncertainty quantification failed: {e}")
            return {
                'confidence_factor': 0.5,
                'area_uncertainty': 0.3,
                'ratio_uncertainty': 0.2,
                'data_quality_grade': 'C',
                'uncertainty_sources': {}
            }
    
    def _assess_data_quality(self, stress_tensor: Dict, cap_rock_props: CapRockProperties) -> Dict:
        """Assess quality of input data"""
        
        # Check completeness of stress tensor
        stress_completeness = sum([
            1 if stress_tensor.get('sigma_1') is not None else 0,
            1 if stress_tensor.get('sigma_2') is not None else 0,
            1 if stress_tensor.get('sigma_3') is not None else 0,
            1 if stress_tensor.get('von_mises_stress') is not None else 0
        ]) / 4
        
        # Check rock property completeness
        property_completeness = sum([
            1 if cap_rock_props.unconfined_compressive_strength_mpa > 0 else 0,
            1 if cap_rock_props.tensile_strength_mpa > 0 else 0,
            1 if cap_rock_props.cohesion_mpa >= 0 else 0,
            1 if cap_rock_props.friction_angle_deg > 0 else 0
        ]) / 4
        
        # Overall data quality
        overall_quality = (stress_completeness + property_completeness) / 2
        
        # Assign grade
        if overall_quality >= 0.9:
            grade = 'A'
        elif overall_quality >= 0.7:
            grade = 'B'
        elif overall_quality >= 0.5:
            grade = 'C'
        else:
            grade = 'D'
        
        return {
            'confidence': overall_quality,
            'grade': grade,
            'stress_completeness': stress_completeness,
            'property_completeness': property_completeness
        }
    
    def _assess_model_uncertainty(self, max_ratio: float, coords: List[float]) -> Dict:
        """Assess uncertainty in model predictions"""
        
        # Model uncertainty increases with extreme conditions
        depth_km = abs(coords[2])
        
        # Depth-dependent uncertainty
        depth_uncertainty = min(0.3, depth_km * 0.02)
        
        # Failure ratio uncertainty
        ratio_uncertainty = 0.1 if max_ratio < 1.0 else min(0.4, (max_ratio - 1.0) * 0.2)
        
        # Area calculation uncertainty
        area_uncertainty = 0.2 + depth_uncertainty + ratio_uncertainty * 0.5
        
        return {
            'uncertainty': min(0.5, depth_uncertainty + ratio_uncertainty),
            'area_uncertainty': min(0.5, area_uncertainty),
            'depth_uncertainty': depth_uncertainty,
            'ratio_uncertainty': ratio_uncertainty
        }
    
    def _assess_parameter_uncertainty(self, cap_rock_props: CapRockProperties) -> Dict:
        """Assess uncertainty in rock property parameters"""
        
        # Typical parameter uncertainties (based on testing standards)
        uncertainties = {
            'ucs_uncertainty': 0.15,  # ±15% typical for UCS tests
            'tensile_uncertainty': 0.25,  # ±25% typical for tensile tests
            'cohesion_uncertainty': 0.20,  # ±20% typical for triaxial tests
            'friction_uncertainty': 0.10   # ±10% typical for friction angle
        }
        
        # Overall parameter uncertainty
        overall_uncertainty = np.mean(list(uncertainties.values()))
        
        return {
            'uncertainty': overall_uncertainty,
            'ratio_uncertainty': overall_uncertainty * 0.5,
            'individual_uncertainties': uncertainties
        }
    
    async def _perform_multiscale_failure_analysis(self, coords: List[float], element: Dict,
                                                  stress_tensor: Dict, cap_rock_props: CapRockProperties) -> Dict:
        """Perform multi-scale failure analysis"""
        
        try:
            # Microscale analysis (grain-scale effects)
            microscale_analysis = await self._analyze_microscale_effects(stress_tensor, cap_rock_props, coords)
            
            # Mesoscale analysis (fracture network effects) 
            mesoscale_analysis = await self._analyze_mesoscale_effects(coords, stress_tensor, cap_rock_props)
            
            # Macroscale analysis (regional effects)
            macroscale_analysis = await self._analyze_macroscale_effects(coords, stress_tensor)
            
            return {
                'microscale': microscale_analysis,
                'mesoscale': mesoscale_analysis,
                'macroscale': macroscale_analysis,
                'propagation_risk': self._calculate_multiscale_propagation_risk(
                    microscale_analysis, mesoscale_analysis, macroscale_analysis
                ),
                'stress_paths': self._identify_critical_stress_paths(
                    coords, stress_tensor, microscale_analysis, mesoscale_analysis
                ),
                'chamber_proximity': macroscale_analysis.get('chamber_proximity_factor', 0),
                'intrusion_risk': macroscale_analysis.get('magma_intrusion_risk', 0),
                'volatile_effect': mesoscale_analysis.get('volatile_weakening_effect', 0)
            }
            
        except Exception as e:
            self.logger.error(f"Multiscale failure analysis failed: {e}")
            return {
                'propagation_risk': 0.5,
                'stress_paths': [],
                'chamber_proximity': 0,
                'intrusion_risk': 0,
                'volatile_effect': 0
            }
    
    async def _analyze_microscale_effects(self, stress_tensor: Dict, cap_rock_props: CapRockProperties, coords: List[float] = None) -> Dict:
        """Analyze microscale (grain-level) effects"""
        
        # Grain boundary effects using micromechanical models
        porosity = cap_rock_props.porosity
        
        # Hashin-Shtrikman bounds for effective properties
        # Account for pore shape, connectivity, and stress concentration
        pore_aspect_ratio = 0.1  # Typical for sedimentary rocks (oblate pores)
        connectivity_factor = min(1.0, porosity / 0.03)  # Percolation threshold effects
        
        # Comprehensive petrographic grain boundary sliding analysis (Paterson & Wong, 2005)
        # Depends on comprehensive petrographic analysis
        comprehensive_grain_analysis = await self._comprehensive_grain_boundary_sliding_analysis(coords, cap_rock_props)
        pore_pressure = stress_tensor.get('pore_pressure_mpa', 0) if stress_tensor else 0
        confining_pressure = stress_tensor.get('confining_pressure_mpa', 10) if stress_tensor else 10
        
        # Effective pressure for grain boundary processes
        effective_pressure = max(0.1, confining_pressure - pore_pressure)
        
        # Grain boundary weakening based on micromechanical theory
        # Combines comprehensive petrographic analysis with porosity effects and pore pressure
        porosity_factor = porosity**0.3 / (1 - porosity)**0.7  # Non-linear porosity dependence
        pore_pressure_factor = 1 + (pore_pressure / effective_pressure)**0.5  # Pore pressure weakening
        grain_size_factor = comprehensive_grain_analysis['grain_boundary_weakening_factor']
        
        grain_boundary_weakening = (
            porosity_factor * 
            pore_pressure_factor * 
            grain_size_factor * 
            connectivity_factor *
            0.3  # Base weakening coefficient
        )
        
        # Thermal microcracking
        temperature = stress_tensor.get('temperature_c', 200)
        thermal_microcracking = max(0, (temperature - 100) / 300)  # Normalized
        
        # Stress concentration at grain boundaries
        von_mises = stress_tensor.get('von_mises_stress', 0)
        grain_stress_concentration = min(2.0, von_mises / (cap_rock_props.unconfined_compressive_strength_mpa * 0.1))
        
        return {
            'grain_boundary_weakening': grain_boundary_weakening,
            'thermal_microcracking': thermal_microcracking,
            'grain_stress_concentration': grain_stress_concentration,
            'microscale_damage': (grain_boundary_weakening + thermal_microcracking) / 2
        }
    
    async def _analyze_mesoscale_effects(self, coords: List[float], stress_tensor: Dict,
                                        cap_rock_props: CapRockProperties) -> Dict:
        """Analyze mesoscale (fracture network) effects"""
        
        try:
            # Fracture density effects
            fracture_density = cap_rock_props.fracture_density_per_m3
            fracture_weakening = min(1.0, fracture_density / 100)  # Normalized
            
            # Fracture connectivity
            permeability = cap_rock_props.permeability_m2
            fracture_connectivity = min(1.0, np.log10(permeability + 1e-20) / (-15))  # Normalized
            
            # Volatile weakening (if volcanic system available)
            volatile_effect = 0.0
            if self.volcanic_chamber_system:
                volatile_effect = await self._calculate_volatile_weakening_ratio(coords, stress_tensor)
            
            # Hydrothermal alteration effects
            temperature = stress_tensor.get('temperature_c', 200)
            alteration_intensity = min(1.0, max(0, (temperature - 150) / 200))
            
            return {
                'fracture_weakening': fracture_weakening,
                'fracture_connectivity': fracture_connectivity,
                'volatile_weakening_effect': volatile_effect,
                'alteration_intensity': alteration_intensity,
                'mesoscale_damage': (fracture_weakening + fracture_connectivity + alteration_intensity) / 3
            }
            
        except Exception as e:
            self.logger.warning(f"Mesoscale analysis failed: {e}")
            return {
                'fracture_weakening': 0.1,
                'fracture_connectivity': 0.1,
                'volatile_weakening_effect': 0.0,
                'alteration_intensity': 0.1,
                'mesoscale_damage': 0.1
            }
    
    async def _analyze_macroscale_effects(self, coords: List[float], stress_tensor: Dict) -> Dict:
        """Analyze macroscale (regional) effects using comprehensive geomechanical modeling"""
        
        try:
            x, y, z = coords
            depth_km = abs(z)
            
            # 1. Advanced magma chamber proximity analysis
            chamber_proximity_factor = 0.0
            magma_intrusion_risk = 0.0
            thermal_aureole_factor = 0.0
            
            if self.volcanic_chamber_system:
                chamber_data = await self.volcanic_chamber_system.get_nearest_chambers(
                    x=x, y=y, z=z, search_radius_km=50  # Extended search radius
                )
                
                if chamber_data:
                    for chamber in chamber_data[:3]:  # Consider multiple chambers
                        distance_km = chamber.get('distance_km', 50)
                        chamber_volume = chamber.get('volume_km3', 1.0)
                        chamber_temp = chamber.get('temperature_c', 1000)
                        activity_level = chamber.get('activity_level', 0)
                        
                        # Distance decay with chamber size consideration
                        size_factor = min(2.0, (chamber_volume / 10.0)**0.3)
                        distance_influence = np.exp(-distance_km / (10.0 * size_factor))
                        
                        chamber_proximity_factor += distance_influence * activity_level
                        
                        # Thermal aureole extent (contact metamorphism zone)
                        aureole_radius = 2.0 * chamber_volume**0.33  # Empirical relation
                        if distance_km < aureole_radius:
                            thermal_aureole_factor = max(thermal_aureole_factor, 
                                                       1.0 - distance_km / aureole_radius)
                        
                        # Magma intrusion risk using dike propagation mechanics
                        buoyancy_pressure = 0.003 * chamber_temp * depth_km  # GPa
                        regional_stress = stress_tensor.get('minimum_horizontal_stress', 20)  # MPa
                        
                        if buoyancy_pressure * 1000 > regional_stress:  # Convert GPa to MPa
                            propagation_potential = (buoyancy_pressure * 1000 - regional_stress) / 50.0
                            intrusion_risk = distance_influence * propagation_potential * activity_level
                            magma_intrusion_risk = max(magma_intrusion_risk, intrusion_risk)
            
            # 2. Regional stress field analysis using elastic plate theory
            lithostatic_pressure = 0.027 * depth_km  # GPa (average crustal density)
            
            # Tectonic stress regime identification
            s1 = stress_tensor.get('sigma_1', lithostatic_pressure * 1000)  # MPa
            s2 = stress_tensor.get('sigma_2', lithostatic_pressure * 800)   # MPa
            s3 = stress_tensor.get('sigma_3', lithostatic_pressure * 600)   # MPa
            
            # Stress regime ratios (Zoback stress polygon)
            phi = (s2 - s3) / (s1 - s3) if s1 != s3 else 0.5
            stress_ratio = s1 / s3 if s3 > 0 else 1.0
            
            # Classify tectonic regime
            if s1 > lithostatic_pressure * 1200:  # Vertical stress
                if phi < 0.5:
                    stress_regime = 'thrust_faulting'
                    regime_factor = 1.2  # High compression
                else:
                    stress_regime = 'transpression'
                    regime_factor = 1.0
            elif s3 < lithostatic_pressure * 400:
                if phi > 0.5:
                    stress_regime = 'normal_faulting'
                    regime_factor = 0.7  # Extension
                else:
                    stress_regime = 'transtension'
                    regime_factor = 0.8
            else:
                stress_regime = 'strike_slip'
                regime_factor = 0.9
            
            # 3. Crustal rheology and strength analysis
            # Temperature-dependent viscosity using Arrhenius law
            temperature_k = stress_tensor.get('temperature_c', 200) + 273.15
            activation_energy = 540000  # J/mol for quartz (dominant crustal mineral)
            gas_constant = 8.314  # J/mol/K
            
            # Brittle-ductile transition depth
            strain_rate = 1e-15  # s^-1 typical geological strain rate
            reference_viscosity = 1e22  # Pa·s
            viscosity = reference_viscosity * np.exp(activation_energy / (gas_constant * temperature_k))
            
            # Critical stress for brittle failure (Griffith-Coulomb criterion)
            tensile_strength = 5.0  # MPa typical for sedimentary rocks
            friction_coeff = 0.6   # Internal friction coefficient
            cohesion = 10.0       # MPa
            
            critical_stress = (2 * cohesion * np.cos(np.arctan(friction_coeff)) / 
                             (1 - np.sin(np.arctan(friction_coeff))))
            
            brittleness_index = min(1.0, critical_stress / (s1 - s3)) if s1 != s3 else 1.0
            
            # 4. Fluid flow and pore pressure coupling
            pore_pressure = stress_tensor.get('pore_pressure_mpa', lithostatic_pressure * 400)
            
            # Hubbert-Rubey fluid pressure ratio
            fluid_pressure_ratio = pore_pressure / (lithostatic_pressure * 1000)
            overpressure_factor = max(0, fluid_pressure_ratio - 0.4)  # Above hydrostatic
            
            # Darcy flow velocity estimation
            permeability = 1e-18  # m² typical for tight rocks
            fluid_viscosity = 1e-3  # Pa·s for water
            hydraulic_gradient = 0.01  # Typical regional gradient
            
            darcy_velocity = (permeability * hydraulic_gradient) / fluid_viscosity
            fluid_migration_potential = min(1.0, darcy_velocity * 1e6)  # Normalized
            
            # 5. Structural geological controls
            # Fault proximity and orientation analysis
            fault_density = stress_tensor.get('fault_density_per_km2', 0.1)
            fault_proximity_factor = min(1.0, fault_density / 1.0)
            
            # Fracture network connectivity using percolation theory
            fractal_dimension = 1.8  # Typical for natural fracture networks
            connectivity_threshold = 0.3  # 3D percolation threshold
            fracture_connectivity = fault_proximity_factor**fractal_dimension
            
            # 6. Composite macroscale influence calculation
            # Weighted combination of all factors
            thermal_weight = 0.25
            structural_weight = 0.30
            stress_weight = 0.25
            fluid_weight = 0.20
            
            macroscale_influence = (
                thermal_weight * (chamber_proximity_factor + thermal_aureole_factor) +
                structural_weight * (fault_proximity_factor + fracture_connectivity) +
                stress_weight * (regime_factor * brittleness_index) +
                fluid_weight * (overpressure_factor + fluid_migration_potential)
            )
            
            return {
                'chamber_proximity_factor': float(chamber_proximity_factor),
                'magma_intrusion_risk': float(magma_intrusion_risk),
                'thermal_aureole_factor': float(thermal_aureole_factor),
                'regional_stress_ratio': float(stress_ratio),
                'stress_regime': stress_regime,
                'regime_factor': float(regime_factor),
                'tectonic_loading': float(regime_factor * depth_km / 20.0),
                'brittleness_index': float(brittleness_index),
                'fluid_pressure_ratio': float(fluid_pressure_ratio),
                'overpressure_factor': float(overpressure_factor),
                'fault_proximity_factor': float(fault_proximity_factor),
                'fracture_connectivity': float(fracture_connectivity),
                'macroscale_influence': float(min(1.0, macroscale_influence)),
                'crustal_viscosity_pas': float(viscosity),
                'critical_stress_mpa': float(critical_stress)
            }
            
        except Exception as e:
            self.logger.warning(f"Macroscale analysis failed: {e}")
            return {
                'chamber_proximity_factor': 0.0,
                'magma_intrusion_risk': 0.0,
                'thermal_aureole_factor': 0.0,
                'regional_stress_ratio': 1.0,
                'stress_regime': 'unknown',
                'regime_factor': 1.0,
                'tectonic_loading': 0.1,
                'brittleness_index': 0.5,
                'fluid_pressure_ratio': 0.4,
                'overpressure_factor': 0.0,
                'fault_proximity_factor': 0.0,
                'fracture_connectivity': 0.0,
                'macroscale_influence': 0.05,
                'crustal_viscosity_pas': 1e22,
                'critical_stress_mpa': 50.0
            }
    
    def _calculate_multiscale_propagation_risk(self, microscale: Dict, mesoscale: Dict, macroscale: Dict) -> float:
        """Calculate propagation risk across multiple scales"""
        
        # Weight different scales
        micro_contribution = microscale.get('microscale_damage', 0) * 0.2
        meso_contribution = mesoscale.get('mesoscale_damage', 0) * 0.5
        macro_contribution = macroscale.get('macroscale_influence', 0) * 0.3
        
        propagation_risk = micro_contribution + meso_contribution + macro_contribution
        
        return min(1.0, propagation_risk)
    
    def _identify_critical_stress_paths(self, coords: List[float], stress_tensor: Dict,
                                       microscale: Dict, mesoscale: Dict) -> List[Dict]:
        """Identify critical stress propagation paths using comprehensive stress tensor analysis"""
        
        stress_paths = []
        
        # Extract full stress tensor components
        sigma_xx = stress_tensor.get('sigma_xx', stress_tensor.get('sigma_1', 0))
        sigma_yy = stress_tensor.get('sigma_yy', stress_tensor.get('sigma_2', 0))
        sigma_zz = stress_tensor.get('sigma_zz', stress_tensor.get('sigma_3', 0))
        tau_xy = stress_tensor.get('tau_xy', 0)
        tau_xz = stress_tensor.get('tau_xz', 0)
        tau_yz = stress_tensor.get('tau_yz', 0)
        
        # Construct 3D stress tensor matrix
        stress_matrix = np.array([
            [sigma_xx, tau_xy, tau_xz],
            [tau_xy, sigma_yy, tau_yz],
            [tau_xz, tau_yz, sigma_zz]
        ])
        
        # Calculate principal stresses and directions via eigenvalue decomposition
        eigenvals, eigenvecs = np.linalg.eigh(stress_matrix)
        
        # Sort by magnitude (descending)
        sorted_indices = np.argsort(eigenvals)[::-1]
        principal_stresses = eigenvals[sorted_indices]
        principal_directions = eigenvecs[:, sorted_indices]
        
        # Path 1: Maximum principal stress direction (σ1)
        if principal_stresses[0] > 1.0:  # Minimum threshold for significance
            sigma_1_direction = principal_directions[:, 0]
            stress_paths.append({
                'path_type': 'maximum_principal',
                'direction': sigma_1_direction.tolist(),
                'magnitude': float(principal_stresses[0]),
                'criticality': min(1.0, principal_stresses[0] / 200.0),  # Scaled to typical rock strength
                'mechanism': 'tensile_failure'
            })
        
        # Path 2: Shear failure plane (Mohr-Coulomb criterion)
        differential_stress = principal_stresses[0] - principal_stresses[2]
        if differential_stress > 10.0:  # Significant differential stress
            # Calculate optimal shear plane orientation
            friction_angle = np.radians(30)  # Typical for sedimentary rocks
            theta_optimal = np.pi/4 + friction_angle/2  # Angle to σ1
            
            # Shear plane normal direction
            cos_theta, sin_theta = np.cos(theta_optimal), np.sin(theta_optimal)
            shear_normal = (cos_theta * principal_directions[:, 0] + 
                          sin_theta * principal_directions[:, 2])
            
            stress_paths.append({
                'path_type': 'shear_failure',
                'direction': shear_normal.tolist(),
                'magnitude': float(differential_stress),
                'criticality': min(1.0, differential_stress / 150.0),
                'mechanism': 'shear_failure',
                'friction_angle_deg': float(np.degrees(friction_angle))
            })
        
        # Path 3: Fracture network connectivity paths
        fracture_connectivity = mesoscale.get('fracture_connectivity', 0)
        if fracture_connectivity > 0.2:
            # Calculate fracture-controlled stress paths using percolation theory
            fracture_orientation = mesoscale.get('dominant_fracture_strike', 0)  # degrees
            fracture_dip = mesoscale.get('dominant_fracture_dip', 90)  # degrees
            
            # Convert to direction vector
            strike_rad = np.radians(fracture_orientation)
            dip_rad = np.radians(fracture_dip)
            
            fracture_direction = np.array([
                np.cos(strike_rad) * np.sin(dip_rad),
                np.sin(strike_rad) * np.sin(dip_rad),
                -np.cos(dip_rad)  # Negative for downward dip
            ])
            
            # Stress magnitude along fracture plane
            fracture_stress = np.dot(stress_matrix @ fracture_direction, fracture_direction)
            
            stress_paths.append({
                'path_type': 'fracture_network',
                'direction': fracture_direction.tolist(),
                'magnitude': float(fracture_stress),
                'criticality': fracture_connectivity,
                'mechanism': 'fracture_propagation',
                'connectivity': fracture_connectivity
            })
        
        # Path 4: Thermally-induced stress paths
        thermal_stress = microscale.get('thermal_stress_mpa', 0)
        if thermal_stress > 5.0:
            # Thermal expansion creates radial stress patterns
            # Direction depends on temperature gradient
            temp_gradient_x = stress_tensor.get('temp_gradient_x', 0)
            temp_gradient_y = stress_tensor.get('temp_gradient_y', 0)
            temp_gradient_z = stress_tensor.get('temp_gradient_z', 1.0)  # Default vertical
            
            gradient_magnitude = np.sqrt(temp_gradient_x**2 + temp_gradient_y**2 + temp_gradient_z**2)
            if gradient_magnitude > 0:
                thermal_direction = np.array([temp_gradient_x, temp_gradient_y, temp_gradient_z]) / gradient_magnitude
            else:
                thermal_direction = np.array([0, 0, 1])  # Default vertical
            
            stress_paths.append({
                'path_type': 'thermal_gradient',
                'direction': thermal_direction.tolist(),
                'magnitude': float(thermal_stress),
                'criticality': min(1.0, thermal_stress / 50.0),
                'mechanism': 'thermal_expansion',
                'temperature_gradient': float(gradient_magnitude)
            })
        
        # Path 5: Pore pressure-driven paths
        pore_pressure = stress_tensor.get('pore_pressure_mpa', 0)
        if pore_pressure > 10.0:
            # Hydraulic fracturing potential - perpendicular to minimum principal stress
            hydraulic_direction = principal_directions[:, 2]  # σ3 direction
            
            # Effective stress for hydraulic fracturing
            effective_stress = principal_stresses[2] - pore_pressure
            hydraulic_potential = max(0, pore_pressure - effective_stress)
            
            if hydraulic_potential > 0:
                stress_paths.append({
                    'path_type': 'hydraulic_fracturing',
                    'direction': hydraulic_direction.tolist(),
                    'magnitude': float(hydraulic_potential),
                    'criticality': min(1.0, hydraulic_potential / 30.0),
                    'mechanism': 'hydraulic_fracturing',
                    'pore_pressure': float(pore_pressure)
                })
        
        return stress_paths
    
    def _analyze_contributing_factors(self, failure_assessments: Dict,
                                    stress_state: StressState,
                                    cap_rock_props: CapRockProperties,
                                    thermal_data: Dict) -> Dict[str, float]:
        """Analyze contributing factors to failure"""
        
        factors = {}
        
        # Stress contributions
        total_stress_effect = stress_state.differential_stress
        factors['differential_stress'] = min(1.0, stress_state.differential_stress / 200)  # Normalized
        factors['pore_pressure'] = min(1.0, stress_state.pore_pressure_mpa / 100)
        factors['mean_stress'] = min(1.0, stress_state.mean_stress / 300)
        
        # Thermal contributions
        temp = thermal_data.get('cap_rock_temperature_c', 200)
        factors['temperature'] = min(1.0, (temp - 100) / 500)  # Normalized above 100°C
        
        # Rock property contributions
        factors['low_strength'] = 1.0 - min(1.0, cap_rock_props.tensile_strength_mpa / 20)
        factors['high_permeability'] = min(1.0, cap_rock_props.permeability_m2 / 1e-15)
        factors['fracture_density'] = min(1.0, cap_rock_props.fracture_density_per_m3 / 100)
        
        # Alteration effects
        alteration_score = len(cap_rock_props.alteration_minerals) * 0.2
        factors['alteration'] = min(1.0, alteration_score)
        
        return factors
    
    def _estimate_time_to_failure(self, time_evolution: Dict, 
                                failure_probability: float) -> Optional[float]:
        """Estimate time to failure from evolution"""
        
        if failure_probability < 0.1:
            return None  # Very low probability - no meaningful time estimate
        
        time_days = time_evolution['time_days']
        stability_probs = time_evolution['stability_probability']
        
        # Find when probability exceeds threshold
        threshold = 0.5
        exceed_indices = np.where(stability_probs > threshold)[0]
        
        if len(exceed_indices) > 0:
            time_to_failure_days = time_days[exceed_indices[0]]
            return time_to_failure_days / 365.25  # Convert to years
        else:
            # Extrapolate from trend
            if len(stability_probs) > 10:
                # Fit exponential growth to last part of curve
                recent_times = time_days[-20:]
                recent_probs = stability_probs[-20:]
                
                if np.any(recent_probs > 0.01):  # Avoid log(0)
                    try:
                        # Linear fit to log(prob) vs time
                        log_probs = np.log(recent_probs + 1e-6)
                        coeffs = np.polyfit(recent_times, log_probs, 1)
                        
                        # Extrapolate to threshold
                        target_log_prob = np.log(threshold)
                        extrapolated_time = (target_log_prob - coeffs[1]) / coeffs[0]
                        
                        if extrapolated_time > time_days[-1]:
                            return extrapolated_time / 365.25
                    except:
                        pass
            
            return None  # Cannot estimate
    
    async def train_ml_model(self, training_data: List[Dict]) -> Dict[str, Any]:
        """Train ML model for cap rock stability"""
        
        self.logger.info("Training cap rock stability ML model")
        
        # Prepare training data
        X, y = self._prepare_training_data(training_data)
        
        # Initialize model
        input_features = X.shape[1]
        self.stability_model = CapRockStabilityNN(input_features)
        
        # Training setup
        optimizer = torch.optim.Adam(self.stability_model.parameters(), 
                                   lr=self.config['ml_training']['learning_rate'])
        scheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(
            optimizer, patience=20, factor=0.5
        )
        
        # Convert to tensors
        X_train, X_val, y_train, y_val = train_test_split(
            X, y, test_size=self.config['ml_training']['validation_split'], random_state=42
        )
        
        X_train_tensor = torch.FloatTensor(X_train)
        X_val_tensor = torch.FloatTensor(X_val)
        y_train_tensor = {k: torch.FloatTensor(v_train) for k, v_train in 
                         {k: v[:len(X_train)] for k, v in y.items()}.items()}
        y_val_tensor = {k: torch.FloatTensor(v_val) for k, v_val in 
                       {k: v[len(X_train):] for k, v in y.items()}.items()}
        
        # Training loop
        epochs = self.config['ml_training']['epochs']
        batch_size = self.config['ml_training']['batch_size']
        best_val_loss = float('inf')
        patience_counter = 0
        
        training_losses = []
        validation_losses = []
        
        for epoch in range(epochs):
            # Training phase
            self.stability_model.train()
            epoch_train_loss = 0
            
            for i in range(0, len(X_train_tensor), batch_size):
                batch_X = X_train_tensor[i:i+batch_size]
                batch_y = {k: v[i:i+batch_size] for k, v in y_train_tensor.items()}
                
                optimizer.zero_grad()
                
                outputs = self.stability_model(batch_X)
                
                # Multi-task loss
                stability_loss = F.binary_cross_entropy(
                    outputs['stability_probability'].squeeze(),
                    batch_y['stability_probability']
                )
                
                time_loss = F.mse_loss(
                    outputs['time_to_failure_years'].squeeze(),
                    batch_y['time_to_failure_years']
                )
                
                ratio_loss = F.mse_loss(
                    outputs['critical_stress_ratio'].squeeze(),
                    batch_y['critical_stress_ratio']
                )
                
                total_loss = stability_loss + 0.3 * time_loss + 0.2 * ratio_loss
                
                total_loss.backward()
                optimizer.step()
                
                epoch_train_loss += total_loss.item()
            
            # Validation phase
            self.stability_model.eval()
            with torch.no_grad():
                val_outputs = self.stability_model(X_val_tensor)
                
                val_stability_loss = F.binary_cross_entropy(
                    val_outputs['stability_probability'].squeeze(),
                    y_val_tensor['stability_probability']
                )
                
                val_time_loss = F.mse_loss(
                    val_outputs['time_to_failure_years'].squeeze(),
                    y_val_tensor['time_to_failure_years']
                )
                
                val_ratio_loss = F.mse_loss(
                    val_outputs['critical_stress_ratio'].squeeze(),
                    y_val_tensor['critical_stress_ratio']
                )
                
                val_total_loss = val_stability_loss + 0.3 * val_time_loss + 0.2 * val_ratio_loss
            
            # Record losses
            training_losses.append(epoch_train_loss / (len(X_train_tensor) // batch_size + 1))
            validation_losses.append(val_total_loss.item())
            
            # Learning rate scheduling
            scheduler.step(val_total_loss)
            
            # Early stopping
            if val_total_loss < best_val_loss:
                best_val_loss = val_total_loss
                patience_counter = 0
                # Save best model state
                torch.save(self.stability_model.state_dict(), 'best_cap_rock_model.pth')
            else:
                patience_counter += 1
                if patience_counter >= self.config['ml_training']['early_stopping_patience']:
                    self.logger.info(f"Early stopping at epoch {epoch}")
                    break
            
            if epoch % 50 == 0:
                self.logger.info(f"Epoch {epoch}: Train Loss = {training_losses[-1]:.6f}, "
                               f"Val Loss = {validation_losses[-1]:.6f}")
        
        # Load best model
        self.stability_model.load_state_dict(torch.load('best_cap_rock_model.pth'))
        
        return {
            'status': 'trained',
            'epochs_completed': len(training_losses),
            'final_train_loss': training_losses[-1],
            'final_val_loss': validation_losses[-1],
            'best_val_loss': best_val_loss,
            'training_losses': training_losses,
            'validation_losses': validation_losses
        }
    
    def _prepare_training_data(self, training_data: List[Dict]) -> Tuple[np.ndarray, Dict[str, np.ndarray]]:
        """Prepare training data for ML model"""
        
        features = []
        targets = {
            'stability_probability': [],
            'time_to_failure_years': [],
            'critical_stress_ratio': []
        }
        
        for sample in training_data:
            # Extract features (same as in _prepare_ml_features)
            cap_rock = sample['cap_rock_properties']
            stress = sample['stress_state']
            thermal = sample['thermal_data']
            
            feature_vector = self._prepare_ml_features(cap_rock, stress, thermal)
            features.append(feature_vector)
            
            # Extract targets
            targets['stability_probability'].append(sample.get('stability_probability', 0.5))
            targets['time_to_failure_years'].append(sample.get('time_to_failure_years', 1000))
            targets['critical_stress_ratio'].append(sample.get('critical_stress_ratio', 0.5))
        
        X = np.array(features)
        y = {k: np.array(v) for k, v in targets.items()}
        
        # Normalize features
        scaler = StandardScaler()
        X = scaler.fit_transform(X)
        
        return X, y
    
