    def _add_mohr_circle_plot(self, fig: go.Figure, stress_state: StressState,
                            cap_rock_props: CapRockProperties, row: int, col: int):
        """Add Mohr circle analysis to plot"""
        
        # Mohr circle parameters
        center = (stress_state.effective_stress_1 + stress_state.effective_stress_3) / 2
        radius = (stress_state.effective_stress_1 - stress_state.effective_stress_3) / 2
        
        # Circle points
        theta = np.linspace(0, 2*np.pi, 100)
        circle_x = center + radius * np.cos(theta)
        circle_y = radius * np.sin(theta)
        
        # Mohr circle
        fig.add_trace(
            go.Scatter(
                x=circle_x,
                y=circle_y,
                mode='lines',
                name='Mohr Circle',
                line=dict(color='blue', width=2)
            ),
            row=row, col=col
        )
        
        # Failure envelope (Mohr-Coulomb)
        friction_angle = np.radians(cap_rock_props.friction_angle_deg)
        cohesion = cap_rock_props.cohesion_mpa
        
        sigma_range = np.linspace(-10, max(stress_state.effective_stress_1, 200), 100)
        tau_failure = cohesion + sigma_range * np.tan(friction_angle)
        
        fig.add_trace(
            go.Scatter(
                x=sigma_range,
                y=tau_failure,
                mode='lines',
                name='Failure Envelope',
                line=dict(color='red', width=2, dash='dash')
            ),
            row=row, col=col
        )
        
        # Principal stresses
        fig.add_trace(
            go.Scatter(
                x=[stress_state.effective_stress_3, stress_state.effective_stress_1],
                y=[0, 0],
                mode='markers',
                name='Principal Stresses',
                marker=dict(color='red', size=8, symbol='diamond')
            ),
            row=row, col=col
        )

    # Support methods for comprehensive implementations
    def _calculate_great_circle_distance(self, lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Calculate great circle distance between two points in degrees"""
        try:
            lat1_rad = math.radians(lat1)
            lon1_rad = math.radians(lon1)
            lat2_rad = math.radians(lat2)
            lon2_rad = math.radians(lon2)
            
            dlat = lat2_rad - lat1_rad
            dlon = lon2_rad - lon1_rad
            
            a = math.sin(dlat/2)**2 + math.cos(lat1_rad) * math.cos(lat2_rad) * math.sin(dlon/2)**2
            c = 2 * math.asin(math.sqrt(a))
            
            # Convert to degrees (111.32 km per degree)
            distance_degrees = c * 180 / math.pi
            return distance_degrees * 111.32  # Return distance in km
        except Exception:
            return math.sqrt((lat2 - lat1)**2 + (lon2 - lon1)**2) * 111.32
    
    def _calculate_pacific_rim_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to Pacific Ring of Fire"""
        pacific_rim_points = [
            (61.0, -153.0),  # Alaska
            (46.0, -122.0),  # Cascade
            (35.0, 139.0),   # Japan  
            (14.0, 121.0),   # Philippines
            (-6.0, 107.0),   # Indonesia
            (-37.0, 177.0),  # New Zealand
            (-22.0, -68.0)   # Andes
        ]
        
        min_distance = float('inf')
        for pr_lat, pr_lon in pacific_rim_points:
            distance = self._calculate_great_circle_distance(lat, lon, pr_lat, pr_lon)
            min_distance = min(min_distance, distance)
        
        return min_distance
    
    def _calculate_ridge_distance(self, lat: float, lon: float) -> float:
        """Calculate distance to mid-ocean ridges"""
        ridge_points = [
            (64.0, -19.0),   # Iceland
            (0.0, -30.0),    # Mid-Atlantic
            (-50.0, 0.0),    # Southwest Indian
            (0.0, 90.0),     # Central Indian
            (0.0, -110.0)    # East Pacific Rise
        ]
        
        min_distance = float('inf')
        for r_lat, r_lon in ridge_points:
            distance = self._calculate_great_circle_distance(lat, lon, r_lat, r_lon)
            min_distance = min(min_distance, distance)
        
        return min_distance
    
