            # Comprehensive plume potential calculation
            thermal_weight = 0.25 * plume_analysis['thermal_structure']['potential']
            velocity_weight = 0.20 * plume_analysis['velocity_field']['potential'] 
            chemical_weight = 0.20 * plume_analysis['chemical_signature']['potential']
            seismic_weight = 0.20 * plume_analysis['seismic_tomography']['potential']
            surface_weight = 0.15 * plume_analysis['surface_expression']['potential']
            
