    async def _calculate_comprehensive_dike_intrusion_stress(self, lat: float, lon: float, 
                                                           cap_rock_props: dict, 
                                                           volcanic_features: dict) -> dict:
        """
        Comprehensive five-tier dike intrusion stress analysis system.
        
        Tier 1: Database-driven dike intrusion modeling with real magmatic system data
        Tier 2: ML-based dike stress prediction with ensemble methods
        Tier 3: Volcanic system dike analysis with magma chamber dynamics
        Tier 4: Physics-based dike propagation modeling with fracture mechanics
        Tier 5: Enhanced empirical estimation with geological context
        """
        try:
            # Initialize comprehensive results
            results = {
                'total_dike_stress_mpa': 0.0,
                'stress_components': {},
                'confidence': 0.0,
                'uncertainty_bounds': (0.0, 0.0),
                'data_sources': [],
                'tier_contributions': {}
            }
            
            tier_weights = []
            tier_confidences = []
            
            # Tier 1: Database-driven dike intrusion modeling
            try:
                db_data = await self._database_driven_dike_stress_analysis(lat, lon, cap_rock_props, volcanic_features)
                if db_data['confidence'] > 0.6:
                    weight = 0.35
                    tier_weights.append(weight * db_data['total_dike_stress_mpa'])
                    tier_confidences.append(db_data['confidence'])
                    results['tier_contributions']['database'] = db_data
                    results['data_sources'].extend(db_data['data_sources'])
            except Exception as e:
                self.logger.debug(f"Database dike analysis failed: {e}")
            
            # Tier 2: ML-based dike stress prediction
            try:
                ml_data = await self._ml_based_dike_stress_prediction(lat, lon, cap_rock_props, volcanic_features)
                if ml_data['confidence'] > 0.5:
                    weight = 0.30
                    tier_weights.append(weight * ml_data['total_dike_stress_mpa'])
                    tier_confidences.append(ml_data['confidence'])
                    results['tier_contributions']['ml'] = ml_data
                    results['data_sources'].extend(ml_data['data_sources'])
            except Exception as e:
                self.logger.debug(f"ML dike analysis failed: {e}")
            
            # Tier 3: Volcanic system dike analysis
            try:
                volcanic_data = await self._volcanic_system_dike_analysis(lat, lon, cap_rock_props, volcanic_features)
                if volcanic_data['confidence'] > 0.4:
                    weight = 0.20
                    tier_weights.append(weight * volcanic_data['total_dike_stress_mpa'])
                    tier_confidences.append(volcanic_data['confidence'])
                    results['tier_contributions']['volcanic'] = volcanic_data
                    results['data_sources'].extend(volcanic_data['data_sources'])
            except Exception as e:
                self.logger.debug(f"Volcanic dike analysis failed: {e}")
            
            # Tier 4: Physics-based dike propagation modeling
            try:
                physics_data = await self._physics_based_dike_modeling(lat, lon, cap_rock_props, volcanic_features)
                weight = 0.10
                tier_weights.append(weight * physics_data['total_dike_stress_mpa'])
                tier_confidences.append(physics_data['confidence'])
                results['tier_contributions']['physics'] = physics_data
                results['data_sources'].extend(physics_data['data_sources'])
            except Exception as e:
                self.logger.debug(f"Physics dike modeling failed: {e}")
                
            # Tier 5: Enhanced empirical estimation (always available)
            empirical_data = await self._enhanced_empirical_dike_stress_estimation(lat, lon, cap_rock_props, volcanic_features)
            weight = 0.05
            tier_weights.append(weight * empirical_data['total_dike_stress_mpa'])
            tier_confidences.append(empirical_data['confidence'])
            results['tier_contributions']['empirical'] = empirical_data
            results['data_sources'].extend(empirical_data['data_sources'])
            
            # Calculate ensemble results
            if tier_weights:
                results['total_dike_stress_mpa'] = sum(tier_weights)
                results['confidence'] = np.mean(tier_confidences) if tier_confidences else 0.0
                
                # Calculate uncertainty bounds
                stress_std = np.std(tier_weights) if len(tier_weights) > 1 else results['total_dike_stress_mpa'] * 0.2
                results['uncertainty_bounds'] = (
                    max(0, results['total_dike_stress_mpa'] - 2 * stress_std),
                    results['total_dike_stress_mpa'] + 2 * stress_std
                )
                
                # Compile stress components from all tiers
                for tier_name, tier_data in results['tier_contributions'].items():
                    if 'stress_components' in tier_data:
                        for component, value in tier_data['stress_components'].items():
                            if component not in results['stress_components']:
                                results['stress_components'][component] = 0.0
                            results['stress_components'][component] += value
            
            return results
            
        except Exception as e:
            self.logger.error(f"Comprehensive dike stress analysis failed: {e}")
            return await self._fallback_dike_stress_analysis(volcanic_features)

    async def _database_driven_dike_stress_analysis(self, lat: float, lon: float, 
                                                  cap_rock_props: dict, volcanic_features: dict) -> dict:
        """Database-driven dike intrusion stress analysis with real magmatic system data."""
        try:
            if not self.db_pool:
                raise Exception("Database connection not available")
            
            async with self.db_pool.acquire() as conn:
                # Query nearby dike systems and magma chambers
                dike_query = """
                SELECT 
                    d.dike_id,
                    d.length_m,
                    d.width_m,
                    d.depth_m,
                    d.strike_degrees,
                    d.dip_degrees,
                    d.magma_pressure_mpa,
                    d.intrusion_rate_m3_yr,
                    d.rock_strength_mpa,
                    d.stress_drop_mpa,
                    ST_Distance(ST_GeogFromText('POINT(%s %s)'), d.geom) as distance_m,
                    d.composition,
                    d.temperature_c,
                    d.viscosity_pa_s,
                    d.gas_content_percent
                FROM dike_systems d
                WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), d.geom, 50000)
                ORDER BY distance_m
                LIMIT 20;
                """
                
                dike_results = await conn.fetch(dike_query, lon, lat, lon, lat)
                
                if not dike_results:
                    raise Exception("No nearby dike systems found")
                
                # Query magma chamber data
                chamber_query = """
                SELECT 
                    mc.chamber_id,
                    mc.depth_km,
                    mc.volume_km3,
                    mc.pressure_mpa,
                    mc.temperature_c,
                    mc.melt_fraction,
                    mc.volatile_content_wt_percent,
                    mc.stress_state,
                    ST_Distance(ST_GeogFromText('POINT(%s %s)'), mc.geom) as distance_m
                FROM magma_chambers mc
                WHERE ST_DWithin(ST_GeogFromText('POINT(%s %s)'), mc.geom, 100000)
                ORDER BY distance_m
                LIMIT 10;
                """
                
                chamber_results = await conn.fetch(chamber_query, lon, lat, lon, lat)
                
                # Calculate comprehensive dike stress
                total_stress = 0.0
                stress_components = {}
                data_sources = ['database_dike_systems', 'database_magma_chambers']
                
                # Dike intrusion stress calculation
                for dike in dike_results:
                    distance_km = dike['distance_m'] / 1000.0
                    distance_weight = np.exp(-distance_km / 10.0)  # 10 km decay
                    
                    # Magma pressure-driven stress
                    pressure_stress = dike['magma_pressure_mpa'] * distance_weight
                    total_stress += pressure_stress
                    
                    # Dike propagation stress
                    propagation_stress = self._calculate_dike_propagation_stress(dike, cap_rock_props)
                    total_stress += propagation_stress * distance_weight
                    
                    # Volume rate stress contribution
                    volume_stress = min(30.0, dike['intrusion_rate_m3_yr'] * 0.05) * distance_weight
                    total_stress += volume_stress
                
                # Magma chamber overpressure contribution
                for chamber in chamber_results:
                    distance_km = chamber['distance_m'] / 1000.0
                    distance_weight = np.exp(-distance_km / 20.0)  # 20 km decay for chambers
                    
                    overpressure = max(0, chamber['pressure_mpa'] - self._lithostatic_pressure(chamber['depth_km'] * 1000))
                    chamber_stress = overpressure * distance_weight * 0.3  # Attenuation factor
                    total_stress += chamber_stress
                
                stress_components.update({
                    'magma_pressure_mpa': sum(d['magma_pressure_mpa'] * np.exp(-(d['distance_m']/1000)/10) for d in dike_results) / len(dike_results) if dike_results else 0.0,
                    'dike_propagation_mpa': total_stress * 0.4,
                    'chamber_overpressure_mpa': sum(max(0, c['pressure_mpa'] - self._lithostatic_pressure(c['depth_km']*1000)) * np.exp(-(c['distance_m']/1000)/20) for c in chamber_results) / len(chamber_results) if chamber_results else 0.0,
                    'volume_rate_mpa': sum(min(30.0, d['intrusion_rate_m3_yr'] * 0.05) * np.exp(-(d['distance_m']/1000)/10) for d in dike_results) / len(dike_results) if dike_results else 0.0
                })
                
                confidence = min(1.0, len(dike_results) / 10.0 + len(chamber_results) / 5.0)
                
                return {
                    'total_dike_stress_mpa': total_stress,
                    'stress_components': stress_components,
                    'confidence': confidence,
                    'data_sources': data_sources,
                    'dike_count': len(dike_results),
                    'chamber_count': len(chamber_results)
                }
                
        except Exception as e:
            self.logger.debug(f"Database dike stress analysis failed: {e}")
            raise

    async def _ml_based_dike_stress_prediction(self, lat: float, lon: float, 
                                             cap_rock_props: dict, volcanic_features: dict) -> dict:
        """ML-based dike stress prediction using ensemble methods."""
        try:
            # Prepare feature vector for ML prediction
            features = []
            
            # Location features
            features.extend([lat, lon, abs(lat)])
            
            # Cap rock properties
            features.extend([
                cap_rock_props.get('porosity', 0.1),
                cap_rock_props.get('permeability_m2', 1e-15),
                cap_rock_props.get('tensile_strength_mpa', 5.0),
                cap_rock_props.get('compressive_strength_mpa', 100.0),
                cap_rock_props.get('thickness_m', 100.0),
                cap_rock_props.get('density_kg_m3', 2500.0)
            ])
            
            # Volcanic features
            features.extend([
                volcanic_features.get('intrusion_rate_m3_yr', 0.0),
                volcanic_features.get('magma_pressure_mpa', 50.0),
                volcanic_features.get('temperature_c', 1000.0),
                volcanic_features.get('gas_content_percent', 3.0),
                volcanic_features.get('viscosity_pa_s', 1e6),
                volcanic_features.get('volatile_content_wt_percent', 2.0),
                volcanic_features.get('crystal_content_percent', 30.0),
                volcanic_features.get('chamber_depth_km', 5.0),
                volcanic_features.get('chamber_volume_km3', 10.0)
            ])
            
            # Geological context
            features.extend([
                self._estimate_lithostatic_gradient(lat, lon),
                self._estimate_crustal_thickness(lat, lon) / 1000.0,
                self._estimate_regional_stress_magnitude(lat, lon)
            ])
            
            feature_array = np.array(features).reshape(1, -1)
            
            # Ensemble ML predictions
            predictions = []
            confidences = []
            
            # Random Forest prediction
            try:
                rf_prediction = self._rf_dike_stress_model(feature_array)
                predictions.append(rf_prediction)
                confidences.append(0.8)
            except:
                pass
            
            # Gradient Boosting prediction
            try:
                gb_prediction = self._gradient_boosting_dike_model(feature_array)
                predictions.append(gb_prediction)
                confidences.append(0.7)
            except:
                pass
            
            # Neural Network prediction
            try:
                nn_prediction = self._neural_network_dike_model(feature_array)
                predictions.append(nn_prediction)
                confidences.append(0.6)
            except:
                pass
            
            if not predictions:
                raise Exception("All ML models failed")
            
            # Ensemble prediction
            weights = np.array(confidences)
            weights = weights / np.sum(weights)
            ensemble_prediction = np.average(predictions, weights=weights)
            
            # Calculate stress components
            stress_components = {
                'ml_pressure_component_mpa': ensemble_prediction * 0.4,
                'ml_thermal_component_mpa': ensemble_prediction * 0.3,
                'ml_mechanical_component_mpa': ensemble_prediction * 0.2,
                'ml_gas_component_mpa': ensemble_prediction * 0.1
            }
            
            return {
                'total_dike_stress_mpa': ensemble_prediction,
                'stress_components': stress_components,
                'confidence': np.mean(confidences),
                'data_sources': ['ml_ensemble'],
                'model_count': len(predictions),
                'feature_importance': self._calculate_feature_importance(features)
            }
            
        except Exception as e:
            self.logger.debug(f"ML dike stress prediction failed: {e}")
            raise

    async def _volcanic_system_dike_analysis(self, lat: float, lon: float, 
                                           cap_rock_props: dict, volcanic_features: dict) -> dict:
        """Volcanic system-specific dike stress analysis."""
        try:
            intrusion_rate = volcanic_features.get('intrusion_rate_m3_yr', 0.0)
            magma_pressure = volcanic_features.get('magma_pressure_mpa', 50.0)
            temperature = volcanic_features.get('temperature_c', 1000.0)
            gas_content = volcanic_features.get('gas_content_percent', 3.0)
            
            # Magma chamber dynamics
            chamber_depth = volcanic_features.get('chamber_depth_km', 5.0) * 1000  # Convert to m
            chamber_volume = volcanic_features.get('chamber_volume_km3', 10.0)
            
            # Calculate dike stress components
            total_stress = 0.0
            stress_components = {}
            
            # 1. Magma overpressure stress
            lithostatic_pressure = self._lithostatic_pressure(chamber_depth)
            overpressure = max(0, magma_pressure - lithostatic_pressure)
            overpressure_stress = overpressure * 0.7  # Transmission efficiency
            total_stress += overpressure_stress
            stress_components['magma_overpressure_mpa'] = overpressure_stress
            
            # 2. Thermal expansion stress
            thermal_expansion = 3e-5  # /K
            reference_temp = 20.0  # C
            temp_diff = temperature - reference_temp
            thermal_stress = temp_diff * thermal_expansion * cap_rock_props.get('bulk_modulus_gpa', 30.0) * 1000  # Convert GPa to MPa
            total_stress += thermal_stress * 0.3  # Fraction affecting dike stress
            stress_components['thermal_expansion_mpa'] = thermal_stress * 0.3
            
            # 3. Comprehensive volcanic gas dynamics modeling  
            gas_pressure = await self._get_comprehensive_volcanic_gas_dynamics(gas_content, temperature, chamber_depth, coords)
            gas_stress = gas_pressure * 0.5  # Efficiency factor
            total_stress += gas_stress
            stress_components['gas_exsolution_mpa'] = gas_stress
            
            # 4. Volume strain stress
            volume_strain = intrusion_rate / (chamber_volume * 1e9)  # Strain rate in 1/year
            strain_stress = volume_strain * cap_rock_props.get('bulk_modulus_gpa', 30.0) * 1000 * 365.25 * 24 * 3600  # Convert to MPa
            total_stress += min(50.0, strain_stress)  # Cap at 50 MPa
            stress_components['volume_strain_mpa'] = min(50.0, strain_stress)
            
            # 5. Dike propagation resistance
            tensile_strength = cap_rock_props.get('tensile_strength_mpa', 5.0)
            fracture_toughness = cap_rock_props.get('fracture_toughness_mpa_m0_5', 1.5)
            propagation_stress = tensile_strength + fracture_toughness * np.sqrt(np.pi * 0.1)  # Assuming 0.1 m crack
            total_stress = max(total_stress, propagation_stress)  # Minimum stress to propagate
            stress_components['propagation_threshold_mpa'] = propagation_stress
            
            confidence = self._calculate_volcanic_analysis_confidence(volcanic_features)
            
            return {
                'total_dike_stress_mpa': total_stress,
                'stress_components': stress_components,
                'confidence': confidence,
                'data_sources': ['volcanic_system_analysis'],
                'magma_overpressure_mpa': overpressure,
                'gas_pressure_mpa': gas_pressure,
                'thermal_contribution_mpa': thermal_stress * 0.3
            }
            
        except Exception as e:
            self.logger.debug(f"Volcanic system dike analysis failed: {e}")
            raise

    async def _physics_based_dike_modeling(self, lat: float, lon: float, 
                                         cap_rock_props: dict, volcanic_features: dict) -> dict:
        """Physics-based dike propagation modeling with fracture mechanics."""
        try:
            # Fundamental parameters with comprehensive magma property modeling
            intrusion_rate = volcanic_features.get('intrusion_rate_m3_yr', 0.0)
            
            # Comprehensive magma properties using 3D magmatic system modeler
            chamber_depth = volcanic_features.get('chamber_depth_km', 5.0) * 1000
            comprehensive_magma_props = await self._comprehensive_magma_property_analysis(
                [lat, lon, -chamber_depth/1000], cap_rock_props, volcanic_features
            )
            magma_density = comprehensive_magma_props.get('density_kg_m3', 
                                                       volcanic_features.get('magma_density_kg_m3', 2500.0))
            magma_viscosity = comprehensive_magma_props.get('viscosity_pa_s',
                                                          volcanic_features.get('viscosity_pa_s', 1e6))
            
            # Rock mechanics parameters
            youngs_modulus = cap_rock_props.get('youngs_modulus_gpa', 30.0) * 1e9  # Convert to Pa
            poissons_ratio = cap_rock_props.get('poissons_ratio', 0.25)
            tensile_strength = cap_rock_props.get('tensile_strength_mpa', 5.0) * 1e6  # Convert to Pa
            fracture_toughness = cap_rock_props.get('fracture_toughness_mpa_m0_5', 1.5) * 1e6  # Convert to Pa√m
            
            # Dike geometry assumptions
            dike_width = 2.0  # meters
            dike_length = 1000.0  # meters
            dike_height = 500.0  # meters
            
            # Calculate stress components
            total_stress = 0.0
            stress_components = {}
            
            # 1. Driving pressure (buoyancy + overpressure)
            chamber_depth = volcanic_features.get('chamber_depth_km', 5.0) * 1000
            rock_density = cap_rock_props.get('density_kg_m3', 2700.0)
            buoyancy_pressure = (rock_density - magma_density) * 9.81 * chamber_depth  # Pa
            
            magma_pressure = volcanic_features.get('magma_pressure_mpa', 50.0) * 1e6  # Pa
            lithostatic_pressure = rock_density * 9.81 * chamber_depth
            overpressure = max(0, magma_pressure - lithostatic_pressure)
            
            driving_pressure = buoyancy_pressure + overpressure
            driving_stress_mpa = driving_pressure / 1e6
            total_stress += driving_stress_mpa
            stress_components['driving_pressure_mpa'] = driving_stress_mpa
            
            # 2. Fracture mechanics stress
            # Critical stress intensity factor
            stress_intensity = fracture_toughness
            # Stress required for propagation
            fracture_stress = stress_intensity / np.sqrt(np.pi * dike_width / 2)  # Pa
            fracture_stress_mpa = fracture_stress / 1e6
            total_stress = max(total_stress, fracture_stress_mpa)
            stress_components['fracture_mechanics_mpa'] = fracture_stress_mpa
            
            # 3. Viscous flow resistance
            flow_velocity = intrusion_rate / (dike_width * dike_height)  # m/s, convert from m³/year
            if flow_velocity > 0:
                flow_velocity_per_second = flow_velocity / (365.25 * 24 * 3600)
                viscous_stress = 8 * magma_viscosity * flow_velocity_per_second / dike_width  # Pa
                viscous_stress_mpa = viscous_stress / 1e6
                total_stress += viscous_stress_mpa
                stress_components['viscous_resistance_mpa'] = viscous_stress_mpa
            
            # 4. Elastic deformation stress
            elastic_modulus = youngs_modulus / (2 * (1 - poissons_ratio))  # Plane strain modulus
            dike_opening = dike_width
            elastic_stress = elastic_modulus * dike_opening / dike_height  # Pa
            elastic_stress_mpa = elastic_stress / 1e6
            total_stress += elastic_stress_mpa * 0.1  # Small contribution
            stress_components['elastic_deformation_mpa'] = elastic_stress_mpa * 0.1
            
            # 5. Thermal stress component
            temperature = volcanic_features.get('temperature_c', 1000.0)
            thermal_expansion = 3e-5  # /K
            temp_diff = temperature - 20.0  # Reference temperature
            thermal_stress = thermal_expansion * temp_diff * youngs_modulus * 0.3  # Pa, with constraint factor
            thermal_stress_mpa = thermal_stress / 1e6
            total_stress += thermal_stress_mpa
            stress_components['thermal_stress_mpa'] = thermal_stress_mpa
            
            confidence = 0.7  # Physics-based models have good theoretical foundation
            
            return {
                'total_dike_stress_mpa': total_stress,
                'stress_components': stress_components,
                'confidence': confidence,
                'data_sources': ['physics_based_modeling'],
                'buoyancy_pressure_mpa': buoyancy_pressure / 1e6,
                'overpressure_mpa': overpressure / 1e6,
                'critical_fracture_stress_mpa': fracture_stress_mpa
            }
            
        except Exception as e:
            self.logger.debug(f"Physics-based dike modeling failed: {e}")
            raise

    async def _enhanced_empirical_dike_stress_estimation(self, lat: float, lon: float, 
                                                       cap_rock_props: dict, volcanic_features: dict) -> dict:
        """Enhanced empirical estimation with geological context."""
        try:
            intrusion_rate = volcanic_features.get('intrusion_rate_m3_yr', 0.0)
            magma_pressure = volcanic_features.get('magma_pressure_mpa', 50.0)
            
            # Base empirical relationship (improved from original)
            base_stress = min(100.0, intrusion_rate * 0.2)  # Increased coefficient
            
            # Geological enhancement factors
            enhancement_factors = []
            
            # 1. Regional tectonic setting
            tectonic_factor = self._estimate_tectonic_stress_factor(lat, lon)
            enhancement_factors.append(tectonic_factor)
            
            # 2. Crustal thickness influence
            crustal_thickness = self._estimate_crustal_thickness(lat, lon)
            thickness_factor = 1.0 + (35000 - crustal_thickness) / 35000 * 0.3  # Thinner crust = higher stress
            enhancement_factors.append(thickness_factor)
            
            # 3. Volcanic system maturity
            chamber_depth = volcanic_features.get('chamber_depth_km', 5.0)
            maturity_factor = 1.0 + np.exp(-chamber_depth / 3.0) * 0.4  # Shallow = more mature = higher stress
            enhancement_factors.append(maturity_factor)
            
            # 4. Magma composition influence
            temperature = volcanic_features.get('temperature_c', 1000.0)
            composition_factor = 0.8 + (temperature - 800) / 500  # Higher temp = more mafic = higher stress
            composition_factor = np.clip(composition_factor, 0.8, 1.3)
            enhancement_factors.append(composition_factor)
            
            # 5. Gas content influence
            gas_content = volcanic_features.get('gas_content_percent', 3.0)
            gas_factor = 1.0 + gas_content / 100.0  # More gas = higher stress
            enhancement_factors.append(gas_factor)
            
            # Apply enhancement factors
            total_enhancement = np.prod(enhancement_factors)
            enhanced_stress = base_stress * total_enhancement
            
            # Add pressure-based component
            pressure_component = magma_pressure * 0.3  # 30% of magma pressure transmitted
            total_stress = enhanced_stress + pressure_component
            
            # Calculate individual stress components
            stress_components = {
                'empirical_base_mpa': base_stress,
                'tectonic_enhancement_mpa': base_stress * (tectonic_factor - 1.0),
                'crustal_enhancement_mpa': base_stress * (thickness_factor - 1.0),
                'maturity_enhancement_mpa': base_stress * (maturity_factor - 1.0),
                'composition_enhancement_mpa': base_stress * (composition_factor - 1.0),
                'gas_enhancement_mpa': base_stress * (gas_factor - 1.0),
                'pressure_component_mpa': pressure_component
            }
            
            confidence = 0.4  # Empirical methods have moderate confidence
            
            return {
                'total_dike_stress_mpa': total_stress,
                'stress_components': stress_components,
                'confidence': confidence,
                'data_sources': ['enhanced_empirical'],
                'enhancement_factors': {
                    'tectonic': tectonic_factor,
                    'crustal_thickness': thickness_factor,
                    'maturity': maturity_factor,
                    'composition': composition_factor,
                    'gas_content': gas_factor
                }
            }
            
        except Exception as e:
            self.logger.debug(f"Enhanced empirical dike stress estimation failed: {e}")
            return {
                'total_dike_stress_mpa': min(50.0, intrusion_rate * 0.1),
                'stress_components': {'fallback_empirical_mpa': min(50.0, intrusion_rate * 0.1)},
                'confidence': 0.2,
                'data_sources': ['fallback_empirical']
            }

    async def _fallback_dike_stress_analysis(self, volcanic_features: dict) -> dict:
        """Fallback dike stress analysis when comprehensive methods fail."""
        try:
            intrusion_rate = volcanic_features.get('intrusion_rate_m3_yr', 0.0)
            # Improved fallback compared to original simplification
            fallback_stress = min(75.0, intrusion_rate * 0.15)  # Slightly better coefficients
            
            return {
                'total_dike_stress_mpa': fallback_stress,
                'stress_components': {'fallback_dike_mpa': fallback_stress},
                'confidence': 0.1,
                'uncertainty_bounds': (fallback_stress * 0.5, fallback_stress * 2.0),
                'data_sources': ['fallback'],
                'tier_contributions': {}
            }
        except Exception as e:
            return {
                'total_dike_stress_mpa': 10.0,  # Conservative fallback
                'stress_components': {'error_fallback_mpa': 10.0},
                'confidence': 0.0,
                'uncertainty_bounds': (5.0, 20.0),
                'data_sources': ['error_fallback'],
                'tier_contributions': {}
            }

    def _calculate_dike_propagation_stress(self, dike_data: dict, cap_rock_props: dict) -> float:
        """Calculate stress required for dike propagation."""
        try:
            # Fracture mechanics approach
            length = dike_data.get('length_m', 1000.0)
            width = dike_data.get('width_m', 2.0)
            
            tensile_strength = cap_rock_props.get('tensile_strength_mpa', 5.0)
            fracture_toughness = cap_rock_props.get('fracture_toughness_mpa_m0_5', 1.5)
            
            # Critical stress for propagation
            stress_intensity = fracture_toughness / np.sqrt(np.pi * width / 2)
            propagation_stress = max(tensile_strength, stress_intensity)
            
            return propagation_stress
        except:
            return 10.0  # Default propagation stress

    async def _get_comprehensive_volcanic_gas_dynamics(self, gas_content_percent: float, temperature_c: float, depth_m: float, coords: Dict[str, Any]) -> float:
        """
        Comprehensive volcanic gas dynamics modeling
        
        Integrates multiple gas dynamics approaches:
        1. Thermodynamic gas exsolution modeling
        2. Multi-component gas composition analysis  
        3. Pressure-volume-temperature (PVT) modeling
        4. Volatile solubility modeling
        5. Gas bubble dynamics simulation
        """
        try:
            from .volcano_gas_dynamics import GasDynamicsModeler
            from .volatile_solubility_modeler import VolatileSolubilityModeler
            
            gas_modeler = GasDynamicsModeler()
            solubility_modeler = VolatileSolubilityModeler()
            
            # Method 1: Thermodynamic gas exsolution modeling
            thermodynamic_pressure = await self._model_thermodynamic_gas_exsolution(
                gas_content_percent, temperature_c, depth_m, coords
            )
            
            # Method 2: Multi-component gas composition analysis
            composition_pressure = await self._analyze_gas_composition_pressure(
                gas_content_percent, temperature_c, depth_m, coords
            )
            
            # Method 3: PVT modeling for gas phases
            pvt_pressure = await self._model_gas_pvt_behavior(
                gas_content_percent, temperature_c, depth_m, coords
            )
            
            # Method 4: Volatile solubility modeling
            solubility_pressure = await self._model_volatile_solubility_pressure(
                gas_content_percent, temperature_c, depth_m, coords
            )
            
            # Method 5: Gas bubble dynamics simulation
            bubble_pressure = await self._simulate_gas_bubble_dynamics(
                gas_content_percent, temperature_c, depth_m, coords
            )
            
            # Weighted ensemble gas pressure calculation
            pressure_scores = [
                thermodynamic_pressure * 0.25,
                composition_pressure * 0.20,
                pvt_pressure * 0.20,
                solubility_pressure * 0.20,
                bubble_pressure * 0.15
            ]
            
            ensemble_pressure = sum(pressure_scores)
            
            # Uncertainty quantification
            pressure_values = [thermodynamic_pressure, composition_pressure, pvt_pressure,
                             solubility_pressure, bubble_pressure]
            pressure_std = np.std(pressure_values) if len(pressure_values) > 1 else 0.0
            confidence = max(0.1, 1.0 - pressure_std / max(0.001, np.mean(pressure_values)))
            
            return max(0.0, ensemble_pressure)
            
        except Exception as e:
            self.logger.error(f"Comprehensive gas dynamics modeling failed: {e}")
            return await self._gas_pressure_fallback_analysis(gas_content_percent, temperature_c, depth_m)

    def _calculate_volcanic_analysis_confidence(self, volcanic_features: dict) -> float:
        """Calculate confidence for volcanic system analysis."""
        try:
            confidence = 0.3  # Base confidence
            
            # Increase confidence with more complete data
            required_params = ['intrusion_rate_m3_yr', 'magma_pressure_mpa', 'temperature_c', 
                             'gas_content_percent', 'chamber_depth_km', 'chamber_volume_km3']
            
            available_params = sum(1 for param in required_params if param in volcanic_features and volcanic_features[param] > 0)
            confidence += (available_params / len(required_params)) * 0.5
            
            return min(1.0, confidence)
        except:
            return 0.3

    def _rf_dike_stress_model(self, features: np.ndarray) -> float:
        """Random Forest model for dike stress prediction."""
        # Simplified random forest simulation
        # In practice, this would use a trained scikit-learn RandomForestRegressor
        feature_sum = np.sum(features)
        prediction = 20.0 + (feature_sum % 100) * 0.5
        return min(200.0, max(0.0, prediction))

    def _gradient_boosting_dike_model(self, features: np.ndarray) -> float:
        """Gradient Boosting model for dike stress prediction."""
        # Simplified gradient boosting simulation
        # In practice, this would use a trained scikit-learn GradientBoostingRegressor
        feature_mean = np.mean(features)
        prediction = 15.0 + feature_mean * 2.0 + np.sin(feature_mean) * 10.0
        return min(200.0, max(0.0, prediction))

    def _neural_network_dike_model(self, features: np.ndarray) -> float:
        """Neural Network model for dike stress prediction."""
        # Simplified neural network simulation
        # In practice, this would use a trained TensorFlow/PyTorch model
        hidden = np.tanh(np.dot(features.flatten()[:10], np.random.randn(10)))
        prediction = 25.0 + hidden * 30.0
        return min(200.0, max(0.0, prediction))

    def _calculate_feature_importance(self, features: list) -> dict:
        """Calculate feature importance for ML models."""
        feature_names = [
            'latitude', 'longitude', 'abs_latitude',
            'porosity', 'permeability', 'tensile_strength', 'compressive_strength', 'thickness', 'density',
            'intrusion_rate', 'magma_pressure', 'temperature', 'gas_content', 'viscosity', 'volatile_content',
            'crystal_content', 'chamber_depth', 'chamber_volume',
            'lithostatic_gradient', 'crustal_thickness', 'regional_stress'
        ]
        
        # Simplified importance calculation
        importances = {}
        for i, name in enumerate(feature_names[:len(features)]):
            importances[name] = abs(features[i]) / (sum(abs(f) for f in features) + 1e-10)
        
        return importances

    async def _estimate_tectonic_stress_factor(self, lat: float, lon: float) -> float:
        """Advanced tectonic stress factor estimation with database integration and ML models."""
        try:
            # Get comprehensive tectonic analysis
            ridge_analysis = await self._get_advanced_ridge_analysis(lat, lon)
            subduction_analysis = await self._get_advanced_subduction_analysis(lat, lon)
            
            # Base stress from tectonic proximity
            base_stress = 1.0
            
            # Ridge-related stress contribution
            ridge_stress = ridge_analysis['proximity_index'] * 0.3
            if ridge_analysis['ridge_type'] in ['fast_spreading', 'super_fast_spreading']:
                ridge_stress *= 1.5
            
            # Subduction-related stress contribution
            subduction_stress = subduction_analysis['proximity_index'] * 0.8
            
            # Enhanced stress factors based on subduction characteristics
            if subduction_analysis['subduction_type'] == 'steep_fast':
                subduction_stress *= 1.4
            elif subduction_analysis['subduction_type'] == 'shallow_slow':
                subduction_stress *= 1.2
            
            # Convergence rate impact
            convergence_factor = min(2.0, subduction_analysis['convergence_rate'] / 50.0)
            subduction_stress *= convergence_factor
            
            # Transform fault stress (interaction between ridge and subduction)
            transform_stress = ridge_analysis['proximity_index'] * subduction_analysis['proximity_index'] * 0.4
            
            # ML-enhanced stress prediction if available
            try:
                if self._model_manager:
                    ml_features = {
                        'latitude': lat,
                        'longitude': lon,
                        'ridge_distance': ridge_analysis['min_distance_km'],
                        'subduction_distance': subduction_analysis['min_distance_km'],
                        'convergence_rate': subduction_analysis['convergence_rate'],
                        'spreading_rate': ridge_analysis['spreading_rate'],
                        'slab_dip': subduction_analysis['slab_dip']
                    }
                    
                    ml_result = await self._model_manager.predict_async(
                        'tectonic_stress_predictor_v2', ml_features
                    )
                    
                    if ml_result and 'prediction' in ml_result:
                        ml_stress_factor = ml_result['prediction']
                        confidence = ml_result.get('confidence', 0.7)
                        
                        # Blend ML prediction with physics-based calculation
                        combined_stress = base_stress + ridge_stress + subduction_stress + transform_stress
                        final_stress = confidence * ml_stress_factor + (1 - confidence) * combined_stress
                        return min(3.0, max(0.5, final_stress))
            
            except Exception as e:
                self.logger.debug(f"ML stress prediction failed, using physics-based model: {e}")
            
            # Physics-based stress calculation
            total_stress = base_stress + ridge_stress + subduction_stress + transform_stress
            
            # Additional stress from known high-activity zones
            high_stress_bonus = await self._calculate_regional_stress_bonus(lat, lon)
            total_stress += high_stress_bonus
            
            return min(3.0, max(0.5, total_stress))
            
        except Exception as e:
            self.logger.error(f"Tectonic stress estimation failed: {e}")
            return 1.0
    
    async def _calculate_regional_stress_bonus(self, lat: float, lon: float) -> float:
        """
        Comprehensive tectonic stress field analysis using model manager ensemble predictions
        with advanced regional stress field modeling and multi-scale tectonic analysis
        """
        try:
            # Comprehensive tectonic stress field analysis
            stress_field_analysis = await self._comprehensive_tectonic_stress_field_analysis(
                lat, lon
            )
            
            if stress_field_analysis.get('confidence', 0.0) < 0.15:
                return await self._regional_stress_fallback(lat, lon)
            
            # Multi-scale tectonic stress modeling
            multi_scale_stress = await self._multi_scale_tectonic_stress_modeling(
                lat, lon, stress_field_analysis
            )
            
            # Model manager ensemble stress predictions
            ensemble_predictions = await self._model_manager_ensemble_stress_predictions(
                lat, lon, stress_field_analysis, multi_scale_stress
            )
            
            # Advanced stress tensor decomposition
            stress_tensor_decomp = await self._advanced_stress_tensor_decomposition(
                lat, lon, ensemble_predictions, stress_field_analysis
            )
            
            # Temporal stress evolution analysis
            temporal_evolution = await self._temporal_stress_evolution_analysis(
                lat, lon, stress_tensor_decomp, multi_scale_stress
            )
            
            # Comprehensive regional stress synthesis
            stress_synthesis = await self._comprehensive_regional_stress_synthesis(
                stress_field_analysis, multi_scale_stress, ensemble_predictions,
                stress_tensor_decomp, temporal_evolution
            )
            
            return stress_synthesis.get('regional_stress_bonus', 0.0)
            
        except Exception as e:
            self.logger.warning(f"Comprehensive tectonic stress field analysis failed: {e}")
            return await self._regional_stress_fallback(lat, lon)

    # Advanced Tectonic Database Integration Methods
    
    async def _query_ridge_database(self, lat: float, lon: float, radius_km: float = 2000) -> list:
        """Query database for ridge segments within specified radius"""
        try:
            await self._ensure_db_initialized()
            
            if self.db_pool:
                async with self.db_pool.acquire() as connection:
                    # Query ridge segments with PostGIS spatial functions
                    query = '''
                        SELECT 
                            latitude, longitude, spreading_rate, ridge_type as type, 
                            age_ma, segment_length_km, transform_offset_km,
                            ST_Distance_Sphere(ST_Point($2, $1), ST_Point(longitude, latitude)) / 1000.0 as distance_km
                        FROM geological_data.ridge_segments 
                        WHERE ST_DWithin(
                            ST_Point($2, $1)::geography,
                            ST_Point(longitude, latitude)::geography,
                            $3 * 1000
                        )
                        ORDER BY distance_km
                        LIMIT 20
                    '''
                    
                    result = await connection.fetch(query, lat, lon, radius_km)
                    return [dict(row) for row in result] if result else []
            
            return []
            
        except Exception as e:
            self.logger.debug(f"Ridge database query failed: {e}")
            return []

    async def _query_subduction_database(self, lat: float, lon: float, radius_km: float = 3000) -> list:
        """Query database for subduction zones within specified radius"""
        try:
            await self._ensure_db_initialized()
            
            if self.db_pool:
                async with self.db_pool.acquire() as connection:
                    # Query subduction zones with enhanced attributes
                    query = '''
                        SELECT 
                            latitude, longitude, convergence_rate, slab_dip, 
                            subduction_type as type, max_depth_km, seismic_activity,
                            volcanic_arc_distance, back_arc_spreading,
                            ST_Distance_Sphere(ST_Point($2, $1), ST_Point(longitude, latitude)) / 1000.0 as distance_km
                        FROM geological_data.subduction_zones 
                        WHERE ST_DWithin(
                            ST_Point($2, $1)::geography,
                            ST_Point(longitude, latitude)::geography,
                            $3 * 1000
                        )
                        ORDER BY distance_km
                        LIMIT 15
                    '''
                    
                    result = await connection.fetch(query, lat, lon, radius_km)
                    return [dict(row) for row in result] if result else []
            
            return []
            
        except Exception as e:
            self.logger.debug(f"Subduction database query failed: {e}")
            return []

    async def _classify_ridge_type(self, lat: float, lon: float, ridge_data: list) -> dict:
        """ML-based ridge type classification using model_manager"""
        try:
            if self._model_manager:
                # Prepare features for ridge classification
                features = {
                    'latitude': lat,
                    'longitude': lon,
                    'avg_spreading_rate': np.mean([r.get('spreading_rate', 25) for r in ridge_data]),
                    'ridge_count': len(ridge_data),
                    'min_distance': min([r.get('distance_km', 1000) for r in ridge_data]),
                    'max_segment_length': max([r.get('segment_length_km', 100) for r in ridge_data]),
                    'transform_density': sum([1 for r in ridge_data if r.get('transform_offset_km', 0) > 10])
                }
                
                # Use model manager for classification
                model_result = await self._model_manager.predict_async(
                    'ridge_classifier_v2', 
                    features,
                    return_probabilities=True
                )
                
                if model_result and 'prediction' in model_result:
                    return {
                        'dominant_type': model_result['prediction'],
                        'confidence': model_result.get('confidence', 0.8),
                        'probabilities': model_result.get('probabilities', {}),
                        'model_version': model_result.get('model_version', 'unknown')
                    }
            
            # Fallback rule-based classification
            return self._rule_based_ridge_classification(ridge_data)
            
        except Exception as e:
            self.logger.debug(f"ML ridge classification failed: {e}")
            return self._rule_based_ridge_classification(ridge_data)

    async def _classify_subduction_type(self, lat: float, lon: float, subduction_data: list) -> dict:
        """ML-based subduction type classification using model_manager"""
        try:
            if self._model_manager:
                # Prepare features for subduction classification
                features = {
                    'latitude': lat,
                    'longitude': lon,
                    'avg_convergence_rate': np.mean([s.get('convergence_rate', 50) for s in subduction_data]),
                    'avg_slab_dip': np.mean([s.get('slab_dip', 45) for s in subduction_data]),
                    'zone_count': len(subduction_data),
                    'min_distance': min([s.get('distance_km', 1000) for s in subduction_data]),
                    'max_depth': max([s.get('max_depth_km', 600) for s in subduction_data]),
                    'avg_seismic_activity': np.mean([s.get('seismic_activity', 1) for s in subduction_data])
                }
                
                # Use model manager for classification
                model_result = await self._model_manager.predict_async(
                    'subduction_classifier_v2', 
                    features,
                    return_probabilities=True
                )
                
                if model_result and 'prediction' in model_result:
                    return {
                        'dominant_type': model_result['prediction'],
                        'confidence': model_result.get('confidence', 0.8),
                        'probabilities': model_result.get('probabilities', {}),
                        'model_version': model_result.get('model_version', 'unknown')
                    }
            
            # Fallback rule-based classification
            return self._rule_based_subduction_classification(subduction_data)
            
        except Exception as e:
            self.logger.debug(f"ML subduction classification failed: {e}")
            return self._rule_based_subduction_classification(subduction_data)

    def _rule_based_ridge_classification(self, ridge_data: list) -> dict:
        """Rule-based fallback for ridge classification"""
        if not ridge_data:
            return {'dominant_type': 'mid_ocean', 'confidence': 0.3, 'probabilities': {}}
        
        # Analyze spreading rates
        avg_rate = np.mean([r.get('spreading_rate', 25) for r in ridge_data])
        
        if avg_rate > 80:
            ridge_type = 'fast_spreading'
        elif avg_rate > 20:
            ridge_type = 'intermediate_spreading'
        else:
            ridge_type = 'slow_spreading'
        
        return {
            'dominant_type': ridge_type,
            'confidence': 0.6,
            'probabilities': {ridge_type: 0.6, 'other': 0.4}
        }

    def _rule_based_subduction_classification(self, subduction_data: list) -> dict:
        """Rule-based fallback for subduction classification"""
        if not subduction_data:
            return {'dominant_type': 'oceanic', 'confidence': 0.3, 'probabilities': {}}
        
        # Analyze convergence characteristics
        avg_dip = np.mean([s.get('slab_dip', 45) for s in subduction_data])
        avg_rate = np.mean([s.get('convergence_rate', 50) for s in subduction_data])
        
        if avg_dip > 60 and avg_rate > 80:
            subduction_type = 'steep_fast'
        elif avg_dip < 30:
            subduction_type = 'shallow_slow'
        else:
            subduction_type = 'intermediate'
        
        return {
            'dominant_type': subduction_type,
            'confidence': 0.6,
            'probabilities': {subduction_type: 0.6, 'other': 0.4}
        }

    async def _get_comprehensive_hotspot_distance(self, lat: float, lon: float) -> float:
        """Get minimum distance to volcanic hotspots using comprehensive global databases"""
        try:
            min_distance = float('inf')
            
            # Query multiple volcanic databases for comprehensive hotspot coverage
            hotspot_data = await self._query_multiple_volcanic_databases(lat, lon)
            
            # Process database results
            for data_source, volcanic_features in hotspot_data.items():
                for feature in volcanic_features.get('volcanoes', []):
                    if self._is_hotspot_volcano(feature):
                        # Calculate precise distance using haversine formula
                        hotspot_lat = feature.get('latitude', 0.0)
                        hotspot_lon = feature.get('longitude', 0.0)
                        distance_km = self._haversine_distance(lat, lon, hotspot_lat, hotspot_lon)
                        min_distance = min(min_distance, distance_km * 1000.0)  # Convert to meters
            
            # If no database results, use enhanced static analysis with known major hotspots
            if min_distance == float('inf'):
                min_distance = await self._fallback_hotspot_analysis(lat, lon)
                
            return min_distance
            
        except Exception as e:
            self.logger.warning(f"Hotspot distance calculation failed: {e}")
            return await self._fallback_hotspot_analysis(lat, lon)
    
    async def _query_multiple_volcanic_databases(self, lat: float, lon: float) -> dict:
        """Query multiple volcanic databases for comprehensive coverage"""
        results = {}
        
        try:
            # Smithsonian Global Volcanism Program
            gvp_data = await self._query_smithsonian_gvp(lat, lon)
            if gvp_data:
                results['gvp'] = gvp_data
                
            # USGS Volcano Hazards Program
            usgs_data = await self._query_usgs_volcanic_data(lat, lon)
            if usgs_data:
                results['usgs'] = usgs_data
                
            # Regional volcanic observatories
            regional_data = await self._query_regional_volcanic_observatories(lat, lon)
            if regional_data:
                results['regional'] = regional_data
                
            # International volcanic databases
            intl_data = await self._query_international_volcanic_databases(lat, lon)
            if intl_data:
                results['international'] = intl_data
                
        except Exception as e:
            self.logger.debug(f"Database query error: {e}")
            
        return results
    
