    async def _get_alteration_thermal_correction(self, coords: List[float]) -> float:
        """Get hydrothermal alteration thermal property correction"""
        try:
            alteration_data = await self._get_hydrothermal_alteration_thermal_effects(coords)
            return alteration_data.get('thermal_diffusivity_factor', 1.0)
        except Exception:
            return 1.0
    
    async def _calculate_thermal_stress(self, temperature_c: float, thermal_props: dict,
                                       cap_rock_props: CapRockProperties) -> float:
        """Calculate thermal stress from temperature and thermal expansion"""
        try:
            thermal_expansion = thermal_props.get('thermal_expansion', 2e-5)
            elastic_modulus = (cap_rock_props.youngs_modulus_gpa * 1e9) if cap_rock_props.youngs_modulus_gpa else 50e9
            
            # Thermal stress = E * α * ΔT
            thermal_stress = elastic_modulus * thermal_expansion * temperature_c
            return thermal_stress
            
        except Exception:
            return 10e6  # Default 10 MPa
    
    async def _get_regional_thermal_gradient(self, coords: List[float]) -> float:
        """Get regional thermal gradient"""
        try:
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            return volcanic_data.get('thermal_gradient_k_km', 25.0) / 1000.0  # K/m
        except Exception:
            return 0.025  # Default 25 K/km
    
    async def _get_volcanic_gas_thermal_effects(self, coords: List[float], temperature_c: float) -> dict:
        """Get volcanic gas effects on thermal damping"""
        try:
            # Real-time volcanic gas data integration
            from .external_data_connectors import USGSConnector
            from .database_integration import DatabaseManager
            
            damping_amplification = 1.0
            
            # Get volcanic activity data from USGS
            usgs = USGSConnector()
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            
            # Gas composition effects on thermal damping
            gas_co2_ppm = volcanic_data.get('gas_co2_ppm', 400)  # Background CO2
            gas_so2_ppm = volcanic_data.get('gas_so2_ppm', 0)
            gas_h2s_ppm = volcanic_data.get('gas_h2s_ppm', 0)
            
            # Temperature-dependent gas effects
            if temperature_c > 100:  # Above boiling point
                # CO2 effects on thermal damping
                co2_factor = 1.0 + 0.0001 * (gas_co2_ppm - 400)  # Enhanced above background
                
                # SO2 corrosive effects on rock structure
                so2_factor = 1.0 + 0.001 * gas_so2_ppm
                
                # H2S alteration effects
                h2s_factor = 1.0 + 0.0005 * gas_h2s_ppm
                
                damping_amplification = max(1.0, co2_factor * so2_factor * h2s_factor)
                damping_amplification = min(3.0, damping_amplification)  # Cap at 3x
            
            # Database logging for gas effects analysis
            db_manager = getattr(self, 'db_manager', None)
            if db_manager:
                async with db_manager.get_session() as session:
                    await session.execute("""
                        INSERT INTO gas_thermal_effects_log 
                        (coords, temperature_c, co2_ppm, so2_ppm, h2s_ppm, damping_factor, timestamp)
                        VALUES ($1, $2, $3, $4, $5, $6, $7)
                    """, coords, temperature_c, gas_co2_ppm, gas_so2_ppm, 
                         gas_h2s_ppm, damping_amplification, datetime.now())
            
            return {'damping_amplification': damping_amplification}
            
        except Exception as e:
            self.logger.error(f"Gas thermal effects analysis failed: {e}")
            return {'damping_amplification': 1.0}
    
    async def _get_hydrothermal_alteration_thermal_effects(self, coords: List[float]) -> dict:
        """Get hydrothermal alteration effects on thermal properties"""
        try:
            # Real-time hydrothermal alteration data integration
            from .external_data_connectors import USGSConnector, NASAEarthDataConnector
            from .database_integration import DatabaseManager
            
            thermal_damping_factor = 1.0
            thermal_diffusivity_factor = 1.0
            grain_boundary_factor = 1.0
            
            # Get mineral resource and alteration data
            usgs = USGSConnector()
            mineral_data = await self._get_regional_mineral_resources(coords)
            
            # Analyze alteration mineral assemblages
            alteration_minerals = mineral_data.get('alteration_minerals', [])
            
            for mineral in alteration_minerals:
                mineral_name = mineral.get('name', '').lower()
                abundance = mineral.get('abundance_percent', 0)
                
                # Clay mineral effects (smectite, illite, kaolinite)
                if any(clay in mineral_name for clay in ['smectite', 'illite', 'kaolinite', 'montmorillonite']):
                    clay_effect = 1.0 + 0.002 * abundance  # Increases thermal damping
                    thermal_damping_factor = max(thermal_damping_factor, clay_effect)
                    thermal_diffusivity_factor *= (1.0 - 0.001 * abundance)  # Reduces diffusivity
                
                # Zeolite effects
                elif 'zeolite' in mineral_name or 'analcime' in mineral_name:
                    zeolite_effect = 1.0 + 0.001 * abundance
                    thermal_damping_factor = max(thermal_damping_factor, zeolite_effect)
                
                # Sulfide alteration effects
                elif any(sulfide in mineral_name for sulfide in ['pyrite', 'pyrrhotite', 'chalcopyrite']):
                    sulfide_effect = 1.0 + 0.0015 * abundance
                    thermal_damping_factor = max(thermal_damping_factor, sulfide_effect)
                    grain_boundary_factor *= (1.0 + 0.0005 * abundance)
                
                # Carbonate alteration effects
                elif any(carb in mineral_name for carb in ['calcite', 'dolomite', 'aragonite']):
                    carbonate_effect = 1.0 + 0.0008 * abundance
                    thermal_diffusivity_factor = max(thermal_diffusivity_factor, carbonate_effect)
            
            # Get thermal spring data for hydrothermal activity assessment
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            thermal_springs = volcanic_data.get('thermal_springs_count', 0)
            geothermal_gradient = volcanic_data.get('geothermal_gradient_k_km', 25.0)
            
            # Enhanced alteration effects near thermal features
            if thermal_springs > 0 or geothermal_gradient > 30.0:
                hydrothermal_enhancement = 1.0 + 0.1 * min(thermal_springs / 10.0, 1.0)
                thermal_damping_factor *= hydrothermal_enhancement
                thermal_diffusivity_factor *= (2.0 - hydrothermal_enhancement)  # Inverse relationship
            
            # Database integration for alteration tracking
            db_manager = getattr(self, 'db_manager', None)
            if db_manager:
                async with db_manager.get_session() as session:
                    await session.execute("""
                        INSERT INTO hydrothermal_alteration_log 
                        (coords, alteration_minerals, thermal_springs_count, 
                         thermal_damping_factor, thermal_diffusivity_factor, 
                         grain_boundary_factor, timestamp)
                        VALUES ($1, $2, $3, $4, $5, $6, $7)
                    """, coords, json.dumps(alteration_minerals), thermal_springs,
                         thermal_damping_factor, thermal_diffusivity_factor,
                         grain_boundary_factor, datetime.now())
            
            return {
                'thermal_damping_factor': min(5.0, thermal_damping_factor),  # Cap at 5x
                'thermal_diffusivity_factor': max(0.1, thermal_diffusivity_factor),  # Min 0.1x
                'grain_boundary_factor': min(3.0, grain_boundary_factor)  # Cap at 3x
            }
            
        except Exception as e:
            self.logger.error(f"Hydrothermal alteration analysis failed: {e}")
            return {'thermal_damping_factor': 1.0, 'thermal_diffusivity_factor': 1.0, 'grain_boundary_factor': 1.0}
    
    async def _determine_rock_phase(self, cap_rock_props: CapRockProperties) -> str:
        """
        Advanced rock phase determination using comprehensive mineralogical analysis.
        
        Integrates multiple approaches for accurate phase determination:
        1. Petrological database lookup with mineralogical composition
        2. Thermodynamic phase stability modeling
        3. ML-based phase prediction using geochemical signatures
        4. Pressure-temperature phase diagram analysis
        5. Multi-modal ensemble phase classification
        """
        try:
            # Method 1: Comprehensive petrological analysis
            petrological_phase = await self._analyze_petrological_phase_composition(cap_rock_props)
            
            # Method 2: Thermodynamic phase stability analysis
            thermodynamic_phase = await self._model_thermodynamic_phase_stability(cap_rock_props)
            
            # Method 3: ML-based phase prediction
            ml_phase_prediction = await self._predict_rock_phase_ml_ensemble(cap_rock_props)
            
            # Method 4: PT phase diagram analysis
            pt_phase_analysis = await self._analyze_pressure_temperature_phase_diagram(cap_rock_props)
            
            # Method 5: Geochemical signature phase determination
            geochemical_phase = await self._determine_phase_from_geochemistry(cap_rock_props)
            
            # Ensemble phase determination with confidence weighting
            phase_candidates = [
                {'phase': petrological_phase.get('dominant_phase', 'quartz'), 'confidence': petrological_phase.get('confidence', 0.7), 'method': 'petrological'},
                {'phase': thermodynamic_phase.get('stable_phase', 'feldspar'), 'confidence': thermodynamic_phase.get('confidence', 0.8), 'method': 'thermodynamic'},
                {'phase': ml_phase_prediction.get('predicted_phase', 'plagioclase'), 'confidence': ml_phase_prediction.get('confidence', 0.6), 'method': 'ml_ensemble'},
                {'phase': pt_phase_analysis.get('pt_stable_phase', 'quartz'), 'confidence': pt_phase_analysis.get('confidence', 0.7), 'method': 'pt_diagram'},
                {'phase': geochemical_phase.get('geochemical_phase', 'feldspar'), 'confidence': geochemical_phase.get('confidence', 0.5), 'method': 'geochemical'}
            ]
            
            # Weight-based ensemble decision
            phase_scores = {}
            total_weight = 0
            
            for candidate in phase_candidates:
                phase = candidate['phase']
                confidence = candidate['confidence']
                
                if phase not in phase_scores:
                    phase_scores[phase] = 0
                phase_scores[phase] += confidence
                total_weight += confidence
            
            # Select phase with highest weighted score
            if phase_scores and total_weight > 0:
                best_phase = max(phase_scores.items(), key=lambda x: x[1])[0]
                confidence_score = phase_scores[best_phase] / total_weight
                
                self.logger.debug(f"Rock phase determined: {best_phase} (confidence: {confidence_score:.2f})")
                return best_phase
            
            # Advanced fallback with lithology-specific phase mapping
            return await self._advanced_lithology_phase_mapping(cap_rock_props)
            
        except Exception as e:
            self.logger.warning(f"Advanced rock phase determination failed: {e}")
            # Conservative fallback
            return self._conservative_rock_phase_fallback(cap_rock_props)
    
    async def _analyze_petrological_phase_composition(self, cap_rock_props: CapRockProperties) -> Dict[str, Any]:
        """Analyze mineralogical composition for dominant phase determination"""
        try:
            alteration_minerals = cap_rock_props.alteration_minerals if hasattr(cap_rock_props, 'alteration_minerals') else {}
            lithology = cap_rock_props.lithology.lower() if cap_rock_props.lithology else 'unknown'
            
            # Query comprehensive petrological database
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                petro_query = await self._query_integrated_geological_data(
                    'geological',
                    {
                        'lithology': lithology,
                        'query_type': 'mineralogical_composition',
                        'alteration_minerals': alteration_minerals
                    }
                )
                
                if petro_query and 'mineralogy' in petro_query:
                    mineral_composition = petro_query['mineralogy']
                    
                    # Determine dominant mineral phase
                    phase_abundance = {}
                    for mineral, abundance in mineral_composition.items():
                        primary_phase = self._mineral_to_primary_phase(mineral)
                        if primary_phase not in phase_abundance:
                            phase_abundance[primary_phase] = 0
                        phase_abundance[primary_phase] += abundance
                    
                    if phase_abundance:
                        dominant_phase = max(phase_abundance.items(), key=lambda x: x[1])[0]
                        confidence = phase_abundance[dominant_phase] / sum(phase_abundance.values())
                        
                        return {
                            'dominant_phase': dominant_phase,
                            'confidence': min(confidence, 0.9),
                            'phase_distribution': phase_abundance,
                            'method': 'petrological_database'
                        }
            
            # Fallback to lithology-based analysis
            return await self._lithology_based_phase_analysis(lithology)
            
        except Exception as e:
            self.logger.debug(f"Petrological phase analysis failed: {e}")
            return {'dominant_phase': 'quartz', 'confidence': 0.4, 'method': 'petrological_fallback'}
    
    def _mineral_to_primary_phase(self, mineral: str) -> str:
        """Map mineral names to primary thermodynamic phases"""
        mineral = mineral.lower()
        
        phase_mapping = {
            # Feldspar group
            'orthoclase': 'feldspar', 'microcline': 'feldspar', 'sanidine': 'feldspar',
            'albite': 'feldspar', 'anorthite': 'feldspar', 'plagioclase': 'plagioclase',
            'oligoclase': 'plagioclase', 'labradorite': 'plagioclase',
            
            # Quartz group
            'quartz': 'quartz', 'cristobalite': 'quartz', 'tridymite': 'quartz',
            
            # Pyroxene group
            'augite': 'pyroxene', 'diopside': 'pyroxene', 'enstatite': 'pyroxene',
            'hypersthene': 'pyroxene', 'pigeonite': 'pyroxene',
            
            # Amphibole group
            'hornblende': 'amphibole', 'actinolite': 'amphibole', 'tremolite': 'amphibole',
            
            # Mica group
            'biotite': 'mica', 'muscovite': 'mica', 'phlogopite': 'mica',
            
            # Clay minerals
            'kaolinite': 'clay', 'smectite': 'clay', 'illite': 'clay', 'chlorite': 'chlorite',
            
            # Carbonate group
            'calcite': 'calcite', 'dolomite': 'dolomite', 'aragonite': 'calcite',
            
            # Olivine group
            'olivine': 'olivine', 'forsterite': 'olivine', 'fayalite': 'olivine',
            
            # Other important phases
            'garnet': 'garnet', 'epidote': 'epidote', 'tourmaline': 'tourmaline',
            'zircon': 'zircon', 'apatite': 'apatite'
        }
        
        return phase_mapping.get(mineral, 'quartz')  # Default to quartz
    
