    async def _model_thermodynamic_phase_stability(self, cap_rock_props: CapRockProperties) -> Dict[str, Any]:
        """Model thermodynamic phase stability using PT conditions"""
        try:
            # Get pressure and temperature estimates
            pressure_pa = getattr(cap_rock_props, 'pressure_mpa', 100.0) * 1e6  # Convert to Pa
            temperature_k = getattr(cap_rock_props, 'temperature_c', 25.0) + 273.15  # Convert to K
            
            # Phase stability analysis based on PT conditions
            if temperature_k > 1000:  # High temperature
                if pressure_pa > 500e6:  # High pressure
                    stable_phase = 'garnet'  # High P-T metamorphic
                    confidence = 0.85
                else:
                    stable_phase = 'pyroxene'  # High T, moderate P
                    confidence = 0.80
            elif temperature_k > 700:  # Moderate temperature
                if pressure_pa > 300e6:
                    stable_phase = 'amphibole'  # Moderate P-T
                    confidence = 0.82
                else:
                    stable_phase = 'feldspar'  # Moderate T, low P
                    confidence = 0.75
            else:  # Low temperature
                if pressure_pa > 200e6:
                    stable_phase = 'mica'  # Low T, moderate P
                    confidence = 0.70
                else:
                    stable_phase = 'quartz'  # Low P-T conditions
                    confidence = 0.85
            
            return {
                'stable_phase': stable_phase,
                'confidence': confidence,
                'pt_conditions': {'pressure_pa': pressure_pa, 'temperature_k': temperature_k},
                'method': 'thermodynamic_stability'
            }
            
        except Exception as e:
            self.logger.debug(f"Thermodynamic phase modeling failed: {e}")
            return {'stable_phase': 'feldspar', 'confidence': 0.5, 'method': 'thermodynamic_fallback'}
    
    async def _predict_rock_phase_ml_ensemble(self, cap_rock_props: CapRockProperties) -> Dict[str, Any]:
        """ML-based rock phase prediction using ensemble models"""
        try:
            model_manager = await self._get_model_manager()
            if not model_manager:
                return {'predicted_phase': 'plagioclase', 'confidence': 0.4, 'method': 'ml_unavailable'}
            
            # Prepare features for ML phase prediction
            ml_features = {
                'lithology_encoded': self._encode_lithology(cap_rock_props.lithology),
                'ucs_mpa': cap_rock_props.unconfined_compressive_strength_mpa,
                'elastic_modulus_gpa': cap_rock_props.elastic_modulus_gpa,
                'poisson_ratio': cap_rock_props.poisson_ratio,
                'thermal_conductivity': cap_rock_props.thermal_conductivity_w_m_k,
                'porosity': cap_rock_props.porosity,
                'alteration_score': self._calculate_alteration_score(cap_rock_props.alteration_minerals),
                'fracture_density': cap_rock_props.fracture_density_per_m3
            }
            
            # Use ensemble of phase prediction models
            phase_prediction = await self._get_versioned_model_prediction(
                'rock_phase_classifier_ensemble',
                ml_features,
                version='latest'
            )
            
            if phase_prediction and 'predicted_phase' in phase_prediction:
                return {
                    'predicted_phase': phase_prediction['predicted_phase'],
                    'confidence': phase_prediction.get('confidence', 0.6),
                    'phase_probabilities': phase_prediction.get('class_probabilities', {}),
                    'method': 'ml_ensemble_prediction'
                }
            
            # Fallback ML prediction
            return await self._simple_ml_phase_prediction(ml_features)
            
        except Exception as e:
            self.logger.debug(f"ML phase prediction failed: {e}")
            return {'predicted_phase': 'plagioclase', 'confidence': 0.3, 'method': 'ml_prediction_failed'}
    
    def _encode_lithology(self, lithology: str) -> float:
        """Encode lithology for ML features"""
        if not lithology:
            return 0.0
        
        lithology_encoding = {
            'granite': 0.1, 'granodiorite': 0.2, 'diorite': 0.3, 'gabbro': 0.4,
            'basalt': 0.5, 'andesite': 0.6, 'rhyolite': 0.7, 'dacite': 0.8,
            'gneiss': 1.1, 'schist': 1.2, 'slate': 1.3, 'phyllite': 1.4,
            'amphibolite': 1.5, 'quartzite': 1.6, 'marble': 1.7,
            'sandstone': 2.1, 'limestone': 2.2, 'shale': 2.3, 'mudstone': 2.4
        }
        
        return lithology_encoding.get(lithology.lower(), 0.0)
    
    def _calculate_alteration_score(self, alteration_minerals: Dict[str, float]) -> float:
        """Calculate alteration intensity score"""
        if not alteration_minerals:
            return 0.0
        
        alteration_weights = {
            'clay': 1.0, 'smectite': 0.9, 'kaolinite': 0.8,
            'chlorite': 0.7, 'sericite': 0.6, 'epidote': 0.5,
            'calcite': 0.4, 'pyrite': 0.3
        }
        
        total_score = 0.0
        for mineral, fraction in alteration_minerals.items():
            weight = alteration_weights.get(mineral.lower(), 0.5)
            total_score += fraction * weight
        
        return min(total_score, 1.0)
    
    async def _simple_ml_phase_prediction(self, features: Dict[str, float]) -> Dict[str, Any]:
        """Simple ML-based phase prediction fallback"""
        # Simple decision tree-like logic for phase prediction
        ucs = features.get('ucs_mpa', 50)
        porosity = features.get('porosity', 0.1)
        alteration = features.get('alteration_score', 0.0)
        
        if alteration > 0.5:
            phase = 'clay'
            confidence = 0.7
        elif ucs > 150 and porosity < 0.05:
            phase = 'quartz'
            confidence = 0.8
        elif ucs > 100:
            phase = 'feldspar'
            confidence = 0.75
        else:
            phase = 'plagioclase'
            confidence = 0.6
        
        return {
            'predicted_phase': phase,
            'confidence': confidence,
            'method': 'simple_ml_fallback'
        }
    
    async def _analyze_pressure_temperature_phase_diagram(self, cap_rock_props: CapRockProperties) -> Dict[str, Any]:
        """Analyze phase stability using PT phase diagrams"""
        try:
            # Estimate PT conditions
            pressure_mpa = getattr(cap_rock_props, 'pressure_mpa', 100.0)
            temperature_c = getattr(cap_rock_props, 'temperature_c', 25.0)
            
            # PT phase diagram analysis for common mineral systems
            if temperature_c > 600:  # High temperature metamorphic conditions
                if pressure_mpa > 500:
                    phase = 'garnet'  # High P-T
                    confidence = 0.88
                elif pressure_mpa > 200:
                    phase = 'amphibole'  # Moderate P, high T
                    confidence = 0.82
                else:
                    phase = 'pyroxene'  # Low P, high T
                    confidence = 0.85
            elif temperature_c > 300:  # Moderate metamorphic conditions
                if pressure_mpa > 300:
                    phase = 'mica'  # Moderate P-T
                    confidence = 0.80
                else:
                    phase = 'feldspar'  # Low P, moderate T
                    confidence = 0.78
            else:  # Low grade or surface conditions
                if pressure_mpa > 100:
                    phase = 'clay'  # Diagenetic conditions
                    confidence = 0.75
                else:
                    phase = 'quartz'  # Surface conditions
                    confidence = 0.90
            
            return {
                'pt_stable_phase': phase,
                'confidence': confidence,
                'pt_regime': self._classify_pt_regime(pressure_mpa, temperature_c),
                'method': 'pt_phase_diagram'
            }
            
        except Exception as e:
            self.logger.debug(f"PT phase diagram analysis failed: {e}")
            return {'pt_stable_phase': 'quartz', 'confidence': 0.5, 'method': 'pt_analysis_failed'}
    
    def _classify_pt_regime(self, pressure_mpa: float, temperature_c: float) -> str:
        """Classify pressure-temperature regime"""
        if temperature_c > 700:
            return 'high_grade_metamorphic'
        elif temperature_c > 400:
            return 'medium_grade_metamorphic'
        elif temperature_c > 150:
            return 'low_grade_metamorphic'
        else:
            return 'diagenetic'
    
    async def _determine_phase_from_geochemistry(self, cap_rock_props: CapRockProperties) -> Dict[str, Any]:
        """Determine phase from geochemical signature"""
        try:
            # Use thermal conductivity and elastic properties as geochemical proxies
            thermal_cond = cap_rock_props.thermal_conductivity_w_m_k
            elastic_mod = cap_rock_props.elastic_modulus_gpa
            poisson = cap_rock_props.poisson_ratio
            
            # Geochemical signature analysis
            if thermal_cond > 3.0 and elastic_mod > 60:
                phase = 'quartz'  # High thermal conductivity, high stiffness
                confidence = 0.85
            elif thermal_cond > 2.5 and elastic_mod > 40:
                phase = 'feldspar'  # Moderate properties
                confidence = 0.80
            elif poisson > 0.3:
                phase = 'clay'  # High Poisson's ratio indicates clay
                confidence = 0.75
            elif elastic_mod < 30:
                phase = 'clay'  # Low stiffness
                confidence = 0.70
            else:
                phase = 'plagioclase'  # Intermediate properties
                confidence = 0.65
            
            return {
                'geochemical_phase': phase,
                'confidence': confidence,
                'geochemical_indicators': {
                    'thermal_conductivity': thermal_cond,
                    'elastic_modulus': elastic_mod,
                    'poisson_ratio': poisson
                },
                'method': 'geochemical_signature'
            }
            
        except Exception as e:
            self.logger.debug(f"Geochemical phase determination failed: {e}")
            return {'geochemical_phase': 'feldspar', 'confidence': 0.4, 'method': 'geochemical_failed'}
    
    async def _advanced_lithology_phase_mapping(self, cap_rock_props: CapRockProperties) -> str:
        """Advanced fallback with comprehensive lithology mapping"""
        lithology = cap_rock_props.lithology.lower() if cap_rock_props.lithology else 'unknown'
        
        # Comprehensive phase mapping with alteration considerations
        alteration_minerals = getattr(cap_rock_props, 'alteration_minerals', {})
        
        if alteration_minerals:
            # Check for dominant alteration minerals
            dominant_alteration = max(alteration_minerals.items(), key=lambda x: x[1])[0]
            if dominant_alteration in ['clay', 'smectite', 'kaolinite']:
                return 'clay'
            elif dominant_alteration in ['chlorite', 'sericite']:
                return 'mica'
            elif dominant_alteration in ['epidote', 'calcite']:
                return 'epidote'
        
        # Standard lithology mapping
        advanced_mapping = {
            'granite': 'feldspar', 'granodiorite': 'plagioclase', 'diorite': 'plagioclase',
            'gabbro': 'pyroxene', 'basalt': 'pyroxene', 'andesite': 'plagioclase',
            'rhyolite': 'feldspar', 'dacite': 'plagioclase', 'peridotite': 'olivine',
            'gneiss': 'feldspar', 'schist': 'mica', 'slate': 'clay',
            'amphibolite': 'amphibole', 'quartzite': 'quartz', 'marble': 'calcite',
            'sandstone': 'quartz', 'limestone': 'calcite', 'shale': 'clay'
        }
        
        return advanced_mapping.get(lithology, 'quartz')
    
    def _conservative_rock_phase_fallback(self, cap_rock_props: CapRockProperties) -> str:
        """Conservative fallback when all methods fail"""
        # Use most common/stable phases based on basic properties
        if hasattr(cap_rock_props, 'lithology') and cap_rock_props.lithology:
            lithology = cap_rock_props.lithology.lower()
            if 'granite' in lithology or 'gneiss' in lithology:
                return 'feldspar'
            elif 'basalt' in lithology or 'gabbro' in lithology:
                return 'pyroxene'
            elif 'limestone' in lithology or 'marble' in lithology:
                return 'calcite'
            elif 'shale' in lithology or 'clay' in lithology:
                return 'clay'
        
        # Ultimate fallback - quartz is most stable at surface conditions
        return 'quartz'
    
    async def _estimate_lithostatic_pressure(self, coords: List[float]) -> float:
        """
        Advanced lithostatic pressure estimation using comprehensive geophysical data integration.
        
        Integrates multiple data sources and methods:
        1. High-resolution DEM analysis with topographic correction
        2. Crustal density modeling using gravity data
        3. Seismic velocity-density correlation from regional models
        4. Geological structure and layering analysis
        5. ML-based pressure prediction with uncertainty quantification
        """
        try:
            lat, lon, depth_km = coords[0], coords[1], abs(coords[2]) if len(coords) > 2 else 1.0
            
            # Method 1: Comprehensive elevation and depth analysis
            elevation_analysis = await self._analyze_comprehensive_elevation_depth(lat, lon, depth_km)
            
            # Method 2: Integrated crustal density modeling
            density_analysis = await self._model_integrated_crustal_density(lat, lon, depth_km)
            
            # Method 3: Seismic velocity-density correlation
            seismic_density_analysis = await self._correlate_seismic_velocity_to_density(lat, lon, depth_km)
            
            # Method 4: Geological structure-based pressure modeling
            structural_analysis = await self._model_structural_pressure_effects(lat, lon, depth_km)
            
            # Method 5: ML-enhanced pressure prediction
            ml_pressure_prediction = await self._predict_lithostatic_pressure_ml(lat, lon, depth_km, elevation_analysis, density_analysis)
            
            # Ensemble pressure calculation with uncertainty quantification
            pressure_estimates = [
                {'pressure_pa': elevation_analysis.get('pressure_pa', 100e6), 'confidence': elevation_analysis.get('confidence', 0.7), 'method': 'elevation'},
                {'pressure_pa': density_analysis.get('pressure_pa', 100e6), 'confidence': density_analysis.get('confidence', 0.8), 'method': 'density'},
                {'pressure_pa': seismic_density_analysis.get('pressure_pa', 100e6), 'confidence': seismic_density_analysis.get('confidence', 0.75), 'method': 'seismic'},
                {'pressure_pa': structural_analysis.get('pressure_pa', 100e6), 'confidence': structural_analysis.get('confidence', 0.6), 'method': 'structural'},
                {'pressure_pa': ml_pressure_prediction.get('pressure_pa', 100e6), 'confidence': ml_pressure_prediction.get('confidence', 0.65), 'method': 'ml_prediction'}
            ]
            
            # Confidence-weighted ensemble calculation
            total_weight = sum(est['confidence'] for est in pressure_estimates)
            if total_weight > 0:
                weighted_pressure = sum(
                    est['pressure_pa'] * est['confidence'] 
                    for est in pressure_estimates
                ) / total_weight
                
                # Calculate ensemble confidence
                pressure_values = [est['pressure_pa'] for est in pressure_estimates if est['confidence'] > 0.5]
                if pressure_values:
                    pressure_std = np.std(pressure_values)
                    mean_pressure = np.mean(pressure_values)
                    ensemble_confidence = max(0.1, 0.95 - (pressure_std / mean_pressure))
                    
                    self.logger.debug(f"Lithostatic pressure estimated: {weighted_pressure/1e6:.1f} MPa "
                                    f"(confidence: {ensemble_confidence:.2f})")
                    
                    return weighted_pressure
            
            # Advanced fallback with regional corrections
            return await self._advanced_pressure_fallback(lat, lon, depth_km)
            
        except Exception as e:
            self.logger.warning(f"Advanced lithostatic pressure estimation failed: {e}")
            return await self._conservative_pressure_fallback(depth_km if len(coords) > 2 else 1.0)
    
    async def _analyze_comprehensive_elevation_depth(self, lat: float, lon: float, depth_km: float) -> Dict[str, Any]:
        """Comprehensive elevation and depth analysis using DEM data"""
        try:
            # Query integrated geological data for elevation and topographic information
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                elevation_query = await self._query_integrated_geological_data(
                    'geophysical',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'query_type': 'elevation_topography',
                        'include_bathymetry': True,
                        'spatial_resolution': 'high'
                    }
                )
                
                if elevation_query and 'elevation_data' in elevation_query:
                    elevation_data = elevation_query['elevation_data']
                    surface_elevation_m = elevation_data.get('surface_elevation_m', 0.0)
                    water_depth_m = elevation_data.get('water_depth_m', 0.0)
                    
                    # Calculate total depth below reference level
                    total_depth_m = max(depth_km * 1000, 100)  # Minimum 100m depth
                    
                    # Account for water column if present
                    if water_depth_m > 0:
                        water_pressure_pa = 1025.0 * 9.81 * water_depth_m  # Seawater density
                        rock_depth_m = total_depth_m
                    else:
                        water_pressure_pa = 0.0
                        rock_depth_m = total_depth_m + max(0, -surface_elevation_m)  # Add below sea level correction
                    
                    # Regional rock density estimation
                    rock_density = await self._estimate_regional_rock_density(lat, lon, rock_depth_m)
                    
                    # Calculate lithostatic pressure
                    rock_pressure_pa = rock_density * 9.81 * rock_depth_m
                    total_pressure_pa = water_pressure_pa + rock_pressure_pa
                    
                    # Confidence based on data quality and depth certainty
                    elevation_confidence = elevation_data.get('data_quality', 0.8)
                    depth_confidence = min(0.9, 0.5 + 0.4 * np.exp(-depth_km / 5.0))  # Higher confidence at shallow depths
                    combined_confidence = (elevation_confidence + depth_confidence) / 2.0
                    
                    return {
                        'pressure_pa': total_pressure_pa,
                        'confidence': combined_confidence,
                        'surface_elevation_m': surface_elevation_m,
                        'water_depth_m': water_depth_m,
                        'rock_depth_m': rock_depth_m,
                        'rock_density_kg_m3': rock_density,
                        'method': 'comprehensive_elevation_analysis'
                    }
            
            # Fallback to basic calculation
            return await self._basic_elevation_pressure_calculation(depth_km)
            
        except Exception as e:
            self.logger.debug(f"Comprehensive elevation analysis failed: {e}")
            return {'pressure_pa': depth_km * 1000 * 2700 * 9.81, 'confidence': 0.4, 'method': 'elevation_fallback'}
    
    async def _estimate_regional_rock_density(self, lat: float, lon: float, depth_m: float) -> float:
        """Estimate regional rock density using geological and geophysical data"""
        try:
            # Query geological data for regional lithology
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                geology_query = await self._query_integrated_geological_data(
                    'geological',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'depth_range': [0, depth_m],
                        'query_type': 'regional_lithology'
                    }
                )
                
                if geology_query and 'lithology_distribution' in geology_query:
                    lithology_dist = geology_query['lithology_distribution']
                    
                    # Calculate weighted average density
                    total_density = 0.0
                    total_fraction = 0.0
                    
                    lithology_densities = {
                        'granite': 2650, 'granodiorite': 2700, 'diorite': 2800, 'gabbro': 2950,
                        'basalt': 2900, 'andesite': 2600, 'rhyolite': 2400, 'dacite': 2500,
                        'gneiss': 2700, 'schist': 2750, 'slate': 2700, 'amphibolite': 3000,
                        'quartzite': 2650, 'marble': 2700, 'limestone': 2700, 'dolomite': 2850,
                        'sandstone': 2200, 'shale': 2400, 'mudstone': 2300, 'conglomerate': 2500,
                        'peridotite': 3300, 'dunite': 3250, 'serpentine': 2600
                    }
                    
                    for lithology, fraction in lithology_dist.items():
                        density = lithology_densities.get(lithology.lower(), 2700)
                        total_density += density * fraction
                        total_fraction += fraction
                    
                    if total_fraction > 0:
                        weighted_density = total_density / total_fraction
                        
                        # Apply depth-dependent compaction correction
                        compaction_factor = 1.0 + (depth_m / 10000) * 0.1  # 10% increase per 10km
                        return min(weighted_density * compaction_factor, 3500)  # Cap at 3500 kg/m³
            
            # Depth-dependent fallback density
            if depth_m < 1000:
                return 2400  # Shallow sediments/weathered rock
            elif depth_m < 5000:
                return 2700  # Average crustal density
            elif depth_m < 15000:
                return 2800  # Lower crust
            else:
                return 3200  # Upper mantle approach
                
        except Exception as e:
            self.logger.debug(f"Regional rock density estimation failed: {e}")
            return 2700  # Standard crustal density
    
    async def _basic_elevation_pressure_calculation(self, depth_km: float) -> Dict[str, Any]:
        """Basic elevation-based pressure calculation fallback"""
        depth_m = depth_km * 1000
        rock_density = 2700  # Standard crustal density
        pressure_pa = rock_density * 9.81 * depth_m
        
        return {
            'pressure_pa': pressure_pa,
            'confidence': 0.6,
            'rock_density_kg_m3': rock_density,
            'method': 'basic_elevation_calculation'
        }
    
    async def _model_integrated_crustal_density(self, lat: float, lon: float, depth_km: float) -> Dict[str, Any]:
        """Model crustal density using integrated geophysical data"""
        try:
            # Query gravity and magnetic data for density modeling
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                geophysical_query = await self._query_integrated_geological_data(
                    'geophysical',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'depth_km': depth_km,
                        'query_type': 'density_modeling',
                        'include_gravity': True,
                        'include_magnetic': True
                    }
                )
                
                if geophysical_query and 'density_model' in geophysical_query:
                    density_model = geophysical_query['density_model']
                    
                    # Extract density profile
                    density_profile = density_model.get('density_profile', [])
                    if density_profile:
                        # Calculate integrated pressure using variable density
                        total_pressure = 0.0
                        for i, layer in enumerate(density_profile):
                            layer_density = layer.get('density_kg_m3', 2700)
                            layer_thickness_m = layer.get('thickness_m', 500)
                            
                            # Stop at target depth
                            if total_pressure / (layer_density * 9.81) >= depth_km * 1000:
                                remaining_depth = depth_km * 1000 - (total_pressure / (layer_density * 9.81))
                                total_pressure += layer_density * 9.81 * remaining_depth
                                break
                            else:
                                total_pressure += layer_density * 9.81 * layer_thickness_m
                        
                        confidence = density_model.get('model_confidence', 0.7)
                        
                        return {
                            'pressure_pa': total_pressure,
                            'confidence': confidence,
                            'density_profile': density_profile,
                            'method': 'integrated_density_modeling'
                        }
            
            # Fallback to gravity-based density estimation
            return await self._gravity_based_density_estimation(lat, lon, depth_km)
            
        except Exception as e:
            self.logger.debug(f"Integrated crustal density modeling failed: {e}")
            return {'pressure_pa': depth_km * 1000 * 2800 * 9.81, 'confidence': 0.5, 'method': 'density_modeling_failed'}
    
    async def _gravity_based_density_estimation(self, lat: float, lon: float, depth_km: float) -> Dict[str, Any]:
        """Estimate density using gravity anomaly data"""
        try:
            # Use gravity data to estimate crustal density variations
            # This is a simplified approach - would normally use full gravity inversion
            
            # Query for regional gravity data
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                gravity_query = await self._query_integrated_geological_data(
                    'geophysical',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'query_type': 'gravity_field',
                        'spatial_radius_km': 50  # 50km radius for regional context
                    }
                )
                
                if gravity_query and 'gravity_data' in gravity_query:
                    gravity_anomaly_mgal = gravity_query['gravity_data'].get('bouguer_anomaly_mgal', 0.0)
                    
                    # Convert gravity anomaly to density estimate
                    # Rough approximation: 1 mGal ≈ 23 kg/m³ density contrast per km thickness
                    density_contrast = gravity_anomaly_mgal / 23.0 * (depth_km / 1.0)
                    base_density = 2670  # Standard continental crust
                    estimated_density = max(2200, min(3200, base_density + density_contrast))
                    
                    pressure_pa = estimated_density * 9.81 * depth_km * 1000
                    confidence = 0.7 if abs(gravity_anomaly_mgal) < 50 else 0.8  # Higher confidence for strong anomalies
                    
                    return {
                        'pressure_pa': pressure_pa,
                        'confidence': confidence,
                        'estimated_density_kg_m3': estimated_density,
                        'gravity_anomaly_mgal': gravity_anomaly_mgal,
                        'method': 'gravity_based_estimation'
                    }
            
            # No gravity data available
            return {'pressure_pa': depth_km * 1000 * 2700 * 9.81, 'confidence': 0.4, 'method': 'no_gravity_data'}
            
        except Exception as e:
            self.logger.debug(f"Gravity-based density estimation failed: {e}")
            return {'pressure_pa': depth_km * 1000 * 2700 * 9.81, 'confidence': 0.3, 'method': 'gravity_estimation_failed'}
    
    async def _correlate_seismic_velocity_to_density(self, lat: float, lon: float, depth_km: float) -> Dict[str, Any]:
        """Correlate seismic velocity to density for pressure estimation"""
        try:
            # Query seismic velocity data
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                seismic_query = await self._query_integrated_geological_data(
                    'seismic',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'depth_km': depth_km,
                        'query_type': 'velocity_structure',
                        'include_p_wave': True,
                        'include_s_wave': True
                    }
                )
                
                if seismic_query and 'velocity_structure' in seismic_query:
                    velocity_data = seismic_query['velocity_structure']
                    
                    # Use P-wave velocity for density estimation
                    vp_km_s = velocity_data.get('vp_km_s', 6.0)
                    vs_km_s = velocity_data.get('vs_km_s', 3.5)
                    
                    # Empirical velocity-density relationships
                    # Nafe-Drake relationship: ρ = 1.6612*Vp - 0.4721*Vp² + 0.0671*Vp³ - 0.0043*Vp⁴ + 0.000106*Vp⁵
                    # Simplified Brocher (2005) relationship
                    if vp_km_s > 0:
                        if vp_km_s < 2.0:
                            # Sedimentary rocks
                            density_kg_m3 = 1740 + 310 * vp_km_s
                        elif vp_km_s < 6.5:
                            # Crustal rocks
                            density_kg_m3 = 1740 + 310 * vp_km_s
                        else:
                            # Mantle rocks
                            density_kg_m3 = 1740 + 310 * vp_km_s
                        
                        # Refine using Vp/Vs ratio if available
                        if vs_km_s > 0:
                            vp_vs_ratio = vp_km_s / vs_km_s
                            if vp_vs_ratio > 1.85:  # High Vp/Vs indicates mafic composition
                                density_kg_m3 += 100
                            elif vp_vs_ratio < 1.70:  # Low Vp/Vs indicates felsic composition
                                density_kg_m3 -= 100
                        
                        density_kg_m3 = max(2000, min(3500, density_kg_m3))  # Reasonable bounds
                        pressure_pa = density_kg_m3 * 9.81 * depth_km * 1000
                        
                        confidence = velocity_data.get('velocity_uncertainty', 0.1)
                        confidence = max(0.5, 0.9 - confidence)  # Convert uncertainty to confidence
                        
                        return {
                            'pressure_pa': pressure_pa,
                            'confidence': confidence,
                            'seismic_density_kg_m3': density_kg_m3,
                            'vp_km_s': vp_km_s,
                            'vs_km_s': vs_km_s,
                            'vp_vs_ratio': vp_km_s / vs_km_s if vs_km_s > 0 else None,
                            'method': 'seismic_velocity_density_correlation'
                        }
            
            # Fallback using typical crustal velocities
            return await self._typical_velocity_density_fallback(depth_km)
            
        except Exception as e:
            self.logger.debug(f"Seismic velocity-density correlation failed: {e}")
            return {'pressure_pa': depth_km * 1000 * 2750 * 9.81, 'confidence': 0.4, 'method': 'seismic_correlation_failed'}
    
    async def _typical_velocity_density_fallback(self, depth_km: float) -> Dict[str, Any]:
        """Fallback using typical velocity-depth relationships"""
        # Typical crustal velocity-depth profile
        if depth_km < 1:
            vp_km_s = 2.5  # Sediments/weathered rock
            density = 2200
        elif depth_km < 5:
            vp_km_s = 5.5  # Upper crust
            density = 2650
        elif depth_km < 15:
            vp_km_s = 6.2  # Middle crust
            density = 2750
        elif depth_km < 35:
            vp_km_s = 6.8  # Lower crust
            density = 2900
        else:
            vp_km_s = 8.0  # Upper mantle
            density = 3200
        
        pressure_pa = density * 9.81 * depth_km * 1000
        
        return {
            'pressure_pa': pressure_pa,
            'confidence': 0.6,
            'seismic_density_kg_m3': density,
            'typical_vp_km_s': vp_km_s,
            'method': 'typical_velocity_density'
        }
    
    async def _model_structural_pressure_effects(self, lat: float, lon: float, depth_km: float) -> Dict[str, Any]:
        """Model pressure effects from geological structures"""
        try:
            # Query structural geological data
            pipeline = await self._get_data_integration_pipeline()
            if pipeline:
                structure_query = await self._query_integrated_geological_data(
                    'geological',
                    {
                        'latitude': lat,
                        'longitude': lon,
                        'query_type': 'structural_geology',
                        'include_faults': True,
                        'include_folds': True,
                        'spatial_radius_km': 20
                    }
                )
                
                if structure_query and 'structural_features' in structure_query:
                    structures = structure_query['structural_features']
                    
                    # Base pressure calculation
                    base_pressure = 2700 * 9.81 * depth_km * 1000
                    pressure_modifier = 1.0
                    
                    # Analyze structural effects
                    for structure in structures:
                        structure_type = structure.get('type', '')
                        distance_km = structure.get('distance_km', 50)
                        
                        if distance_km < 10:  # Nearby structures have more effect
                            if structure_type in ['thrust_fault', 'reverse_fault']:
                                # Compressive structures increase effective pressure
                                pressure_modifier += 0.05
                            elif structure_type in ['normal_fault', 'extensional_fault']:
                                # Extensional structures reduce effective pressure
                                pressure_modifier -= 0.03
                            elif structure_type in ['anticline']:
                                # Uplifted areas may have reduced pressure
                                pressure_modifier -= 0.02
                            elif structure_type in ['syncline']:
                                # Downwarped areas may have increased pressure
                                pressure_modifier += 0.02
                    
                    # Apply structural corrections
                    pressure_modifier = max(0.8, min(1.3, pressure_modifier))  # Reasonable bounds
                    structural_pressure = base_pressure * pressure_modifier
                    
                    # Confidence based on structural complexity
                    structure_count = len([s for s in structures if s.get('distance_km', 50) < 20])
                    confidence = max(0.5, 0.8 - structure_count * 0.05)  # Lower confidence with more complexity
                    
                    return {
                        'pressure_pa': structural_pressure,
                        'confidence': confidence,
                        'pressure_modifier': pressure_modifier,
                        'nearby_structures': structure_count,
                        'method': 'structural_pressure_modeling'
                    }
            
            # No structural data - use standard pressure
            return {'pressure_pa': 2700 * 9.81 * depth_km * 1000, 'confidence': 0.5, 'method': 'no_structural_data'}
            
        except Exception as e:
            self.logger.debug(f"Structural pressure modeling failed: {e}")
            return {'pressure_pa': 2700 * 9.81 * depth_km * 1000, 'confidence': 0.4, 'method': 'structural_modeling_failed'}
    
    async def _predict_lithostatic_pressure_ml(self, lat: float, lon: float, depth_km: float,
                                             elevation_analysis: Dict, density_analysis: Dict) -> Dict[str, Any]:
        """ML-based lithostatic pressure prediction"""
        try:
            model_manager = await self._get_model_manager()
            if not model_manager:
                return {'pressure_pa': depth_km * 1000 * 2700 * 9.81, 'confidence': 0.3, 'method': 'ml_unavailable'}
            
            # Prepare features for ML pressure prediction
            ml_features = {
                'latitude': lat,
                'longitude': lon,
                'depth_km': depth_km,
                'surface_elevation_m': elevation_analysis.get('surface_elevation_m', 0.0),
                'water_depth_m': elevation_analysis.get('water_depth_m', 0.0),
                'regional_density': density_analysis.get('estimated_density_kg_m3', 2700),
                'tectonic_setting': self._encode_tectonic_setting(lat, lon),
                'crustal_age': self._estimate_crustal_age(lat, lon),
                'distance_to_plate_boundary': self._calculate_plate_boundary_distance(lat, lon)
            }
            
            # Use pressure prediction model
            pressure_prediction = await self._get_versioned_model_prediction(
                'lithostatic_pressure_predictor',
                ml_features,
                version='latest'
            )
            
            if pressure_prediction and 'predicted_pressure_pa' in pressure_prediction:
                return {
                    'pressure_pa': pressure_prediction['predicted_pressure_pa'],
                    'confidence': pressure_prediction.get('confidence', 0.6),
                    'pressure_uncertainty_pa': pressure_prediction.get('uncertainty_pa', 0),
                    'method': 'ml_pressure_prediction'
                }
            
            # Simple ML fallback
            return await self._simple_ml_pressure_fallback(ml_features)
            
        except Exception as e:
            self.logger.debug(f"ML pressure prediction failed: {e}")
            return {'pressure_pa': depth_km * 1000 * 2750 * 9.81, 'confidence': 0.3, 'method': 'ml_prediction_failed'}
    
    def _encode_tectonic_setting(self, lat: float, lon: float) -> float:
        """Encode tectonic setting for ML features"""
        # Simplified global tectonic setting encoding
        # This would normally use comprehensive plate tectonic databases
        
        # Mid-ocean ridges
        if -70 < lat < 70 and ((-30 < lon < 30) or (100 < lon < 160)):
            return 0.1  # Divergent boundary
        # Subduction zones (simplified Pacific Ring of Fire)
        elif (lat > 30 and 120 < lon < 180) or (-60 < lat < -30 and -80 < lon < -60):
            return 0.9  # Convergent boundary
        # Transform boundaries
        elif (30 < lat < 40 and -125 < lon < -115):  # San Andreas-like
            return 0.5  # Transform boundary
        else:
            return 0.3  # Intraplate/stable craton
    
    def _estimate_crustal_age(self, lat: float, lon: float) -> float:
        """Estimate crustal age in billions of years"""
        # Very simplified crustal age estimation
        # Real implementation would use geological age databases
        
        # Continental shields (old crust)
        if (45 < lat < 70 and -110 < lon < -60) or (55 < lat < 75 and 20 < lon < 60):
            return 2.5  # Archean shields
        # Ocean basins (young crust)
        elif abs(lat) < 60 and ((-40 < lon < 20) or (120 < lon < 180)):
            return 0.1  # Young oceanic crust
        else:
            return 1.0  # Average continental crust
    
    def _calculate_plate_boundary_distance(self, lat: float, lon: float) -> float:
        """Calculate approximate distance to nearest plate boundary in km"""
        # Simplified calculation - would normally use detailed plate boundary databases
        
        # Major plate boundaries (very simplified)
        plate_boundaries = [
            (0, -30, 'atlantic_ridge'),    # Mid-Atlantic Ridge
            (0, 140, 'pacific_ridge'),     # East Pacific Rise
            (40, 140, 'japan_trench'),     # Japan Trench
            (10, -85, 'central_america'),  # Central America Trench
            (-15, -75, 'peru_trench')      # Peru-Chile Trench
        ]
        
        min_distance = 5000  # Default far from boundaries
        
        for boundary_lat, boundary_lon, boundary_name in plate_boundaries:
            # Simple spherical distance approximation
            dlat = lat - boundary_lat
            dlon = lon - boundary_lon
            distance = np.sqrt(dlat**2 + (dlon * np.cos(np.radians(lat)))**2) * 111  # Convert to km
            min_distance = min(min_distance, distance)
        
        return min_distance
    
    async def _simple_ml_pressure_fallback(self, features: Dict) -> Dict[str, Any]:
        """Simple ML-based pressure estimation fallback"""
        depth_km = features.get('depth_km', 1.0)
        tectonic_setting = features.get('tectonic_setting', 0.3)
        crustal_age = features.get('crustal_age', 1.0)
        
        # Simple decision tree-like logic
        if tectonic_setting > 0.7:  # Convergent boundary
            density = 2850  # Denser due to compression
        elif tectonic_setting < 0.3:  # Divergent boundary
            density = 2600  # Less dense due to extension
        else:
            if crustal_age > 2.0:  # Old crust
                density = 2700  # Stable continental
            else:
                density = 2750  # Younger crust
        
        pressure_pa = density * 9.81 * depth_km * 1000
        confidence = 0.6
        
        return {
            'pressure_pa': pressure_pa,
            'confidence': confidence,
            'ml_density_kg_m3': density,
            'method': 'simple_ml_fallback'
        }
    
    async def _advanced_pressure_fallback(self, lat: float, lon: float, depth_km: float) -> float:
        """Advanced fallback with regional geological considerations"""
        # Depth-dependent density with regional corrections
        if depth_km < 0.5:
            base_density = 2200  # Shallow sediments/soil
        elif depth_km < 2:
            base_density = 2400  # Sedimentary rocks
        elif depth_km < 10:
            base_density = 2650  # Upper crust
        elif depth_km < 25:
            base_density = 2800  # Middle-lower crust
        else:
            base_density = 3200  # Approaching mantle
        
        # Regional corrections based on latitude (very simplified)
        if abs(lat) > 60:  # Polar regions - often cratons
            regional_factor = 1.05  # Slightly denser
        elif abs(lat) < 30:  # Tropical regions - often younger crust
            regional_factor = 0.98  # Slightly less dense
        else:
            regional_factor = 1.0
        
        adjusted_density = base_density * regional_factor
        pressure_pa = adjusted_density * 9.81 * depth_km * 1000
        
        return pressure_pa
    
    async def _conservative_pressure_fallback(self, depth_km: float) -> float:
        """Conservative fallback when all methods fail"""
        # Use standard crustal density with depth correction
        if depth_km < 1:
            density = 2500  # Shallow crust
        elif depth_km < 10:
            density = 2700  # Average crust
        elif depth_km < 30:
            density = 2900  # Deep crust
        else:
            density = 3200  # Mantle-like
        
        return density * 9.81 * depth_km * 1000
    
    async def _enhanced_empirical_thermal_properties(self, temperature_c: float,
                                                    cap_rock_props: CapRockProperties,
                                                    coords: List[float] = None) -> dict:
        """Enhanced empirical thermal properties when thermodynamic engine unavailable"""
        try:
            # Enhanced empirical correlations
            base_expansion = 2e-5  # Base thermal expansion
            
            # Temperature-dependent thermal expansion
            temp_correction = 1.0 + 0.0002 * temperature_c
            thermal_expansion = base_expansion * temp_correction
            
            # Rock-type specific adjustments
            rock_type = getattr(cap_rock_props, 'rock_type', 'unknown').lower()
            expansion_factors = {
                'granite': 1.1,
                'basalt': 0.9,
                'limestone': 0.8,
                'sandstone': 1.0,
                'shale': 0.7,
                'quartzite': 1.2
            }
            thermal_expansion *= expansion_factors.get(rock_type, 1.0)
            
            return {
                'thermal_expansion': thermal_expansion,
                'thermal_diffusivity': await self._calculate_enhanced_thermal_diffusivity(
                    temperature_c, cap_rock_props, coords
                ),
                'thermal_conductivity': await self._get_temperature_dependent_thermal_conductivity(
                    temperature_c, cap_rock_props, coords
                ),
                'specific_heat': await self._get_volcanic_corrected_specific_heat(
                    temperature_c, cap_rock_props, coords
                )
            }
            
        except Exception:
            return await self._fallback_thermal_properties(temperature_c, cap_rock_props)
    
    async def _fallback_thermal_properties(self, temperature_c: float,
                                          cap_rock_props: CapRockProperties) -> dict:
        """Fallback thermal properties with basic temperature dependence"""
        return {
            'thermal_expansion': max(1e-6, 2e-5 * (1.0 + 0.0001 * temperature_c)),
            'thermal_diffusivity': max(5e-7, 1e-6 * (1.0 - 0.0002 * temperature_c)),
            'thermal_conductivity': max(1.0, 2.5 * (1.0 - 0.0005 * temperature_c)),
            'specific_heat': max(600, 800 * (1.0 + 0.0003 * temperature_c))
        }

    async def _get_comprehensive_creep_analysis(self, temperature_c: float, differential_stress: float,
                                              cap_rock_props: CapRockProperties,
                                              coords: List[float] = None) -> dict:
        """Comprehensive multi-mechanism creep analysis with real-time parameter estimation"""
        try:
            temperature_k = temperature_c + 273.15
            mechanisms = []
            
            # Get enhanced material properties for creep analysis
            creep_properties = await self._get_enhanced_creep_properties(
                temperature_c, cap_rock_props, coords
            )
            
            # 1. Dislocation creep (power-law) - dominant at high stress/temperature
            if temperature_c > 300 and differential_stress > 10e6:  # 10 MPa threshold
                dislocation_creep = await self._calculate_dislocation_creep_strain_rate(
                    temperature_k, differential_stress, creep_properties, coords
                )
                mechanisms.append(('dislocation', dislocation_creep['strain_rate'], dislocation_creep['confidence']))
            
            # 2. Diffusion creep (Nabarro-Herring/Coble) - dominant at low stress, high temperature
            if temperature_c > 400:
                diffusion_creep = await self._calculate_diffusion_creep_strain_rate(
                    temperature_k, differential_stress, creep_properties, coords
                )
                mechanisms.append(('diffusion', diffusion_creep['strain_rate'], diffusion_creep['confidence']))
            
            # 3. Dissolution-precipitation creep - important in hydrous environments
            dissolution_creep = await self._calculate_dissolution_precipitation_creep(
                temperature_k, differential_stress, creep_properties, coords
            )
            mechanisms.append(('dissolution', dissolution_creep['strain_rate'], dissolution_creep['confidence']))
            
            # 4. Grain boundary sliding - important for fine-grained materials
            if creep_properties.get('grain_size_m', 1e-3) < 1e-3:  # Fine-grained materials
                gbs_creep = await self._calculate_grain_boundary_sliding_creep(
                    temperature_k, differential_stress, creep_properties, coords
                )
                mechanisms.append(('grain_boundary_sliding', gbs_creep['strain_rate'], gbs_creep['confidence']))
            
            # 5. Volcanic/magmatic creep enhancement
            if coords:
                volcanic_creep = await self._calculate_volcanic_enhanced_creep(
                    temperature_k, differential_stress, creep_properties, coords
                )
                mechanisms.append(('volcanic_enhanced', volcanic_creep['strain_rate'], volcanic_creep['confidence']))
            
            # 6. Transient creep - time-dependent effects
            transient_creep = await self._calculate_transient_creep_effects(
                temperature_k, differential_stress, creep_properties
            )
            mechanisms.append(('transient', transient_creep['strain_rate'], transient_creep['confidence']))
            
            return {
                'mechanisms': mechanisms,
                'total_mechanisms': len(mechanisms),
                'dominant_mechanism': max(mechanisms, key=lambda x: x[1])[0] if mechanisms else 'none',
                'creep_properties': creep_properties
            }
            
        except Exception as e:
            self.logger.warning(f"Comprehensive creep analysis failed: {e}")
            return await self._fallback_creep_analysis(temperature_c, differential_stress, cap_rock_props)
    
    async def _get_enhanced_creep_properties(self, temperature_c: float,
                                           cap_rock_props: CapRockProperties,
                                           coords: List[float] = None) -> dict:
        """Get enhanced creep properties with real-time parameter estimation"""
        try:
            properties = {}
            
            # Rock-type specific creep parameters
            rock_type = getattr(cap_rock_props, 'rock_type', 'unknown').lower()
            properties.update(self._get_rock_type_creep_parameters(rock_type))
            
            # Temperature-dependent activation energies and pre-exponentials
            properties.update(await self._calculate_temperature_dependent_creep_parameters(
                temperature_c, rock_type, coords
            ))
            
            # Pressure-dependent parameters
            if coords:
                pressure_effects = await self._calculate_pressure_dependent_creep_parameters(coords)
                properties.update(pressure_effects)
            
            # Comprehensive petrographic grain size effects (critical for creep mechanisms)
            comprehensive_grain_data = await self._comprehensive_petrographic_grain_creep_analysis(coords, cap_rock_props, rock_type, temperature_c)
            properties['grain_size_m'] = comprehensive_grain_data['grain_size_m']
            properties['grain_size_exponent'] = comprehensive_grain_data['grain_size_exponent']
            
            # Water content effects (critical for creep rates)
            water_content = await self._estimate_water_content_effects(coords) if coords else 0.01
            properties['water_content'] = water_content
            properties['water_enhancement_factor'] = self._calculate_water_enhancement_factor(water_content)
            
            # Volcanic alteration effects on creep parameters
            if coords:
                alteration_effects = await self._get_alteration_creep_effects(coords)
                properties.update(alteration_effects)
            
            return properties
            
        except Exception:
            return self._fallback_creep_properties(cap_rock_props)
    
