    async def _calculate_temperature_dependent_creep_parameters(self, temperature_c: float,
                                                              rock_type: str,
                                                              coords: List[float] = None) -> dict:
        """Calculate temperature-dependent modifications to creep parameters"""
        try:
            temp_effects = {}
            
            # Temperature-dependent activation energy variations
            base_Q_factor = 1.0
            
            # High temperature effects (activation energy may change with temperature)
            if temperature_c > 600:
                base_Q_factor *= (1.0 + 0.1 * (temperature_c - 600) / 400)  # Slight increase at very high T
            
            # Volcanic thermal gradient effects
            if coords:
                volcanic_thermal = await self._get_comprehensive_regional_volcanic_analysis(coords)
                thermal_gradient = volcanic_thermal.get('thermal_gradient_k_km', 25.0)
                
                # Enhanced activation energies in high thermal gradient regions
                gradient_factor = 1.0 + 0.05 * thermal_gradient / 30.0
                base_Q_factor *= gradient_factor
            
            temp_effects['Q_temperature_factor'] = base_Q_factor
            temp_effects['thermal_gradient_effects'] = True if coords else False
            
            return temp_effects
            
        except Exception:
            return {'Q_temperature_factor': 1.0}
    
    async def _calculate_pressure_dependent_creep_parameters(self, coords: List[float]) -> dict:
        """Calculate pressure-dependent creep parameter modifications"""
        try:
            pressure_pa = await self._estimate_lithostatic_pressure(coords)
            
            # Activation volume effects
            activation_volume = 20e-6  # m³/mol (typical for rock deformation)
            gas_constant = 8.314  # J/(mol·K)
            
            # Pressure enhancement factor for activation energy
            pressure_factor = 1.0 + activation_volume * pressure_pa / (gas_constant * 1000)  # At 1000K reference
            
            return {
                'pressure_factor': max(0.5, min(3.0, pressure_factor)),
                'activation_volume': activation_volume,
                'lithostatic_pressure_pa': pressure_pa
            }
            
        except Exception:
            return {'pressure_factor': 1.0}
    
    async def _get_grain_size_creep_exponent(self, rock_type: str, temperature_c: float) -> float:
        """Get grain size exponent for different creep mechanisms"""
        # Grain size exponents vary by mechanism and rock type
        base_exponents = {
            'granite': 2.5,
            'basalt': 2.3,
            'limestone': 2.0,  # More sensitive to grain size
            'sandstone': 2.1,
            'shale': 1.8,      # Less sensitive due to layered structure
            'quartzite': 2.7   # Highly sensitive
        }
        
        base_exp = base_exponents.get(rock_type, 2.3)
        
        # Temperature dependence of grain size sensitivity
        if temperature_c > 500:
            temp_factor = 1.0 + 0.2 * (temperature_c - 500) / 500  # Increased sensitivity at high T
            base_exp *= temp_factor
        
        return max(1.5, min(3.5, base_exp))
    
    async def _estimate_water_content_effects(self, coords: List[float]) -> float:
        """Estimate water content effects from volcanic/hydrothermal systems"""
        try:
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            
            # Base water content
            base_water = 0.01  # 1 wt% base
            
            # Enhanced water content near volcanic systems
            hydrothermal_activity = volcanic_data.get('hydrothermal_activity', 0.1)
            alteration_index = volcanic_data.get('alteration_index', 0.1)
            
            enhanced_water = base_water * (1.0 + 2.0 * hydrothermal_activity + alteration_index)
            
            return min(0.1, enhanced_water)  # Max 10 wt%
            
        except Exception:
            return 0.01  # 1 wt% fallback
    
    def _calculate_water_enhancement_factor(self, water_content: float) -> float:
        """Calculate water enhancement factor for creep rates"""
        # Water dramatically enhances creep rates through weakening mechanisms
        # Exponential relationship based on experimental data
        water_enhancement = np.exp(20 * water_content)  # Strong exponential dependence
        
        return max(1.0, min(1000.0, water_enhancement))  # Cap at 1000x enhancement
    
    async def _calculate_dislocation_creep_strain_rate(self, temperature_k: float, differential_stress: float,
                                                     creep_properties: dict, coords: List[float] = None) -> dict:
        """Calculate dislocation creep strain rate using advanced constitutive models"""
        try:
            # Extract parameters
            A = creep_properties.get('dislocation_A', 3.2e-26)
            n = creep_properties.get('dislocation_n', 3.3)
            Q = creep_properties.get('dislocation_Q', 186e3)
            
            # Temperature and pressure corrections
            Q *= creep_properties.get('Q_temperature_factor', 1.0)
            Q *= creep_properties.get('pressure_factor', 1.0)
            
            # Water enhancement
            water_factor = creep_properties.get('water_enhancement_factor', 1.0)
            
            # Grain size effects (dislocation creep is typically grain size independent)
            grain_size_factor = 1.0  # Dislocation creep is generally grain size independent
            
            # Volcanic enhancement effects
            volcanic_factor = await self._get_volcanic_creep_enhancement(coords) if coords else 1.0
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate strain rate
            exponential_term = np.exp(-Q / (gas_constant * temperature_k))
            stress_term = (differential_stress / 1e6) ** n  # Convert stress to MPa for calculation
            
            strain_rate = (A * stress_term * exponential_term * water_factor * 
                          grain_size_factor * volcanic_factor)
            
            # Confidence based on parameter certainty and applicability
            confidence = await self._calculate_mechanism_confidence('dislocation', temperature_k, 
                                                           differential_stress, creep_properties, coords)
            
            return {
                'strain_rate': max(1e-15, strain_rate),  # Minimum strain rate
                'confidence': confidence,
                'dominant_temperature_range': (573, 1273),  # 300-1000°C
                'mechanism_details': {
                    'stress_exponent': n,
                    'activation_energy': Q,
                    'water_enhancement': water_factor,
                    'volcanic_enhancement': volcanic_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-12, 'confidence': 0.3}
    
    async def _calculate_diffusion_creep_strain_rate(self, temperature_k: float, differential_stress: float,
                                                   creep_properties: dict, coords: List[float] = None) -> dict:
        """Calculate diffusion creep strain rate (Nabarro-Herring/Coble creep)"""
        try:
            # Extract parameters
            A = creep_properties.get('diffusion_A', 8.7e-28)
            n = creep_properties.get('diffusion_n', 1.0)  # Linear stress dependence
            Q = creep_properties.get('diffusion_Q', 154e3)
            
            # Comprehensive petrographic grain size dependence (critical for diffusion creep)
            comprehensive_grain_creep = await self._comprehensive_petrographic_diffusion_creep_analysis(coords, creep_properties)
            grain_size_factor = comprehensive_grain_creep['grain_size_factor']
            grain_size_exponent = comprehensive_grain_creep['grain_size_exponent']
            
            # Temperature and pressure corrections
            Q *= creep_properties.get('Q_temperature_factor', 1.0)
            Q *= creep_properties.get('pressure_factor', 1.0)
            
            # Water enhancement
            water_factor = creep_properties.get('water_enhancement_factor', 1.0)
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate strain rate
            exponential_term = np.exp(-Q / (gas_constant * temperature_k))
            stress_term = (differential_stress / 1e6) ** n
            
            strain_rate = (A * stress_term * exponential_term * grain_size_factor * water_factor)
            
            # Confidence assessment
            confidence = await self._calculate_mechanism_confidence('diffusion', temperature_k, 
                                                           differential_stress, creep_properties, coords)
            
            return {
                'strain_rate': max(1e-15, strain_rate),
                'confidence': confidence,
                'dominant_temperature_range': (673, 1473),  # 400-1200°C
                'mechanism_details': {
                    'grain_size_dependence': grain_size_exponent,
                    'grain_size_factor': grain_size_factor,
                    'water_enhancement': water_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-13, 'confidence': 0.4}
    
    async def _calculate_dissolution_precipitation_creep(self, temperature_k: float, differential_stress: float,
                                                       creep_properties: dict, coords: List[float] = None) -> dict:
        """Calculate dissolution-precipitation creep strain rate"""
        try:
            # Extract parameters
            A = creep_properties.get('dissolution_A', 1.0e-12)
            Q = creep_properties.get('dissolution_Q', 150e3)
            
            # Water content is critical for dissolution-precipitation
            water_content = creep_properties.get('water_content', 0.01)
            
            # Enhanced in hydrothermal environments
            hydrothermal_factor = await self._get_hydrothermal_dissolution_enhancement(coords) if coords else 1.0
            
            # Comprehensive petrographic grain size effects (dissolution-precipitation is grain size dependent)
            comprehensive_dissolution_grain = await self._comprehensive_petrographic_dissolution_creep_analysis(coords, creep_properties)
            grain_size_factor = comprehensive_dissolution_grain['grain_size_factor']
            
            # pH and fluid composition effects
            fluid_composition_factor = await self._get_fluid_composition_effects(coords) if coords else 1.0
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate strain rate - typically linear stress dependence
            exponential_term = np.exp(-Q / (gas_constant * temperature_k))
            stress_term = differential_stress / 1e6  # Linear stress dependence
            
            strain_rate = (A * stress_term * exponential_term * water_content * 
                          hydrothermal_factor * grain_size_factor * fluid_composition_factor)
            
            # Confidence assessment
            confidence = await self._calculate_mechanism_confidence('dissolution', temperature_k, 
                                                           differential_stress, creep_properties, coords)
            
            return {
                'strain_rate': max(1e-14, strain_rate),
                'confidence': confidence,
                'dominant_temperature_range': (373, 773),  # 100-500°C
                'mechanism_details': {
                    'water_content': water_content,
                    'hydrothermal_enhancement': hydrothermal_factor,
                    'fluid_composition_factor': fluid_composition_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-13, 'confidence': 0.5}
    
    async def _calculate_grain_boundary_sliding_creep(self, temperature_k: float, differential_stress: float,
                                                    creep_properties: dict, coords: List[float] = None) -> dict:
        """Calculate grain boundary sliding creep strain rate"""
        try:
            # Grain boundary sliding parameters (typically similar to diffusion creep but with different kinetics)
            A = creep_properties.get('diffusion_A', 8.7e-28) * 10  # Enhanced pre-exponential
            Q = creep_properties.get('diffusion_Q', 154e3) * 0.8  # Lower activation energy
            
            # Comprehensive petrographic grain boundary sliding analysis with strong grain size dependence
            comprehensive_gbs_grain = await self._comprehensive_petrographic_grain_boundary_sliding_creep(coords, creep_properties)
            grain_size_factor = comprehensive_gbs_grain['grain_size_factor']
            
            # Water enhancement (critical for grain boundary processes)
            water_factor = creep_properties.get('water_enhancement_factor', 1.0)
            
            # Volcanic alteration can create favorable grain boundary conditions
            alteration_factor = await self._get_alteration_grain_boundary_effects(coords) if coords else 1.0
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate strain rate
            exponential_term = np.exp(-Q / (gas_constant * temperature_k))
            stress_term = (differential_stress / 1e6) ** 2.0  # Intermediate stress dependence
            
            strain_rate = (A * stress_term * exponential_term * grain_size_factor * 
                          water_factor * alteration_factor)
            
            # Confidence assessment
            confidence = await self._calculate_mechanism_confidence('grain_boundary_sliding', temperature_k, 
                                                           differential_stress, creep_properties, coords)
            
            return {
                'strain_rate': max(1e-15, strain_rate),
                'confidence': confidence,
                'dominant_temperature_range': (473, 973),  # 200-700°C
                'mechanism_details': {
                    'grain_size_sensitivity': 3.0,
                    'grain_size_factor': grain_size_factor,
                    'alteration_enhancement': alteration_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-13, 'confidence': 0.4}
    
    async def _calculate_volcanic_enhanced_creep(self, temperature_k: float, differential_stress: float,
                                               creep_properties: dict, coords: List[float]) -> dict:
        """Calculate volcanic system enhanced creep mechanisms"""
        try:
            # Get volcanic context
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            
            # Magmatic loading effects from comprehensive volcanic process modeling
            comprehensive_loading_pa_s = await self._comprehensive_volcanic_loading_rate_analysis(coords, None)
            magmatic_loading = (comprehensive_loading_pa_s * 3.15e7) / 1e6  # Convert Pa/s to MPa/year
            
            # Enhanced creep due to cyclic loading from volcanic processes
            cyclic_loading_factor = 1.0 + 2.0 * magmatic_loading / 10.0  # Enhanced creep under cyclic loading
            
            # Fluid pressure effects from volcanic gases
            fluid_pressure_factor = 1.0 + volcanic_data.get('fluid_pressure_ratio', 0.1)
            
            # Temperature fluctuations enhance creep through thermal cycling
            thermal_cycling_factor = 1.0 + 0.5 * volcanic_data.get('thermal_variability', 0.1)
            
            # Base creep rate using dislocation creep parameters as reference
            A = creep_properties.get('dislocation_A', 3.2e-26) * 5  # Enhanced pre-exponential
            n = 2.5  # Modified stress exponent for volcanic conditions
            Q = creep_properties.get('dislocation_Q', 186e3) * 0.9  # Slightly lower activation energy
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate enhanced strain rate
            exponential_term = np.exp(-Q / (gas_constant * temperature_k))
            stress_term = (differential_stress / 1e6) ** n
            
            enhancement_factor = (cyclic_loading_factor * fluid_pressure_factor * thermal_cycling_factor)
            
            strain_rate = A * stress_term * exponential_term * enhancement_factor
            
            # Confidence based on volcanic activity level
            volcanic_confidence = min(0.9, 0.5 + 0.4 * volcanic_data.get('volcanic_activity_index', 0.1))
            
            return {
                'strain_rate': max(1e-14, strain_rate),
                'confidence': volcanic_confidence,
                'dominant_conditions': 'active_volcanic_systems',
                'mechanism_details': {
                    'cyclic_loading_enhancement': cyclic_loading_factor,
                    'fluid_pressure_enhancement': fluid_pressure_factor,
                    'thermal_cycling_enhancement': thermal_cycling_factor,
                    'total_enhancement': enhancement_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-12, 'confidence': 0.3}
    
    async def _calculate_transient_creep_effects(self, temperature_k: float, differential_stress: float,
                                               creep_properties: dict) -> dict:
        """Calculate transient (primary) creep effects"""
        try:
            # Transient creep parameters
            A_transient = creep_properties.get('dislocation_A', 3.2e-26) * 100  # Higher pre-exponential
            Q_transient = creep_properties.get('dislocation_Q', 186e3) * 0.7  # Lower activation energy
            
            # Time-dependent term (assuming loading started recently)
            time_factor = 0.5  # Simplified transient factor
            
            # Water content enhances transient creep
            water_factor = creep_properties.get('water_enhancement_factor', 1.0) ** 0.5
            
            gas_constant = 8.314  # J/(mol·K)
            
            # Calculate transient strain rate
            exponential_term = np.exp(-Q_transient / (gas_constant * temperature_k))
            stress_term = (differential_stress / 1e6) ** 1.8  # Lower stress sensitivity for transient
            
            strain_rate = A_transient * stress_term * exponential_term * time_factor * water_factor
            
            return {
                'strain_rate': max(1e-14, strain_rate),
                'confidence': 0.6,
                'mechanism_details': {
                    'time_dependence': 'primary_creep',
                    'time_factor': time_factor
                }
            }
            
        except Exception:
            return {'strain_rate': 1e-13, 'confidence': 0.4}
    
    async def _calculate_mechanism_confidence(self, mechanism: str, temperature_k: float,
                                      differential_stress: float, creep_properties: dict, coords: List[float] = None) -> float:
        """Calculate confidence level for each creep mechanism based on conditions"""
        try:
            temperature_c = temperature_k - 273.15
            stress_mpa = differential_stress / 1e6
            
            confidence = 0.5  # Base confidence
            
            # Temperature-based confidence adjustments
            temp_ranges = {
                'dislocation': (573, 1273),  # 300-1000°C
                'diffusion': (673, 1473),    # 400-1200°C  
                'dissolution': (373, 773),    # 100-500°C
                'grain_boundary_sliding': (473, 973),  # 200-700°C
                'volcanic_enhanced': (473, 1073),      # 200-800°C
                'transient': (373, 873)       # 100-600°C
            }
            
            if mechanism in temp_ranges:
                min_temp, max_temp = temp_ranges[mechanism]
                if min_temp <= temperature_k <= max_temp:
                    # Maximum confidence in optimal temperature range
                    temp_confidence = 0.9
                elif temperature_k < min_temp:
                    # Reduced confidence below optimal range
                    temp_confidence = 0.3 * (temperature_k / min_temp)
                else:
                    # Reduced confidence above optimal range  
                    temp_confidence = 0.3 * (max_temp / temperature_k)
                
                confidence = max(confidence, temp_confidence)
            
            # Stress-based confidence adjustments
            if mechanism == 'dislocation' and stress_mpa > 10:
                confidence = min(0.9, confidence + 0.2)
            elif mechanism == 'diffusion' and stress_mpa < 50:
                confidence = min(0.9, confidence + 0.2)
            elif mechanism == 'dissolution' and stress_mpa < 20:
                confidence = min(0.9, confidence + 0.2)
            
            # Comprehensive petrographic grain size considerations for mechanism selection
            comprehensive_mechanism_grain = await self._comprehensive_petrographic_mechanism_grain_analysis(coords, creep_properties)
            if mechanism in ['diffusion', 'grain_boundary_sliding'] and comprehensive_mechanism_grain['grain_size_m'] < 1e-3:
                confidence = min(0.9, confidence + 0.15)
            
            return max(0.1, min(0.9, confidence))
            
        except Exception:
            return 0.5
    
    # Helper methods for creep analysis
    
    async def _get_volcanic_creep_enhancement(self, coords: List[float]) -> float:
        """Get volcanic system enhancement factor for creep"""
        try:
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            activity_index = volcanic_data.get('volcanic_activity_index', 0.1)
            return 1.0 + 3.0 * activity_index  # Up to 4x enhancement
        except Exception:
            return 1.0
    
    async def _get_hydrothermal_dissolution_enhancement(self, coords: List[float]) -> float:
        """Get hydrothermal enhancement for dissolution-precipitation creep"""
        try:
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            hydrothermal_activity = volcanic_data.get('hydrothermal_activity', 0.1)
            return 1.0 + 5.0 * hydrothermal_activity  # Strong enhancement
        except Exception:
            return 1.0
    
    async def _get_fluid_composition_effects(self, coords: List[float]) -> float:
        """Get fluid composition effects on dissolution creep"""
        try:
            # Real-time fluid composition data integration
            from .external_data_connectors import USGSConnector
            from .database_integration import DatabaseManager
            
            enhancement_factor = 1.0
            
            # Get water quality and geochemical data from USGS
            usgs = USGSConnector()
            
            # Analyze volcanic and hydrothermal fluid composition
            volcanic_data = await self._get_comprehensive_regional_volcanic_analysis(coords)
            alteration_data = await self._get_hydrothermal_alteration_thermal_effects(coords)
            
            # Dissolved ion concentration effects
            dissolved_solids_ppm = volcanic_data.get('dissolved_solids_ppm', 200)
            ph_level = volcanic_data.get('ph_level', 7.0)
            sulfate_ppm = volcanic_data.get('sulfate_ppm', 10)
            chloride_ppm = volcanic_data.get('chloride_ppm', 15)
            bicarbonate_ppm = volcanic_data.get('bicarbonate_ppm', 120)
            
            # pH effects on dissolution creep (optimal around 4-6 for most minerals)
            if ph_level < 7.0:  # Acidic conditions enhance dissolution
                ph_enhancement = 1.0 + 0.05 * (7.0 - ph_level)
            else:  # Basic conditions reduce dissolution
                ph_enhancement = 1.0 / (1.0 + 0.02 * (ph_level - 7.0))
            
            # Total dissolved solids effects
            if dissolved_solids_ppm > 500:  # High mineralization
                tds_enhancement = 1.0 + 0.0002 * (dissolved_solids_ppm - 500)
            else:
                tds_enhancement = 1.0
            
            # Specific ion effects on mineral dissolution
            # Sulfate enhances gypsum/anhydrite dissolution
            sulfate_factor = 1.0 + 0.0001 * sulfate_ppm
            
            # Chloride enhances halite dissolution and general corrosion
            chloride_factor = 1.0 + 0.00008 * chloride_ppm
            
            # Bicarbonate enhances carbonate dissolution
            bicarbonate_factor = 1.0 + 0.00005 * bicarbonate_ppm
            
            # Temperature effects on fluid reactivity
            surface_temp_c = volcanic_data.get('surface_temperature_c', 15.0)
            if surface_temp_c > 25.0:  # Enhanced reactivity at higher temperatures
                temp_factor = 1.0 + 0.01 * (surface_temp_c - 25.0)
            else:
                temp_factor = 1.0
            
            # Combined enhancement factor
            enhancement_factor = (ph_enhancement * tds_enhancement * 
                                sulfate_factor * chloride_factor * 
                                bicarbonate_factor * temp_factor)
            
            # Cap enhancement at reasonable limits
            enhancement_factor = max(0.5, min(3.0, enhancement_factor))
            
            # Database logging for fluid composition analysis
            db_manager = getattr(self, 'db_manager', None)
            if db_manager:
                async with db_manager.get_session() as session:
                    await session.execute("""
                        INSERT INTO fluid_composition_log 
                        (coords, ph_level, dissolved_solids_ppm, sulfate_ppm, 
                         chloride_ppm, bicarbonate_ppm, surface_temp_c, 
                         enhancement_factor, timestamp)
                        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
                    """, coords, ph_level, dissolved_solids_ppm, sulfate_ppm,
                         chloride_ppm, bicarbonate_ppm, surface_temp_c,
                         enhancement_factor, datetime.now())
            
            return enhancement_factor
            
        except Exception as e:
            self.logger.error(f"Fluid composition analysis failed: {e}")
            return 1.0
    
