    def _fallback_creep_properties(self, cap_rock_props: CapRockProperties) -> dict:
        """Fallback creep properties when advanced analysis fails"""
        rock_type = getattr(cap_rock_props, 'rock_type', 'granite').lower()
        
        return {
            'dislocation_A': 3.2e-26,
            'dislocation_n': 3.3,
            'dislocation_Q': 186e3,
            'diffusion_A': 8.7e-28,
            'diffusion_n': 1.0,
            'diffusion_Q': 154e3,
            'grain_size_m': (cap_rock_props.grain_size_mm or 1.0) * 1e-3,
            'water_content': 0.01,
            'water_enhancement_factor': 1.0,
            'Q_temperature_factor': 1.0,
            'pressure_factor': 1.0
        }
    
    async def _fallback_creep_analysis(self, temperature_c: float, differential_stress: float,
                                     cap_rock_props: CapRockProperties) -> dict:
        """Fallback creep analysis using simplified models"""
        try:
            # Simple power-law creep as fallback
            temperature_k = temperature_c + 273.15
            
            # Enhanced parameters based on temperature
            if temperature_c > 600:
                A = 1e-14  # Higher pre-exponential for high temperature
                n = 3.0
                Q = 200e3
                confidence = 0.7
            elif temperature_c > 400:
                A = 1e-15
                n = 3.2
                Q = 180e3  
                confidence = 0.6
            else:
                A = 1e-16
                n = 2.5
                Q = 150e3
                confidence = 0.4
            
            gas_constant = 8.314  # J/(mol·K)
            
            strain_rate = A * (differential_stress / 1e6) ** n * np.exp(-Q / (gas_constant * temperature_k))
            
            return {
                'mechanisms': [('fallback_powerlaw', max(1e-15, strain_rate), confidence)],
                'total_mechanisms': 1,
                'dominant_mechanism': 'fallback_powerlaw'
            }
            
        except Exception:
            return {
                'mechanisms': [('emergency_fallback', 1e-12, 0.3)],
                'total_mechanisms': 1,
                'dominant_mechanism': 'emergency_fallback'
            }

