    async def _get_comprehensive_tectonic_analysis(self, lat: float, lon: float) -> dict:
        """Comprehensive tectonic analysis using multiple data sources"""
        try:
            # Database-driven tectonic analysis
            query = """
                SELECT 
                    plate_name,
                    plate_motion_velocity,
                    motion_direction,
                    tectonic_setting,
                    stress_regime,
                    seismicity_level,
                    ST_Distance_Sphere(
                        ST_Point(%s, %s)::geometry, 
                        plate_boundary_geom
                    )/1000 as distance_km
                FROM geological_data.tectonic_plates tp
                ORDER BY distance_km
                LIMIT 5
            """
            
            async with self.db.get_connection() as conn:
                results = await conn.fetch(query, lon, lat)
                
            if results:
                primary_plate = results[0]
                return {
                    'primary_plate': primary_plate['plate_name'],
                    'plate_velocity': primary_plate['plate_motion_velocity'],
                    'motion_direction': primary_plate['motion_direction'],
                    'tectonic_setting': primary_plate['tectonic_setting'],
                    'stress_regime': primary_plate['stress_regime'],
                    'seismicity_level': primary_plate['seismicity_level'],
                    'distance_to_boundary_km': primary_plate['distance_km'],
                    'nearby_plates': [r['plate_name'] for r in results[1:]]
                }
                
        except Exception as e:
            self.logger.error(f"Comprehensive tectonic analysis failed: {e}")
            
        # Fallback to simplified analysis
        return {
            'primary_plate': 'Unknown',
            'plate_velocity': 25.0,
            'motion_direction': 0.0,
            'tectonic_setting': 'intraplate',
            'stress_regime': 'extensional',
            'seismicity_level': 'moderate',
            'distance_to_boundary_km': 100.0,
            'nearby_plates': []
        }

    async def _query_plate_boundaries_database(self, lat: float, lon: float) -> dict:
        """Query plate boundaries using PostGIS spatial analysis"""
        try:
            query = """
                WITH boundary_distances AS (
                    SELECT 
                        boundary_type,
                        boundary_name,
                        ST_Distance_Sphere(
                            ST_Point(%s, %s)::geometry, 
                            boundary_geom
                        )/1000 as distance_km,
                        spreading_rate,
                        convergence_rate,
                        transform_motion
                    FROM geological_data.plate_boundaries pb
                    WHERE ST_DWithin(
                        ST_Point(%s, %s)::geometry, 
                        boundary_geom, 
                        500000
                    )
                    ORDER BY distance_km
                    LIMIT 10
                )
                SELECT * FROM boundary_distances
            """
            
            async with self.db.get_connection() as conn:
                results = await conn.fetch(query, lon, lat, lon, lat)
                
            if results:
                closest = results[0]
                boundary_types = [r['boundary_type'] for r in results[:3]]
                dominant_type = max(set(boundary_types), key=boundary_types.count)
                
                return {
                    'min_distance_km': closest['distance_km'],
                    'closest_boundary': closest['boundary_name'],
                    'dominant_boundary_type': dominant_type,
                    'boundary_characteristics': {
                        'spreading_rate': closest.get('spreading_rate', 0.0),
                        'convergence_rate': closest.get('convergence_rate', 0.0),
                        'transform_motion': closest.get('transform_motion', 0.0)
                    }
                }
                
        except Exception as e:
            self.logger.error(f"Plate boundary query failed: {e}")
            
        return {
            'min_distance_km': 100.0,
            'closest_boundary': 'Unknown',
            'dominant_boundary_type': 'intraplate',
            'boundary_characteristics': {
                'spreading_rate': 0.0,
                'convergence_rate': 0.0,
                'transform_motion': 0.0
            }
        }

    async def _analyze_transform_systems(self, lat: float, lon: float) -> dict:
        """Analyze transform fault systems with GPS velocity fields"""
        try:
            # Query transform faults and fracture zones
            query = """
                SELECT 
                    transform_name,
                    fault_orientation,
                    slip_rate_mm_yr,
                    fault_length_km,
                    ST_Distance_Sphere(
                        ST_Point(%s, %s)::geometry, 
                        transform_geom
                    )/1000 as distance_km
                FROM geological_data.transform_faults tf
                WHERE ST_DWithin(
                    ST_Point(%s, %s)::geometry, 
                    transform_geom, 
                    200000
                )
                ORDER BY distance_km
                LIMIT 5
            """
            
            async with self.db.get_connection() as conn:
                results = await conn.fetch(query, lon, lat, lon, lat)
                
            if results:
                closest = results[0]
                avg_slip_rate = sum(r['slip_rate_mm_yr'] or 0 for r in results) / len(results)
                proximity_index = max(0, (200 - closest['distance_km']) / 200)
                
                return {
                    'proximity_index': proximity_index,
                    'closest_transform': closest['transform_name'],
                    'distance_km': closest['distance_km'],
                    'fault_orientation': closest['fault_orientation'],
                    'slip_rate_mm_yr': avg_slip_rate,
                    'system_length_km': sum(r['fault_length_km'] or 0 for r in results)
                }
                
        except Exception as e:
            self.logger.error(f"Transform system analysis failed: {e}")
            
        return {
            'proximity_index': 0.1,
            'closest_transform': 'Unknown',
            'distance_km': 200.0,
            'fault_orientation': 0.0,
            'slip_rate_mm_yr': 5.0,
            'system_length_km': 100.0
        }

