    def _fallback_archean_craton_detection(self, lat: float, lon: float) -> bool:
        """Enhanced fallback Archean craton detection with additional geological context"""
        # Major cratonic regions with enhanced boundaries
        archean_regions = [
            {'lat_range': (45, 75), 'lon_range': (-130, -50)},    # Canadian Shield (expanded)
            {'lat_range': (55, 75), 'lon_range': (15, 130)},     # Baltic/Siberian Shield (expanded)
            {'lat_range': (-40, -5), 'lon_range': (10, 40)},     # African cratons (expanded)
            {'lat_range': (-35, -10), 'lon_range': (105, 145)},  # Australian cratons (expanded)
            {'lat_range': (15, 30), 'lon_range': (70, 90)},      # Indian craton
            {'lat_range': (-35, -20), 'lon_range': (-70, -40)},  # São Francisco craton
        ]
        
        return any(
            r['lat_range'][0] <= lat <= r['lat_range'][1] and 
            r['lon_range'][0] <= lon <= r['lon_range'][1]
            for r in archean_regions
        )
    
    def _fallback_proterozoic_terrane_detection(self, lat: float, lon: float) -> bool:
        """Enhanced fallback Proterozoic terrane detection with mobile belt context"""
        # Adjacent to cratons, mobile belts, and transitional zones
        is_high_latitude = abs(lat) > 25
        not_in_craton = not self._fallback_archean_craton_detection(lat, lon)
        not_in_young_orogen = not self._fallback_phanerozoic_orogen_detection(lat, lon)
        
        return is_high_latitude and not_in_craton and not_in_young_orogen
    
    def _fallback_phanerozoic_orogen_detection(self, lat: float, lon: float) -> bool:
        """Enhanced fallback Phanerozoic orogenic belt detection with detailed mountain ranges"""
        # Major mountain belts and orogenic systems
        orogenic_belts = [
            {'lat_range': (25, 60), 'lon_range': (-15, 170)},    # Alpine-Himalayan (expanded)
            {'lat_range': (25, 75), 'lon_range': (-180, -50)},   # North American Cordillera (expanded)
            {'lat_range': (-65, 15), 'lon_range': (-85, -25)},   # Andes (expanded)
            {'lat_range': (30, 50), 'lon_range': (120, 155)},    # Japanese Arc
            {'lat_range': (-50, -30), 'lon_range': (165, 180)},  # New Zealand
            {'lat_range': (50, 70), 'lon_range': (-35, 15)},     # Caledonian
        ]
        
        return any(
            r['lat_range'][0] <= lat <= r['lat_range'][1] and 
            r['lon_range'][0] <= lon <= r['lon_range'][1]
            for r in orogenic_belts
        )
    
    def _fallback_active_volcanic_zone_detection(self, lat: float, lon: float) -> bool:
        """Enhanced fallback active volcanic zone detection with detailed volcanic regions"""
        # Pacific Ring of Fire and major volcanic regions (enhanced)
        volcanic_zones = [
            {'lat_range': (-70, 70), 'lon_range': (-180, -110)},  # Pacific West Coast
            {'lat_range': (-70, 70), 'lon_range': (110, 180)},   # Pacific West Pacific
            {'lat_range': (30, 75), 'lon_range': (-40, 40)},     # Mediterranean-Iceland (expanded)
            {'lat_range': (-25, 5), 'lon_range': (-95, -75)},    # Central American arc
            {'lat_range': (5, 25), 'lon_range': (120, 140)},     # Philippine arc
            {'lat_range': (-20, -5), 'lon_range': (105, 125)},   # Indonesian arc
        ]
        
        return any(
            r['lat_range'][0] <= lat <= r['lat_range'][1] and 
            r['lon_range'][0] <= lon <= r['lon_range'][1]
            for r in volcanic_zones
        )
    
