    async def _get_versioned_model_prediction(self, model_name: str, features: Dict,
                                            version: str = 'latest',
                                            fallback_enabled: bool = True) -> Dict:
        """
        Get model prediction with version control and automatic fallback.
        
        Features:
        - Version-specific model loading
        - Automatic fallback to stable versions
        - Prediction caching and performance tracking
        - Error handling with graceful degradation
        """
        try:
            model_manager = await self._get_model_manager()
            if not model_manager:
                if fallback_enabled:
                    return await self._fallback_prediction(model_name, features)
                else:
                    raise ValueError("Model manager not available")
            
            # Check if model exists with specified version
            if not await model_manager.model_exists(model_name, version):
                if version != 'latest' and fallback_enabled:
                    self.logger.warning(f"Model {model_name} v{version} not found, falling back to latest")
                    version = 'latest'
                else:
                    raise ValueError(f"Model {model_name} v{version} not found")
            
            # Load model with caching
            model = await model_manager.load_model(model_name, version=version, cache=True)
            
            # Get prediction with performance tracking
            prediction = await model_manager.predict_with_monitoring(
                model=model,
                features=features,
                track_performance=True,
                log_prediction=True
            )
            
            # Add metadata
            prediction.update({
                'model_name': model_name,
                'model_version': version,
                'prediction_timestamp': time.time(),
                'prediction_method': 'versioned_model_manager'
            })
            
            return prediction
            
        except Exception as e:
            self.logger.warning(f"Versioned model prediction failed for {model_name}: {e}")
            
            if fallback_enabled:
                return await self._fallback_prediction(model_name, features)
            else:
                raise
    
    async def _fallback_prediction(self, model_name: str, features: Dict) -> Dict:
        """Fallback prediction method when model manager is unavailable"""
        self.logger.info(f"Using fallback prediction for {model_name}")
        
        # Simple heuristic-based predictions as fallback
        fallback_predictions = {
            'rock_density_predictor_v2': {
                'density_kg_m3': 2650.0,  # Typical rock density
                'confidence': 0.3,
                'method': 'fallback_heuristic'
            },
            'fracture_toughness_predictor_v3': {
                'toughness_mpa_sqrt_m': 1.5,  # Typical fracture toughness
                'confidence': 0.3,
                'method': 'fallback_heuristic'
            },
            'seismic_velocity_nn': {
                'velocity_m_s': 3500.0,  # Typical seismic velocity
                'confidence': 0.3,
                'method': 'fallback_heuristic'
            }
        }
        
        return fallback_predictions.get(model_name, {
            'prediction': 0.0,
            'confidence': 0.2,
            'method': 'fallback_default'
        })
    
