    # ===== GLOBAL TECTONIC DATABASE TIER IMPLEMENTATIONS =====
    
    async def _tier1_global_plate_boundary_query(self, db_manager, lat: float, lon: float) -> Dict:
        """Tier 1: Global plate boundary database query with distance analysis"""
        try:
            if not db_manager:
                return {'success': False, 'data': {}}
            
            # Query global plate boundaries within 500km
            async with db_manager.get_session() as session:
                query = """
                SELECT 
                    pb.boundary_type,
                    pb.plate_name_1,
                    pb.plate_name_2,
                    pb.convergence_rate_mm_yr,
                    pb.spreading_rate_mm_yr,
                    pb.transform_rate_mm_yr,
                    ST_Distance(pb.boundary_geometry::geography, ST_Point(%s, %s)::geography) as distance_m,
                    pb.properties->>'age_ma' as boundary_age_ma,
                    pb.properties->>'confidence' as boundary_confidence,
                    pb.properties->>'seismic_coupling' as seismic_coupling
                FROM plate_boundaries pb
                WHERE ST_DWithin(pb.boundary_geometry::geography, ST_Point(%s, %s)::geography, 500000)
                AND pb.boundary_type IS NOT NULL
                ORDER BY distance_m ASC
                LIMIT 10;
                """
                
                from sqlalchemy import text
                result = await session.execute(text(query), [lon, lat, lon, lat])
                boundaries = result.fetchall()
                
                if boundaries:
                    boundary_data = []
                    min_distance = float('inf')
                    
                    for boundary in boundaries:
                        distance_km = boundary.distance_m / 1000.0
                        min_distance = min(min_distance, distance_km)
                        
                        boundary_data.append({
                            'boundary_type': boundary.boundary_type,
                            'plates': [boundary.plate_name_1, boundary.plate_name_2],
                            'distance_km': distance_km,
                            'convergence_rate': boundary.convergence_rate_mm_yr or 0.0,
                            'spreading_rate': boundary.spreading_rate_mm_yr or 0.0,
                            'transform_rate': boundary.transform_rate_mm_yr or 0.0,
                            'boundary_age_ma': float(boundary.boundary_age_ma or 0.0),
                            'confidence': float(boundary.boundary_confidence or 0.7),
                            'seismic_coupling': float(boundary.seismic_coupling or 0.5)
                        })
                    
                    return {
                        'success': True,
                        'distance_km': min_distance,
                        'boundary_count': len(boundary_data),
                        'boundaries': boundary_data,
                        'confidence': 0.9
                    }
                
                return {'success': False, 'data': {}, 'reason': 'No plate boundaries found'}
                
        except Exception as e:
            self.logger.error(f"Tier 1 plate boundary query failed: {e}")
            return {'success': False, 'data': {}, 'error': str(e)}
    
