    async def _tier5_tectonic_integration(self, data_dict: Dict) -> Dict:
        """Tier 5: Comprehensive tectonic integration with confidence weighting"""
        try:
            # Extract data from all tiers
            plate_boundaries = data_dict.get('plate_boundaries', {})
            earthquakes = data_dict.get('earthquakes', {})
            plate_motion = data_dict.get('plate_motion', {})
            fault_systems = data_dict.get('fault_systems', {})
            
            # Weighted integration
            total_weight = 0.0
            weighted_distance = 0.0
            weighted_seismic_activity = 0.0
            weighted_motion_velocity = 0.0
            
            # Plate boundary contribution (weight: 0.4)
            if plate_boundaries.get('success'):
                weight = 0.4 * plate_boundaries.get('confidence', 0.7)
                weighted_distance += plate_boundaries.get('distance_km', 1000.0) * weight
                total_weight += weight
            
            # Earthquake contribution (weight: 0.3)
            if earthquakes.get('success'):
                weight = 0.3 * earthquakes.get('confidence', 0.7)
                weighted_seismic_activity += earthquakes.get('seismic_activity', 0.0) * weight
                total_weight += weight
            
            # Plate motion contribution (weight: 0.2)
            if plate_motion.get('success'):
                weight = 0.2 * plate_motion.get('confidence', 0.7)
                weighted_motion_velocity += plate_motion.get('plate_motion_velocity', 0.0) * weight
                total_weight += weight
            
            # Fault systems contribution (weight: 0.1)
            if fault_systems.get('success'):
                weight = 0.1 * fault_systems.get('confidence', 0.6)
                # Incorporate fault proximity into distance calculation
                fault_distance = fault_systems.get('nearest_fault_distance', 1000.0)
                combined_distance = min(weighted_distance, fault_distance)
                weighted_distance = (weighted_distance + combined_distance) / 2.0
                total_weight += weight
            
            # Normalize results
            if total_weight > 0:
                final_distance = weighted_distance / (total_weight / 0.4)  # Normalize to plate boundary weight
                final_seismic = weighted_seismic_activity / (total_weight / 0.3)  # Normalize to earthquake weight
                final_velocity = weighted_motion_velocity / (total_weight / 0.2)  # Normalize to motion weight
            else:
                final_distance = 1000.0
                final_seismic = 0.0
                final_velocity = 0.0
            
            return {
                'success': True,
                'distance_km': min(final_distance, 2000.0),
                'seismic_activity': min(final_seismic, 100.0),
                'plate_motion_velocity': min(final_velocity, 200.0),
                'integration_confidence': min(total_weight, 1.0),
                'data_sources': {
                    'plate_boundaries': plate_boundaries.get('success', False),
                    'earthquakes': earthquakes.get('success', False),
                    'plate_motion': plate_motion.get('success', False),
                    'fault_systems': fault_systems.get('success', False)
                }
            }
            
        except Exception as e:
            self.logger.error(f"Tier 5 tectonic integration failed: {e}")
            return {'success': False, 'distance_km': 1000.0, 'seismic_activity': 0.0, 'plate_motion_velocity': 0.0}
    
