    async def _enhanced_volcanic_fallback_system(self, lat: float, lon: float, shear_modulus: float,
                                                cap_rock_props: CapRockProperties = None) -> dict:
        """Enhanced volcanic fallback system with basic multi-chamber considerations"""
        try:
            # Enhanced volcanic proximity with chamber awareness
            volcanic_proximity = await self._estimate_volcanic_proximity(lat, lon)
            
            if volcanic_proximity < 0.05:
                return {'confidence': 0.0}
            
            # Enhanced stress calculations with multi-factor approach
            magma_pressure_stress = volcanic_proximity * 25.0 * (shear_modulus / 30000.0)
            thermal_stress = volcanic_proximity * 15.0 * (1 + 0.1 * math.sin(math.radians(lat)))
            edifice_loading = volcanic_proximity * 8.0 * (1 + 0.05 * abs(lat) / 90.0)
            
            # Multi-chamber approximation
            chamber_interaction = min(1.2, 1 + volcanic_proximity * 0.3)
            
            total_stress = (magma_pressure_stress + thermal_stress + edifice_loading) * chamber_interaction
            velocity = volcanic_proximity * 45.0 * chamber_interaction
            
            return {
                'method_used': 'enhanced_volcanic_fallback',
                'confidence': min(0.7, volcanic_proximity * 1.2),
                'total_tectonic_stress_mpa': total_stress,
                'plate_motion_velocity_mm_yr': velocity,
                'stress_components': {
                    'magma_pressure_stress_mpa': magma_pressure_stress * chamber_interaction,
                    'thermal_stress_mpa': thermal_stress * chamber_interaction,
                    'edifice_loading_stress_mpa': edifice_loading * chamber_interaction
                },
                'uncertainty_mpa': total_stress * 0.4,
                'data_sources': ['enhanced_volcanic_proximity', 'multi_chamber_approximation']
            }
            
        except Exception as e:
            self.logger.error(f"Enhanced volcanic fallback system failed: {e}")
            return {'confidence': 0.0}

