    async def _query_global_volcanic_databases(self, lat: float, lon: float) -> dict:
        """Query global volcanic databases with comprehensive volcanic information"""
        try:
            from .external_data_connectors import USGSConnector, SmithsonianVolcanoConnector
            from .database_integration import DatabaseManager
            
            # Initialize connectors
            usgs = USGSConnector()
            smithsonian = SmithsonianVolcanoConnector() if hasattr(self, 'smithsonian_connector') else None
            
            active_volcanoes = []
            volcanic_fields = []
            caldera_systems = []
            
            # Query USGS Volcano Hazards Program
            usgs_volcano_data = await self._fetch_usgs_volcano_data(lat, lon, radius_km=200)
            
            if usgs_volcano_data.get('success'):
                for volcano in usgs_volcano_data.get('volcanoes', []):
                    volcano_record = {
                        'volcano_id': volcano.get('id'),
                        'name': volcano.get('name'),
                        'coordinates': [volcano.get('latitude'), volcano.get('longitude')],
                        'elevation_m': volcano.get('elevation_m'),
                        'volcano_type': volcano.get('type', 'unknown'),
                        'last_eruption': volcano.get('last_eruption'),
                        'hazard_level': volcano.get('hazard_level', 0),
                        'distance_km': volcano.get('distance_km'),
                        'monitoring_status': volcano.get('monitoring_status', 'unknown'),
                        'eruption_history': volcano.get('eruption_history', [])
                    }
                    
                    if volcano.get('status') == 'active':
                        active_volcanoes.append(volcano_record)
                    elif volcano.get('type') in ['volcanic_field', 'monogenetic_field']:
                        volcanic_fields.append(volcano_record)
                    elif volcano.get('type') in ['caldera', 'large_caldera']:
                        caldera_systems.append(volcano_record)
            
            # Query local database for cached global volcano data
            db_manager = getattr(self, 'db_manager', None)
            if db_manager:
                async with db_manager.get_session() as session:
                    # Query Smithsonian Global Volcanism Program data from cache
                    gvp_data = await session.fetch("""
                        SELECT volcano_number, volcano_name, country, 
                               latitude, longitude, elevation, 
                               primary_volcano_type, last_known_eruption,
                               evidence_category, major_rock_type
                        FROM global_volcanism_program
                        WHERE ST_DWithin(
                            ST_GeogFromText('POINT(' || longitude || ' ' || latitude || ')'),
                            ST_GeogFromText('POINT(' || $2 || ' ' || $1 || ')'),
                            300000  -- 300km radius for global survey
                        )
                        ORDER BY ST_Distance(
                            ST_GeogFromText('POINT(' || longitude || ' ' || latitude || ')'),
                            ST_GeogFromText('POINT(' || $2 || ' ' || $1 || ')')) 
                    """, lat, lon)
                    
                    for row in gvp_data:
                        distance_km = await self._calculate_distance(lat, lon, 
                                                                   row['latitude'], 
                                                                   row['longitude'])
                        volcano_record = {
                            'volcano_id': f"gvp_{row['volcano_number']}",
                            'name': row['volcano_name'],
                            'country': row['country'],
                            'coordinates': [row['latitude'], row['longitude']],
                            'elevation_m': row['elevation'],
                            'volcano_type': row['primary_volcano_type'],
                            'last_eruption': row['last_known_eruption'],
                            'evidence_category': row['evidence_category'],
                            'rock_type': row['major_rock_type'],
                            'distance_km': distance_km,
                            'source': 'smithsonian_gvp'
                        }
                        
                        # Classify by type
                        if row['evidence_category'] in ['Eruption observed', 'Eruption dated']:
                            if distance_km <= 100:  # Active within reasonable range
                                active_volcanoes.append(volcano_record)
                        
                        if 'field' in row['primary_volcano_type'].lower():
                            volcanic_fields.append(volcano_record)
                        elif 'caldera' in row['primary_volcano_type'].lower():
                            caldera_systems.append(volcano_record)
            
            # Calculate confidence based on data availability and quality
            total_volcanoes = len(active_volcanoes) + len(volcanic_fields) + len(caldera_systems)
            confidence = min(0.95, 0.5 + (total_volcanoes * 0.05))  # Higher confidence with more data
            
            return {
                'active_volcanoes': active_volcanoes,
                'volcanic_fields': volcanic_fields,
                'caldera_systems': caldera_systems,
                'total_count': total_volcanoes,
                'confidence': confidence,
                'sources': ['usgs_volcano_hazards', 'smithsonian_gvp']
            }
            
        except Exception as e:
            self.logger.error(f"Global volcanic database query failed: {e}")
            return {
                'active_volcanoes': [],
                'volcanic_fields': [],
                'caldera_systems': [],
                'confidence': 0.3,
                'error': str(e)
            }

    async def _classify_regional_volcanic_systems(self, lat: float, lon: float, global_data: dict) -> dict:
        """Classify regional volcanic systems with tectonic setting analysis"""
        try:
            from .database_integration import DatabaseManager
            
            # Initialize classification flags
            volcanic_arc = False
            hotspot_system = False
            rift_volcanism = False
            continental_volcanism = False
            
            # Get tectonic setting data
            tectonic_data = await self._get_comprehensive_tectonic_setting(lat, lon)
            plate_boundary_data = tectonic_data.get('plate_boundaries', {})
            
            # Analyze volcanic distribution patterns
            active_volcanoes = global_data.get('active_volcanoes', [])
            volcanic_fields = global_data.get('volcanic_fields', [])
            
            # Classification based on tectonic setting
            if plate_boundary_data.get('convergent_boundary_distance', float('inf')) < 200:
                # Near convergent boundary - likely volcanic arc
                if len(active_volcanoes) >= 3:
                    volcanic_arc = True
                    
            elif plate_boundary_data.get('divergent_boundary_distance', float('inf')) < 100:
                # Near divergent boundary - rift volcanism
                rift_volcanism = True
            
            # Hotspot detection - isolated volcanoes away from plate boundaries
            min_boundary_distance = min(
                plate_boundary_data.get('convergent_boundary_distance', float('inf')),
                plate_boundary_data.get('divergent_boundary_distance', float('inf')),
                plate_boundary_data.get('transform_boundary_distance', float('inf'))
            )
            
            if min_boundary_distance > 500 and len(active_volcanoes) > 0:
                # Check for age progression (hotspot track)
                if self._detect_age_progression(active_volcanoes):
                    hotspot_system = True
            
            # Continental volcanism - widespread volcanic fields in continental setting
            if len(volcanic_fields) > len(active_volcanoes) and not rift_volcanism:
                continental_volcanism = True
            
            # Query database for regional volcanic province classification
            db_manager = getattr(self, 'db_manager', None)
            if db_manager:
                async with db_manager.get_session() as session:
                    province_data = await session.fetchrow("""
                        SELECT province_type, tectonic_setting, 
                               magma_type, activity_period
                        FROM volcanic_provinces
                        WHERE ST_Contains(
                            province_geom,
                            ST_GeogFromText('POINT(' || $2 || ' ' || $1 || ')')
                        )
                        ORDER BY ST_Area(province_geom) ASC
                        LIMIT 1
                    """, lat, lon)
                    
                    if province_data:
                        province_type = province_data['province_type'].lower()
                        if 'arc' in province_type or 'subduction' in province_type:
                            volcanic_arc = True
                        elif 'rift' in province_type or 'extensional' in province_type:
                            rift_volcanism = True
                        elif 'hotspot' in province_type or 'plume' in province_type:
                            hotspot_system = True
                        elif 'continental' in province_type or 'intraplate' in province_type:
                            continental_volcanism = True
            
            # Calculate confidence based on data quality and consistency
            classification_count = sum([volcanic_arc, hotspot_system, rift_volcanism, continental_volcanism])
            data_quality = global_data.get('confidence', 0.5)
            tectonic_confidence = tectonic_data.get('confidence', 0.5)
            
            confidence = (data_quality + tectonic_confidence) / 2.0
            if classification_count == 1:
                confidence += 0.2  # Bonus for clear classification
            elif classification_count > 1:
                confidence -= 0.1  # Penalty for ambiguous classification
            
            return {
                'volcanic_arc': volcanic_arc,
                'hotspot_system': hotspot_system,
                'rift_volcanism': rift_volcanism,
                'continental_volcanism': continental_volcanism,
                'primary_setting': self._determine_primary_setting(
                    volcanic_arc, hotspot_system, rift_volcanism, continental_volcanism
                ),
                'confidence': min(0.95, max(0.1, confidence))
            }
            
        except Exception as e:
            self.logger.error(f"Regional volcanic system classification failed: {e}")
            return {
                'volcanic_arc': False,
                'hotspot_system': False,
                'rift_volcanism': False,
                'continental_volcanism': False,
                'confidence': 0.3
            }

