    async def _advanced_stress_tensor_field_analysis(self, lat: float, lon: float, shear_modulus: float,
                                                    fem_analysis: dict, chamber_geometry: dict,
                                                    cap_rock_props: CapRockProperties = None) -> dict:
        """
        Advanced stress tensor field analysis with full 6-component stress tensors
        """
        try:
            # Import stress analysis modules
            from .stress_analysis import StressTensorAnalyzer
            from .volcano_modules import VolcanicStressModeler
            import numpy as np
            
            tensor_analyzer = StressTensorAnalyzer()
            volcanic_stress = VolcanicStressModeler()
            
            # 6-component stress tensor field calculation
            stress_tensor_field = await tensor_analyzer.calculate_3d_stress_tensor_field(
                lat, lon, fem_analysis['stress_state'], chamber_geometry['chamber_3d_geometry']
            )
            
            # Principal stress analysis
            principal_stresses = await tensor_analyzer.calculate_principal_stresses(
                stress_tensor_field, shear_modulus
            )
            
            # Von Mises stress distribution
            von_mises = await tensor_analyzer.calculate_von_mises_stress_distribution(
                stress_tensor_field, principal_stresses
            )
            
            # Deviatoric stress analysis
            deviatoric_analysis = await tensor_analyzer.analyze_deviatoric_stress_components(
                stress_tensor_field, principal_stresses, von_mises
            )
            
            # Stress gradient analysis
            stress_gradients = await self._analyze_stress_gradient_patterns(
                stress_tensor_field, chamber_geometry['wall_stress_distribution']
            )
            
            # Critical stress zone identification
            critical_zones = await self._identify_critical_stress_zones(
                principal_stresses, von_mises, deviatoric_analysis, stress_gradients
            )
            
            return {
                'stress_tensor_field': stress_tensor_field,
                'principal_stresses': principal_stresses,
                'von_mises_distribution': von_mises,
                'deviatoric_analysis': deviatoric_analysis,
                'stress_gradients': stress_gradients,
                'critical_stress_zones': critical_zones,
                'confidence': min(0.90, critical_zones.get('analysis_confidence', 0.82)),
                'method': 'advanced_stress_tensor_analysis'
            }
            
        except Exception as e:
            self.logger.error(f"Stress tensor field analysis failed: {e}")
            return await self._stress_tensor_fallback(lat, lon, shear_modulus, fem_analysis, chamber_geometry)

