    async def _define_chamber_boundary_conditions(self, lat: float, lon: float, chamber_geometry: dict,
                                                 material_props: dict) -> dict:
        """Define boundary conditions for FEM analysis"""
        try:
            from .geodynamics import GeodynamicModeler
            from .tectonic_loading import TectonicLoadingCalculator
            
            geodynamic = GeodynamicModeler()
            tectonic_loading = TectonicLoadingCalculator()
            
            # Regional stress field
            regional_stress = await geodynamic.get_regional_stress_field(lat, lon)
            
            # Tectonic loading conditions
            tectonic_loads = await tectonic_loading.calculate_tectonic_loads(
                lat, lon, chamber_geometry
            )
            
            # Gravitational loading
            gravity_loading = await self._calculate_gravitational_loading(
                chamber_geometry, material_props
            )
            
            return {
                'displacement_bc': {
                    'fixed_boundaries': chamber_geometry.get('fixed_surfaces', []),
                    'free_boundaries': chamber_geometry.get('free_surfaces', [])
                },
                'stress_bc': {
                    'regional_stress_tensor': regional_stress,
                    'tectonic_loading': tectonic_loads,
                    'magma_pressure': chamber_geometry.get('chamber_pressure_pa', 1e7)
                },
                'thermal_bc': {
                    'chamber_temperature': material_props['magma_properties']['temperature'],
                    'surface_temperature': 288,  # K
                    'geothermal_gradient': 0.025  # K/m
                }
            }
            
        except Exception as e:
            self.logger.error(f"Boundary condition definition failed: {e}")
            return self._default_boundary_conditions()

    async def _calculate_magma_pressure_distribution(self, lat: float, lon: float, chamber_geometry: dict,
                                                   stress_analysis: dict) -> dict:
        """Calculate detailed magma pressure distribution"""
        try:
            from .volcano_modules import MagmaPressureModeler
            from .fluid_dynamics import MagmaFlowModeler
            
            pressure_modeler = MagmaPressureModeler()
            flow_modeler = MagmaFlowModeler()
            
            # Hydrostatic pressure calculation
            hydrostatic = await pressure_modeler.calculate_hydrostatic_pressure(
                chamber_geometry, lat, lon
            )
            
            # Dynamic pressure from magma flow
            dynamic_pressure = await flow_modeler.calculate_dynamic_pressure(
                chamber_geometry, hydrostatic
            )
            
            # Overpressure from crystallization
            crystallization_pressure = await pressure_modeler.calculate_crystallization_overpressure(
                chamber_geometry, dynamic_pressure, lat, lon
            )
            
            # Gas pressure contribution
            gas_pressure = await pressure_modeler.calculate_gas_pressure_contribution(
                chamber_geometry, crystallization_pressure
            )
            
            return {
                'hydrostatic_pressure': hydrostatic,
                'dynamic_pressure': dynamic_pressure,
                'crystallization_overpressure': crystallization_pressure,
                'gas_pressure_contribution': gas_pressure,
                'total_pressure_distribution': {
                    'mean_pressure_mpa': (
                        hydrostatic.get('mean_pressure_mpa', 50.0) +
                        dynamic_pressure.get('mean_pressure_mpa', 5.0) +
                        crystallization_pressure.get('mean_pressure_mpa', 10.0) +
                        gas_pressure.get('mean_pressure_mpa', 3.0)
                    ),
                    'pressure_gradients': hydrostatic.get('pressure_gradients', {}),
                    'spatial_distribution': hydrostatic.get('spatial_distribution', {})
                }
            }
            
        except Exception as e:
            self.logger.error(f"Magma pressure calculation failed: {e}")
            return self._default_magma_pressure()

    async def _calculate_thermal_stress_coupling(self, lat: float, lon: float, chamber_geometry: dict,
                                               stress_analysis: dict, magma_pressure: dict) -> dict:
        """Calculate thermal stress coupling effects"""
        try:
            from .thermal_modeling import ThermalStressModeler
            from .volcano_modules import VolcanicThermalAnalyzer
            
            thermal_modeler = ThermalStressModeler()
            volcanic_thermal = VolcanicThermalAnalyzer()
            
            # Temperature field calculation
            temperature_field = await volcanic_thermal.calculate_3d_temperature_field(
                lat, lon, chamber_geometry, magma_pressure
            )
            
            # Thermal expansion stress
            thermal_expansion = await thermal_modeler.calculate_thermal_expansion_stress(
                temperature_field, chamber_geometry, stress_analysis
            )
            
            # Thermal gradient stress
            thermal_gradients = await thermal_modeler.calculate_thermal_gradient_stress(
                temperature_field, thermal_expansion
            )
            
            # Phase change thermal effects
            phase_change = await thermal_modeler.calculate_phase_change_thermal_effects(
                temperature_field, magma_pressure, chamber_geometry
            )
            
            return {
                'temperature_field': temperature_field,
                'thermal_expansion_stress': thermal_expansion,
                'thermal_gradient_stress': thermal_gradients,
                'phase_change_effects': phase_change,
                'coupled_thermal_stress': {
                    'total_thermal_stress_mpa': (
                        thermal_expansion.get('mean_stress_mpa', 15.0) +
                        thermal_gradients.get('mean_stress_mpa', 8.0) +
                        phase_change.get('mean_stress_mpa', 5.0)
                    ),
                    'thermal_stress_distribution': thermal_expansion.get('stress_distribution', {}),
                    'coupling_coefficient': 0.85
                }
            }
            
        except Exception as e:
            self.logger.error(f"Thermal stress coupling calculation failed: {e}")
            return self._default_thermal_coupling()

    async def _analyze_comprehensive_stress_state(self, stress_analysis: dict, magma_pressure: dict,
                                                 thermal_coupling: dict, shear_modulus: float) -> dict:
        """Analyze comprehensive stress state from all components"""
        try:
            from .stress_analysis import ComprehensiveStressAnalyzer
            
            stress_analyzer = ComprehensiveStressAnalyzer()
            
            # Combine all stress components
            combined_stress = await stress_analyzer.combine_stress_components(
                stress_analysis, magma_pressure, thermal_coupling, shear_modulus
            )
            
            # Principal stress analysis
            principal_stresses = await stress_analyzer.calculate_principal_stresses(
                combined_stress
            )
            
            # Stress invariants
            stress_invariants = await stress_analyzer.calculate_stress_invariants(
                combined_stress, principal_stresses
            )
            
            # Critical stress assessment
            critical_assessment = await stress_analyzer.assess_critical_stress_conditions(
                principal_stresses, stress_invariants, shear_modulus
            )
            
            return {
                'combined_stress_tensor': combined_stress,
                'principal_stresses': principal_stresses,
                'stress_invariants': stress_invariants,
                'critical_assessment': critical_assessment,
                'analysis_quality': min(0.88, critical_assessment.get('assessment_confidence', 0.80))
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive stress state analysis failed: {e}")
            return self._default_stress_state(shear_modulus)

    # Fallback methods for graceful degradation
    async def _fem_analysis_fallback(self, lat: float, lon: float, shear_modulus: float,
                                   cap_rock_props: CapRockProperties = None) -> dict:
        """Fallback for FEM analysis"""
        return {
            'fem_analysis': {'simplified_stress_field': shear_modulus * 0.001},
            'chamber_geometry': {'estimated_depth_km': 5.0, 'estimated_radius_km': 2.0},
            'magma_pressure': {'total_pressure_distribution': {'mean_pressure_mpa': 40.0}},
            'thermal_coupling': {'coupled_thermal_stress': {'total_thermal_stress_mpa': 12.0}},
            'stress_state': {'analysis_quality': 0.60},
            'confidence': 0.60,
            'method': 'simplified_fallback'
        }

    async def _integrate_all_stress_components(self, fem_analysis: dict, multi_scale_analysis: dict,
                                             chamber_geometry: dict, stress_tensor_field: dict,
                                             temporal_evolution: dict, multi_physics: dict,
                                             shear_modulus: float) -> dict:
        """Integrate all stress components into final result"""
        try:
            fem_stress = fem_analysis.get('stress_state', {}).get('analysis_quality', 0.0) * 45.0
            multi_scale_stress = multi_scale_analysis.get('scale_synthesis', {}).get('total_stress_mpa', 25.0)
            chamber_stress = chamber_geometry.get('wall_stress_distribution', {}).get('max_stress_mpa', 35.0)
            tensor_stress = stress_tensor_field.get('von_mises_distribution', {}).get('max_stress_mpa', 40.0)
            temporal_stress = temporal_evolution.get('future_stress_prediction', {}).get('predicted_stress_mpa', 20.0)
            physics_stress = multi_physics.get('coupled_field_evolution', {}).get('total_coupling_stress_mpa', 15.0)
            
            return {
                'fem_component': fem_stress,
                'multi_scale_component': multi_scale_stress,
                'chamber_geometry_component': chamber_stress,
                'tensor_field_component': tensor_stress,
                'temporal_component': temporal_stress,
                'multi_physics_component': physics_stress,
                'tectonic_velocity': 28.0
            }
        except Exception as e:
            self.logger.error(f"Stress component integration failed: {e}")
            return {'total_stress': 35.0, 'tectonic_velocity': 20.0}

    async def _calculate_total_stress_magnitude(self, integrated_stress: dict, von_mises_dist: dict) -> float:
        """Calculate total stress magnitude"""
        try:
            total = sum([
                integrated_stress.get('fem_component', 0.0),
                integrated_stress.get('multi_scale_component', 0.0),
                integrated_stress.get('chamber_geometry_component', 0.0) * 0.8,
                integrated_stress.get('tensor_field_component', 0.0) * 0.9,
                integrated_stress.get('temporal_component', 0.0) * 0.7,
                integrated_stress.get('multi_physics_component', 0.0) * 0.6
            ])
            
            von_mises_factor = von_mises_dist.get('stress_amplification_factor', 1.0)
            return max(25.0, total * von_mises_factor)
            
        except Exception as e:
            self.logger.error(f"Total stress calculation failed: {e}")
            return 35.0

    async def _assess_overall_confidence(self, *confidence_values) -> float:
        """Assess overall confidence from individual component confidences"""
        try:
            valid_confidences = [c for c in confidence_values if isinstance(c, (int, float)) and 0 <= c <= 1]
            if not valid_confidences:
                return 0.65
            
            # Use harmonic mean for conservative confidence estimate
            harmonic_mean = len(valid_confidences) / sum(1/c for c in valid_confidences if c > 0)
            return min(0.92, max(0.50, harmonic_mean))
            
        except Exception as e:
            self.logger.error(f"Confidence assessment failed: {e}")
            return 0.70

