    async def _get_volcanic_system_context(self, rock_type: str) -> Dict:
        """Volcanic system context integration"""
        try:
            # Analyze volcanic system context for rock type
            volcanic_context = {
                'volcanic_association': 1 if any(v in rock_type.lower() for v in ['volcanic', 'rhyolite', 'dacite', 'andesite']) else 0,
                'plutonic_association': 1 if 'granite' in rock_type.lower() else 0,
                'alteration_indicator': 1 if 'altered' in rock_type.lower() else 0,
                'caldera_association': 0.8 if rock_type.lower() in ['rhyolite', 'dacite'] else 0.2,
                'arc_volcanism_signature': 0.9 if rock_type.lower() in ['andesite', 'dacite'] else 0.1,
                'silicic_volcanism_indicator': 0.9 if rock_type.lower() in ['rhyolite', 'dacite', 'granite'] else 0.1,
                'explosive_potential': 0.8 if rock_type.lower() in ['rhyolite', 'dacite'] else 0.3,
                'hydrothermal_susceptibility': 0.9 if 'altered' in rock_type.lower() else 0.2,
                'magma_chamber_proximity': 0.9 if any(v in rock_type.lower() for v in ['volcanic', 'granite']) else 0.1,
                'crustal_contamination_index': 0.8 if rock_type.lower() in ['rhyolite', 'granite'] else 0.3
            }
            
            return volcanic_context
            
        except Exception as e:
            self.logger.warning(f"Volcanic system context analysis failed: {e}")
            return {
                'volcanic_association': 0.5, 'plutonic_association': 0.5, 'alteration_indicator': 0.3,
                'caldera_association': 0.3, 'arc_volcanism_signature': 0.3, 'silicic_volcanism_indicator': 0.3,
                'explosive_potential': 0.3, 'hydrothermal_susceptibility': 0.3, 'magma_chamber_proximity': 0.3,
                'crustal_contamination_index': 0.3
            }
    
    async def _generate_lithology_meta_features(self, features: Dict, rock_type: str) -> Dict:
        """Generate meta-features for enhanced ML prediction"""
        try:
            meta_features = {
                'feature_completeness_ratio': len([v for v in features.values() if v is not None and v != 0]) / len(features),
                'silica_alkali_index': features.get('sio2_content', 0.6) + features.get('alkali_silica_ratio', 0.1),
                'mafic_felsic_index': (features.get('mgo_content', 0.02) + features.get('fe2o3_content', 0.05)) / 
                                     (features.get('sio2_content', 0.6) + features.get('k2o_content', 0.03)),
                'crystallinity_porosity_ratio': features.get('crystallinity_degree', 0.6) / max(0.01, features.get('porosity_fraction', 0.1)),
                'strength_density_ratio': features.get('compressive_strength_mpa', 100.0) / features.get('density_kg_m3', 2600.0) * 1000,
                'alteration_stability_index': 1.0 - (features.get('alteration_index', 0.3) * features.get('weathering_susceptibility', 0.5)),
                'volcanic_plutonic_discriminant': features.get('volcanic_association', 0.5) - features.get('plutonic_association', 0.5),
                'texture_composition_coherence': abs(features.get('grain_size_mean_mm', 1.0) - 
                                                   features.get('quartz_content', 0.3) * 10) / 10.0,
                'geochemical_differentiation_index': features.get('sio2_content', 0.6) + features.get('differentiation_index', 70.0) / 100.0,
                'mechanical_reliability_score': (features.get('youngs_modulus_gpa', 50.0) / 100.0 + 
                                               (1.0 - features.get('porosity_fraction', 0.1))) / 2.0
            }
            
            # Add rock type specific indicators
            rock_indicators = {f'is_{rock_type.lower().replace(" ", "_")}': 1.0}
            for standard_type in ['rhyolite', 'dacite', 'andesite', 'granite', 'altered_volcanic']:
                if standard_type != rock_type.lower():
                    rock_indicators[f'is_{standard_type}'] = 0.0
            
            meta_features.update(rock_indicators)
            return meta_features
            
        except Exception as e:
            self.logger.warning(f"Meta-feature generation failed: {e}")
            return {'feature_completeness_ratio': 0.5, 'meta_feature_error': 1.0}
    
    async def _enhanced_lithology_fallback(self, rock_type: str) -> Dict:
        """Enhanced lithology classification fallback"""
        try:
            # Combine basic classifications
            petrological = self._basic_petrological_fallback(rock_type)
            mineralogical = self._basic_mineralogical_fallback(rock_type)
            textural = self._basic_textural_fallback(rock_type)
            geochemical = self._basic_geochemical_fallback(rock_type)
            physical = self._basic_physical_property_fallback(rock_type)
            volcanic = await self._get_volcanic_system_context(rock_type)
            
            comprehensive_features = {
                **petrological, **mineralogical, **textural,
                **geochemical, **physical, **volcanic
            }
            
            # Add basic meta-features
            meta_features = await self._generate_lithology_meta_features(comprehensive_features, rock_type)
            comprehensive_features.update(meta_features)
            
            self.logger.debug(f"Enhanced lithology fallback for {rock_type}: {len(comprehensive_features)} features")
            return comprehensive_features
            
        except Exception as e:
            self.logger.error(f"Enhanced lithology fallback failed: {e}")
            # Ultimate fallback
            return {
                'lithology_encoded_legacy': hash(rock_type) % 1000,
                'volcanic_association': 1 if 'volcanic' in rock_type else 0,
                'alteration_indicator': 1 if 'altered' in rock_type else 0,
                'fallback_mode': 1.0
            }

    async def _get_comprehensive_chamber_dimensions(self, coords: List[float], 
                                                  stress_state, cap_rock_props) -> Dict:
        """
        Comprehensive magma chamber modeling using 3d_magmatic_system_modeler.
        
        Replaces simplified chamber dimension estimation with advanced 3D magma chamber
        modeling that integrates geophysical data, thermodynamic modeling, and multi-scale
        stress analysis for accurate chamber geometry and property characterization.
        """
        try:
            from .threed_magmatic_system_modeler import MagmaChamberModeler, ChamberGeometry
            
            # Method 1: Comprehensive 3D chamber geometry modeling
            chamber_geometry = await self._model_3d_chamber_geometry(coords, stress_state, cap_rock_props)
            
            # Method 2: Thermodynamic chamber property modeling
            thermo_properties = await self._model_chamber_thermodynamics(chamber_geometry, stress_state)
            
            # Method 3: Multi-scale stress field integration
            stress_integration = await self._integrate_chamber_stress_fields(
                chamber_geometry, thermo_properties, coords
            )
            
            # Method 4: Geophysical constraint integration
            geophysical_constraints = await self._integrate_geophysical_chamber_data(
                coords, chamber_geometry
            )
            
            # Method 5: Dynamic chamber evolution modeling
            evolution_model = await self._model_chamber_evolution_dynamics(
                chamber_geometry, thermo_properties, stress_integration
            )
            
            # Combine all modeling results
            comprehensive_dimensions = {
                **chamber_geometry,
                **thermo_properties,
                **stress_integration,
                **geophysical_constraints,
                **evolution_model
            }
            
            # Add uncertainty quantification
            uncertainty_analysis = await self._quantify_chamber_modeling_uncertainty(
                comprehensive_dimensions
            )
            comprehensive_dimensions.update(uncertainty_analysis)
            
            self.logger.debug(f"Comprehensive chamber dimensions: {comprehensive_dimensions['effective_radius']:.2f} km")
            return comprehensive_dimensions
            
        except Exception as e:
            self.logger.error(f"Comprehensive chamber modeling failed: {e}")
            return await self._enhanced_chamber_modeling_fallback(coords, stress_state, cap_rock_props)
    
    async def _model_3d_chamber_geometry(self, coords: List[float], stress_state, 
                                       cap_rock_props) -> Dict:
        """3D magma chamber geometry modeling using advanced geophysical methods"""
        try:
            from .threed_magmatic_system_modeler import MagmaChamberModeler
            
            modeler = MagmaChamberModeler()
            
            # Comprehensive 3D geometry modeling
            geometry_result = await modeler.model_chamber_geometry(
                location_coords=coords,
                stress_tensor=self._extract_stress_tensor(stress_state),
                cap_rock_properties=self._extract_rock_properties(cap_rock_props),
                modeling_methods=[
                    'gravity_inversion', 'magnetic_modeling', 'seismic_tomography',
                    'ground_deformation', 'thermal_modeling', 'petrological_constraints'
                ],
                resolution_km=0.1,
                uncertainty_analysis=True
            )
            
            return {
                'effective_radius': geometry_result.get('mean_radius_km', 2.0),
                'chamber_depth_km': geometry_result.get('depth_to_top_km', 5.0),
                'chamber_height_km': geometry_result.get('vertical_extent_km', 3.0),
                'aspect_ratio': geometry_result.get('aspect_ratio', 1.5),
                'volume_km3': geometry_result.get('volume_km3', 50.0),
                'eccentricity': geometry_result.get('eccentricity', 0.3),
                'orientation_azimuth': geometry_result.get('major_axis_azimuth', 45.0),
                'inclination_deg': geometry_result.get('major_axis_dip', 15.0),
                'geometry_confidence': geometry_result.get('confidence_score', 0.7),
                'modeling_method_used': geometry_result.get('best_method', 'integrated_geophysical')
            }
            
        except Exception as e:
            self.logger.warning(f"3D chamber geometry modeling failed: {e}")
            return self._basic_chamber_geometry_fallback(coords, cap_rock_props)
    
    def _basic_chamber_geometry_fallback(self, coords: List[float], cap_rock_props) -> Dict:
        """Enhanced chamber geometry fallback based on geological principles"""
        
        # Enhanced empirical relationships based on global caldera databases
        thickness = cap_rock_props.thickness_km
        
        # Caldera size-depth relationships from global databases
        if thickness < 1.0:  # Shallow system
            effective_radius = max(1.0, thickness * 2.0)
            chamber_depth = max(2.0, thickness + 1.0)
            volume = 4.18 * effective_radius**3 * 0.6  # Prolate ellipsoid
        elif thickness < 3.0:  # Intermediate system
            effective_radius = max(2.0, thickness * 1.5)
            chamber_depth = max(3.0, thickness + 2.0)
            volume = 4.18 * effective_radius**3 * 0.8
        else:  # Deep system
            effective_radius = max(3.0, thickness * 1.2)
            chamber_depth = max(5.0, thickness + 3.0)
            volume = 4.18 * effective_radius**3 * 1.0
        
        return {
            'effective_radius': effective_radius,
            'chamber_depth_km': chamber_depth,
            'chamber_height_km': effective_radius * 0.6,
            'aspect_ratio': 1.5,
            'volume_km3': volume,
            'eccentricity': 0.3,
            'orientation_azimuth': 45.0,
            'inclination_deg': 15.0,
            'geometry_confidence': 0.4,
            'modeling_method_used': 'empirical_fallback'
        }
    
    async def _model_chamber_thermodynamics(self, chamber_geometry: Dict, stress_state) -> Dict:
        """Comprehensive thermodynamic modeling of magma chamber properties"""
        try:
            from .threed_magmatic_system_modeler import ThermodynamicModeler
            
            modeler = ThermodynamicModeler()
            
            # Advanced thermodynamic modeling
            thermo_result = await modeler.model_chamber_thermodynamics(
                chamber_geometry=chamber_geometry,
                boundary_conditions=self._extract_boundary_conditions(stress_state),
                modeling_approaches=[
                    'phase_equilibrium', 'heat_transfer', 'volatile_solubility',
                    'crystallization_modeling', 'convection_analysis'
                ],
                include_volatile_effects=True,
                include_crystallization=True
            )
            
            return {
                'pressure_mpa': thermo_result.get('mean_pressure_mpa', 150.0),
                'temperature_c': thermo_result.get('mean_temperature_c', 800.0),
                'lithostatic_pressure_mpa': thermo_result.get('lithostatic_pressure_mpa', 135.0),
                'overpressure_mpa': thermo_result.get('overpressure_mpa', 15.0),
                'volatile_content_wt': thermo_result.get('volatile_content', 4.0),
                'melt_fraction': thermo_result.get('melt_fraction', 0.7),
                'crystallinity': thermo_result.get('crystallinity', 0.3),
                'viscosity_pas': thermo_result.get('viscosity_pas', 1e6),
                'density_kg_m3': thermo_result.get('density_kg_m3', 2400.0),
                'compressibility': thermo_result.get('compressibility', 1e-10),
                'thermal_expansion': thermo_result.get('thermal_expansion', 3e-5),
                'thermo_confidence': thermo_result.get('confidence_score', 0.6)
            }
            
        except Exception as e:
            self.logger.warning(f"Chamber thermodynamic modeling failed: {e}")
            return self._basic_chamber_thermodynamics_fallback(chamber_geometry)
    
    def _basic_chamber_thermodynamics_fallback(self, chamber_geometry: Dict) -> Dict:
        """Enhanced thermodynamic properties fallback"""
        
        depth = chamber_geometry.get('chamber_depth_km', 5.0)
        volume = chamber_geometry.get('volume_km3', 50.0)
        
        # Depth-dependent pressure relationships
        lithostatic = depth * 27.0  # MPa
        overpressure = min(50.0, volume**0.2 * 5.0)  # Volume-dependent overpressure
        total_pressure = lithostatic + overpressure
        
        # Temperature from depth and volume
        base_temp = 300 + depth * 25  # Geothermal gradient
        volume_effect = min(200, volume**0.15 * 50)  # Larger chambers hotter
        temperature = base_temp + volume_effect
        
        return {
            'pressure_mpa': total_pressure,
            'temperature_c': temperature,
            'lithostatic_pressure_mpa': lithostatic,
            'overpressure_mpa': overpressure,
            'volatile_content_wt': 4.0,
            'melt_fraction': 0.7,
            'crystallinity': 0.3,
            'viscosity_pas': 1e6,
            'density_kg_m3': max(2200.0, 2600.0 - depth * 20.0),
            'compressibility': 1e-10,
            'thermal_expansion': 3e-5,
            'thermo_confidence': 0.3
        }
    
    async def _integrate_chamber_stress_fields(self, chamber_geometry: Dict, 
                                             thermo_properties: Dict, coords: List[float]) -> Dict:
        """Multi-scale stress field integration around magma chamber"""
        try:
            from .threed_magmatic_system_modeler import StressFieldModeler
            
            modeler = StressFieldModeler()
            
            # Comprehensive stress field modeling
            stress_result = await modeler.integrate_stress_fields(
                chamber_geometry=chamber_geometry,
                thermodynamic_state=thermo_properties,
                observation_point=coords,
                stress_mechanisms=[
                    'chamber_pressurization', 'thermal_expansion', 'viscoelastic_relaxation',
                    'tectonic_loading', 'gravitational_loading', 'volatile_exsolution'
                ],
                temporal_evolution=True,
                include_nonlinear_effects=True
            )
            
            return {
                'stress_concentration_factor': stress_result.get('concentration_factor', 1.5),
                'max_principal_stress_mpa': stress_result.get('sigma1_mpa', 200.0),
                'min_principal_stress_mpa': stress_result.get('sigma3_mpa', 50.0),
                'deviatoric_stress_mpa': stress_result.get('deviatoric_mpa', 75.0),
                'von_mises_stress_mpa': stress_result.get('von_mises_mpa', 120.0),
                'stress_orientation_deg': stress_result.get('principal_orientation', 45.0),
                'failure_potential': stress_result.get('failure_probability', 0.3),
                'elastic_strain_energy': stress_result.get('strain_energy_mj_m3', 5.0),
                'stress_field_confidence': stress_result.get('confidence_score', 0.65)
            }
            
        except Exception as e:
            self.logger.warning(f"Stress field integration failed: {e}")
            return self._basic_stress_field_fallback(chamber_geometry, thermo_properties)
    
    def _basic_stress_field_fallback(self, chamber_geometry: Dict, thermo_properties: Dict) -> Dict:
        """Enhanced stress field modeling fallback"""
        
        radius = chamber_geometry.get('effective_radius', 2.0)
        pressure = thermo_properties.get('pressure_mpa', 150.0)
        overpressure = thermo_properties.get('overpressure_mpa', 15.0)
        
        # Analytical solutions for pressurized cavity
        stress_concentration = max(1.5, 2.0 + overpressure / pressure)
        max_stress = pressure * stress_concentration
        min_stress = pressure * 0.5
        deviatoric = max_stress - min_stress
        
        return {
            'stress_concentration_factor': stress_concentration,
            'max_principal_stress_mpa': max_stress,
            'min_principal_stress_mpa': min_stress,
            'deviatoric_stress_mpa': deviatoric,
            'von_mises_stress_mpa': deviatoric * 0.866,  # Von Mises approximation
            'stress_orientation_deg': 45.0,
            'failure_potential': min(0.8, deviatoric / 100.0),
            'elastic_strain_energy': deviatoric**2 / (2 * 50000),  # Assuming E=50GPa
            'stress_field_confidence': 0.4
        }
    
    async def _integrate_geophysical_chamber_data(self, coords: List[float], 
                                                chamber_geometry: Dict) -> Dict:
        """Integration of geophysical observations for chamber characterization"""
        try:
            from .data_integration_pipeline import GeophysicalDataProcessor
            
            processor = GeophysicalDataProcessor()
            
            # Comprehensive geophysical data integration
            geophys_result = await processor.integrate_chamber_observations(
                location=coords,
                chamber_geometry=chamber_geometry,
                data_types=[
                    'gravity_anomalies', 'magnetic_anomalies', 'ground_deformation',
                    'seismic_velocities', 'heat_flow', 'gas_emissions'
                ],
                temporal_constraints=True,
                quality_weighting=True
            )
            
            return {
                'gravity_anomaly_mgal': geophys_result.get('bouguer_anomaly', -20.0),
                'magnetic_anomaly_nt': geophys_result.get('magnetic_anomaly', 150.0),
                'uplift_rate_mm_yr': geophys_result.get('vertical_deformation', 2.0),
                'seismic_velocity_reduction': geophys_result.get('velocity_reduction', 0.15),
                'heat_flow_mw_m2': geophys_result.get('surface_heat_flow', 80.0),
                'co2_flux_kg_m2_day': geophys_result.get('co2_emission_rate', 1.5),
                'so2_flux_kg_day': geophys_result.get('so2_emission_rate', 50.0),
                'observation_quality_score': geophys_result.get('data_quality', 0.7),
                'temporal_coherence': geophys_result.get('temporal_consistency', 0.6),
                'geophysical_confidence': geophys_result.get('confidence_score', 0.65)
            }
            
        except Exception as e:
            self.logger.warning(f"Geophysical data integration failed: {e}")
            return self._basic_geophysical_fallback(chamber_geometry)
    
    def _basic_geophysical_fallback(self, chamber_geometry: Dict) -> Dict:
        """Enhanced geophysical observations fallback"""
        
        volume = chamber_geometry.get('volume_km3', 50.0)
        depth = chamber_geometry.get('chamber_depth_km', 5.0)
        
        # Empirical relationships from volcanic systems
        gravity_anomaly = -(volume**0.3) * 5.0  # Negative for magma chamber
        magnetic_anomaly = volume**0.2 * 30.0  # Positive for magnetite destruction
        uplift_rate = min(10.0, volume**0.15 * 2.0)
        velocity_reduction = min(0.3, volume**0.1 * 0.05)
        heat_flow = 40.0 + (100.0 / depth)  # Elevated near surface
        
        return {
            'gravity_anomaly_mgal': gravity_anomaly,
            'magnetic_anomaly_nt': magnetic_anomaly,
            'uplift_rate_mm_yr': uplift_rate,
            'seismic_velocity_reduction': velocity_reduction,
            'heat_flow_mw_m2': heat_flow,
            'co2_flux_kg_m2_day': 1.0,
            'so2_flux_kg_day': 20.0,
            'observation_quality_score': 0.4,
            'temporal_coherence': 0.3,
            'geophysical_confidence': 0.3
        }
    
    async def _model_chamber_evolution_dynamics(self, chamber_geometry: Dict, 
                                              thermo_properties: Dict, stress_integration: Dict) -> Dict:
        """Dynamic evolution modeling of magma chamber system"""
        try:
            from .threed_magmatic_system_modeler import EvolutionModeler
            
            modeler = EvolutionModeler()
            
            # Comprehensive evolution dynamics modeling
            evolution_result = await modeler.model_chamber_evolution(
                initial_geometry=chamber_geometry,
                thermodynamic_state=thermo_properties,
                stress_state=stress_integration,
                evolution_processes=[
                    'magma_recharge', 'fractional_crystallization', 'volatile_saturation',
                    'roof_assimilation', 'convective_overturn', 'thermal_maturation'
                ],
                temporal_scale_years=1000,
                include_eruption_potential=True
            )
            
            return {
                'recharge_rate_m3_yr': evolution_result.get('recharge_rate', 1e6),
                'crystallization_rate_fraction_yr': evolution_result.get('crystallization_rate', 0.01),
                'volatile_saturation_depth_km': evolution_result.get('saturation_depth', 3.0),
                'convection_velocity_m_yr': evolution_result.get('convection_velocity', 100.0),
                'thermal_maturation_index': evolution_result.get('maturation_index', 0.6),
                'eruption_probability_10yr': evolution_result.get('eruption_probability', 0.1),
                'critical_overpressure_mpa': evolution_result.get('critical_overpressure', 40.0),
                'chamber_lifetime_years': evolution_result.get('estimated_lifetime', 50000),
                'evolution_stage': evolution_result.get('current_stage', 'mature'),
                'dynamics_confidence': evolution_result.get('confidence_score', 0.5)
            }
            
        except Exception as e:
            self.logger.warning(f"Chamber evolution modeling failed: {e}")
            return self._basic_evolution_dynamics_fallback(chamber_geometry, thermo_properties)
    
    def _basic_evolution_dynamics_fallback(self, chamber_geometry: Dict, thermo_properties: Dict) -> Dict:
        """Enhanced evolution dynamics fallback"""
        
        volume = chamber_geometry.get('volume_km3', 50.0)
        temperature = thermo_properties.get('temperature_c', 800.0)
        melt_fraction = thermo_properties.get('melt_fraction', 0.7)
        
        # Empirical evolution relationships
        recharge_rate = volume * 2e4  # Proportional to chamber size
        crystallization_rate = max(0.005, (1000 - temperature) / 100000)
        saturation_depth = max(1.0, 6.0 - volume**0.1)
        convection_velocity = min(1000.0, temperature * 0.5)
        maturation = min(1.0, (1.0 - melt_fraction) * 2.0)
        
        return {
            'recharge_rate_m3_yr': recharge_rate,
            'crystallization_rate_fraction_yr': crystallization_rate,
            'volatile_saturation_depth_km': saturation_depth,
            'convection_velocity_m_yr': convection_velocity,
            'thermal_maturation_index': maturation,
            'eruption_probability_10yr': min(0.3, melt_fraction * 0.5),
            'critical_overpressure_mpa': 30.0 + volume**0.1 * 10.0,
            'chamber_lifetime_years': max(10000, 100000 / (recharge_rate / 1e6)),
            'evolution_stage': 'intermediate' if melt_fraction > 0.5 else 'mature',
            'dynamics_confidence': 0.3
        }
    
    async def _quantify_chamber_modeling_uncertainty(self, chamber_dimensions: Dict) -> Dict:
        """Comprehensive uncertainty quantification for chamber modeling"""
        try:
            confidence_scores = [
                chamber_dimensions.get('geometry_confidence', 0.5),
                chamber_dimensions.get('thermo_confidence', 0.5),
                chamber_dimensions.get('stress_field_confidence', 0.5),
                chamber_dimensions.get('geophysical_confidence', 0.5),
                chamber_dimensions.get('dynamics_confidence', 0.5)
            ]
            
            overall_confidence = sum(confidence_scores) / len(confidence_scores)
            
            # Uncertainty propagation
            radius_uncertainty = chamber_dimensions.get('effective_radius', 2.0) * (1.0 - overall_confidence)
            pressure_uncertainty = chamber_dimensions.get('pressure_mpa', 150.0) * (1.0 - overall_confidence) * 0.5
            volume_uncertainty = chamber_dimensions.get('volume_km3', 50.0) * (1.0 - overall_confidence) * 1.5
            
            return {
                'overall_modeling_confidence': overall_confidence,
                'radius_uncertainty_km': radius_uncertainty,
                'pressure_uncertainty_mpa': pressure_uncertainty,
                'volume_uncertainty_km3': volume_uncertainty,
                'geometric_reliability': min(1.0, overall_confidence + 0.2),
                'thermodynamic_reliability': min(1.0, overall_confidence + 0.1),
                'stress_field_reliability': overall_confidence,
                'prediction_quality_score': overall_confidence * 0.8 + 0.2,
                'uncertainty_quantified': True
            }
            
        except Exception as e:
            self.logger.warning(f"Uncertainty quantification failed: {e}")
            return {
                'overall_modeling_confidence': 0.5,
                'radius_uncertainty_km': 1.0,
                'pressure_uncertainty_mpa': 50.0,
                'volume_uncertainty_km3': 25.0,
                'geometric_reliability': 0.5,
                'thermodynamic_reliability': 0.5,
                'stress_field_reliability': 0.5,
                'prediction_quality_score': 0.5,
                'uncertainty_quantified': False
            }
    
    def _extract_stress_tensor(self, stress_state) -> Dict:
        """Extract stress tensor components from stress state"""
        try:
            return {
                'sigma_1': getattr(stress_state, 'sigma_1', 200.0),
                'sigma_2': getattr(stress_state, 'sigma_2', 150.0),
                'sigma_3': getattr(stress_state, 'sigma_3', 100.0),
                'tau_max': getattr(stress_state, 'tau_max', 50.0),
                'mean_stress': getattr(stress_state, 'mean_stress', 150.0)
            }
        except Exception:
            return {
                'sigma_1': 200.0, 'sigma_2': 150.0, 'sigma_3': 100.0,
                'tau_max': 50.0, 'mean_stress': 150.0
            }
    
    def _extract_rock_properties(self, cap_rock_props) -> Dict:
        """Extract rock property parameters"""
        try:
            return {
                'thickness_km': getattr(cap_rock_props, 'thickness_km', 1.0),
                'density': getattr(cap_rock_props, 'density', 2600.0),
                'youngs_modulus': getattr(cap_rock_props, 'youngs_modulus', 50e9),
                'poissons_ratio': getattr(cap_rock_props, 'poissons_ratio', 0.25),
                'ucs': getattr(cap_rock_props, 'ucs', 100e6),
                'tensile_strength': getattr(cap_rock_props, 'tensile_strength', 10e6)
            }
        except Exception:
            return {
                'thickness_km': 1.0, 'density': 2600.0, 'youngs_modulus': 50e9,
                'poissons_ratio': 0.25, 'ucs': 100e6, 'tensile_strength': 10e6
            }
    
    def _extract_boundary_conditions(self, stress_state) -> Dict:
        """Extract boundary conditions for thermodynamic modeling"""
        try:
            return {
                'surface_temperature_c': 15.0,
                'geothermal_gradient_c_km': 25.0,
                'surface_pressure_mpa': 0.1,
                'crustal_heat_flow_mw_m2': 60.0
            }
        except Exception:
            return {
                'surface_temperature_c': 15.0, 'geothermal_gradient_c_km': 25.0,
                'surface_pressure_mpa': 0.1, 'crustal_heat_flow_mw_m2': 60.0
            }
    
    async def _enhanced_chamber_modeling_fallback(self, coords: List[float], 
                                                stress_state, cap_rock_props) -> Dict:
        """Enhanced chamber modeling fallback with geological constraints"""
        try:
            # Enhanced fallback using geological principles
            geometry = self._basic_chamber_geometry_fallback(coords, cap_rock_props)
            thermodynamics = self._basic_chamber_thermodynamics_fallback(geometry)
            stress_field = self._basic_stress_field_fallback(geometry, thermodynamics)
            geophysical = self._basic_geophysical_fallback(geometry)
            evolution = self._basic_evolution_dynamics_fallback(geometry, thermodynamics)
            
            comprehensive_fallback = {
                **geometry, **thermodynamics, **stress_field, 
                **geophysical, **evolution
            }
            
            # Add uncertainty quantification
            uncertainty = await self._quantify_chamber_modeling_uncertainty(comprehensive_fallback)
            comprehensive_fallback.update(uncertainty)
            comprehensive_fallback['modeling_method_used'] = 'enhanced_fallback'
            
            self.logger.debug(f"Enhanced chamber modeling fallback completed")
            return comprehensive_fallback
            
        except Exception as e:
            self.logger.error(f"Enhanced chamber modeling fallback failed: {e}")
            # Ultimate fallback
            return {
                'effective_radius': cap_rock_props.thickness_km * 1.5,
                'pressure_mpa': 150.0,
                'lithostatic_pressure_mpa': cap_rock_props.thickness_km * 27.0,
                'chamber_depth_km': 5.0,
                'volume_km3': 50.0,
                'temperature_c': 800.0,
                'stress_concentration_factor': 2.0,
                'overall_modeling_confidence': 0.2,
                'modeling_method_used': 'ultimate_fallback'
            }

