    async def _ml_rf_volcanic_proximity_analysis(self, features: dict) -> dict:
        """Random Forest volcanic proximity analysis using model manager"""
        try:
            from .model_manager import ModelManager
            
            # Initialize model manager for Random Forest volcanic proximity
            model_manager = ModelManager()
            
            # Enhanced feature engineering for RF model
            rf_features = {
                **features,
                'tectonic_complexity': self._calculate_tectonic_complexity_features(features),
                'volcanic_hazard_index': self._calculate_volcanic_hazard_features(features),
                'spatial_correlations': self._calculate_spatial_correlation_features(features),
                'temporal_patterns': self._calculate_temporal_pattern_features(features),
                'geochemical_signatures': self._calculate_geochemical_signature_features(features)
            }
            
            # Random Forest ensemble with multiple model variants
            rf_models = [
                'volcanic_proximity_rf_standard',
                'volcanic_proximity_rf_depth_optimized', 
                'volcanic_proximity_rf_feature_selected',
                'volcanic_proximity_rf_balanced',
                'volcanic_proximity_rf_ensemble'
            ]
            
            predictions = []
            confidences = []
            
            for model_name in rf_models:
                try:
                    # Load or train RF model variant
                    model = await model_manager.get_or_create_model(
                        model_name, 
                        model_type='random_forest',
                        task_type='regression',
                        target_variable='volcanic_proximity'
                    )
                    
                    # Make prediction with uncertainty quantification
                    result = await model_manager.predict_with_uncertainty(
                        model_name, 
                        rf_features
                    )
                    
                    predictions.append(result['prediction'])
                    confidences.append(result['confidence'])
                    
                except Exception as model_e:
                    self.logger.warning(f"RF model {model_name} failed: {model_e}")
                    continue
            
            if predictions:
                # Ensemble RF predictions with confidence weighting
                weighted_pred = sum(p * c for p, c in zip(predictions, confidences)) / sum(confidences)
                ensemble_confidence = min(0.95, sum(confidences) / len(confidences))
                
                return {
                    'proximity': max(0.0, min(1.0, weighted_pred)),
                    'confidence': ensemble_confidence,
                    'method': 'rf_ensemble',
                    'n_models': len(predictions),
                    'model_variants': rf_models[:len(predictions)]
                }
            else:
                # RF fallback using simplified ensemble
                return await self._rf_fallback_volcanic_proximity(features)
                
        except Exception as e:
            self.logger.error(f"RF volcanic proximity analysis failed: {e}")
            return await self._rf_fallback_volcanic_proximity(features)
    
