    # Feature engineering methods for ML models
    def _calculate_tectonic_complexity_features(self, features: dict) -> dict:
        """Calculate tectonic complexity features for RF model"""
        try:
            plate_boundary_dist = features.get('plate_boundary_distance', 1.0)
            subduction_dist = features.get('subduction_zone_distance', 1.0)
            transform_dist = features.get('transform_fault_distance', 1.0)
            
            complexity_score = 1.0 / (1.0 + plate_boundary_dist + subduction_dist + transform_dist)
            interaction_factor = plate_boundary_dist * subduction_dist * transform_dist
            
            return {
                'complexity_score': complexity_score,
                'interaction_factor': interaction_factor,
                'boundary_density': 1.0 / (1.0 + min(plate_boundary_dist, subduction_dist, transform_dist)),
                'tectonic_stress_proxy': complexity_score * (2.0 - interaction_factor),
                'multi_boundary_influence': len([d for d in [plate_boundary_dist, subduction_dist, transform_dist] if d < 0.5])
            }
        except Exception as e:
            self.logger.warning(f"Tectonic complexity calculation failed: {e}")
            return {'complexity_score': 0.5, 'interaction_factor': 0.5, 'boundary_density': 0.5, 'tectonic_stress_proxy': 0.5, 'multi_boundary_influence': 0}
    
    def _calculate_volcanic_hazard_features(self, features: dict) -> dict:
        """Calculate volcanic hazard features for RF model"""
        try:
            pacific_dist = features.get('distance_to_pacific_rim', 1000)
            hotspot_dist = features.get('hotspot_distance', 1.0)
            thermal_anomaly = features.get('thermal_anomaly', 0.0)
            seismic_activity = features.get('seismic_activity_proxy', 0.0)
            
            hazard_index = (1.0 - pacific_dist / 1000.0) + (1.0 - hotspot_dist) + thermal_anomaly + seismic_activity
            
            return {
                'volcanic_hazard_index': max(0.0, min(4.0, hazard_index)),
                'ring_of_fire_proximity': max(0.0, 1.0 - pacific_dist / 2000.0),
                'hotspot_influence': max(0.0, 1.0 - hotspot_dist),
                'combined_thermal_seismic': thermal_anomaly * seismic_activity,
                'hazard_category': 'high' if hazard_index > 2.0 else 'medium' if hazard_index > 1.0 else 'low'
            }
        except Exception as e:
            self.logger.warning(f"Volcanic hazard calculation failed: {e}")
            return {'volcanic_hazard_index': 1.0, 'ring_of_fire_proximity': 0.5, 'hotspot_influence': 0.5, 'combined_thermal_seismic': 0.25, 'hazard_category': 'medium'}
    
    def _calculate_spatial_correlation_features(self, features: dict) -> dict:
        """Calculate spatial correlation features"""
        try:
            lat = features.get('latitude', 0)
            lon = features.get('longitude', 0)
            elevation = features.get('elevation_proxy', 0)
            
            return {
                'lat_lon_product': lat * lon,
                'elevation_lat_correlation': elevation * abs(lat),
                'longitude_quadrant': 1 if lon > 0 else -1,
                'latitude_hemisphere': 1 if lat > 0 else -1,
                'distance_from_equator': abs(lat),
                'distance_from_prime_meridian': abs(lon)
            }
        except Exception as e:
            self.logger.warning(f"Spatial correlation calculation failed: {e}")
            return {'lat_lon_product': 0, 'elevation_lat_correlation': 0, 'longitude_quadrant': 0, 'latitude_hemisphere': 0, 'distance_from_equator': 0, 'distance_from_prime_meridian': 0}
    
