    async def _model_subsurface_temperatures(self, lat: float, lon: float, coords: Dict[str, Any]) -> float:
        """Model subsurface temperatures using geophysical data"""
        try:
            # Use geophysical data for subsurface temperature modeling
            subsurface_data = await self.data_integration.query_subsurface_data({
                'location': {'lat': lat, 'lon': lon},
                'depth_range': [0, 10000],  # 0-10km depth
                'data_types': ['temperature_logs', 'geothermal_wells', 'thermal_modeling']
            })
            
            if subsurface_data and 'temperature_profiles' in subsurface_data:
                profiles = subsurface_data['temperature_profiles']
                
                # Calculate thermal anomaly from subsurface temperatures
                thermal_scores = []
                for profile in profiles:
                    if 'temperature_k' in profile and 'depth_m' in profile:
                        temp = profile['temperature_k']
                        depth = profile['depth_m']
                        
                        # Expected temperature at depth (geothermal gradient)
                        expected_temp = 288 + (depth / 1000) * 25  # 25 K/km gradient
                        
                        # Calculate thermal anomaly
                        temp_anomaly = (temp - expected_temp) / expected_temp
                        thermal_score = max(0.0, min(1.0, temp_anomaly * 0.5 + 0.5))
                        thermal_scores.append(thermal_score)
                
                if thermal_scores:
                    return np.mean(thermal_scores)
            
            return await self._subsurface_thermal_fallback(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Subsurface temperature modeling failed: {e}")
            return await self._subsurface_thermal_fallback(lat, lon)
    
    async def _thermal_fallback_analysis(self, lat: float, lon: float, coords: Dict[str, Any]) -> float:
        """Enhanced fallback thermal analysis with geological context"""
        try:
            # Use existing methods with enhanced geological context
            volcanic_proximity = await self._estimate_volcanic_proximity(lat, lon)
            
            # Enhanced ridge thermal analysis
            ridge_distance = self._calculate_ridge_distance(lat, lon)
            ridge_thermal = max(0.0, 1.0 - ridge_distance / 1000) * 0.6
            
            # Hotspot proximity thermal analysis
            hotspots = [
                {'lat': 19.4, 'lon': -155.6, 'name': 'Hawaii', 'thermal_intensity': 0.9},
                {'lat': 64.4, 'lon': -17.3, 'name': 'Iceland', 'thermal_intensity': 0.8},
                {'lat': -37.8, 'lon': 77.5, 'name': 'Kerguelen', 'thermal_intensity': 0.7},
                {'lat': -21.1, 'lon': 55.5, 'name': 'Reunion', 'thermal_intensity': 0.8},
                {'lat': 14.0, 'lon': -24.3, 'name': 'Cape Verde', 'thermal_intensity': 0.6}
            ]
            
            hotspot_thermal = 0.0
            for hotspot in hotspots:
                distance = self._calculate_great_circle_distance(
                    lat, lon, hotspot['lat'], hotspot['lon']
                )
                if distance < 1000:  # Within 1000km
                    thermal_influence = hotspot['thermal_intensity'] * (1.0 - distance / 1000)
                    hotspot_thermal = max(hotspot_thermal, thermal_influence)
            
            # Combine thermal sources
            thermal_score = max(volcanic_proximity * 0.5, ridge_thermal, hotspot_thermal * 0.4)
            
            return min(1.0, max(0.0, thermal_score))
            
        except Exception as e:
            self.logger.error(f"Enhanced thermal fallback failed: {e}")
            return 0.3  # Conservative thermal estimate
    
    async def _identify_volcanic_heat_sources(self, lat: float, lon: float) -> float:
        """Identify volcanic heat sources in the region"""
        try:
            volcanic_features = await self._query_volcanic_database(lat, lon, 50)
            
            thermal_score = 0.0
            if volcanic_features:
                for feature in volcanic_features:
                    if feature.get('thermal_state') == 'active':
                        distance = feature.get('distance_km', 100)
                        thermal_influence = max(0.0, 1.0 - distance / 100) * 0.8
                        thermal_score = max(thermal_score, thermal_influence)
                    elif feature.get('thermal_state') == 'dormant':
                        distance = feature.get('distance_km', 100) 
                        thermal_influence = max(0.0, 1.0 - distance / 200) * 0.4
                        thermal_score = max(thermal_score, thermal_influence)
            
            return thermal_score
            
        except Exception as e:
            self.logger.error(f"Volcanic heat source identification failed: {e}")
            return 0.2
    
