    async def _measure_ground_thermal_anomalies(self, lat: float, lon: float) -> float:
        """Measure ground thermal anomalies"""
        try:
            ground_thermal_data = await self.data_integration.query_database({
                'data_type': 'ground_temperature',
                'location': {'lat': lat, 'lon': lon},
                'radius_km': 10,
                'temporal_range': '1_month'
            })
            
            if ground_thermal_data and 'measurements' in ground_thermal_data:
                measurements = ground_thermal_data['measurements']
                
                temperatures = [m['temperature_c'] for m in measurements if 'temperature_c' in m]
                if temperatures:
                    mean_temp = np.mean(temperatures)
                    background_temp = 15.0  # Typical ground temperature
                    
                    temp_anomaly = (mean_temp - background_temp) / background_temp
                    thermal_score = max(0.0, min(1.0, temp_anomaly * 2 + 0.5))
                    return thermal_score
            
            return 0.1  # Background ground thermal
            
        except Exception as e:
            self.logger.error(f"Ground thermal measurement failed: {e}")
            return 0.1
    
