    async def _extract_wovo_volcano_list(self, comprehensive_data: Dict[str, Any], lat: float, lon: float) -> List[Dict[str, Any]]:
        """Extract comprehensive volcano list from WOVO data"""
        try:
            volcano_list = []
            
            # Extract volcanoes from different data sources
            sources = [
                comprehensive_data.get('monitoring_network', {}),
                comprehensive_data.get('alert_systems', {}),
                comprehensive_data.get('historical_eruptions', {}),
                comprehensive_data.get('hazard_assessments', {})
            ]
            
            # Combine volcano information from all sources
            volcano_registry = {}
            
            for source in sources:
                if 'volcanoes' in source:
                    for volcano in source['volcanoes']:
                        volcano_id = volcano.get('id') or volcano.get('name', 'unknown')
                        
                        if volcano_id not in volcano_registry:
                            volcano_registry[volcano_id] = {
                                'id': volcano_id,
                                'name': volcano.get('name', ''),
                                'latitude': volcano.get('latitude', lat),
                                'longitude': volcano.get('longitude', lon),
                                'elevation_m': volcano.get('elevation_m', 0),
                                'volcano_type': volcano.get('type', 'unknown'),
                                'tectonic_setting': volcano.get('tectonic_setting', 'unknown'),
                                'activity_status': volcano.get('activity_status', 'unknown'),
                                'last_eruption': volcano.get('last_eruption', None),
                                'monitoring_level': volcano.get('monitoring_level', 'none'),
                                'alert_level': volcano.get('alert_level', 'normal'),
                                'hazard_ranking': volcano.get('hazard_ranking', 0),
                                'data_sources': [],
                                'distance_km': self._calculate_great_circle_distance(
                                    lat, lon, 
                                    volcano.get('latitude', lat), 
                                    volcano.get('longitude', lon)
                                )
                            }
                        
                        # Add data source information
                        source_info = {
                            'source_type': source.get('source_type', 'unknown'),
                            'last_update': source.get('last_update', None),
                            'data_quality': source.get('data_quality', 'unknown')
                        }
                        volcano_registry[volcano_id]['data_sources'].append(source_info)
            
            # Convert registry to list and sort by distance
            volcano_list = list(volcano_registry.values())
            volcano_list.sort(key=lambda x: x['distance_km'])
            
            # Limit to reasonable number of volcanoes
            return volcano_list[:50]  # Top 50 closest volcanoes
            
        except Exception as e:
            self.logger.error(f"WOVO volcano list extraction failed: {e}")
            return await self._extract_volcano_fallback(lat, lon)
    
