    # Supporting methods for WOVO integration
    async def _assess_wovo_data_quality(self, monitoring_data: Dict, alert_data: Dict, 
                                       historical_data: Dict, hazard_data: Dict, 
                                       coordination_data: Dict) -> Dict[str, float]:
        """Assess quality of WOVO data from different sources"""
        try:
            quality_scores = {
                'monitoring_network': 0.5,
                'alert_systems': 0.5,
                'historical_eruptions': 0.5,
                'hazard_assessments': 0.5,
                'observatory_coordination': 0.5
            }
            
            # Assess monitoring network data quality
            if monitoring_data and 'active_stations' in monitoring_data:
                station_count = len(monitoring_data['active_stations'])
                quality_scores['monitoring_network'] = min(1.0, station_count / 10)
            
            # Assess alert systems data quality
            if alert_data and 'current_alerts' in alert_data:
                alert_coverage = len(alert_data.get('observatory_networks', []))
                quality_scores['alert_systems'] = min(1.0, alert_coverage / 5)
            
            # Assess historical data quality
            if historical_data and 'eruption_catalog' in historical_data:
                eruption_count = len(historical_data['eruption_catalog'])
                quality_scores['historical_eruptions'] = min(1.0, eruption_count / 20)
            
            # Assess hazard data quality
            if hazard_data and 'hazard_maps' in hazard_data:
                hazard_coverage = len(hazard_data['hazard_maps'])
                quality_scores['hazard_assessments'] = min(1.0, hazard_coverage / 5)
            
            # Assess coordination data quality
            if coordination_data and 'participating_observatories' in coordination_data:
                observatory_count = len(coordination_data['participating_observatories'])
                quality_scores['observatory_coordination'] = min(1.0, observatory_count / 3)
            
            # Calculate overall quality score
            quality_scores['overall'] = np.mean(list(quality_scores.values()))
            
            return quality_scores
            
        except Exception as e:
            self.logger.error(f"WOVO data quality assessment failed: {e}")
            return {'overall': 0.3, 'error': str(e)}
    
    async def _assess_wovo_coverage(self, lat: float, lon: float) -> Dict[str, Any]:
        """Assess WOVO database coverage for the query location"""
        try:
            coverage_assessment = {
                'geographic_coverage': 'regional',
                'temporal_coverage': 'historical',
                'data_completeness': 0.5,
                'monitoring_density': 'moderate',
                'update_frequency': 'weekly'
            }
            
            # Assess geographic coverage based on known WOVO observatory locations
            wovo_observatories = [
                {'lat': 46.20, 'lon': -122.18, 'name': 'CVO'},  # Cascades Volcano Observatory
                {'lat': 19.42, 'lon': -155.29, 'name': 'HVO'},  # Hawaiian Volcano Observatory
                {'lat': 58.30, 'lon': -155.00, 'name': 'AVO'},  # Alaska Volcano Observatory
                {'lat': 40.82, 'lon': 14.43, 'name': 'INGV'},  # Italy
                {'lat': 35.35, 'lon': 138.73, 'name': 'JMA'}   # Japan
            ]
            
            # Find closest observatory
            min_distance = float('inf')
            closest_observatory = None
            
            for obs in wovo_observatories:
                distance = self._calculate_great_circle_distance(lat, lon, obs['lat'], obs['lon'])
                if distance < min_distance:
                    min_distance = distance
                    closest_observatory = obs
            
            # Adjust coverage assessment based on distance to observatories
            if min_distance < 200:
                coverage_assessment['geographic_coverage'] = 'excellent'
                coverage_assessment['monitoring_density'] = 'high'
                coverage_assessment['data_completeness'] = 0.9
            elif min_distance < 500:
                coverage_assessment['geographic_coverage'] = 'good'
                coverage_assessment['monitoring_density'] = 'moderate'
                coverage_assessment['data_completeness'] = 0.7
            elif min_distance < 1000:
                coverage_assessment['geographic_coverage'] = 'fair'
                coverage_assessment['monitoring_density'] = 'low'
                coverage_assessment['data_completeness'] = 0.4
            else:
                coverage_assessment['geographic_coverage'] = 'limited'
                coverage_assessment['monitoring_density'] = 'sparse'
                coverage_assessment['data_completeness'] = 0.2
            
            coverage_assessment['closest_observatory'] = closest_observatory
            coverage_assessment['distance_to_observatory_km'] = min_distance
            
            return coverage_assessment
            
        except Exception as e:
            self.logger.error(f"WOVO coverage assessment failed: {e}")
            return {'geographic_coverage': 'unknown', 'error': str(e)}
    
