    async def _fracture_mechanics_fallback(self, cap_rock_props: CapRockProperties, 
                                         coords: List[float]) -> float:
        """Enhanced fallback for fracture mechanics"""
        try:
            # Physics-based fallback calculation
            fracture_density = cap_rock_props.fracture_density_per_m3
            if fracture_density > 0:
                spacing = (1.0 / fracture_density)**(1/3)
                base_length = spacing * 0.15
            else:
                base_length = 0.01  # 1 cm
            
            # Rock property adjustments
            porosity = cap_rock_props.porosity
            grain_factor = max(0.5, 1.0 + porosity * 2)
            
            thermal_expansion = cap_rock_props.thermal_expansion_per_k
            thermal_factor = 1.0 + thermal_expansion * 1e5
            
            final_length = base_length * grain_factor * thermal_factor
            
            return min(1.0, max(1e-4, final_length))
        except Exception:
            return 0.01  # 1 cm ultimate fallback

