    async def _calculate_comprehensive_dynamic_loading_frequency(self, coords: List[float] = None) -> float:
        """Comprehensive dynamic loading frequency analysis using volcano modules and advanced geophysical modeling"""
        try:
            if not coords or len(coords) < 2:
                coords = [0.0, 0.0, 1.0]  # Default coordinates with 1 km depth
            
            # Initialize comprehensive dynamic loading analysis ensemble
            loading_methods = [
                self._analyze_volcanic_dynamic_loading,
                self._model_magma_chamber_dynamics,
                self._calculate_tectonic_loading_frequency,
                self._analyze_hydrothermal_system_dynamics,
                self._predict_loading_frequency_ml
            ]
            
            method_names = ['volcanic_dynamics', 'magma_chamber', 'tectonic_loading', 
                          'hydrothermal_dynamics', 'ml_prediction']
            
            loading_results = []
            
            # Execute all methods with enhanced error handling
            for method, name in zip(loading_methods, method_names):
                try:
                    result = await method(coords)
                    if result and isinstance(result, dict) and 'loading_frequency' in result:
                        result['method'] = name
                        loading_results.append(result)
                except Exception as e:
                    self.logger.warning(f"Dynamic loading method {name} failed: {e}")
                    # Enhanced fallback for each method
                    fallback_result = await self._dynamic_loading_fallback(coords, name)
                    if fallback_result:
                        loading_results.append(fallback_result)
            
            if not loading_results:
                return await self._comprehensive_loading_fallback(coords)
            
            # Ensemble analysis with uncertainty quantification
            frequencies = [r['loading_frequency'] for r in loading_results if 'loading_frequency' in r]
            confidences = [r.get('confidence', 0.5) for r in loading_results]
            loading_types = [r.get('dominant_loading_type', 'mixed') for r in loading_results]
            
            if not frequencies:
                return await self._comprehensive_loading_fallback(coords)
            
            # Multi-scale frequency analysis
            frequency_scales = self._analyze_frequency_scales(loading_results)
            
            # Weighted ensemble with frequency scale considerations
            weighted_frequencies = []
            for freq, conf, result in zip(frequencies, confidences, loading_results):
                # Scale weighting based on volcanic proximity and loading type
                scale_weight = self._calculate_scale_weight(result.get('dominant_loading_type', 'mixed'), coords)
                total_weight = conf * scale_weight
                weighted_frequencies.append((freq, total_weight))
            
            # Calculate ensemble frequency
            total_weight = sum(weight for _, weight in weighted_frequencies)
            if total_weight > 0:
                ensemble_frequency = sum(freq * weight for freq, weight in weighted_frequencies) / total_weight
            else:
                ensemble_frequency = np.median(frequencies)
            
            # Apply uncertainty and conservatism
            frequency_std = np.std(frequencies) if len(frequencies) > 1 else ensemble_frequency * 0.1
            conservative_factor = 1.2  # Conservative estimate for safety
            final_frequency = ensemble_frequency * conservative_factor
            
            # Ensure physically reasonable bounds
            final_frequency = max(0.001, min(100.0, final_frequency))  # 1 mHz to 100 Hz
            
            self.logger.debug(f"Comprehensive dynamic loading frequency: {final_frequency:.3f} Hz "
                            f"(ensemble of {len(loading_results)} methods, scales: {frequency_scales})")
            
            return float(final_frequency)
            
        except Exception as e:
            self.logger.error(f"Comprehensive dynamic loading frequency analysis failed: {e}")
            return await self._comprehensive_loading_fallback(coords)

    async def _analyze_volcanic_dynamic_loading(self, coords: List[float]) -> Dict[str, float]:
        """Analyze volcanic dynamic loading using volcano modules and real-time monitoring data"""
        try:
            if not hasattr(self, 'volcano_modules'):
                return await self._volcanic_loading_fallback(coords)
            
            # Get comprehensive volcanic dynamics data
            volcanic_dynamics = await self.volcano_modules.analyze_dynamic_processes(
                coords[0], coords[1], depth_km=abs(coords[2]) if len(coords) > 2 else 1.0)
            
            if not volcanic_dynamics:
                return await self._volcanic_loading_fallback(coords)
            
            loading_frequencies = []
            
            # 1. Magma convection dynamics
            if 'convection_analysis' in volcanic_dynamics:
                convection = volcanic_dynamics['convection_analysis']
                if 'convection_frequency_hz' in convection and convection['convection_frequency_hz'] > 0:
                    loading_frequencies.append({
                        'frequency': convection['convection_frequency_hz'],
                        'amplitude': convection.get('convection_intensity', 1.0),
                        'type': 'magma_convection',
                        'confidence': convection.get('analysis_confidence', 0.7)
                    })
            
            # 2. Volatile exsolution dynamics
            if 'volatile_analysis' in volcanic_dynamics:
                volatiles = volcanic_dynamics['volatile_analysis']
                if 'bubble_nucleation_frequency_hz' in volatiles:
                    loading_frequencies.append({
                        'frequency': volatiles['bubble_nucleation_frequency_hz'],
                        'amplitude': volatiles.get('volatile_pressure_mpa', 10.0) / 10.0,
                        'type': 'volatile_exsolution',
                        'confidence': volatiles.get('volatile_confidence', 0.6)
                    })
            
            # 3. Conduit flow dynamics
            if 'conduit_flow' in volcanic_dynamics:
                flow = volcanic_dynamics['conduit_flow']
                if 'flow_oscillation_frequency_hz' in flow:
                    loading_frequencies.append({
                        'frequency': flow['flow_oscillation_frequency_hz'],
                        'amplitude': flow.get('flow_rate_kg_s', 1000.0) / 1000.0,
                        'type': 'conduit_flow',
                        'confidence': flow.get('flow_confidence', 0.75)
                    })
            
            # 4. Degassing dynamics
            if 'degassing_analysis' in volcanic_dynamics:
                degassing = volcanic_dynamics['degassing_analysis']
                if 'degassing_frequency_hz' in degassing:
                    loading_frequencies.append({
                        'frequency': degassing['degassing_frequency_hz'],
                        'amplitude': degassing.get('gas_flux_kg_s', 10.0) / 10.0,
                        'type': 'degassing',
                        'confidence': degassing.get('degassing_confidence', 0.65)
                    })
            
            if not loading_frequencies:
                return await self._volcanic_loading_fallback(coords)
            
            # Multi-frequency ensemble analysis
            weighted_frequencies = []
            total_amplitude = sum(lf['amplitude'] for lf in loading_frequencies)
            
            for lf in loading_frequencies:
                # Weight by amplitude and confidence
                amplitude_weight = lf['amplitude'] / total_amplitude if total_amplitude > 0 else 1.0
                total_weight = amplitude_weight * lf['confidence']
                weighted_frequencies.append(lf['frequency'] * total_weight)
            
            # Calculate ensemble frequency
            if weighted_frequencies:
                ensemble_frequency = sum(weighted_frequencies)
                dominant_type = max(loading_frequencies, key=lambda x: x['amplitude'] * x['confidence'])['type']
                ensemble_confidence = np.mean([lf['confidence'] for lf in loading_frequencies])
            else:
                return await self._volcanic_loading_fallback(coords)
            
            return {
                'loading_frequency': float(ensemble_frequency),
                'confidence': float(ensemble_confidence),
                'dominant_loading_type': dominant_type,
                'frequency_components': len(loading_frequencies),
                'analysis_method': 'volcanic_dynamics_ensemble'
            }
            
        except Exception as e:
            self.logger.warning(f"Volcanic dynamic loading analysis failed: {e}")
            return await self._volcanic_loading_fallback(coords)

    async def _model_magma_chamber_dynamics(self, coords: List[float]) -> Dict[str, float]:
        """Model magma chamber dynamics using 3D magmatic system modeler"""
        try:
            if not hasattr(self, '3d_magmatic_system_modeler'):
                return await self._chamber_dynamics_fallback(coords)
            
            # Get comprehensive magma chamber dynamics
            chamber_dynamics = await getattr(self, '3d_magmatic_system_modeler').model_chamber_dynamics(
                coords[0], coords[1], depth_km=abs(coords[2]) if len(coords) > 2 else 1.0,
                analysis_types=['pressure_oscillations', 'thermal_convection', 'crystallization_dynamics', 
                              'volatile_dynamics', 'chamber_resonance'])
            
            if not chamber_dynamics:
                return await self._chamber_dynamics_fallback(coords)
            
            chamber_frequencies = []
            
            # 1. Pressure oscillation frequencies
            if 'pressure_oscillations' in chamber_dynamics:
                pressure_osc = chamber_dynamics['pressure_oscillations']
                for oscillation in pressure_osc.get('oscillation_modes', []):
                    if 'frequency_hz' in oscillation and oscillation['frequency_hz'] > 0:
                        chamber_frequencies.append({
                            'frequency': oscillation['frequency_hz'],
                            'amplitude': oscillation.get('pressure_amplitude_pa', 1000.0) / 1000.0,
                            'type': 'pressure_oscillation',
                            'mode': oscillation.get('mode_type', 'fundamental'),
                            'confidence': oscillation.get('confidence', 0.7)
                        })
            
            # 2. Thermal convection frequencies
            if 'thermal_convection' in chamber_dynamics:
                convection = chamber_dynamics['thermal_convection']
                convection_cells = convection.get('convection_cells', [])
                for cell in convection_cells:
                    if 'turnover_frequency_hz' in cell:
                        chamber_frequencies.append({
                            'frequency': cell['turnover_frequency_hz'],
                            'amplitude': cell.get('convection_velocity_m_s', 0.01) * 100,  # Normalize
                            'type': 'thermal_convection',
                            'confidence': cell.get('cell_confidence', 0.65)
                        })
            
            # 3. Crystallization dynamics
            if 'crystallization_dynamics' in chamber_dynamics:
                crystallization = chamber_dynamics['crystallization_dynamics']
                if 'nucleation_frequency_hz' in crystallization:
                    chamber_frequencies.append({
                        'frequency': crystallization['nucleation_frequency_hz'],
                        'amplitude': crystallization.get('nucleation_rate_m3_s', 1e-6) * 1e6,
                        'type': 'crystallization',
                        'confidence': crystallization.get('crystallization_confidence', 0.6)
                    })
            
            # 4. Chamber resonance frequencies
            if 'chamber_resonance' in chamber_dynamics:
                resonance = chamber_dynamics['chamber_resonance']
                resonance_modes = resonance.get('resonance_modes', [])
                for mode in resonance_modes:
                    if 'resonance_frequency_hz' in mode:
                        chamber_frequencies.append({
                            'frequency': mode['resonance_frequency_hz'],
                            'amplitude': mode.get('q_factor', 100.0) / 100.0,
                            'type': 'chamber_resonance',
                            'mode': mode.get('mode_number', 1),
                            'confidence': mode.get('resonance_confidence', 0.8)
                        })
            
            if not chamber_frequencies:
                return await self._chamber_dynamics_fallback(coords)
            
            # Ensemble chamber dynamics analysis
            frequencies = [cf['frequency'] for cf in chamber_frequencies]
            amplitudes = [cf['amplitude'] for cf in chamber_frequencies]
            confidences = [cf['confidence'] for cf in chamber_frequencies]
            
            # Multi-modal frequency analysis
            fundamental_frequencies = [cf for cf in chamber_frequencies 
                                     if cf.get('mode', 'fundamental') == 'fundamental' or cf.get('mode_number', 1) == 1]
            
            if fundamental_frequencies:
                # Use fundamental modes as primary
                primary_frequency = np.average([ff['frequency'] for ff in fundamental_frequencies],
                                             weights=[ff['confidence'] for ff in fundamental_frequencies])
            else:
                # Use all frequencies
                primary_frequency = np.average(frequencies, weights=confidences)
            
            # Dominant loading type
            type_counts = {}
            for cf in chamber_frequencies:
                cf_type = cf['type']
                if cf_type in type_counts:
                    type_counts[cf_type] += cf['confidence'] * cf['amplitude']
                else:
                    type_counts[cf_type] = cf['confidence'] * cf['amplitude']
            
            dominant_type = max(type_counts.keys(), key=lambda k: type_counts[k]) if type_counts else 'chamber_mixed'
            ensemble_confidence = np.mean(confidences)
            
            return {
                'loading_frequency': float(primary_frequency),
                'confidence': float(ensemble_confidence),
                'dominant_loading_type': dominant_type,
                'frequency_modes': len(chamber_frequencies),
                'analysis_method': 'magma_chamber_dynamics'
            }
            
        except Exception as e:
            self.logger.warning(f"Magma chamber dynamics modeling failed: {e}")
            return await self._chamber_dynamics_fallback(coords)

    async def _calculate_tectonic_loading_frequency(self, coords: List[float]) -> Dict[str, float]:
        """Calculate tectonic loading frequency using data integration pipeline"""
        try:
            if not hasattr(self, 'data_integration_pipeline'):
                return await self._tectonic_loading_fallback(coords)
            
            # Get comprehensive tectonic loading data
            tectonic_data = await self.data_integration_pipeline.query_tectonic_loading(
                coords[0], coords[1], radius_km=50.0,
                data_types=['seismic_activity', 'plate_motion', 'stress_changes', 'fault_dynamics'])
            
            if not tectonic_data:
                return await self._tectonic_loading_fallback(coords)
            
            tectonic_frequencies = []
            
            # 1. Seismic loading frequencies
            if 'seismic_activity' in tectonic_data:
                seismic = tectonic_data['seismic_activity']
                
                # Earthquake cycle frequencies
                if 'earthquake_cycles' in seismic:
                    for cycle in seismic['earthquake_cycles']:
                        if 'cycle_frequency_hz' in cycle and cycle['cycle_frequency_hz'] > 0:
                            tectonic_frequencies.append({
                                'frequency': cycle['cycle_frequency_hz'],
                                'amplitude': cycle.get('magnitude_range', 2.0),
                                'type': 'earthquake_cycle',
                                'confidence': cycle.get('cycle_confidence', 0.6)
                            })
                
                # Aftershock sequences
                if 'aftershock_sequences' in seismic:
                    for sequence in seismic['aftershock_sequences']:
                        if 'decay_frequency_hz' in sequence:
                            tectonic_frequencies.append({
                                'frequency': sequence['decay_frequency_hz'],
                                'amplitude': sequence.get('sequence_magnitude', 1.0),
                                'type': 'aftershock_sequence',
                                'confidence': sequence.get('sequence_confidence', 0.5)
                            })
            
            # 2. Plate motion loading
            if 'plate_motion' in tectonic_data:
                plate_motion = tectonic_data['plate_motion']
                if 'motion_frequency_hz' in plate_motion and plate_motion['motion_frequency_hz'] > 0:
                    tectonic_frequencies.append({
                        'frequency': plate_motion['motion_frequency_hz'],
                        'amplitude': plate_motion.get('velocity_mm_yr', 10.0) / 10.0,
                        'type': 'plate_motion',
                        'confidence': plate_motion.get('motion_confidence', 0.7)
                    })
            
            # 3. Stress change frequencies
            if 'stress_changes' in tectonic_data:
                stress = tectonic_data['stress_changes']
                stress_cycles = stress.get('stress_cycles', [])
                for cycle in stress_cycles:
                    if 'stress_frequency_hz' in cycle:
                        tectonic_frequencies.append({
                            'frequency': cycle['stress_frequency_hz'],
                            'amplitude': cycle.get('stress_amplitude_mpa', 1.0),
                            'type': 'stress_cycle',
                            'confidence': cycle.get('stress_confidence', 0.65)
                        })
            
            # 4. Fault dynamics
            if 'fault_dynamics' in tectonic_data:
                faults = tectonic_data['fault_dynamics']
                for fault in faults.get('active_faults', []):
                    if 'fault_loading_frequency_hz' in fault:
                        tectonic_frequencies.append({
                            'frequency': fault['fault_loading_frequency_hz'],
                            'amplitude': fault.get('slip_rate_mm_yr', 1.0),
                            'type': 'fault_loading',
                            'confidence': fault.get('fault_confidence', 0.6)
                        })
            
            if not tectonic_frequencies:
                return await self._tectonic_loading_fallback(coords)
            
            # Tectonic frequency ensemble
            frequencies = [tf['frequency'] for tf in tectonic_frequencies]
            weights = [tf['confidence'] * tf['amplitude'] for tf in tectonic_frequencies]
            
            if frequencies and weights:
                weighted_frequency = np.average(frequencies, weights=weights)
                ensemble_confidence = np.mean([tf['confidence'] for tf in tectonic_frequencies])
                
                # Determine dominant tectonic loading type
                type_weights = {}
                for tf in tectonic_frequencies:
                    tf_type = tf['type']
                    if tf_type in type_weights:
                        type_weights[tf_type] += tf['confidence'] * tf['amplitude']
                    else:
                        type_weights[tf_type] = tf['confidence'] * tf['amplitude']
                
                dominant_type = max(type_weights.keys(), key=lambda k: type_weights[k])
            else:
                return await self._tectonic_loading_fallback(coords)
            
            return {
                'loading_frequency': float(weighted_frequency),
                'confidence': float(ensemble_confidence),
                'dominant_loading_type': dominant_type,
                'tectonic_components': len(tectonic_frequencies),
                'analysis_method': 'tectonic_loading_ensemble'
            }
            
        except Exception as e:
            self.logger.warning(f"Tectonic loading frequency calculation failed: {e}")
            return await self._tectonic_loading_fallback(coords)

    async def _analyze_hydrothermal_system_dynamics(self, coords: List[float]) -> Dict[str, float]:
        """Analyze hydrothermal system dynamics using volcano modules"""
        try:
            if not hasattr(self, 'volcano_modules'):
                return await self._hydrothermal_fallback(coords)
            
            # Get hydrothermal system dynamics
            hydrothermal_data = await self.volcano_modules.analyze_hydrothermal_dynamics(
                coords[0], coords[1], depth_km=abs(coords[2]) if len(coords) > 2 else 1.0)
            
            if not hydrothermal_data:
                return await self._hydrothermal_fallback(coords)
            
            hydrothermal_frequencies = []
            
            # 1. Fluid circulation frequencies
            if 'fluid_circulation' in hydrothermal_data:
                circulation = hydrothermal_data['fluid_circulation']
                circulation_cells = circulation.get('circulation_cells', [])
                for cell in circulation_cells:
                    if 'circulation_frequency_hz' in cell:
                        hydrothermal_frequencies.append({
                            'frequency': cell['circulation_frequency_hz'],
                            'amplitude': cell.get('flow_rate_kg_s', 1.0),
                            'type': 'fluid_circulation',
                            'confidence': cell.get('circulation_confidence', 0.6)
                        })
            
            # 2. Boiling dynamics
            if 'boiling_dynamics' in hydrothermal_data:
                boiling = hydrothermal_data['boiling_dynamics']
                if 'bubble_formation_frequency_hz' in boiling:
                    hydrothermal_frequencies.append({
                        'frequency': boiling['bubble_formation_frequency_hz'],
                        'amplitude': boiling.get('vapor_fraction', 0.1) * 10,
                        'type': 'boiling_dynamics',
                        'confidence': boiling.get('boiling_confidence', 0.65)
                    })
            
            # 3. Pressure wave propagation
            if 'pressure_waves' in hydrothermal_data:
                waves = hydrothermal_data['pressure_waves']
                wave_modes = waves.get('wave_modes', [])
                for mode in wave_modes:
                    if 'wave_frequency_hz' in mode:
                        hydrothermal_frequencies.append({
                            'frequency': mode['wave_frequency_hz'],
                            'amplitude': mode.get('pressure_amplitude_pa', 1000.0) / 1000.0,
                            'type': 'pressure_wave',
                            'confidence': mode.get('wave_confidence', 0.7)
                        })
            
            # 4. Phase change dynamics
            if 'phase_changes' in hydrothermal_data:
                phase_changes = hydrothermal_data['phase_changes']
                if 'phase_transition_frequency_hz' in phase_changes:
                    hydrothermal_frequencies.append({
                        'frequency': phase_changes['phase_transition_frequency_hz'],
                        'amplitude': phase_changes.get('latent_heat_j_kg', 2e6) / 2e6,
                        'type': 'phase_transition',
                        'confidence': phase_changes.get('phase_confidence', 0.6)
                    })
            
            if not hydrothermal_frequencies:
                return await self._hydrothermal_fallback(coords)
            
            # Hydrothermal frequency ensemble
            frequencies = [hf['frequency'] for hf in hydrothermal_frequencies]
            confidences = [hf['confidence'] for hf in hydrothermal_frequencies]
            amplitudes = [hf['amplitude'] for hf in hydrothermal_frequencies]
            
            # Weighted ensemble
            weights = [conf * amp for conf, amp in zip(confidences, amplitudes)]
            if weights and frequencies:
                ensemble_frequency = np.average(frequencies, weights=weights)
                ensemble_confidence = np.mean(confidences)
                
                # Dominant hydrothermal process
                dominant_process = max(hydrothermal_frequencies, 
                                     key=lambda hf: hf['confidence'] * hf['amplitude'])['type']
            else:
                return await self._hydrothermal_fallback(coords)
            
            return {
                'loading_frequency': float(ensemble_frequency),
                'confidence': float(ensemble_confidence),
                'dominant_loading_type': dominant_process,
                'hydrothermal_processes': len(hydrothermal_frequencies),
                'analysis_method': 'hydrothermal_dynamics'
            }
            
        except Exception as e:
            self.logger.warning(f"Hydrothermal system dynamics analysis failed: {e}")
            return await self._hydrothermal_fallback(coords)

    async def _predict_loading_frequency_ml(self, coords: List[float]) -> Dict[str, float]:
        """ML-based loading frequency prediction with ensemble uncertainty"""
        try:
            if not hasattr(self, 'model_manager'):
                return await self._ml_loading_fallback(coords)
            
            # Compile comprehensive feature vector
            feature_vector = await self._compile_loading_feature_vector(coords)
            if not feature_vector:
                return await self._ml_loading_fallback(coords)
            
            # Get available ML models for loading frequency prediction
            available_models = await self.model_manager.get_available_models(
                task_type='dynamic_loading_prediction',
                model_categories=['ensemble', 'neural_network', 'random_forest', 'gradient_boosting', 'svm'])
            
            if not available_models:
                return await self._ml_loading_fallback(coords)
            
            ml_predictions = []
            
            # Execute ensemble ML predictions
            for model_info in available_models[:6]:  # Use top 6 models
                try:
                    prediction = await self.model_manager.predict(
                        model_info['model_id'], feature_vector,
                        prediction_type='loading_frequency_hz',
                        include_uncertainty=True)
                    
                    if prediction and 'prediction' in prediction and prediction['prediction'] > 0:
                        ml_predictions.append({
                            'frequency': prediction['prediction'],
                            'uncertainty': prediction.get('uncertainty', 0.1),
                            'model_confidence': model_info.get('validation_score', 0.7),
                            'model_type': model_info.get('model_type', 'unknown'),
                            'loading_type': prediction.get('predicted_loading_type', 'mixed')
                        })
                        
                except Exception as e:
                    self.logger.warning(f"ML model {model_info.get('model_id', 'unknown')} failed: {e}")
                    continue
            
            if not ml_predictions:
                return await self._ml_loading_fallback(coords)
            
            # Ensemble ML analysis with uncertainty propagation
            frequencies = [pred['frequency'] for pred in ml_predictions]
            uncertainties = [pred['uncertainty'] for pred in ml_predictions]
            confidences = [pred['model_confidence'] for pred in ml_predictions]
            
            # Uncertainty-weighted ensemble
            uncertainty_weights = [conf / (unc + 1e-6) for conf, unc in zip(confidences, uncertainties)]
            ensemble_frequency = np.average(frequencies, weights=uncertainty_weights)
            
            # Uncertainty propagation
            ensemble_uncertainty = np.sqrt(np.average(
                [(unc * w)**2 for unc, w in zip(uncertainties, uncertainty_weights)]) / np.sum(uncertainty_weights))
            
            ensemble_confidence = np.mean(confidences)
            
            # Determine dominant loading type from ML predictions
            loading_types = [pred.get('loading_type', 'mixed') for pred in ml_predictions]
            type_counts = {lt: loading_types.count(lt) for lt in set(loading_types)}
            dominant_loading_type = max(type_counts.keys(), key=lambda k: type_counts[k])
            
            return {
                'loading_frequency': float(ensemble_frequency),
                'confidence': float(ensemble_confidence),
                'prediction_uncertainty': float(ensemble_uncertainty),
                'dominant_loading_type': dominant_loading_type,
                'model_count': len(ml_predictions),
                'analysis_method': 'ml_ensemble_prediction'
            }
            
        except Exception as e:
            self.logger.warning(f"ML loading frequency prediction failed: {e}")
            return await self._ml_loading_fallback(coords)

    def _analyze_frequency_scales(self, loading_results: List[Dict]) -> Dict[str, int]:
        """Analyze frequency scales in loading results"""
        scale_counts = {
            'micro_scale': 0,      # > 10 Hz
            'meso_scale': 0,       # 0.1 - 10 Hz  
            'macro_scale': 0,      # 0.001 - 0.1 Hz
            'regional_scale': 0    # < 0.001 Hz
        }
        
        for result in loading_results:
            freq = result.get('loading_frequency', 0)
            if freq > 10:
                scale_counts['micro_scale'] += 1
            elif freq > 0.1:
                scale_counts['meso_scale'] += 1
            elif freq > 0.001:
                scale_counts['macro_scale'] += 1
            else:
                scale_counts['regional_scale'] += 1
        
        return scale_counts

    def _calculate_scale_weight(self, loading_type: str, coords: List[float]) -> float:
        """Calculate scale-dependent weighting factor"""
        # Distance-based scaling
        distance_km = np.sqrt(coords[0]**2 + coords[1]**2)
        
        if loading_type in ['magma_convection', 'volatile_exsolution', 'crystallization']:
            # High frequency volcanic processes - more weight closer to source
            return max(0.5, 2.0 / (1.0 + distance_km / 2.0))
        elif loading_type in ['chamber_resonance', 'pressure_oscillation']:
            # Intermediate frequency processes
            return max(0.6, 1.5 / (1.0 + distance_km / 5.0))
        elif loading_type in ['tectonic', 'fault_loading', 'earthquake_cycle']:
            # Regional processes - more uniform weighting
            return max(0.7, 1.2 / (1.0 + distance_km / 20.0))
        else:
            # Mixed or unknown processes
            return 1.0

    # Enhanced fallback methods for each loading analysis method
    async def _comprehensive_loading_fallback(self, coords: List[float]) -> float:
        """Comprehensive fallback using enhanced physics-based calculations"""
        try:
            distance_km = np.sqrt(coords[0]**2 + coords[1]**2)
            depth_km = abs(coords[2]) if len(coords) > 2 else 1.0
            
            # Physics-based frequency estimation with multiple approaches
            frequencies = []
            
            # 1. Volcanic system resonance
            if distance_km < 10:  # Within volcanic system
                # Chamber resonance frequency: f = v / (2 * L)
                acoustic_velocity = 1000.0  # m/s in magma
                chamber_dimension = max(500.0, distance_km * 100)  # Estimated chamber size
                chamber_frequency = acoustic_velocity / (2 * chamber_dimension)
                frequencies.append(chamber_frequency)
                
                # Convection frequency based on Rayleigh number
                thermal_diffusivity = 1e-6  # m²/s
                chamber_height = chamber_dimension
                convection_frequency = thermal_diffusivity / (chamber_height**2)
                frequencies.append(convection_frequency)
            
            # 2. Stress wave propagation
            seismic_velocity = 3000.0  # m/s
            wavelength = depth_km * 1000  # Characteristic wavelength
            stress_wave_frequency = seismic_velocity / wavelength
            frequencies.append(stress_wave_frequency)
            
            # 3. Thermal oscillations
            thermal_time_scale = (depth_km * 1000)**2 / (1e-6)  # Thermal diffusion time
            thermal_frequency = 1.0 / thermal_time_scale
            frequencies.append(thermal_frequency)
            
            # Select appropriate frequency based on distance and depth
            if frequencies:
                if distance_km < 2:  # Near field - high frequency processes dominate
                    fallback_frequency = max(frequencies)
                elif distance_km < 10:  # Intermediate - mixed frequencies
                    fallback_frequency = np.median(frequencies)
                else:  # Far field - low frequency processes dominate
                    fallback_frequency = min(frequencies)
            else:
                # Ultimate fallback
                fallback_frequency = 0.01  # 10 mHz
            
            # Ensure physical bounds
            return max(0.001, min(10.0, fallback_frequency))
            
        except Exception as e:
            self.logger.error(f"Comprehensive loading fallback failed: {e}")
            return 0.01  # 10 mHz default

    async def _volcanic_loading_fallback(self, coords: List[float]) -> Dict[str, float]:
        """Enhanced fallback for volcanic loading analysis"""
        distance_km = np.sqrt(coords[0]**2 + coords[1]**2)
        
        if distance_km < 2:
            frequency = 0.5  # High frequency volcanic processes
        elif distance_km < 10:
            frequency = 0.1  # Moderate frequency
        else:
            frequency = 0.01  # Low frequency regional
        
        return {
            'loading_frequency': frequency,
            'confidence': 0.4,
            'dominant_loading_type': 'volcanic_mixed',
            'analysis_method': 'volcanic_loading_fallback'
        }

    async def _chamber_dynamics_fallback(self, coords: List[float]) -> Dict[str, float]:
        """Enhanced fallback for chamber dynamics"""
        depth_km = abs(coords[2]) if len(coords) > 2 else 1.0
        # Chamber resonance based on depth
        frequency = 1000.0 / (4 * depth_km * 1000)  # Acoustic resonance
        
        return {
            'loading_frequency': max(0.001, frequency),
            'confidence': 0.45,
            'dominant_loading_type': 'chamber_resonance',
            'analysis_method': 'chamber_dynamics_fallback'
        }

