    async def _ml_loading_fallback(self, coords: List[float]) -> Dict[str, float]:
        """Enhanced fallback for ML prediction"""
        distance_km = np.sqrt(coords[0]**2 + coords[1]**2)
        
        # Distance-based empirical model
        frequency = 0.1 * np.exp(-distance_km / 5.0) + 0.001
        
        return {
            'loading_frequency': frequency,
            'confidence': 0.3,
            'dominant_loading_type': 'empirical_model',
            'analysis_method': 'ml_loading_fallback'
        }

    async def _dynamic_loading_fallback(self, coords: List[float], method: str) -> Dict[str, float]:
        """Generic enhanced fallback for any dynamic loading method"""
        distance_km = np.sqrt(coords[0]**2 + coords[1]**2)
        depth_km = abs(coords[2]) if len(coords) > 2 else 1.0
        
        # Method-specific fallback frequencies
        if 'volcanic' in method:
            base_freq = 0.1 / (1 + distance_km / 2.0)
            loading_type = 'volcanic_mixed'
        elif 'chamber' in method:
            base_freq = 0.05 / (1 + depth_km / 1.0)
            loading_type = 'chamber_mixed'
        elif 'tectonic' in method:
            base_freq = 0.001
            loading_type = 'tectonic_regional'
        elif 'hydrothermal' in method:
            base_freq = 0.01 / (1 + distance_km / 10.0)
            loading_type = 'hydrothermal_mixed'
        else:
            base_freq = 0.01
            loading_type = 'mixed'
        
        return {
            'loading_frequency': max(0.001, base_freq),
            'confidence': 0.3,
            'dominant_loading_type': loading_type,
            'analysis_method': f'{method}_fallback'
        }

