    def _basic_crs_heuristics(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Basic CRS heuristics - replaced with comprehensive CRS detection"""
        # This method is being replaced by the comprehensive system below
        return self._comprehensive_crs_detection_fallback(x, y, easting, northing)

    def _comprehensive_crs_detection_fallback(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Comprehensive CRS detection fallback with advanced analysis"""
        try:
            # Initialize comprehensive CRS analysis
            crs_candidates = []
            
            # Analysis 1: Coordinate magnitude and range analysis
            magnitude_analysis = self._analyze_coordinate_magnitude_patterns(x, y)
            for crs_candidate in magnitude_analysis['candidates']:
                crs_candidates.append(crs_candidate)
            
            # Analysis 2: Geographic pattern recognition
            geographic_patterns = self._analyze_geographic_patterns(x, y)
            for pattern in geographic_patterns['patterns']:
                crs_candidates.append(pattern)
            
            # Analysis 3: Projection signature analysis
            projection_signatures = self._analyze_projection_signatures(x, y, easting, northing)
            for signature in projection_signatures['signatures']:
                crs_candidates.append(signature)
            
            # Analysis 4: Regional CRS probability assessment
            regional_assessment = self._assess_regional_crs_probability(x, y)
            for assessment in regional_assessment['assessments']:
                crs_candidates.append(assessment)
            
            # Ensemble CRS determination
            if crs_candidates:
                best_crs = self._determine_best_crs_from_candidates(crs_candidates, x, y)
                return best_crs
            else:
                # Ultimate fallback
                return {
                    'detected_crs': 'EPSG:4326',
                    'confidence': 0.3,
                    'method': 'ultimate_fallback',
                    'coordinates': (y if abs(x) <= 180 and abs(y) <= 90 else 0.0, 
                                  x if abs(x) <= 180 and abs(y) <= 90 else 0.0)
                }
                
        except Exception as e:
            self.logger.warning(f"Comprehensive CRS detection fallback failed: {e}")
            return {
                'detected_crs': 'EPSG:4326',
                'confidence': 0.2,
                'method': 'error_fallback',
                'coordinates': (0.0, 0.0)
            }

    def _analyze_coordinate_magnitude_patterns(self, x: float, y: float) -> Dict[str, Any]:
        """Analyze coordinate magnitude patterns for CRS detection"""
        patterns = []
        
        # Geographic coordinate patterns (WGS84)
        if abs(x) <= 180 and abs(y) <= 90:
            confidence = 0.9 if (abs(x) <= 90 and abs(y) <= 90) else 0.7
            patterns.append({
                'crs': 'EPSG:4326',
                'confidence': confidence,
                'reason': 'geographic_coordinate_range',
                'coordinates': (y, x) if abs(x) > abs(y) else (x, y),
                'pattern_type': 'geographic'
            })
        
        # UTM coordinate patterns
        x_range = 100000 <= abs(x) <= 1000000
        y_range = 1000000 <= abs(y) <= 10000000
        if x_range and y_range:
            # Determine UTM zone and hemisphere
            estimated_zone = max(1, min(60, int((x + 500000) / 1000000) + 30))
            hemisphere = 'north' if y > 0 else 'south'
            epsg_code = f"EPSG:{32600 + estimated_zone if hemisphere == 'north' else 32700 + estimated_zone}"
            
            patterns.append({
                'crs': epsg_code,
                'confidence': 0.8,
                'reason': 'utm_coordinate_pattern',
                'coordinates': self._utm_to_geographic_advanced(x, y, estimated_zone, hemisphere == 'north'),
                'pattern_type': 'utm',
                'utm_zone': estimated_zone,
                'hemisphere': hemisphere
            })
        
        # Web Mercator patterns
        if abs(x) > 1000000 or abs(y) > 1000000:
            if abs(x) <= 20037508.34 and abs(y) <= 20037508.34:
                patterns.append({
                    'crs': 'EPSG:3857',
                    'confidence': 0.75,
                    'reason': 'web_mercator_range',
                    'coordinates': self._web_mercator_to_geographic_advanced(x, y),
                    'pattern_type': 'web_mercator'
                })
        
        # State Plane patterns (US)
        if 10000 <= abs(x) <= 3000000 and 10000 <= abs(y) <= 3000000:
            patterns.append({
                'crs': 'State_Plane_Estimate',
                'confidence': 0.6,
                'reason': 'state_plane_pattern',
                'coordinates': self._state_plane_to_geographic_estimate(x, y),
                'pattern_type': 'state_plane'
            })
        
        return {'candidates': patterns}

    def _analyze_geographic_patterns(self, x: float, y: float) -> Dict[str, Any]:
        """Analyze geographic patterns in coordinates"""
        patterns = []
        
        # Latitude/longitude swap detection
        if abs(x) <= 90 and abs(y) <= 180:
            # Likely lat/lon swapped
            patterns.append({
                'crs': 'EPSG:4326',
                'confidence': 0.8,
                'reason': 'lat_lon_swap_detected',
                'coordinates': (x, y),  # x is likely latitude
                'pattern_type': 'geographic_swapped'
            })
        
        # Decimal degree precision analysis
        if abs(x) <= 180 and abs(y) <= 90:
            decimal_places_x = len(str(x).split('.')[-1]) if '.' in str(x) else 0
            decimal_places_y = len(str(y).split('.')[-1]) if '.' in str(y) else 0
            
            if decimal_places_x >= 4 or decimal_places_y >= 4:
                # High precision suggests accurate geographic coordinates
                patterns.append({
                    'crs': 'EPSG:4326',
                    'confidence': 0.85,
                    'reason': 'high_precision_geographic',
                    'coordinates': (y, x),
                    'pattern_type': 'high_precision_geographic'
                })
        
        return {'patterns': patterns}

    def _analyze_projection_signatures(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Analyze projection signatures for CRS identification"""
        signatures = []
        
        # Lambert Conformal Conic signatures
        if 1000 <= abs(x) <= 3000000 and 1000 <= abs(y) <= 3000000:
            # Check for LCC-like patterns
            if abs(x) < abs(y):  # More north-south extent than east-west
                signatures.append({
                    'crs': 'Lambert_Conformal_Conic',
                    'confidence': 0.65,
                    'reason': 'lambert_conformal_signature',
                    'coordinates': self._lambert_to_geographic_estimate(x, y),
                    'pattern_type': 'lambert_conformal'
                })
        
        # Albers Equal Area signatures
        if 500000 <= abs(x) <= 2000000 and 300000 <= abs(y) <= 2500000:
            signatures.append({
                'crs': 'Albers_Equal_Area',
                'confidence': 0.6,
                'reason': 'albers_projection_signature',
                'coordinates': self._albers_to_geographic_estimate(x, y),
                'pattern_type': 'albers'
            })
        
        # Transverse Mercator signatures (besides UTM)
        if 100000 <= abs(x) <= 800000 and 1000000 <= abs(y) <= 10000000:
            if not (200000 <= abs(x) <= 800000):  # Not standard UTM range
                signatures.append({
                    'crs': 'Transverse_Mercator',
                    'confidence': 0.55,
                    'reason': 'transverse_mercator_signature',
                    'coordinates': self._transverse_mercator_to_geographic_estimate(x, y),
                    'pattern_type': 'transverse_mercator'
                })
        
        return {'signatures': signatures}

    def _assess_regional_crs_probability(self, x: float, y: float) -> Dict[str, Any]:
        """Assess regional CRS probability based on coordinate characteristics"""
        assessments = []
        
        # European coordinates assessment
        if 3000000 <= abs(x) <= 7000000 and 1000000 <= abs(y) <= 6000000:
            assessments.append({
                'crs': 'EPSG:3035',  # ETRS89 LAEA Europe
                'confidence': 0.7,
                'reason': 'european_extent_pattern',
                'coordinates': self._etrs89_laea_to_geographic_estimate(x, y),
                'pattern_type': 'european_regional'
            })
        
        # North American assessment
        if 200000 <= abs(x) <= 3000000 and 500000 <= abs(y) <= 4000000:
            assessments.append({
                'crs': 'NAD83_Estimate',
                'confidence': 0.65,
                'reason': 'north_american_pattern',
                'coordinates': self._nad83_to_geographic_estimate(x, y),
                'pattern_type': 'north_american'
            })
        
        # Australian/New Zealand assessment
        if 200000 <= abs(x) <= 1000000 and 5000000 <= abs(y) <= 8000000:
            assessments.append({
                'crs': 'GDA2020_MGA_Estimate',
                'confidence': 0.6,
                'reason': 'australian_pattern',
                'coordinates': self._gda2020_to_geographic_estimate(x, y),
                'pattern_type': 'australian'
            })
        
        return {'assessments': assessments}

    def _determine_best_crs_from_candidates(self, candidates: List[Dict], x: float, y: float) -> Dict[str, Any]:
        """Determine best CRS from candidate list using ensemble analysis"""
        if not candidates:
            return {
                'detected_crs': 'EPSG:4326',
                'confidence': 0.2,
                'method': 'no_candidates',
                'coordinates': (0.0, 0.0)
            }
        
        # Sort candidates by confidence
        sorted_candidates = sorted(candidates, key=lambda c: c['confidence'], reverse=True)
        
        # Apply ensemble weighting
        best_candidate = sorted_candidates[0]
        
        # Validate coordinates
        coords = best_candidate.get('coordinates', (0.0, 0.0))
        if isinstance(coords, (list, tuple)) and len(coords) >= 2:
            lat, lon = coords[0], coords[1]
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return {
                    'detected_crs': best_candidate['crs'],
                    'confidence': best_candidate['confidence'],
                    'method': 'ensemble_candidate_selection',
                    'coordinates': coords,
                    'pattern_type': best_candidate.get('pattern_type', 'unknown'),
                    'reason': best_candidate.get('reason', 'ensemble_selection')
                }
        
        # Fallback if coordinates are invalid
        return {
            'detected_crs': 'EPSG:4326',
            'confidence': 0.3,
            'method': 'invalid_coordinates_fallback',
            'coordinates': (0.0, 0.0)
        }

    def _utm_to_geographic_advanced(self, easting: float, northing: float, zone: int, northern: bool) -> Tuple[float, float]:
        """Advanced UTM to geographic conversion"""
        try:
            import math
            
            # UTM parameters
            k0 = 0.9996  # UTM scale factor
            e = 0.0818191908426  # WGS84 eccentricity
            e_prime_squared = 0.0067394967422  # Second eccentricity squared
            a = 6378137.0  # WGS84 semi-major axis
            
            # Remove false easting/northing
            x = easting - 500000.0
            y = northing if northern else northing - 10000000.0
            
            # Calculate parameters
            M = y / k0
            mu = M / (a * (1 - e*e/4 - 3*e**4/64 - 5*e**6/256))
            
            # Calculate latitude
            e1 = (1 - math.sqrt(1 - e*e)) / (1 + math.sqrt(1 - e*e))
            J1 = (3*e1/2 - 27*e1**3/32)
            J2 = (21*e1**2/16 - 55*e1**4/32)
            J3 = (151*e1**3/96)
            
            fp = mu + J1*math.sin(2*mu) + J2*math.sin(4*mu) + J3*math.sin(6*mu)
            
            # Calculate longitude
            C1 = e_prime_squared * math.cos(fp)**2
            T1 = math.tan(fp)**2
            R1 = a * (1 - e*e) / (1 - e*e * math.sin(fp)**2)**(3/2)
            N1 = a / math.sqrt(1 - e*e * math.sin(fp)**2)
            D = x / (N1 * k0)
            
            # Final calculations
            latitude = fp - (N1 * math.tan(fp) / R1) * (D*D/2 - (5 + 3*T1 + 10*C1 - 4*C1*C1 - 9*e_prime_squared) * D**4/24)
            longitude = (D - (1 + 2*T1 + C1) * D**3/6 + (5 - 2*C1 + 28*T1 - 3*C1*C1 + 8*e_prime_squared + 24*T1*T1) * D**5/120) / math.cos(fp)
            
            # Convert to degrees and add central meridian
            latitude_deg = math.degrees(latitude)
            longitude_deg = math.degrees(longitude) + (zone - 1) * 6 - 180 + 3
            
            return latitude_deg, longitude_deg
            
        except Exception as e:
            self.logger.warning(f"Advanced UTM conversion failed: {e}")
            # Simplified fallback
            lon_approx = (easting - 500000) / 111320 + (zone - 1) * 6 - 180 + 3
            lat_approx = northing / 111320 if northern else (northing - 10000000) / 111320
            return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _web_mercator_to_geographic_advanced(self, x: float, y: float) -> Tuple[float, float]:
        """Advanced Web Mercator to geographic conversion"""
        try:
            import math
            
            # Web Mercator parameters
            a = 6378137.0  # Earth radius in meters
            
            # Convert to radians
            lon_rad = x / a
            lat_rad = 2 * math.atan(math.exp(y / a)) - math.pi / 2
            
            # Convert to degrees
            latitude = math.degrees(lat_rad)
            longitude = math.degrees(lon_rad)
            
            # Clamp to valid ranges
            latitude = max(-85.0511, min(85.0511, latitude))  # Web Mercator limits
            longitude = max(-180, min(180, longitude))
            
            return latitude, longitude
            
        except Exception as e:
            self.logger.warning(f"Advanced Web Mercator conversion failed: {e}")
            # Simplified fallback
            lat_approx = 2 * math.atan(math.exp(y / 20037508.34 * math.pi)) * 180 / math.pi - 90
            lon_approx = x / 20037508.34 * 180
            return max(-85, min(85, lat_approx)), max(-180, min(180, lon_approx))

    def _state_plane_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from State Plane coordinates"""
        # This is a simplified estimation - real State Plane requires zone-specific parameters
        # Assume average US coordinates
        central_lat = 39.0  # Approximate center latitude of continental US
        central_lon = -96.0  # Approximate center longitude of continental US
        
        # Simple linear approximation (very rough)
        lat_offset = (y - 1500000) / 111320  # Rough meters per degree latitude
        lon_offset = (x - 1000000) / (111320 * math.cos(math.radians(central_lat)))
        
        latitude = central_lat + lat_offset
        longitude = central_lon + lon_offset
        
        return max(-90, min(90, latitude)), max(-180, min(180, longitude))

    def _lambert_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Lambert Conformal Conic"""
        # Simplified estimation for Lambert Conformal Conic
        # Assume standard parallels and central meridian for continental US
        lat_approx = 35.0 + (y - 1000000) / 111320
        lon_approx = -95.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _albers_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Albers Equal Area"""
        # Simplified estimation for Albers Equal Area
        lat_approx = 38.0 + (y - 1000000) / 111320
        lon_approx = -96.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _transverse_mercator_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Transverse Mercator"""
        # Simplified estimation - similar to UTM but different parameters
        lat_approx = y / 111320
        lon_approx = x / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _etrs89_laea_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from ETRS89 LAEA Europe"""
        # Simplified estimation for European coordinates
        # LAEA Europe is centered at 52°N, 10°E
        lat_approx = 52.0 + (y - 3000000) / 111320
        lon_approx = 10.0 + (x - 5000000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _nad83_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from NAD83"""
        # Simplified estimation for North American coordinates
        lat_approx = 40.0 + (y - 2000000) / 111320
        lon_approx = -100.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _gda2020_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from GDA2020 MGA"""
        # Simplified estimation for Australian coordinates
        # Assume MGA Zone 55 (central Australia)
        lat_approx = -(y - 6000000) / 111320  # Southern hemisphere
        lon_approx = 150.0 + (x - 500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    async def _enhanced_coordinate_estimation_with_data_integration(self, coords: List[float]) -> Optional[Tuple[float, float]]:
        """
        Enhanced coordinate estimation replacing basic heuristics with comprehensive 
        data integration-based coordinate reference system detection and transformation.
        """
        try:
            if not coords or len(coords) < 2:
                return None
            
            x, y = coords[0], coords[1]
            z = coords[2] if len(coords) > 2 else 0.0
            
            # Method 1: Comprehensive CRS detection using data integration pipeline
            if hasattr(self, 'data_integration_pipeline'):
                try:
                    crs_result = await self.data_integration_pipeline.detect_coordinate_system(
                        x_coord=x, y_coord=y, z_coord=z,
                        detection_methods=['spatial_database', 'ml_classification', 'pattern_analysis', 'regional_matching'],
                        confidence_threshold=0.6
                    )
                    
                    if crs_result and crs_result.get('confidence', 0) > 0.6:
                        # Transform using detected CRS
                        transformed = await self.data_integration_pipeline.transform_coordinates(
                            x_coord=x, y_coord=y, z_coord=z,
                            source_crs=crs_result['detected_crs'],
                            target_crs='EPSG:4326',
                            transformation_accuracy='high'
                        )
                        
                        if transformed and 'lat' in transformed and 'lon' in transformed:
                            lat, lon = transformed['lat'], transformed['lon']
                            if -90 <= lat <= 90 and -180 <= lon <= 180:
                                self.logger.debug(f"Data integration CRS detection successful: "
                                                f"{crs_result['detected_crs']} -> ({lat:.6f}, {lon:.6f})")
                                return lat, lon
                                
                except Exception as e:
                    self.logger.debug(f"Data integration CRS detection failed: {e}")
            
            # Method 2: ML-enhanced coordinate system detection
            if hasattr(self, 'model_manager'):
                try:
                    # Compile comprehensive coordinate features
                    coordinate_features = {
                        'x_coordinate': x, 'y_coordinate': y, 'z_coordinate': z,
                        'coordinate_magnitude': math.sqrt(x*x + y*y),
                        'coordinate_ratio': abs(x/y) if y != 0 else float('inf'),
                        'x_magnitude_log': math.log10(abs(x) + 1),
                        'y_magnitude_log': math.log10(abs(y) + 1),
                        'is_geographic_range': 1 if (abs(x) <= 180 and abs(y) <= 90) else 0,
                        'is_utm_range': 1 if (100000 <= abs(x) <= 1000000 and 1000000 <= abs(y) <= 10000000) else 0,
                        'is_web_mercator_range': 1 if (abs(x) > 1000000 or abs(y) > 1000000) else 0,
                        'hemisphere_indicator': 1 if y >= 0 else 0,
                        'quadrant': self._determine_coordinate_quadrant(x, y)
                    }
                    
                    # Use ensemble of CRS detection models
                    crs_models = ['crs_detector_ensemble_v4', 'coordinate_system_classifier_v3', 'projection_identifier_v2']
                    model_predictions = []
                    
                    for model_name in crs_models:
                        try:
                            model = await self.model_manager.get_model(model_name)
                            if model:
                                prediction = await model.predict(coordinate_features)
                                if prediction and 'crs_code' in prediction:
                                    model_predictions.append({
                                        'crs': prediction['crs_code'],
                                        'confidence': prediction.get('confidence', 0.5),
                                        'coordinates': prediction.get('transformed_coordinates', None)
                                    })
                        except Exception as e:
                            self.logger.debug(f"ML CRS model {model_name} failed: {e}")
                            continue
                    
                    # Ensemble ML prediction
                    if model_predictions:
                        # Select best prediction based on confidence
                        best_prediction = max(model_predictions, key=lambda p: p['confidence'])
                        if best_prediction['confidence'] > 0.6 and best_prediction.get('coordinates'):
                            coords_result = best_prediction['coordinates']
                            if isinstance(coords_result, (list, tuple)) and len(coords_result) >= 2:
                                lat, lon = coords_result[0], coords_result[1]
                                if -90 <= lat <= 90 and -180 <= lon <= 180:
                                    self.logger.debug(f"ML CRS detection successful: "
                                                    f"{best_prediction['crs']} -> ({lat:.6f}, {lon:.6f})")
                                    return lat, lon
                                    
                except Exception as e:
                    self.logger.debug(f"ML CRS detection failed: {e}")
            
            # Method 3: Comprehensive CRS heuristics (enhanced replacement)
            crs_analysis = self._comprehensive_crs_detection_fallback(x, y, x, y)
            if crs_analysis and crs_analysis.get('confidence', 0) > 0.5:
                coords_result = crs_analysis.get('coordinates', (0.0, 0.0))
                if isinstance(coords_result, (list, tuple)) and len(coords_result) >= 2:
                    lat, lon = coords_result[0], coords_result[1]
                    if -90 <= lat <= 90 and -180 <= lon <= 180:
                        self.logger.debug(f"Comprehensive CRS heuristics successful: "
                                        f"{crs_analysis['detected_crs']} -> ({lat:.6f}, {lon:.6f})")
                        return lat, lon
            
            # Method 4: Physics-based coordinate analysis
            physics_result = await self._physics_based_coordinate_analysis(x, y, z)
            if physics_result:
                return physics_result
            
            # Ultimate fallback with validation
            return self._validated_coordinate_fallback(x, y)
            
        except Exception as e:
            self.logger.error(f"Enhanced coordinate estimation failed: {e}")
            return self._validated_coordinate_fallback(coords[0] if coords else 0.0, 
                                                    coords[1] if len(coords) > 1 else 0.0)

    def _determine_coordinate_quadrant(self, x: float, y: float) -> int:
        """Determine coordinate quadrant for analysis"""
        if x >= 0 and y >= 0:
            return 1
        elif x < 0 and y >= 0:
            return 2
        elif x < 0 and y < 0:
            return 3
        else:
            return 4

    async def _physics_based_coordinate_analysis(self, x: float, y: float, z: float) -> Optional[Tuple[float, float]]:
        """Physics-based coordinate analysis using Earth geometry"""
        try:
            import math
            
            # Earth parameters
            earth_radius_m = 6371000  # meters
            earth_circumference_m = 2 * math.pi * earth_radius_m
            
            # Check if coordinates could represent distance from Earth center
            distance_from_center = math.sqrt(x*x + y*y + z*z)
            
            if 6300000 <= distance_from_center <= 6500000:  # Near Earth's surface
                # Convert Cartesian to spherical coordinates
                lat_rad = math.asin(z / distance_from_center)
                lon_rad = math.atan2(y, x)
                
                latitude = math.degrees(lat_rad)
                longitude = math.degrees(lon_rad)
                
                if -90 <= latitude <= 90 and -180 <= longitude <= 180:
                    self.logger.debug(f"Physics-based Cartesian conversion: ({latitude:.6f}, {longitude:.6f})")
                    return latitude, longitude
            
            # Check for angular measurements in radians
            if abs(x) <= math.pi and abs(y) <= math.pi/2:
                latitude = math.degrees(y)
                longitude = math.degrees(x)
                if -90 <= latitude <= 90 and -180 <= longitude <= 180:
                    self.logger.debug(f"Physics-based radian conversion: ({latitude:.6f}, {longitude:.6f})")
                    return latitude, longitude
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Physics-based coordinate analysis failed: {e}")
            return None

    def _validated_coordinate_fallback(self, x: float, y: float) -> Tuple[float, float]:
        """Validated coordinate fallback with comprehensive bounds checking"""
        try:
            # Geographic coordinate range check
            if abs(x) <= 180 and abs(y) <= 90:
                # Standard lat/lon or lon/lat
                if abs(x) <= 90:  # x could be latitude
                    lat = max(-90, min(90, x))
                    lon = max(-180, min(180, y))
                else:  # x is likely longitude
                    lat = max(-90, min(90, y))
                    lon = max(-180, min(180, x))
                
                self.logger.debug(f"Validated fallback (geographic): ({lat:.6f}, {lon:.6f})")
                return lat, lon
            
            # UTM-like coordinate approximation
            elif 100000 <= abs(x) <= 1000000 and 1000000 <= abs(y) <= 10000000:
                # Estimate UTM zone and convert
                estimated_zone = max(1, min(60, int((x + 500000) / 1000000) + 30))
                lat_approx = (y - 5000000) / 111320 if y > 0 else (y + 5000000) / 111320
                lon_approx = (x - 500000) / 111320 + (estimated_zone - 31) * 6
                
                lat = max(-90, min(90, lat_approx))
                lon = max(-180, min(180, lon_approx))
                
                self.logger.debug(f"Validated fallback (UTM estimate): ({lat:.6f}, {lon:.6f})")
                return lat, lon
            
            # Default to center coordinates for invalid inputs
            else:
                self.logger.debug("Validated fallback (default center): (0.0, 0.0)")
                return 0.0, 0.0
                
        except Exception as e:
            self.logger.warning(f"Validated coordinate fallback failed: {e}")
            return 0.0, 0.0

    def _basic_crs_heuristics(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Basic CRS heuristics - replaced with comprehensive CRS detection"""
        # This method is being replaced by the comprehensive system below
        return self._comprehensive_crs_detection_fallback(x, y, easting, northing)

    def _comprehensive_crs_detection_fallback(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Comprehensive CRS detection fallback with advanced analysis"""
        try:
            # Initialize comprehensive CRS analysis
            crs_candidates = []
            
            # Analysis 1: Coordinate magnitude and range analysis
            magnitude_analysis = self._analyze_coordinate_magnitude_patterns(x, y)
            for crs_candidate in magnitude_analysis['candidates']:
                crs_candidates.append(crs_candidate)
            
            # Analysis 2: Geographic pattern recognition
            geographic_patterns = self._analyze_geographic_patterns(x, y)
            for pattern in geographic_patterns['patterns']:
                crs_candidates.append(pattern)
            
            # Analysis 3: Projection signature analysis
            projection_signatures = self._analyze_projection_signatures(x, y, easting, northing)
            for signature in projection_signatures['signatures']:
                crs_candidates.append(signature)
            
            # Analysis 4: Regional CRS probability assessment
            regional_assessment = self._assess_regional_crs_probability(x, y)
            for assessment in regional_assessment['assessments']:
                crs_candidates.append(assessment)
            
            # Ensemble CRS determination
            if crs_candidates:
                best_crs = self._determine_best_crs_from_candidates(crs_candidates, x, y)
                return best_crs
            else:
                # Ultimate fallback
                return {
                    'detected_crs': 'EPSG:4326',
                    'confidence': 0.3,
                    'method': 'ultimate_fallback',
                    'coordinates': (y if abs(x) <= 180 and abs(y) <= 90 else 0.0, 
                                  x if abs(x) <= 180 and abs(y) <= 90 else 0.0)
                }
                
        except Exception as e:
            self.logger.warning(f"Comprehensive CRS detection fallback failed: {e}")
            return {
                'detected_crs': 'EPSG:4326',
                'confidence': 0.2,
                'method': 'error_fallback',
                'coordinates': (0.0, 0.0)
            }

    def _analyze_coordinate_magnitude_patterns(self, x: float, y: float) -> Dict[str, Any]:
        """Analyze coordinate magnitude patterns for CRS detection"""
        patterns = []
        
        # Geographic coordinate patterns (WGS84)
        if abs(x) <= 180 and abs(y) <= 90:
            confidence = 0.9 if (abs(x) <= 90 and abs(y) <= 90) else 0.7
            patterns.append({
                'crs': 'EPSG:4326',
                'confidence': confidence,
                'reason': 'geographic_coordinate_range',
                'coordinates': (y, x) if abs(x) > abs(y) else (x, y),
                'pattern_type': 'geographic'
            })
        
        # UTM coordinate patterns
        x_range = 100000 <= abs(x) <= 1000000
        y_range = 1000000 <= abs(y) <= 10000000
        if x_range and y_range:
            # Determine UTM zone and hemisphere
            estimated_zone = max(1, min(60, int((x + 500000) / 1000000) + 30))
            hemisphere = 'north' if y > 0 else 'south'
            epsg_code = f"EPSG:{32600 + estimated_zone if hemisphere == 'north' else 32700 + estimated_zone}"
            
            patterns.append({
                'crs': epsg_code,
                'confidence': 0.8,
                'reason': 'utm_coordinate_pattern',
                'coordinates': self._utm_to_geographic_advanced(x, y, estimated_zone, hemisphere == 'north'),
                'pattern_type': 'utm',
                'utm_zone': estimated_zone,
                'hemisphere': hemisphere
            })
        
        # Web Mercator patterns
        if abs(x) > 1000000 or abs(y) > 1000000:
            if abs(x) <= 20037508.34 and abs(y) <= 20037508.34:
                patterns.append({
                    'crs': 'EPSG:3857',
                    'confidence': 0.75,
                    'reason': 'web_mercator_range',
                    'coordinates': self._web_mercator_to_geographic_advanced(x, y),
                    'pattern_type': 'web_mercator'
                })
        
        # State Plane patterns (US)
        if 10000 <= abs(x) <= 3000000 and 10000 <= abs(y) <= 3000000:
            patterns.append({
                'crs': 'State_Plane_Estimate',
                'confidence': 0.6,
                'reason': 'state_plane_pattern',
                'coordinates': self._state_plane_to_geographic_estimate(x, y),
                'pattern_type': 'state_plane'
            })
        
        return {'candidates': patterns}

    def _analyze_geographic_patterns(self, x: float, y: float) -> Dict[str, Any]:
        """Analyze geographic patterns in coordinates"""
        patterns = []
        
        # Latitude/longitude swap detection
        if abs(x) <= 90 and abs(y) <= 180:
            # Likely lat/lon swapped
            patterns.append({
                'crs': 'EPSG:4326',
                'confidence': 0.8,
                'reason': 'lat_lon_swap_detected',
                'coordinates': (x, y),  # x is likely latitude
                'pattern_type': 'geographic_swapped'
            })
        
        # Decimal degree precision analysis
        if abs(x) <= 180 and abs(y) <= 90:
            decimal_places_x = len(str(x).split('.')[-1]) if '.' in str(x) else 0
            decimal_places_y = len(str(y).split('.')[-1]) if '.' in str(y) else 0
            
            if decimal_places_x >= 4 or decimal_places_y >= 4:
                # High precision suggests accurate geographic coordinates
                patterns.append({
                    'crs': 'EPSG:4326',
                    'confidence': 0.85,
                    'reason': 'high_precision_geographic',
                    'coordinates': (y, x),
                    'pattern_type': 'high_precision_geographic'
                })
        
        return {'patterns': patterns}

    def _analyze_projection_signatures(self, x: float, y: float, easting: float, northing: float) -> Dict[str, Any]:
        """Analyze projection signatures for CRS identification"""
        signatures = []
        
        # Lambert Conformal Conic signatures
        if 1000 <= abs(x) <= 3000000 and 1000 <= abs(y) <= 3000000:
            # Check for LCC-like patterns
            if abs(x) < abs(y):  # More north-south extent than east-west
                signatures.append({
                    'crs': 'Lambert_Conformal_Conic',
                    'confidence': 0.65,
                    'reason': 'lambert_conformal_signature',
                    'coordinates': self._lambert_to_geographic_estimate(x, y),
                    'pattern_type': 'lambert_conformal'
                })
        
        # Albers Equal Area signatures
        if 500000 <= abs(x) <= 2000000 and 300000 <= abs(y) <= 2500000:
            signatures.append({
                'crs': 'Albers_Equal_Area',
                'confidence': 0.6,
                'reason': 'albers_projection_signature',
                'coordinates': self._albers_to_geographic_estimate(x, y),
                'pattern_type': 'albers'
            })
        
        # Transverse Mercator signatures (besides UTM)
        if 100000 <= abs(x) <= 800000 and 1000000 <= abs(y) <= 10000000:
            if not (200000 <= abs(x) <= 800000):  # Not standard UTM range
                signatures.append({
                    'crs': 'Transverse_Mercator',
                    'confidence': 0.55,
                    'reason': 'transverse_mercator_signature',
                    'coordinates': self._transverse_mercator_to_geographic_estimate(x, y),
                    'pattern_type': 'transverse_mercator'
                })
        
        return {'signatures': signatures}

    def _assess_regional_crs_probability(self, x: float, y: float) -> Dict[str, Any]:
        """Assess regional CRS probability based on coordinate characteristics"""
        assessments = []
        
        # European coordinates assessment
        if 3000000 <= abs(x) <= 7000000 and 1000000 <= abs(y) <= 6000000:
            assessments.append({
                'crs': 'EPSG:3035',  # ETRS89 LAEA Europe
                'confidence': 0.7,
                'reason': 'european_extent_pattern',
                'coordinates': self._etrs89_laea_to_geographic_estimate(x, y),
                'pattern_type': 'european_regional'
            })
        
        # North American assessment
        if 200000 <= abs(x) <= 3000000 and 500000 <= abs(y) <= 4000000:
            assessments.append({
                'crs': 'NAD83_Estimate',
                'confidence': 0.65,
                'reason': 'north_american_pattern',
                'coordinates': self._nad83_to_geographic_estimate(x, y),
                'pattern_type': 'north_american'
            })
        
        # Australian/New Zealand assessment
        if 200000 <= abs(x) <= 1000000 and 5000000 <= abs(y) <= 8000000:
            assessments.append({
                'crs': 'GDA2020_MGA_Estimate',
                'confidence': 0.6,
                'reason': 'australian_pattern',
                'coordinates': self._gda2020_to_geographic_estimate(x, y),
                'pattern_type': 'australian'
            })
        
        return {'assessments': assessments}

    def _determine_best_crs_from_candidates(self, candidates: List[Dict], x: float, y: float) -> Dict[str, Any]:
        """Determine best CRS from candidate list using ensemble analysis"""
        if not candidates:
            return {
                'detected_crs': 'EPSG:4326',
                'confidence': 0.2,
                'method': 'no_candidates',
                'coordinates': (0.0, 0.0)
            }
        
        # Sort candidates by confidence
        sorted_candidates = sorted(candidates, key=lambda c: c['confidence'], reverse=True)
        
        # Apply ensemble weighting
        best_candidate = sorted_candidates[0]
        
        # Validate coordinates
        coords = best_candidate.get('coordinates', (0.0, 0.0))
        if isinstance(coords, (list, tuple)) and len(coords) >= 2:
            lat, lon = coords[0], coords[1]
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return {
                    'detected_crs': best_candidate['crs'],
                    'confidence': best_candidate['confidence'],
                    'method': 'ensemble_candidate_selection',
                    'coordinates': coords,
                    'pattern_type': best_candidate.get('pattern_type', 'unknown'),
                    'reason': best_candidate.get('reason', 'ensemble_selection')
                }
        
        # Fallback if coordinates are invalid
        return {
            'detected_crs': 'EPSG:4326',
            'confidence': 0.3,
            'method': 'invalid_coordinates_fallback',
            'coordinates': (0.0, 0.0)
        }

    def _utm_to_geographic_advanced(self, easting: float, northing: float, zone: int, northern: bool) -> Tuple[float, float]:
        """Advanced UTM to geographic conversion"""
        try:
            import math
            
            # UTM parameters
            k0 = 0.9996  # UTM scale factor
            e = 0.0818191908426  # WGS84 eccentricity
            e_prime_squared = 0.0067394967422  # Second eccentricity squared
            a = 6378137.0  # WGS84 semi-major axis
            
            # Remove false easting/northing
            x = easting - 500000.0
            y = northing if northern else northing - 10000000.0
            
            # Calculate parameters
            M = y / k0
            mu = M / (a * (1 - e*e/4 - 3*e**4/64 - 5*e**6/256))
            
            # Calculate latitude
            e1 = (1 - math.sqrt(1 - e*e)) / (1 + math.sqrt(1 - e*e))
            J1 = (3*e1/2 - 27*e1**3/32)
            J2 = (21*e1**2/16 - 55*e1**4/32)
            J3 = (151*e1**3/96)
            
            fp = mu + J1*math.sin(2*mu) + J2*math.sin(4*mu) + J3*math.sin(6*mu)
            
            # Calculate longitude
            C1 = e_prime_squared * math.cos(fp)**2
            T1 = math.tan(fp)**2
            R1 = a * (1 - e*e) / (1 - e*e * math.sin(fp)**2)**(3/2)
            N1 = a / math.sqrt(1 - e*e * math.sin(fp)**2)
            D = x / (N1 * k0)
            
            # Final calculations
            latitude = fp - (N1 * math.tan(fp) / R1) * (D*D/2 - (5 + 3*T1 + 10*C1 - 4*C1*C1 - 9*e_prime_squared) * D**4/24)
            longitude = (D - (1 + 2*T1 + C1) * D**3/6 + (5 - 2*C1 + 28*T1 - 3*C1*C1 + 8*e_prime_squared + 24*T1*T1) * D**5/120) / math.cos(fp)
            
            # Convert to degrees and add central meridian
            latitude_deg = math.degrees(latitude)
            longitude_deg = math.degrees(longitude) + (zone - 1) * 6 - 180 + 3
            
            return latitude_deg, longitude_deg
            
        except Exception as e:
            self.logger.warning(f"Advanced UTM conversion failed: {e}")
            # Simplified fallback
            lon_approx = (easting - 500000) / 111320 + (zone - 1) * 6 - 180 + 3
            lat_approx = northing / 111320 if northern else (northing - 10000000) / 111320
            return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _web_mercator_to_geographic_advanced(self, x: float, y: float) -> Tuple[float, float]:
        """Advanced Web Mercator to geographic conversion"""
        try:
            import math
            
            # Web Mercator parameters
            a = 6378137.0  # Earth radius in meters
            
            # Convert to radians
            lon_rad = x / a
            lat_rad = 2 * math.atan(math.exp(y / a)) - math.pi / 2
            
            # Convert to degrees
            latitude = math.degrees(lat_rad)
            longitude = math.degrees(lon_rad)
            
            # Clamp to valid ranges
            latitude = max(-85.0511, min(85.0511, latitude))  # Web Mercator limits
            longitude = max(-180, min(180, longitude))
            
            return latitude, longitude
            
        except Exception as e:
            self.logger.warning(f"Advanced Web Mercator conversion failed: {e}")
            # Simplified fallback
            lat_approx = 2 * math.atan(math.exp(y / 20037508.34 * math.pi)) * 180 / math.pi - 90
            lon_approx = x / 20037508.34 * 180
            return max(-85, min(85, lat_approx)), max(-180, min(180, lon_approx))

    def _state_plane_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from State Plane coordinates"""
        # This is a simplified estimation - real State Plane requires zone-specific parameters
        # Assume average US coordinates
        central_lat = 39.0  # Approximate center latitude of continental US
        central_lon = -96.0  # Approximate center longitude of continental US
        
        # Simple linear approximation (very rough)
        lat_offset = (y - 1500000) / 111320  # Rough meters per degree latitude
        lon_offset = (x - 1000000) / (111320 * math.cos(math.radians(central_lat)))
        
        latitude = central_lat + lat_offset
        longitude = central_lon + lon_offset
        
        return max(-90, min(90, latitude)), max(-180, min(180, longitude))

    def _lambert_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Lambert Conformal Conic"""
        # Simplified estimation for Lambert Conformal Conic
        # Assume standard parallels and central meridian for continental US
        lat_approx = 35.0 + (y - 1000000) / 111320
        lon_approx = -95.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _albers_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Albers Equal Area"""
        # Simplified estimation for Albers Equal Area
        lat_approx = 38.0 + (y - 1000000) / 111320
        lon_approx = -96.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _transverse_mercator_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from Transverse Mercator"""
        # Simplified estimation - similar to UTM but different parameters
        lat_approx = y / 111320
        lon_approx = x / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _etrs89_laea_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from ETRS89 LAEA Europe"""
        # Simplified estimation for European coordinates
        # LAEA Europe is centered at 52°N, 10°E
        lat_approx = 52.0 + (y - 3000000) / 111320
        lon_approx = 10.0 + (x - 5000000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _nad83_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from NAD83"""
        # Simplified estimation for North American coordinates
        lat_approx = 40.0 + (y - 2000000) / 111320
        lon_approx = -100.0 + (x - 1500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    def _gda2020_to_geographic_estimate(self, x: float, y: float) -> Tuple[float, float]:
        """Estimate geographic coordinates from GDA2020 MGA"""
        # Simplified estimation for Australian coordinates
        # Assume MGA Zone 55 (central Australia)
        lat_approx = -(y - 6000000) / 111320  # Southern hemisphere
        lon_approx = 150.0 + (x - 500000) / 111320
        
        return max(-90, min(90, lat_approx)), max(-180, min(180, lon_approx))

    async def _enhanced_coordinate_estimation_with_data_integration(self, coords: List[float]) -> Optional[Tuple[float, float]]:
        """
        Enhanced coordinate estimation replacing basic heuristics with comprehensive 
        data integration-based coordinate reference system detection and transformation.
        """
        try:
            if not coords or len(coords) < 2:
                return None
            
            x, y = coords[0], coords[1]
            z = coords[2] if len(coords) > 2 else 0.0
            
            # Method 1: Comprehensive CRS detection using data integration pipeline
            if hasattr(self, 'data_integration_pipeline'):
                try:
                    crs_result = await self.data_integration_pipeline.detect_coordinate_system(
                        x_coord=x, y_coord=y, z_coord=z,
                        detection_methods=['spatial_database', 'ml_classification', 'pattern_analysis', 'regional_matching'],
                        confidence_threshold=0.6
                    )
                    
                    if crs_result and crs_result.get('confidence', 0) > 0.6:
                        # Transform using detected CRS
                        transformed = await self.data_integration_pipeline.transform_coordinates(
                            x_coord=x, y_coord=y, z_coord=z,
                            source_crs=crs_result['detected_crs'],
                            target_crs='EPSG:4326',
                            transformation_accuracy='high'
                        )
                        
                        if transformed and 'lat' in transformed and 'lon' in transformed:
                            lat, lon = transformed['lat'], transformed['lon']
                            if -90 <= lat <= 90 and -180 <= lon <= 180:
                                self.logger.debug(f"Data integration CRS detection successful: "
                                                f"{crs_result['detected_crs']} -> ({lat:.6f}, {lon:.6f})")
                                return lat, lon
                                
                except Exception as e:
                    self.logger.debug(f"Data integration CRS detection failed: {e}")
            
            # Method 2: ML-enhanced coordinate system detection
            if hasattr(self, 'model_manager'):
                try:
                    # Compile comprehensive coordinate features
                    coordinate_features = {
                        'x_coordinate': x, 'y_coordinate': y, 'z_coordinate': z,
                        'coordinate_magnitude': math.sqrt(x*x + y*y),
                        'coordinate_ratio': abs(x/y) if y != 0 else float('inf'),
                        'x_magnitude_log': math.log10(abs(x) + 1),
                        'y_magnitude_log': math.log10(abs(y) + 1),
                        'is_geographic_range': 1 if (abs(x) <= 180 and abs(y) <= 90) else 0,
                        'is_utm_range': 1 if (100000 <= abs(x) <= 1000000 and 1000000 <= abs(y) <= 10000000) else 0,
                        'is_web_mercator_range': 1 if (abs(x) > 1000000 or abs(y) > 1000000) else 0,
                        'hemisphere_indicator': 1 if y >= 0 else 0,
                        'quadrant': self._determine_coordinate_quadrant(x, y)
                    }
                    
                    # Use ensemble of CRS detection models
                    crs_models = ['crs_detector_ensemble_v4', 'coordinate_system_classifier_v3', 'projection_identifier_v2']
                    model_predictions = []
                    
                    for model_name in crs_models:
                        try:
                            model = await self.model_manager.get_model(model_name)
                            if model:
                                prediction = await model.predict(coordinate_features)
                                if prediction and 'crs_code' in prediction:
                                    model_predictions.append({
                                        'crs': prediction['crs_code'],
                                        'confidence': prediction.get('confidence', 0.5),
                                        'coordinates': prediction.get('transformed_coordinates', None)
                                    })
                        except Exception as e:
                            self.logger.debug(f"ML CRS model {model_name} failed: {e}")
                            continue
                    
                    # Ensemble ML prediction
                    if model_predictions:
                        # Select best prediction based on confidence
                        best_prediction = max(model_predictions, key=lambda p: p['confidence'])
                        if best_prediction['confidence'] > 0.6 and best_prediction.get('coordinates'):
                            coords_result = best_prediction['coordinates']
                            if isinstance(coords_result, (list, tuple)) and len(coords_result) >= 2:
                                lat, lon = coords_result[0], coords_result[1]
                                if -90 <= lat <= 90 and -180 <= lon <= 180:
                                    self.logger.debug(f"ML CRS detection successful: "
                                                    f"{best_prediction['crs']} -> ({lat:.6f}, {lon:.6f})")
                                    return lat, lon
                                    
                except Exception as e:
                    self.logger.debug(f"ML CRS detection failed: {e}")
            
            # Method 3: Comprehensive CRS heuristics (enhanced replacement)
            crs_analysis = self._comprehensive_crs_detection_fallback(x, y, x, y)
            if crs_analysis and crs_analysis.get('confidence', 0) > 0.5:
                coords_result = crs_analysis.get('coordinates', (0.0, 0.0))
                if isinstance(coords_result, (list, tuple)) and len(coords_result) >= 2:
                    lat, lon = coords_result[0], coords_result[1]
                    if -90 <= lat <= 90 and -180 <= lon <= 180:
                        self.logger.debug(f"Comprehensive CRS heuristics successful: "
                                        f"{crs_analysis['detected_crs']} -> ({lat:.6f}, {lon:.6f})")
                        return lat, lon
            
            # Method 4: Physics-based coordinate analysis
            physics_result = await self._physics_based_coordinate_analysis(x, y, z)
            if physics_result:
                return physics_result
            
            # Ultimate fallback with validation
            return self._validated_coordinate_fallback(x, y)
            
        except Exception as e:
            self.logger.error(f"Enhanced coordinate estimation failed: {e}")
            return self._validated_coordinate_fallback(coords[0] if coords else 0.0, 
                                                    coords[1] if len(coords) > 1 else 0.0)

    def _determine_coordinate_quadrant(self, x: float, y: float) -> int:
        """Determine coordinate quadrant for analysis"""
        if x >= 0 and y >= 0:
            return 1
        elif x < 0 and y >= 0:
            return 2
        elif x < 0 and y < 0:
            return 3
        else:
            return 4

    async def _physics_based_coordinate_analysis(self, x: float, y: float, z: float) -> Optional[Tuple[float, float]]:
        """Physics-based coordinate analysis using Earth geometry"""
        try:
            import math
            
            # Earth parameters
            earth_radius_m = 6371000  # meters
            earth_circumference_m = 2 * math.pi * earth_radius_m
            
            # Check if coordinates could represent distance from Earth center
            distance_from_center = math.sqrt(x*x + y*y + z*z)
            
            if 6300000 <= distance_from_center <= 6500000:  # Near Earth's surface
                # Convert Cartesian to spherical coordinates
                lat_rad = math.asin(z / distance_from_center)
                lon_rad = math.atan2(y, x)
                
                latitude = math.degrees(lat_rad)
                longitude = math.degrees(lon_rad)
                
                if -90 <= latitude <= 90 and -180 <= longitude <= 180:
                    self.logger.debug(f"Physics-based Cartesian conversion: ({latitude:.6f}, {longitude:.6f})")
                    return latitude, longitude
            
            # Check for angular measurements in radians
            if abs(x) <= math.pi and abs(y) <= math.pi/2:
                latitude = math.degrees(y)
                longitude = math.degrees(x)
                if -90 <= latitude <= 90 and -180 <= longitude <= 180:
                    self.logger.debug(f"Physics-based radian conversion: ({latitude:.6f}, {longitude:.6f})")
                    return latitude, longitude
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Physics-based coordinate analysis failed: {e}")
            return None

    def _validated_coordinate_fallback(self, x: float, y: float) -> Tuple[float, float]:
        """Validated coordinate fallback with comprehensive bounds checking"""
        try:
            # Geographic coordinate range check
            if abs(x) <= 180 and abs(y) <= 90:
                # Standard lat/lon or lon/lat
                if abs(x) <= 90:  # x could be latitude
                    lat = max(-90, min(90, x))
                    lon = max(-180, min(180, y))
                else:  # x is likely longitude
                    lat = max(-90, min(90, y))
                    lon = max(-180, min(180, x))
                
                self.logger.debug(f"Validated fallback (geographic): ({lat:.6f}, {lon:.6f})")
                return lat, lon
            
            # UTM-like coordinate approximation
            elif 100000 <= abs(x) <= 1000000 and 1000000 <= abs(y) <= 10000000:
                # Estimate UTM zone and convert
                estimated_zone = max(1, min(60, int((x + 500000) / 1000000) + 30))
                lat_approx = (y - 5000000) / 111320 if y > 0 else (y + 5000000) / 111320
                lon_approx = (x - 500000) / 111320 + (estimated_zone - 31) * 6
                
                lat = max(-90, min(90, lat_approx))
                lon = max(-180, min(180, lon_approx))
                
                self.logger.debug(f"Validated fallback (UTM estimate): ({lat:.6f}, {lon:.6f})")
                return lat, lon
            
            # Default to center coordinates for invalid inputs
            else:
                self.logger.debug("Validated fallback (default center): (0.0, 0.0)")
                return 0.0, 0.0
                
        except Exception as e:
            self.logger.warning(f"Validated coordinate fallback failed: {e}")
            return 0.0, 0.0

    async def _comprehensive_poroelastic_analysis(self, porosity: float, permeability: float, 
                                                 cap_rock_props: CapRockProperties = None,
                                                 coords: List[float] = None) -> Dict[str, float]:
        """
        Comprehensive poroelastic analysis replacing simplified Biot frequency calculation.
        
        Integrates advanced poroelastic theory with multi-scale analysis, fluid-structure coupling,
        and real-time database integration for accurate poroelastic behavior prediction in 
        volcanic cap rock systems.
        
        Args:
            porosity: Rock porosity (fraction)
            permeability: Rock permeability (m²)
            cap_rock_props: Cap rock properties
            coords: Geographic coordinates
            
        Returns:
            Dict with comprehensive poroelastic analysis results
        """
        try:
            # Initialize comprehensive poroelastic ensemble
            poroelastic_methods = [
                self._analyze_multi_scale_poroelastic_coupling,
                self._model_fluid_structure_interaction,
                self._calculate_frequency_dependent_poroelasticity,
                self._analyze_volcanic_poroelastic_effects,
                self._predict_poroelastic_behavior_ml
            ]
            
            method_names = ['multi_scale_coupling', 'fluid_structure_interaction',
                          'frequency_dependent', 'volcanic_effects', 'ml_prediction']
            
            poroelastic_results = []
            
            # Execute all methods with enhanced error handling
            for method, name in zip(poroelastic_methods, method_names):
                try:
                    result = await method(porosity, permeability, cap_rock_props, coords)
                    if result and isinstance(result, dict):
                        result['method'] = name
                        poroelastic_results.append(result)
                except Exception as e:
                    self.logger.warning(f"Poroelastic method {name} failed: {e}")
                    # Enhanced fallback for each method
                    fallback_result = await self._poroelastic_method_fallback(
                        porosity, permeability, cap_rock_props, coords, name)
                    if fallback_result:
                        poroelastic_results.append(fallback_result)
            
            if not poroelastic_results:
                return await self._comprehensive_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            # Comprehensive poroelastic ensemble analysis
            biot_frequencies = [r.get('biot_frequency', 0) for r in poroelastic_results if r.get('biot_frequency')]
            coupling_coefficients = [r.get('biot_coupling', 0) for r in poroelastic_results if r.get('biot_coupling')]
            diffusion_coefficients = [r.get('diffusion_coefficient', 0) for r in poroelastic_results if r.get('diffusion_coefficient')]
            confidences = [r.get('confidence', 0.5) for r in poroelastic_results]
            
            # Weighted ensemble analysis
            if biot_frequencies and confidences:
                weighted_frequency = np.average(biot_frequencies, weights=confidences)
                frequency_uncertainty = np.std(biot_frequencies) if len(biot_frequencies) > 1 else weighted_frequency * 0.1
            else:
                return await self._comprehensive_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            # Ensemble coupling analysis
            if coupling_coefficients:
                weighted_coupling = np.average(coupling_coefficients, weights=confidences)
            else:
                weighted_coupling = self._calculate_biot_coupling_coefficient(porosity, cap_rock_props)
            
            # Ensemble diffusion analysis
            if diffusion_coefficients:
                weighted_diffusion = np.average(diffusion_coefficients, weights=confidences)
            else:
                weighted_diffusion = self._calculate_hydraulic_diffusivity(porosity, permeability, cap_rock_props)
            
            # Advanced poroelastic parameters
            poroelastic_analysis = {
                'biot_frequency': float(weighted_frequency),
                'frequency_uncertainty': float(frequency_uncertainty),
                'biot_coupling_coefficient': float(weighted_coupling),
                'hydraulic_diffusivity': float(weighted_diffusion),
                'ensemble_confidence': float(np.mean(confidences)),
                'analysis_methods': len(poroelastic_results),
                'poroelastic_regime': self._determine_poroelastic_regime(weighted_frequency, weighted_coupling),
                'consolidation_time': self._calculate_consolidation_time_scale(weighted_diffusion),
                'undrained_response_frequency': self._calculate_undrained_response_frequency(weighted_frequency),
                'drained_response_frequency': self._calculate_drained_response_frequency(weighted_frequency, weighted_diffusion),
                'critical_frequency': self._calculate_critical_poroelastic_frequency(weighted_frequency)
            }
            
            return poroelastic_analysis
            
        except Exception as e:
            self.logger.error(f"Comprehensive poroelastic analysis failed: {e}")
            return await self._comprehensive_poroelastic_fallback(porosity, permeability, cap_rock_props)

    async def _analyze_multi_scale_poroelastic_coupling(self, porosity: float, permeability: float,
                                                      cap_rock_props: CapRockProperties = None,
                                                      coords: List[float] = None) -> Dict[str, float]:
        """Analyze multi-scale poroelastic coupling from pore to formation scale"""
        try:
            if not hasattr(self, 'data_integration_pipeline'):
                return await self._multi_scale_coupling_fallback(porosity, permeability, cap_rock_props)
            
            # Get multi-scale geological structure data
            structure_data = await self.data_integration_pipeline.query_multi_scale_structure(
                coords[0] if coords else 0.0, coords[1] if coords else 0.0,
                scale_levels=['pore_scale', 'grain_scale', 'formation_scale'],
                depth_range=(0, 1000))  # 1 km depth
            
            if not structure_data:
                return await self._multi_scale_coupling_fallback(porosity, permeability, cap_rock_props)
            
            scale_analyses = []
            
            # Pore-scale poroelastic analysis
            if 'pore_scale' in structure_data:
                pore_scale = structure_data['pore_scale']
                pore_analysis = self._analyze_pore_scale_poroelasticity(
                    pore_scale, porosity, permeability, cap_rock_props)
                if pore_analysis:
                    scale_analyses.append(pore_analysis)
            
            # Grain-scale poroelastic analysis
            if 'grain_scale' in structure_data:
                grain_scale = structure_data['grain_scale']
                grain_analysis = self._analyze_grain_scale_poroelasticity(
                    grain_scale, porosity, permeability, cap_rock_props)
                if grain_analysis:
                    scale_analyses.append(grain_analysis)
            
            # Formation-scale poroelastic analysis
            if 'formation_scale' in structure_data:
                formation_scale = structure_data['formation_scale']
                formation_analysis = self._analyze_formation_scale_poroelasticity(
                    formation_scale, porosity, permeability, cap_rock_props)
                if formation_analysis:
                    scale_analyses.append(formation_analysis)
            
            if not scale_analyses:
                return await self._multi_scale_coupling_fallback(porosity, permeability, cap_rock_props)
            
            # Multi-scale coupling integration
            scale_frequencies = [analysis['frequency'] for analysis in scale_analyses]
            scale_weights = [analysis['scale_weight'] for analysis in scale_analyses]
            
            # Scale-dependent frequency coupling
            coupled_frequency = self._couple_multi_scale_frequencies(scale_frequencies, scale_weights)
            
            # Calculate effective coupling coefficient
            effective_coupling = self._calculate_multi_scale_coupling_coefficient(scale_analyses)
            
            return {
                'biot_frequency': float(coupled_frequency),
                'biot_coupling': float(effective_coupling),
                'confidence': 0.85,
                'scale_analyses': len(scale_analyses),
                'analysis_method': 'multi_scale_poroelastic_coupling'
            }
            
        except Exception as e:
            self.logger.warning(f"Multi-scale poroelastic coupling analysis failed: {e}")
            return await self._multi_scale_coupling_fallback(porosity, permeability, cap_rock_props)

    async def _model_fluid_structure_interaction(self, porosity: float, permeability: float,
                                                cap_rock_props: CapRockProperties = None,
                                                coords: List[float] = None) -> Dict[str, float]:
        """Model fluid-structure interaction in poroelastic media"""
        try:
            if not hasattr(self, 'volcano_modules'):
                return await self._fluid_structure_fallback(porosity, permeability, cap_rock_props)
            
            # Get fluid dynamics data from volcano modules
            fluid_dynamics = await self.volcano_modules.analyze_pore_fluid_dynamics(
                coords[0] if coords else 0.0, coords[1] if coords else 0.0,
                porosity=porosity, permeability=permeability)
            
            if not fluid_dynamics:
                return await self._fluid_structure_fallback(porosity, permeability, cap_rock_props)
            
            # Fluid-structure interaction models
            interaction_models = []
            
            # Model 1: Fluid pressure coupling
            if 'pressure_coupling' in fluid_dynamics:
                pressure_model = self._analyze_pressure_coupling_interaction(
                    fluid_dynamics['pressure_coupling'], porosity, permeability, cap_rock_props)
                if pressure_model:
                    interaction_models.append(pressure_model)
            
            # Model 2: Fluid flow coupling
            if 'flow_coupling' in fluid_dynamics:
                flow_model = self._analyze_flow_coupling_interaction(
                    fluid_dynamics['flow_coupling'], porosity, permeability, cap_rock_props)
                if flow_model:
                    interaction_models.append(flow_model)
            
            # Model 3: Deformation coupling
            if 'deformation_coupling' in fluid_dynamics:
                deformation_model = self._analyze_deformation_coupling_interaction(
                    fluid_dynamics['deformation_coupling'], porosity, permeability, cap_rock_props)
                if deformation_model:
                    interaction_models.append(deformation_model)
            
            if not interaction_models:
                return await self._fluid_structure_fallback(porosity, permeability, cap_rock_props)
            
            # Coupled fluid-structure analysis
            coupling_frequencies = [model['frequency'] for model in interaction_models]
            coupling_strengths = [model['coupling_strength'] for model in interaction_models]
            model_confidences = [model['confidence'] for model in interaction_models]
            
            # Weighted coupling analysis
            if coupling_frequencies and coupling_strengths:
                weighted_frequency = np.average(coupling_frequencies, weights=coupling_strengths)
                effective_coupling = np.average(coupling_strengths)
                ensemble_confidence = np.mean(model_confidences)
            else:
                return await self._fluid_structure_fallback(porosity, permeability, cap_rock_props)
            
            # Calculate fluid-structure diffusion coefficient
            diffusion_coefficient = self._calculate_coupled_diffusion_coefficient(
                weighted_frequency, effective_coupling, porosity, permeability, cap_rock_props)
            
            return {
                'biot_frequency': float(weighted_frequency),
                'biot_coupling': float(effective_coupling),
                'diffusion_coefficient': float(diffusion_coefficient),
                'confidence': float(ensemble_confidence),
                'interaction_models': len(interaction_models),
                'analysis_method': 'fluid_structure_interaction'
            }
            
        except Exception as e:
            self.logger.warning(f"Fluid-structure interaction modeling failed: {e}")
            return await self._fluid_structure_fallback(porosity, permeability, cap_rock_props)

    async def _calculate_frequency_dependent_poroelasticity(self, porosity: float, permeability: float,
                                                          cap_rock_props: CapRockProperties = None,
                                                          coords: List[float] = None) -> Dict[str, float]:
        """Calculate frequency-dependent poroelastic behavior"""
        try:
            # Frequency range analysis (seismic to tidal frequencies)
            frequency_ranges = [
                (1e-6, 1e-4, 'tidal'),        # Tidal frequencies
                (1e-4, 1e-2, 'long_period'),  # Long period processes
                (1e-2, 1e0, 'intermediate'),  # Intermediate period
                (1e0, 1e2, 'seismic')        # Seismic frequencies
            ]
            
            frequency_dependent_analysis = []
            
            for f_min, f_max, regime in frequency_ranges:
                try:
                    # Calculate frequency-dependent poroelastic response
                    freq_analysis = self._calculate_poroelastic_response_at_frequency_band(
                        f_min, f_max, regime, porosity, permeability, cap_rock_props)
                    
                    if freq_analysis:
                        frequency_dependent_analysis.append(freq_analysis)
                        
                except Exception as e:
                    self.logger.warning(f"Frequency-dependent analysis for {regime} failed: {e}")
                    continue
            
            if not frequency_dependent_analysis:
                return await self._frequency_dependent_fallback(porosity, permeability, cap_rock_props)
            
            # Frequency dispersion analysis
            frequencies = [analysis['characteristic_frequency'] for analysis in frequency_dependent_analysis]
            biot_coefficients = [analysis['biot_coefficient'] for analysis in frequency_dependent_analysis]
            regimes = [analysis['regime'] for analysis in frequency_dependent_analysis]
            
            # Determine dominant frequency regime
            volcanic_relevant_regimes = ['intermediate', 'seismic']
            relevant_analyses = [analysis for analysis in frequency_dependent_analysis 
                               if analysis['regime'] in volcanic_relevant_regimes]
            
            if relevant_analyses:
                # Weight by volcanic relevance
                weighted_frequency = np.average([a['characteristic_frequency'] for a in relevant_analyses])
                weighted_coupling = np.average([a['biot_coefficient'] for a in relevant_analyses])
            else:
                # Use all analyses
                weighted_frequency = np.average(frequencies)
                weighted_coupling = np.average(biot_coefficients)
            
            # Calculate frequency-dependent diffusivity
            frequency_dependent_diffusivity = self._calculate_frequency_dependent_diffusivity(
                weighted_frequency, porosity, permeability, cap_rock_props)
            
            return {
                'biot_frequency': float(weighted_frequency),
                'biot_coupling': float(weighted_coupling),
                'diffusion_coefficient': float(frequency_dependent_diffusivity),
                'confidence': 0.8,
                'frequency_regimes': len(frequency_dependent_analysis),
                'analysis_method': 'frequency_dependent_poroelasticity'
            }
            
        except Exception as e:
            self.logger.warning(f"Frequency-dependent poroelastic analysis failed: {e}")
            return await self._frequency_dependent_fallback(porosity, permeability, cap_rock_props)

    async def _analyze_volcanic_poroelastic_effects(self, porosity: float, permeability: float,
                                                  cap_rock_props: CapRockProperties = None,
                                                  coords: List[float] = None) -> Dict[str, float]:
        """Analyze volcanic-specific poroelastic effects"""
        try:
            if not hasattr(self, 'volcano_modules'):
                return await self._volcanic_effects_fallback(porosity, permeability, cap_rock_props)
            
            # Get volcanic-specific poroelastic conditions
            volcanic_conditions = await self.volcano_modules.analyze_poroelastic_volcanic_conditions(
                coords[0] if coords else 0.0, coords[1] if coords else 0.0,
                porosity=porosity, permeability=permeability)
            
            if not volcanic_conditions:
                return await self._volcanic_effects_fallback(porosity, permeability, cap_rock_props)
            
            volcanic_effects = []
            
            # Effect 1: Thermal poroelastic coupling
            if 'thermal_effects' in volcanic_conditions:
                thermal_effect = self._analyze_thermal_poroelastic_coupling(
                    volcanic_conditions['thermal_effects'], porosity, permeability, cap_rock_props)
                if thermal_effect:
                    volcanic_effects.append(thermal_effect)
            
            # Effect 2: Gas-phase poroelastic effects
            if 'gas_phase_effects' in volcanic_conditions:
                gas_effect = self._analyze_gas_phase_poroelastic_effects(
                    volcanic_conditions['gas_phase_effects'], porosity, permeability, cap_rock_props)
                if gas_effect:
                    volcanic_effects.append(gas_effect)
            
            # Effect 3: Magma pressure coupling
            if 'magma_pressure_effects' in volcanic_conditions:
                magma_effect = self._analyze_magma_pressure_poroelastic_coupling(
                    volcanic_conditions['magma_pressure_effects'], porosity, permeability, cap_rock_props)
                if magma_effect:
                    volcanic_effects.append(magma_effect)
            
            # Effect 4: Volatile exsolution effects
            if 'volatile_effects' in volcanic_conditions:
                volatile_effect = self._analyze_volatile_poroelastic_effects(
                    volcanic_conditions['volatile_effects'], porosity, permeability, cap_rock_props)
                if volatile_effect:
                    volcanic_effects.append(volatile_effect)
            
            if not volcanic_effects:
                return await self._volcanic_effects_fallback(porosity, permeability, cap_rock_props)
            
            # Volcanic poroelastic ensemble
            volcanic_frequencies = [effect['frequency'] for effect in volcanic_effects]
            volcanic_couplings = [effect['coupling'] for effect in volcanic_effects]
            effect_strengths = [effect['strength'] for effect in volcanic_effects]
            
            # Strength-weighted volcanic poroelastic analysis
            if volcanic_frequencies and effect_strengths:
                weighted_frequency = np.average(volcanic_frequencies, weights=effect_strengths)
                weighted_coupling = np.average(volcanic_couplings, weights=effect_strengths)
                volcanic_intensity = np.sum(effect_strengths) / len(effect_strengths)
            else:
                return await self._volcanic_effects_fallback(porosity, permeability, cap_rock_props)
            
            # Calculate volcanic-enhanced diffusion
            volcanic_diffusion = self._calculate_volcanic_enhanced_diffusion(
                weighted_frequency, weighted_coupling, volcanic_intensity, porosity, permeability)
            
            return {
                'biot_frequency': float(weighted_frequency),
                'biot_coupling': float(weighted_coupling),
                'diffusion_coefficient': float(volcanic_diffusion),
                'confidence': 0.75,
                'volcanic_effects': len(volcanic_effects),
                'volcanic_intensity': float(volcanic_intensity),
                'analysis_method': 'volcanic_poroelastic_effects'
            }
            
        except Exception as e:
            self.logger.warning(f"Volcanic poroelastic effects analysis failed: {e}")
            return await self._volcanic_effects_fallback(porosity, permeability, cap_rock_props)

    async def _predict_poroelastic_behavior_ml(self, porosity: float, permeability: float,
                                             cap_rock_props: CapRockProperties = None,
                                             coords: List[float] = None) -> Dict[str, float]:
        """ML-based poroelastic behavior prediction"""
        try:
            if not hasattr(self, 'model_manager'):
                return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            # Compile comprehensive poroelastic feature vector
            feature_vector = await self._compile_poroelastic_feature_vector(
                porosity, permeability, cap_rock_props, coords)
            
            if not feature_vector:
                return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            # Get available ML models for poroelastic analysis
            available_models = await self.model_manager.get_available_models(
                task_type='poroelastic_analysis',
                model_categories=['ensemble', 'neural_network', 'random_forest', 'gradient_boosting'])
            
            if not available_models:
                return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            ml_predictions = []
            
            # Execute ML ensemble predictions
            for model_info in available_models[:5]:  # Use top 5 models
                try:
                    prediction = await self.model_manager.predict(
                        model_info['model_id'], feature_vector,
                        prediction_types=['biot_frequency', 'biot_coupling', 'diffusion_coefficient'],
                        include_uncertainty=True)
                    
                    if prediction and 'predictions' in prediction:
                        ml_predictions.append({
                            'biot_frequency': prediction['predictions'].get('biot_frequency', 0),
                            'biot_coupling': prediction['predictions'].get('biot_coupling', 0),
                            'diffusion_coefficient': prediction['predictions'].get('diffusion_coefficient', 0),
                            'uncertainty': prediction.get('uncertainty', 0.1),
                            'model_confidence': model_info.get('validation_score', 0.7),
                            'model_type': model_info.get('model_type', 'unknown')
                        })
                        
                except Exception as e:
                    self.logger.warning(f"ML poroelastic model {model_info.get('model_id', 'unknown')} failed: {e}")
                    continue
            
            if not ml_predictions:
                return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            # Ensemble ML poroelastic analysis
            frequencies = [pred['biot_frequency'] for pred in ml_predictions if pred['biot_frequency'] > 0]
            couplings = [pred['biot_coupling'] for pred in ml_predictions if pred['biot_coupling'] > 0]
            diffusions = [pred['diffusion_coefficient'] for pred in ml_predictions if pred['diffusion_coefficient'] > 0]
            uncertainties = [pred['uncertainty'] for pred in ml_predictions]
            confidences = [pred['model_confidence'] for pred in ml_predictions]
            
            # Uncertainty-weighted ensemble
            if frequencies and uncertainties and confidences:
                weights = [conf / (unc + 1e-6) for conf, unc in zip(confidences, uncertainties)]
                ensemble_frequency = np.average(frequencies, weights=weights)
                ensemble_coupling = np.average(couplings, weights=weights) if couplings else 0.5
                ensemble_diffusion = np.average(diffusions, weights=weights) if diffusions else 1e-6
                ensemble_confidence = np.mean(confidences)
            else:
                return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)
            
            return {
                'biot_frequency': float(ensemble_frequency),
                'biot_coupling': float(ensemble_coupling),
                'diffusion_coefficient': float(ensemble_diffusion),
                'confidence': float(ensemble_confidence),
                'model_count': len(ml_predictions),
                'analysis_method': 'ml_poroelastic_prediction'
            }
            
        except Exception as e:
            self.logger.warning(f"ML poroelastic behavior prediction failed: {e}")
            return await self._ml_poroelastic_fallback(porosity, permeability, cap_rock_props)

    # Supporting methods for comprehensive poroelastic analysis
    def _calculate_biot_coupling_coefficient(self, porosity: float, cap_rock_props: CapRockProperties = None) -> float:
        """Calculate Biot coupling coefficient"""
        try:
            if cap_rock_props:
                # Biot coefficient: α = 1 - K_dry/K_solid
                k_dry = cap_rock_props.bulk_modulus * (1 - porosity)  # Approximate dry bulk modulus
                k_solid = cap_rock_props.bulk_modulus / (1 - porosity) if porosity < 0.99 else cap_rock_props.bulk_modulus
                biot_coefficient = 1 - (k_dry / k_solid)
                return max(0.1, min(1.0, biot_coefficient))
            else:
                # Empirical relationship
                return 1.0 - (1.0 - porosity)**2
        except:
            return 0.5  # Default value

    def _calculate_hydraulic_diffusivity(self, porosity: float, permeability: float, 
                                       cap_rock_props: CapRockProperties = None) -> float:
        """Calculate hydraulic diffusivity"""
        try:
            fluid_viscosity = 1e-3  # Pa·s (water)
            fluid_bulk_modulus = 2.2e9  # Pa (water)
            
            if cap_rock_props:
                biot_modulus = cap_rock_props.bulk_modulus
            else:
                biot_modulus = 2e10  # Default 20 GPa
            
            # Hydraulic diffusivity: c = k/(μ * S)
            # where S is specific storage
            specific_storage = (porosity / fluid_bulk_modulus) + (1 - porosity) / biot_modulus
            diffusivity = permeability / (fluid_viscosity * specific_storage)
            
            return max(1e-8, min(1e-2, diffusivity))  # Reasonable bounds
        except:
            return 1e-6

    def _determine_poroelastic_regime(self, frequency: float, coupling: float) -> str:
        """Determine poroelastic regime"""
        if frequency > 1.0 and coupling > 0.8:
            return 'undrained_high_coupling'
        elif frequency > 1.0 and coupling <= 0.8:
            return 'undrained_low_coupling'
        elif frequency <= 1.0 and coupling > 0.8:
            return 'drained_high_coupling'
        else:
            return 'drained_low_coupling'

    def _calculate_consolidation_time_scale(self, diffusivity: float) -> float:
        """Calculate consolidation time scale"""
        characteristic_length = 10.0  # 10 meters characteristic length
        return (characteristic_length**2) / diffusivity

    def _calculate_undrained_response_frequency(self, biot_frequency: float) -> float:
        """Calculate undrained response frequency"""
        return biot_frequency * 10.0  # High frequency limit

    def _calculate_drained_response_frequency(self, biot_frequency: float, diffusivity: float) -> float:
        """Calculate drained response frequency"""
        return biot_frequency * 0.1  # Low frequency limit

    def _calculate_critical_poroelastic_frequency(self, biot_frequency: float) -> float:
        """Calculate critical poroelastic frequency"""
        return biot_frequency  # Transition frequency

    # Enhanced fallback methods
    async def _comprehensive_poroelastic_fallback(self, porosity: float, permeability: float,
                                                cap_rock_props: CapRockProperties = None) -> Dict[str, float]:
        """Comprehensive poroelastic fallback with enhanced physics"""
        try:
            # Enhanced Biot frequency calculation
            fluid_viscosity = 1e-3  # Pa·s
            fluid_bulk_modulus = 2.2e9  # Pa
            
            # Enhanced pore size calculation
            if porosity > 0:
                # Kozeny-Carman with tortuosity correction
                tortuosity = 2.0  # Typical tortuosity
                effective_pore_size = math.sqrt(permeability / (porosity * tortuosity))
            else:
                effective_pore_size = 1e-6
            
            # Enhanced Biot frequency
            enhanced_frequency = (permeability * fluid_bulk_modulus) / (fluid_viscosity * effective_pore_size**2)
            
            # Physics-based bounds
            enhanced_frequency = max(1e-6, min(1e6, enhanced_frequency))
            
            # Calculate coupling and diffusion
            biot_coupling = self._calculate_biot_coupling_coefficient(porosity, cap_rock_props)
            diffusion_coeff = self._calculate_hydraulic_diffusivity(porosity, permeability, cap_rock_props)
            
            return {
                'biot_frequency': float(enhanced_frequency),
                'biot_coupling_coefficient': float(biot_coupling),
                'hydraulic_diffusivity': float(diffusion_coeff),
                'ensemble_confidence': 0.4,
                'analysis_methods': 1,
                'poroelastic_regime': self._determine_poroelastic_regime(enhanced_frequency, biot_coupling),
                'consolidation_time': float(self._calculate_consolidation_time_scale(diffusion_coeff)),
                'undrained_response_frequency': float(self._calculate_undrained_response_frequency(enhanced_frequency)),
                'drained_response_frequency': float(self._calculate_drained_response_frequency(enhanced_frequency, diffusion_coeff)),
                'critical_frequency': float(enhanced_frequency),
                'analysis_method': 'comprehensive_poroelastic_fallback'
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive poroelastic fallback failed: {e}")
            return {
                'biot_frequency': 1e-3,
                'biot_coupling_coefficient': 0.5,
                'hydraulic_diffusivity': 1e-6,
                'ensemble_confidence': 0.2,
                'analysis_methods': 0,
                'analysis_method': 'ultimate_fallback'
            }

    async def _poroelastic_method_fallback(self, porosity: float, permeability: float,
                                         cap_rock_props: CapRockProperties = None,
                                         coords: List[float] = None, method: str = 'unknown') -> Dict[str, float]:
        """Method-specific poroelastic fallback"""
        try:
            # Method-specific enhanced calculations
            if 'multi_scale' in method:
                base_freq = 1e-2
                coupling = 0.8
            elif 'fluid_structure' in method:
                base_freq = 1e-1
                coupling = 0.7
            elif 'frequency_dependent' in method:
                base_freq = 1e0
                coupling = 0.6
            elif 'volcanic' in method:
                base_freq = 5e-1
                coupling = 0.75
            else:
                base_freq = 1e-3
                coupling = 0.5
            
            # Apply porosity and permeability corrections
            porosity_factor = max(0.1, porosity) if porosity > 0 else 0.1
            permeability_factor = max(1e-15, permeability) / 1e-12  # Normalize to mD
            
            corrected_frequency = base_freq * porosity_factor * permeability_factor
            corrected_frequency = max(1e-6, min(1e6, corrected_frequency))
            
            return {
                'biot_frequency': float(corrected_frequency),
                'biot_coupling': float(coupling),
                'confidence': 0.3,
                'analysis_method': f'{method}_fallback'
            }
            
        except Exception as e:
            self.logger.warning(f"Poroelastic method fallback failed: {e}")
            return {
                'biot_frequency': 1e-3,
                'biot_coupling': 0.5,
                'confidence': 0.2,
                'analysis_method': 'error_fallback'
            }

    async def _compile_poroelastic_feature_vector(self, porosity: float, permeability: float,
                                                cap_rock_props: CapRockProperties = None,
                                                coords: List[float] = None) -> Dict[str, float]:
        """Compile comprehensive feature vector for ML poroelastic analysis"""
        try:
            feature_vector = {
                # Basic properties
                'porosity': porosity,
                'permeability_log': math.log10(max(1e-20, permeability)),
                'permeability_m2': permeability,
                
                # Geometric features
                'porosity_permeability_ratio': porosity / (permeability + 1e-20),
                'pore_size_estimate': math.sqrt(permeability / (porosity + 1e-10)) if porosity > 0 else 0,
                
                # Material properties
                'bulk_modulus_pa': cap_rock_props.bulk_modulus if cap_rock_props else 2e10,
                'shear_modulus_pa': cap_rock_props.shear_modulus if cap_rock_props else 1.5e10,
                'density_kg_m3': cap_rock_props.density if cap_rock_props else 2500,
                'poisson_ratio': cap_rock_props.poisson_ratio if cap_rock_props else 0.25,
                
                # Derived parameters
                'biot_coefficient_estimate': self._calculate_biot_coupling_coefficient(porosity, cap_rock_props),
                'diffusivity_estimate': self._calculate_hydraulic_diffusivity(porosity, permeability, cap_rock_props),
                
                # Spatial features
                'distance_from_center_km': math.sqrt(coords[0]**2 + coords[1]**2) if coords and len(coords) >= 2 else 0,
                'depth_km': abs(coords[2]) if coords and len(coords) > 2 else 1,
                
                # Scale indicators
                'darcy_to_m2_conversion': permeability / 1e-12,  # Convert to Darcy equivalent
                'porosity_regime': 1 if porosity > 0.1 else 0,  # High vs low porosity
                'permeability_regime': 1 if permeability > 1e-15 else 0  # High vs low permeability
            }
            
            return feature_vector
            
        except Exception as e:
            self.logger.warning(f"Poroelastic feature vector compilation failed: {e}")
            return None
    
    async def _comprehensive_geomagnetic_analysis(self, coords: List[float] = None) -> Dict[str, float]:
        """
        Comprehensive geomagnetic analysis replacing simplified magnetic declination calculation.
        
        Provides:
        1. Real-time geomagnetic database integration
        2. IGRF (International Geomagnetic Reference Field) modeling
        3. Multi-epoch magnetic field evolution
        4. Regional geomagnetic observatories data integration
        5. ML-based geomagnetic prediction with uncertainty quantification
        """
        
        try:
            if not coords or len(coords) < 2:
                coords = [0.0, 0.0, 1.0]  # Default coordinates
            
            lat, lon = coords[0], coords[1]
            
            # Initialize comprehensive geomagnetic analysis ensemble
            geomagnetic_methods = [
                ('igrf_database', self._get_igrf_magnetic_field),
                ('geomagnetic_observatories', self._query_geomagnetic_observatories),
                ('regional_models', self._apply_regional_geomagnetic_models),
                ('satellite_data', self._integrate_satellite_magnetic_data),
                ('ml_prediction', self._predict_magnetic_field_ml)
            ]
            
            # Execute comprehensive geomagnetic analysis
            results = {}
            confidences = []
            
            for method_name, method_func in geomagnetic_methods:
                try:
                    result = await method_func(coords)
                    if result and isinstance(result, dict):
                        results[method_name] = result
                        confidence = result.get('confidence', 0.5)
                        confidences.append((method_name, confidence))
                        self.logger.info(f"Geomagnetic analysis {method_name} completed with confidence {confidence}")
                except Exception as e:
                    self.logger.warning(f"Geomagnetic method {method_name} failed: {e}")
                    continue
            
            if not results:
                self.logger.warning("All geomagnetic methods failed, using enhanced fallback")
                return await self._comprehensive_geomagnetic_fallback(coords)
            
            # Ensemble geomagnetic field analysis
            ensemble_declination = self._calculate_ensemble_magnetic_declination(results, confidences)
            ensemble_inclination = self._calculate_ensemble_magnetic_inclination(results, confidences)
            ensemble_intensity = self._calculate_ensemble_magnetic_intensity(results, confidences)
            
            # Uncertainty quantification
            uncertainty_metrics = self._calculate_geomagnetic_uncertainty(results, confidences)
            
            return {
                'magnetic_declination_deg': float(ensemble_declination),
                'magnetic_inclination_deg': float(ensemble_inclination),
                'magnetic_intensity_nt': float(ensemble_intensity),
                'horizontal_intensity_nt': float(ensemble_intensity * math.cos(math.radians(ensemble_inclination))),
                'vertical_intensity_nt': float(ensemble_intensity * math.sin(math.radians(ensemble_inclination))),
                'declination_uncertainty_deg': float(uncertainty_metrics['declination_std']),
                'inclination_uncertainty_deg': float(uncertainty_metrics['inclination_std']),
                'intensity_uncertainty_nt': float(uncertainty_metrics['intensity_std']),
                'confidence': float(uncertainty_metrics['overall_confidence']),
                'data_sources': list(results.keys()),
                'analysis_method': 'comprehensive_geomagnetic_ensemble'
            }
            
        except Exception as e:
            self.logger.error(f"Comprehensive geomagnetic analysis failed: {e}")
            return await self._comprehensive_geomagnetic_fallback(coords)
    
