    async def _integrate_geological_stress_sources(self, lat: float, lon: float) -> Dict[str, Any]:
        """Multi-source geological stress field integration"""
        try:
            import numpy as np
            
            stress_sources = {}
            
            # Topographic stress (elevation-based)
            elevation_data = await self._query_elevation_data(lat, lon)
            if elevation_data:
                elevation_m = elevation_data.get('elevation_m', 0.0)
                topo_stress = min(15.0, max(0.0, elevation_m / 400.0))  # MPa per 400m elevation
                stress_sources['topographic_stress_mpa'] = topo_stress
            
            # Gravitational anomaly stress
            gravity_data = await self._query_gravity_anomaly_data(lat, lon)
            if gravity_data:
                gravity_anomaly = gravity_data.get('bouguer_anomaly_mgal', 0.0)
                gravity_stress = abs(gravity_anomaly) / 50.0  # Rough conversion
                stress_sources['gravity_anomaly_stress_mpa'] = min(10.0, gravity_stress)
            
            # Regional heat flow stress
            heat_flow_data = await self._query_heat_flow_data(lat, lon)  
            if heat_flow_data:
                heat_flow = heat_flow_data.get('surface_heat_flow_mw_m2', 60.0)
                thermal_stress = max(0.0, (heat_flow - 40.0) / 10.0)  # Above normal heat flow
                stress_sources['thermal_stress_mpa'] = min(12.0, thermal_stress)
            
            # Crustal thickness variation stress
            crustal_data = await self._query_crustal_thickness_data(lat, lon)
            if crustal_data:
                thickness_km = crustal_data.get('crustal_thickness_km', 35.0)
                thickness_deviation = abs(thickness_km - 35.0)  # Deviation from average
                crustal_stress = thickness_deviation / 5.0  # MPa per 5km deviation
                stress_sources['crustal_thickness_stress_mpa'] = min(8.0, crustal_stress)
            
            return {
                'success': True,
                'stress_sources': stress_sources,
                'integration_confidence': 0.75
            }
            
        except Exception as e:
            self.logger.error(f"Geological stress source integration failed: {e}")
            return {'success': False}
    
