    async def _tier3_textural_structural_classification(self, cap_rock_props: CapRockProperties) -> Dict:
        """Tier 3: Textural and structural classification database"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.getenv('POSTGRES_HOST', 'localhost'),
                database='geological_structures',
                user=os.getenv('POSTGRES_USER', 'postgres'),
                password=os.getenv('POSTGRES_PASSWORD', ''),
                port=int(os.getenv('POSTGRES_PORT', 5432))
            )
            
            async with PostgreSQLGISManager(db_config) as db:
                # Query textural classification database
                texture_query = """
                    SELECT rock_classification, confidence_score, texture_type, structure_type
                    FROM rock_texture_classification
                    WHERE lithology_group = %s
                    AND porosity BETWEEN %s AND %s
                    AND fracture_density BETWEEN %s AND %s
                    ORDER BY confidence_score DESC
                    LIMIT 3;
                """
                
                porosity_range = 0.05
                fracture_range = cap_rock_props.fracture_density_per_m3 * 0.2
                
                texture_results = await db.fetch_all(
                    texture_query,
                    cap_rock_props.lithology.lower(),
                    max(0, cap_rock_props.porosity - porosity_range),
                    cap_rock_props.porosity + porosity_range,
                    max(0, cap_rock_props.fracture_density_per_m3 - fracture_range),
                    cap_rock_props.fracture_density_per_m3 + fracture_range
                )
                
                if texture_results:
                    best_result = texture_results[0]
                    classification = best_result['rock_classification']
                    confidence = best_result['confidence_score']
                    
                    return {
                        'success': True,
                        'classification': classification,
                        'confidence': float(confidence),
                        'method': 'textural_structural_database',
                        'texture_type': best_result['texture_type'],
                        'structure_type': best_result['structure_type']
                    }
            
        except Exception as e:
            self.logger.debug(f"Tier 3 textural/structural classification failed: {e}")
        
        return {'success': False, 'confidence': 0.0}

