    async def _tier5_enhanced_empirical_rock_classification(self, cap_rock_props: CapRockProperties) -> Dict:
        """Tier 5: Enhanced empirical classification with geological context"""
        try:
            # Enhanced empirical classification with multiple criteria
            lithology = cap_rock_props.lithology.lower()
            
            # Strength-based classification refinement
            ucs = cap_rock_props.unconfined_compressive_strength_mpa
            if ucs > 200:
                strength_modifier = 'high_strength'
            elif ucs > 100:
                strength_modifier = 'medium_strength'
            else:
                strength_modifier = 'low_strength'
            
            # Porosity-based refinement
            porosity = cap_rock_props.porosity
            if porosity > 0.3:
                porosity_modifier = 'high_porosity'
            elif porosity > 0.15:
                porosity_modifier = 'medium_porosity'
            else:
                porosity_modifier = 'low_porosity'
            
            # Alteration-based refinement
            alteration_modifier = 'fresh'
            if cap_rock_props.alteration_minerals:
                total_alteration = sum(cap_rock_props.alteration_minerals.values())
                if total_alteration > 0.5:
                    alteration_modifier = 'heavily_altered'
                elif total_alteration > 0.2:
                    alteration_modifier = 'moderately_altered'
                elif total_alteration > 0.05:
                    alteration_modifier = 'slightly_altered'
            
            # Combine modifiers with base lithology
            enhanced_classification = f"{lithology}_{strength_modifier}_{porosity_modifier}_{alteration_modifier}"
            
            # Geological group mapping
            geological_groups = {
                'granite': 'felsic_intrusive',
                'rhyolite': 'felsic_volcanic',
                'andesite': 'intermediate_volcanic',
                'basalt': 'mafic_volcanic',
                'gabbro': 'mafic_intrusive',
                'sandstone': 'clastic_sedimentary',
                'limestone': 'carbonate_sedimentary',
                'shale': 'fine_grained_sedimentary'
            }
            
            base_group = geological_groups.get(lithology, lithology)
            group_classification = f"{base_group}_{alteration_modifier}"
            
            return {
                'success': True,
                'classification': group_classification,
                'enhanced_classification': enhanced_classification,
                'confidence': 0.75,
                'method': 'enhanced_empirical_classification'
            }
            
        except Exception as e:
            self.logger.debug(f"Tier 5 enhanced empirical classification failed: {e}")
        
        return {
            'success': True,
            'classification': cap_rock_props.lithology.lower().replace(' ', '_'),
            'confidence': 0.5,
            'method': 'basic_empirical_fallback'
        }

    async def _analyze_alteration_assemblages(self, cap_rock_props: CapRockProperties) -> Dict:
        """Analyze alteration mineral assemblages for detailed classification"""
        try:
            if not cap_rock_props.alteration_minerals:
                return {'success': False}
            
            # Analyze dominant alteration minerals
            alteration_minerals = cap_rock_props.alteration_minerals
            dominant_mineral = max(alteration_minerals.items(), key=lambda x: x[1])[0]
            total_alteration = sum(alteration_minerals.values())
            
            # Classification based on alteration assemblages
            alteration_types = {
                'chlorite': 'propylitic',
                'sericite': 'phyllic',
                'kaolinite': 'argillic',
                'pyrophyllite': 'advanced_argillic',
                'epidote': 'propylitic',
                'smectite': 'argillic',
                'illite': 'intermediate_argillic'
            }
            
            primary_alteration = alteration_types.get(dominant_mineral, 'unknown')
            
            return {
                'success': True,
                'primary_alteration': primary_alteration,
                'dominant_mineral': dominant_mineral,
                'alteration_intensity': total_alteration,
                'confidence': min(0.9, total_alteration * 2)
            }
            
        except Exception as e:
            self.logger.debug(f"Alteration assemblage analysis failed: {e}")
            return {'success': False}

    async def _analyze_rock_texture_details(self, cap_rock_props: CapRockProperties) -> Dict:
        """Analyze rock texture details for classification"""
        try:
            # Infer texture from rock properties
            porosity = cap_rock_props.porosity
            permeability = cap_rock_props.permeability_m2
            elastic_modulus = cap_rock_props.elastic_modulus_gpa
            
            # Texture classification based on physical properties
            if porosity > 0.3 and permeability > 1e-12:
                primary_texture = 'vesicular'
            elif porosity < 0.05 and elastic_modulus > 70:
                primary_texture = 'crystalline'
            elif porosity > 0.15 and permeability > 1e-15:
                primary_texture = 'porous'
            elif elastic_modulus > 50:
                primary_texture = 'massive'
            else:
                primary_texture = 'altered'
            
            return {
                'success': True,
                'primary_texture': primary_texture,
                'porosity_class': 'high' if porosity > 0.2 else 'medium' if porosity > 0.1 else 'low',
                'permeability_class': 'high' if permeability > 1e-13 else 'medium' if permeability > 1e-16 else 'low',
                'confidence': 0.7
            }
            
        except Exception as e:
            self.logger.debug(f"Rock texture analysis failed: {e}")
            return {'success': False}

    async def _analyze_structural_features(self, cap_rock_props: CapRockProperties) -> Dict:
        """Analyze structural features for classification"""
        try:
            fracture_density = cap_rock_props.fracture_density_per_m3
            joint_sets = cap_rock_props.joint_sets if cap_rock_props.joint_sets else []
            
            # Structural classification based on fracturing
            if fracture_density > 10:
                primary_structure = 'highly_fractured'
            elif fracture_density > 5:
                primary_structure = 'moderately_fractured'
            elif fracture_density > 1:
                primary_structure = 'lightly_fractured'
            else:
                primary_structure = 'massive'
            
            # Joint set analysis
            joint_complexity = 'simple' if len(joint_sets) <= 1 else 'complex' if len(joint_sets) > 3 else 'moderate'
            
            return {
                'success': True,
                'primary_structure': primary_structure,
                'fracture_intensity': 'high' if fracture_density > 10 else 'medium' if fracture_density > 3 else 'low',
                'joint_complexity': joint_complexity,
                'confidence': 0.8
            }
            
        except Exception as e:
            self.logger.debug(f"Structural features analysis failed: {e}")
            return {'success': False}
    
