    async def _combine_knowledge_integration_results(self, federated_results: Dict,
                                                   ensemble_results: Dict,
                                                   local_knowledge: Dict) -> Dict[str, Any]:
        """Combine results from different knowledge integration approaches"""
        try:
            combined_results = {
                'integrated_predictions': {},
                'confidence_weighted_estimates': {},
                'consensus_indicators': {},
                'disagreement_analysis': {}
            }
            
            # Combine predictions with confidence weighting
            predictions_sources = []
            
            if federated_results.get('predictions'):
                predictions_sources.append({
                    'predictions': federated_results['predictions'],
                    'weight': 0.4,
                    'source': 'federated_learning'
                })
            
            if ensemble_results.get('predictions'):
                predictions_sources.append({
                    'predictions': ensemble_results['predictions'],
                    'weight': 0.35,
                    'source': 'ensemble_integration'
                })
            
            if local_knowledge.get('predictions'):
                predictions_sources.append({
                    'predictions': local_knowledge['predictions'],
                    'weight': 0.25,
                    'source': 'local_knowledge'
                })
            
            # Compute weighted averages for numerical predictions
            if predictions_sources:
                combined_results['integrated_predictions'] = await self._compute_weighted_predictions(
                    predictions_sources
                )
                
                # Analyze consensus and disagreement
                combined_results['consensus_indicators'] = await self._analyze_prediction_consensus(
                    predictions_sources
                )
                
                combined_results['disagreement_analysis'] = await self._analyze_prediction_disagreement(
                    predictions_sources
                )
            
            return combined_results
            
        except Exception as e:
            self.logger.error(f"Knowledge integration results combination failed: {e}")
            return {}
    
    async def _compute_weighted_predictions(self, predictions_sources: List[Dict]) -> Dict[str, Any]:
        """Compute confidence-weighted combined predictions"""
        try:
            weighted_predictions = {}
            total_weight = sum(source['weight'] for source in predictions_sources)
            
            if total_weight == 0:
                return weighted_predictions
            
            # Extract common prediction keys
            all_keys = set()
            for source in predictions_sources:
                if isinstance(source['predictions'], dict):
                    all_keys.update(source['predictions'].keys())
            
            # Compute weighted averages for numerical predictions
            for key in all_keys:
                values = []
                weights = []
                
                for source in predictions_sources:
                    if (key in source['predictions'] and 
                        isinstance(source['predictions'][key], (int, float))):
                        values.append(source['predictions'][key])
                        weights.append(source['weight'])
                
                if values:
                    weighted_avg = sum(v * w for v, w in zip(values, weights)) / sum(weights)
                    weighted_std = np.sqrt(sum(w * (v - weighted_avg)**2 for v, w in zip(values, weights)) / sum(weights))
                    
                    weighted_predictions[key] = {
                        'value': weighted_avg,
                        'uncertainty': weighted_std,
                        'contributing_sources': len(values)
                    }
            
            return weighted_predictions
            
        except Exception as e:
            self.logger.error(f"Weighted prediction computation failed: {e}")
            return {}
    
    async def _analyze_prediction_consensus(self, predictions_sources: List[Dict]) -> Dict[str, Any]:
        """Analyze consensus among different prediction sources"""
        try:
            consensus_analysis = {
                'high_consensus_predictions': [],
                'moderate_consensus_predictions': [],
                'low_consensus_predictions': [],
                'overall_consensus_score': 0.0
            }
            
            # Extract common keys
            all_keys = set()
            for source in predictions_sources:
                if isinstance(source['predictions'], dict):
                    all_keys.update(source['predictions'].keys())
            
            consensus_scores = []
            
            for key in all_keys:
                values = []
                for source in predictions_sources:
                    if (key in source['predictions'] and 
                        isinstance(source['predictions'][key], (int, float))):
                        values.append(source['predictions'][key])
                
                if len(values) >= 2:
                    # Calculate coefficient of variation as consensus metric
                    mean_val = np.mean(values)
                    std_val = np.std(values)
                    cv = std_val / abs(mean_val) if mean_val != 0 else float('inf')
                    
                    consensus_score = max(0, 1 - cv)  # High consensus = low CV
                    consensus_scores.append(consensus_score)
                    
                    if consensus_score > 0.8:
                        consensus_analysis['high_consensus_predictions'].append({
                            'parameter': key,
                            'consensus_score': consensus_score,
                            'mean_value': mean_val,
                            'std_value': std_val
                        })
                    elif consensus_score > 0.5:
                        consensus_analysis['moderate_consensus_predictions'].append({
                            'parameter': key,
                            'consensus_score': consensus_score,
                            'mean_value': mean_val,
                            'std_value': std_val
                        })
                    else:
                        consensus_analysis['low_consensus_predictions'].append({
                            'parameter': key,
                            'consensus_score': consensus_score,
                            'mean_value': mean_val,
                            'std_value': std_val
                        })
            
            if consensus_scores:
                consensus_analysis['overall_consensus_score'] = np.mean(consensus_scores)
            
            return consensus_analysis
            
        except Exception as e:
            self.logger.error(f"Consensus analysis failed: {e}")
            return {}
    
    async def _analyze_prediction_disagreement(self, predictions_sources: List[Dict]) -> Dict[str, Any]:
        """Analyze disagreement among prediction sources to identify uncertainties"""
        try:
            disagreement_analysis = {
                'major_disagreements': [],
                'systematic_biases': [],
                'source_reliability': {},
                'uncertainty_sources': []
            }
            
            # Identify major disagreements (high variance across sources)
            all_keys = set()
            for source in predictions_sources:
                if isinstance(source['predictions'], dict):
                    all_keys.update(source['predictions'].keys())
            
            for key in all_keys:
                source_values = []
                source_names = []
                
                for source in predictions_sources:
                    if (key in source['predictions'] and 
                        isinstance(source['predictions'][key], (int, float))):
                        source_values.append(source['predictions'][key])
                        source_names.append(source['source'])
                
                if len(source_values) >= 2:
                    # Calculate disagreement metrics
                    value_range = max(source_values) - min(source_values)
                    mean_val = np.mean(source_values)
                    relative_disagreement = value_range / abs(mean_val) if mean_val != 0 else float('inf')
                    
                    if relative_disagreement > 0.5:  # High disagreement threshold
                        disagreement_analysis['major_disagreements'].append({
                            'parameter': key,
                            'relative_disagreement': relative_disagreement,
                            'value_range': value_range,
                            'source_values': dict(zip(source_names, source_values)),
                            'potential_causes': await self._identify_disagreement_causes(key, source_values)
                        })
            
            # Analyze systematic biases
            disagreement_analysis['systematic_biases'] = await self._identify_systematic_biases(
                predictions_sources
            )
            
            return disagreement_analysis
            
        except Exception as e:
            self.logger.error(f"Disagreement analysis failed: {e}")
            return {}
    
    async def _identify_disagreement_causes(self, parameter: str, values: List[float]) -> List[str]:
        """Identify potential causes of prediction disagreement"""
        causes = []
        
        # Check for outliers
        q75, q25 = np.percentile(values, [75, 25])
        iqr = q75 - q25
        outlier_threshold = 1.5 * iqr
        
        if any(abs(v - np.median(values)) > outlier_threshold for v in values):
            causes.append('outlier_predictions')
        
        # Check for bimodal distribution
        if len(values) >= 4:
            sorted_values = sorted(values)
            gaps = [sorted_values[i+1] - sorted_values[i] for i in range(len(sorted_values)-1)]
            if max(gaps) > 2 * np.mean(gaps):
                causes.append('bimodal_distribution')
        
        # Parameter-specific causes
        if 'strength' in parameter.lower():
            causes.extend(['scale_effects', 'testing_method_differences', 'sample_variability'])
        elif 'pressure' in parameter.lower():
            causes.extend(['measurement_depth_differences', 'temporal_variations'])
        elif 'temperature' in parameter.lower():
            causes.extend(['seasonal_variations', 'depth_gradient_effects'])
        
        return causes
    
    async def _identify_systematic_biases(self, predictions_sources: List[Dict]) -> List[Dict[str, Any]]:
        """Identify systematic biases in prediction sources"""
        try:
            biases = []
            
            # Check if any source consistently predicts higher/lower than others
            for i, source in enumerate(predictions_sources):
                other_sources = predictions_sources[:i] + predictions_sources[i+1:]
                
                bias_indicators = []
                
                for key in source['predictions']:
                    if isinstance(source['predictions'][key], (int, float)):
                        source_val = source['predictions'][key]
                        
                        other_vals = []
                        for other_source in other_sources:
                            if key in other_source['predictions']:
                                if isinstance(other_source['predictions'][key], (int, float)):
                                    other_vals.append(other_source['predictions'][key])
                        
                        if other_vals:
                            other_mean = np.mean(other_vals)
                            bias = (source_val - other_mean) / abs(other_mean) if other_mean != 0 else 0
                            bias_indicators.append(bias)
                
                if bias_indicators:
                    mean_bias = np.mean(bias_indicators)
                    if abs(mean_bias) > 0.2:  # 20% systematic bias threshold
                        biases.append({
                            'source': source['source'],
                            'bias_magnitude': mean_bias,
                            'bias_direction': 'positive' if mean_bias > 0 else 'negative',
                            'affected_parameters': len(bias_indicators)
                        })
            
            return biases
            
        except Exception as e:
            self.logger.error(f"Systematic bias identification failed: {e}")
            return []
    
