    async def _assess_knowledge_quality(self, integrated_knowledge: Dict[str, Any]) -> Dict[str, Any]:
        """Assess quality of integrated knowledge"""
        try:
            quality_metrics = {
                'integration_completeness': 0.0,
                'source_diversity': 0.0,
                'consensus_strength': 0.0,
                'uncertainty_characterization': 0.0,
                'overall_quality_score': 0.0
            }
            
            # Assess integration completeness
            if 'integrated_predictions' in integrated_knowledge:
                n_predictions = len(integrated_knowledge['integrated_predictions'])
                quality_metrics['integration_completeness'] = min(1.0, n_predictions / 10)  # Expect ~10 key predictions
            
            # Assess source diversity
            if 'ensemble_results' in integrated_knowledge:
                n_sources = integrated_knowledge['ensemble_results'].get('n_sources', 1)
                quality_metrics['source_diversity'] = min(1.0, n_sources / 5)  # Expect ~5 sources
            
            # Assess consensus strength
            if 'consensus_indicators' in integrated_knowledge:
                consensus_score = integrated_knowledge['consensus_indicators'].get('overall_consensus_score', 0.0)
                quality_metrics['consensus_strength'] = consensus_score
            
            # Assess uncertainty characterization
            if 'disagreement_analysis' in integrated_knowledge:
                # Good uncertainty characterization means we can identify and explain disagreements
                n_disagreements = len(integrated_knowledge['disagreement_analysis'].get('major_disagreements', []))
                quality_metrics['uncertainty_characterization'] = min(1.0, 1 - n_disagreements / 20)  # Penalize too many disagreements
            
            # Overall quality score
            quality_metrics['overall_quality_score'] = np.mean([
                quality_metrics['integration_completeness'],
                quality_metrics['source_diversity'],
                quality_metrics['consensus_strength'],
                quality_metrics['uncertainty_characterization']
            ])
            
            return quality_metrics
            
        except Exception as e:
            self.logger.error(f"Knowledge quality assessment failed: {e}")
            return {}